schemas.schema-01-core.prisma:
/// User Account Entity - This implements requirements from 'User Registration & Authentication' and core user management in the requirements document. 
///
/// Represents registered users on the platform with authentication credentials. Maintains 3NF normalization by separating profile, roles, and audit data. For example, used for login, enforcing unique email, managing security settings, and associating with posts or comments.
///
/// Key relationships: Links to profiles (discussionboard_user_profile), role assignments, authored content, and audit logs. 
/// Special behaviors: Enforces unique email, provides account state (active/banned), includes basic audit timestamps.
///
/// @namespace Core
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_user {
  //----
  // COLUMNS
  //----
  /// Primary key for the user. Implements requirement for globally unique user identity. 
  /// Used to join with all user-related models. Ensures normalization by serving as the unique, non-business-meaningful identifier.
  id String @id @db.Uuid

  /// User email for login and notification. Implements requirement for secure authentication and unique identification. 
  /// Ensures normalization by not storing personal info redundantly. For example, user signs in with this email. Must be unique.
  email String

  /// Secure password hash for authentication. Required for account protection as defined in security requirements. 
  /// No duplication with plain-text storage, only hashed. Used on every login, never returned in API responses.
  password_hash String

  /// User's public display name. Implements requirements for post attribution and profile. 
  /// Stored as atomic value, not duplicated; for example, used next to posts/comments visible to other users. Length-constrained by application layer.
  display_name String

  /// Avatar image URI. Implements requirement for customizable profile visuals. 
  /// Ensures normalization by not duplicating images; for example, other tables reference this only via user_id. Nullable if user has no avatar.
  avatar_url String?

  /// Account active state. Implements business rule for enabling/disabling sign-in, without deletion. Used in user locking and compliance flows.
  is_active Boolean

  /// Indicates if user is banned (platform-wide, not per-board). Implements moderation control per business rules. Kept atomic, never pre-computed; moderation history is tracked in other models.
  is_banned Boolean

  /// Account creation timestamp. For audit/compliance (see 'Audit Logging & Analytics' requirements). Always set at insert. Used in temporal queries.
  created_at DateTime @db.Timestamptz

  /// Last profile update timestamp. Used for auditing and change tracking, required by audit logs. Always set at update.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp. Implements requirement for soft deletion and data recoverability. Used by admins in retention windows. Nullable if not deleted.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussionboard_user_profile discussionboard_user_profile?
  discussionboard_moderator discussionboard_moderator[]
  discussionboard_admin discussionboard_admin[]
  discussionboard_role_assignment_of_user_id discussionboard_role_assignment[] @relation("discussionboard_role_assignment_of_user_id")
  discussionboard_role_assignment_of_assigned_by_admin_id discussionboard_role_assignment[] @relation("discussionboard_role_assignment_of_assigned_by_admin_id")
  discussionboard_board discussionboard_board[]
  discussionboard_board_settings discussionboard_board_settings[]
  discussionboard_board_archive discussionboard_board_archive[]
  discussionboard_thread_of_created_by_user_id discussionboard_thread[] @relation("discussionboard_thread_of_created_by_user_id")
  discussionboard_thread_of_deleted_by_user_id discussionboard_thread[] @relation("discussionboard_thread_of_deleted_by_user_id")
  discussionboard_post_of_created_by_user_id discussionboard_post[] @relation("discussionboard_post_of_created_by_user_id")
  discussionboard_post_of_deleted_by_user_id discussionboard_post[] @relation("discussionboard_post_of_deleted_by_user_id")
  discussionboard_post_attachment discussionboard_post_attachment[]
  discussionboard_comment_of_created_by_user_id discussionboard_comment[] @relation("discussionboard_comment_of_created_by_user_id")
  discussionboard_comment_of_deleted_by_user_id discussionboard_comment[] @relation("discussionboard_comment_of_deleted_by_user_id")
  discussionboard_likes discussionboard_likes[]
  discussionboard_bookmarks discussionboard_bookmarks[]
  discussionboard_follows_of_follower_user_id discussionboard_follows[] @relation("discussionboard_follows_of_follower_user_id")
  discussionboard_follows_of_followed_user_id discussionboard_follows[] @relation("discussionboard_follows_of_followed_user_id")
  discussionboard_reports discussionboard_reports[]
  discussionboard_like discussionboard_like[]
  discussionboard_bookmark discussionboard_bookmark[]
  discussionboard_follow_of_follower_user_id discussionboard_follow[] @relation("discussionboard_follow_of_follower_user_id")
  discussionboard_follow_of_followed_user_id discussionboard_follow[] @relation("discussionboard_follow_of_followed_user_id")
  discussionboard_report discussionboard_report[]
  discussionboard_moderation_action_of_actor_moderator_id discussionboard_moderation_action[] @relation("discussionboard_moderation_action_of_actor_moderator_id")
  discussionboard_moderation_action_of_target_user_id discussionboard_moderation_action[] @relation("discussionboard_moderation_action_of_target_user_id")
  discussionboard_ban_of_user_id discussionboard_ban[] @relation("discussionboard_ban_of_user_id")
  discussionboard_ban_of_moderator_id discussionboard_ban[] @relation("discussionboard_ban_of_moderator_id")
  discussionboard_moderator_note_of_author_id discussionboard_moderator_note[] @relation("discussionboard_moderator_note_of_author_id")
  discussionboard_moderator_note_of_target_user_id discussionboard_moderator_note[] @relation("discussionboard_moderator_note_of_target_user_id")
  discussionboard_notification_of_user_id discussionboard_notification[] @relation("discussionboard_notification_of_user_id")
  discussionboard_notification_of_actor_id discussionboard_notification[] @relation("discussionboard_notification_of_actor_id")
  discussionboard_notification_setting discussionboard_notification_setting[]
  discussionboard_audit_log discussionboard_audit_log[]

  @@unique([email])
  @@index([is_active])
  @@index([display_name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// User Profile Entity - Implements the 'Profile Management' and extended information requirement. 
///
/// Stores additional info about the user not essential for authentication. Maintains 3NF by separating profile metadata from core user record. For example, includes bio, location, and social links—referenced only by user_id.
///
/// Key relationships: 1:1 with discussionboard_user. No duplication, always unique per user. Used on profile views, update flows.
/// Special behaviors: Deletions or nulls cascade per user deletion.
///
/// @namespace Core
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_user_profile {
  //----
  // COLUMNS
  //----
  /// Unique profile identifier (same as user_id for 1:1). Enforces strict 1:1 between user and profile.
  id String @id @db.Uuid

  /// 1:1 reference to discussionboard_user. Enforces single profile per user. Implements 3NF by eliminating partial dependencies.
  user_id String @db.Uuid

  /// User biography for profile page. Fulfills business need for user self-description. Conforms to normalization by avoiding duplication with posts or comments. Nullable.
  bio String?

  /// Geographic location (optional, user-provided). Implements user personalization feature. Never pre-aggregated. Nullable.
  location String?

  /// User's website or blog URL. Enables richer profiles per requirements. Not duplicated. Nullable.
  website_url String?

  /// User's Twitter/X account. Supports social connection feature, not duplicated elsewhere. Nullable.
  twitter_handle String?

  /// Profile creation timestamp for auditability.
  created_at DateTime @db.Timestamptz

  /// Profile last update timestamp for audit logs.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  user discussionboard_user @relation(fields: [user_id], references: [id], onDelete: Cascade)

  @@unique([user_id])
  @@index([bio(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Moderator Role Assignment - Implements 'Moderator Role Definition' and moderation flows as per requirements.
///
/// Represents users granted 'moderator' status for specific scopes (e.g. all boards, selected boards). Maintains normalization by linking only user_id and storing moderator-specific info (not duplicating user record).
///
/// Used for: assigning, querying, and removing moderator privilege. e.g., admin promotes a user, logs time, scope.
///
/// Key relationships: Links to user, boards moderated, actions logged.
/// Special behaviors: Promotion/demotion time and scoping per board kept normalized here, not duplicated elsewhere.
///
/// @namespace Core
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_moderator {
  //----
  // COLUMNS
  //----
  /// Primary key for moderator assignment, uniquely identifies each moderation instance.
  id String @id @db.Uuid

  /// User assigned moderator privileges, implements role mapping per business rules. Not unique; a user might be moderator on multiple boards.
  user_id String @db.Uuid

  /// Optional reference to a specific board. Implements per-board moderator scoping. Nullable if platform-wide.
  board_id String? @db.Uuid

  /// Admin user who assigned moderator rights. Implements auditability per role transition requirements. Not a FK for simplicity, resolves via audit logs.
  assigned_by_admin_id String @db.Uuid

  /// Timestamp for moderator assignment (used in privilege lifecycles and audit trails).
  assigned_at DateTime @db.Timestamptz

  /// Timestamp when moderation privileges ended (null if active). Fulfills demotion/transition flows. Nullable.
  revoked_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  user discussionboard_user @relation(fields: [user_id], references: [id], onDelete: Cascade)
  board discussionboard_board? @relation(fields: [board_id], references: [id], onDelete: Cascade)

  discussionboard_report_histories discussionboard_report_histories[]
  discussionboard_report_history discussionboard_report_history[]

  @@index([board_id])

  @@index([user_id, board_id])
}

/// Admin User Assignment Model - Implements 'Admin Role Definition & Escalation' from requirements.
///
/// Records which users have admin privilege. Maintains normalization by separating admin assignments and transitions (not duplicating user records). For example, escalation/demotion history, audit.
///
/// Key relationships: Links only to discussionboard_user. Used in role management, system logs. Admins are platform-wide.
/// Special behaviors: Handles temporal privilege assignment, supports escalation/demotion audit.
///
/// @namespace Core
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_admin {
  //----
  // COLUMNS
  //----
  /// Admin assignment record ID.
  id String @id @db.Uuid

  /// Reference to the user granted admin privileges. Not unique: users may be promoted/demoted multiple times (history tracked).
  user_id String @db.Uuid

  /// Admin that assigned the role. Implements full audit traceability for escalations.
  assigned_by_admin_id String @db.Uuid

  /// Timestamp for admin privilege assignment.
  assigned_at DateTime @db.Timestamptz

  /// Time assignment ended (null if still admin). Supports lifecycle audit, demotion flow. Nullable.
  revoked_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  user discussionboard_user @relation(fields: [user_id], references: [id], onDelete: Cascade)

  discussionboard_report_histories discussionboard_report_histories[]
  discussionboard_report_history discussionboard_report_history[]

  @@index([user_id])
}

/// Comprehensive Role Assignment Journal - Implements 'Role Escalation/Demotion & History' requirement.
///
/// Tracks all role changes (User/Moderator/Admin) with full assignment and revocation details. Maintains strict normalization—never duplicates role logic in user records. Used for full audit of who assigned/removes which role, temporal queries, compliance reporting.
///
/// Key relationships: Links to user and admin. Used in security audits, permissions enforcement.
/// Special behaviors: Immutable journal for compliance; never updated after insertion.
///
/// @namespace Core
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_role_assignment {
  //----
  // COLUMNS
  //----
  /// Primary key for role assignment journal entry.
  id String @id @db.Uuid

  /// Target user for role change. Enables comprehensive user change querying.
  user_id String @db.Uuid

  /// Admin who executed the assignment or revocation. Needed for audit. May duplicate some admin_id, tracked for every event.
  assigned_by_admin_id String @db.Uuid

  /// The assigned role. Implements tight role typing. Enum: 'user','moderator','admin'. Enforced in app layer. No transitive dependencies.
  role String

  /// Timestamp for when the role was assigned.
  assigned_at DateTime @db.Timestamptz

  /// Timestamp for revocation of role (null if currently active). Nullable.
  revoked_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  user discussionboard_user @relation("discussionboard_role_assignment_of_user_id", fields: [user_id], references: [id], onDelete: Cascade)
  assigned_by_admin discussionboard_user @relation("discussionboard_role_assignment_of_assigned_by_admin_id", fields: [assigned_by_admin_id], references: [id], onDelete: Cascade)

  @@index([assigned_by_admin_id])

  @@index([user_id])
  @@index([role, assigned_by_admin_id])
}

/// Organization Model - Implements optional organizational user grouping for enterprise moderation/administration per extensibility requirements.
///
/// Represents a logical group or organization (e.g. civic group, institution) within which users/moderators/admins can be assigned for scoped permissions. Maintains full normalization by not duplicating user/admin data. Used in future for external integrations, reporting.
///
/// Key relationships: Will link with users and assignments in extended usage scenarios. 
/// Special behaviors: None for now; reserved for scalable enterprise/partner features.
///
/// @namespace Core
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_organization {
  //----
  // COLUMNS
  //----
  /// Organization unique identifier.
  id String @id @db.Uuid

  /// Organization name, business requirement for logical grouping.
  name String

  /// Organization creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last modification timestamp, for audit.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([name])
}

schemas.schema-02-boards.prisma:
/// [Board (discussion area) metadata] - Implements Forum/Board concept as per requirements from 02_discussionboard_functional_requirements.md (Board & Topic Configuration; Posting & Content Management), and 01_discussionboard_overview_and_scope.md. Enables the organization of discussions into named boards (forums) for political or economic topics. Maintains strict 3NF—board metadata only. For example, users posting a new thread select the relevant board. Key relationships: links to discussionboard_board_settings (1:1), discussionboard_topic (1:N), moderators (M:N via assignments elsewhere), board_archive (1:N for archiving). Special behaviors: board can be soft-deleted or archived; renaming only by admins.
///
/// @namespace Boards
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_board {
  //----
  // COLUMNS
  //----
  /// [Board unique ID] - Unique board identifier. Ensures normalization by acting as sole identifier. Used as foreign key elsewhere.
  id String @id @db.Uuid

  /// [Board creator FK] - References discussionboard_user.id; shows who created the board. Ensures board accountability. Nullable for legacy/auto-created boards.
  created_by_user_id String? @db.Uuid

  /// [Board display name] - Human-readable label shown in board lists and navigation. Example: 'Current Affairs'.
  name String

  /// [Board slug/unique key] - Unique, URL-safe string for direct navigation. Example: 'economics'.
  slug String

  /// [Board description] - Short summary about the board. Example: 'A forum for global economic discussions.'.
  description String

  /// [Archive flag] - Marks the board as inactive (archived/deleted logic).
  is_archived Boolean

  /// [Creation timestamp] - When the board was created.
  created_at DateTime @db.Timestamptz

  /// [Last update timestamp] - Tracks last modification for auditing.
  updated_at DateTime @db.Timestamptz

  /// [Soft deletion timestamp] - Only present if soft-deleted, else null. For admin control/business logic.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_discussionboard_board_created_by_user discussionboard_user? @relation(fields: [created_by_user_id], references: [id], onDelete: Cascade)

  discussionboard_moderator discussionboard_moderator[]
  discussionboard_topic discussionboard_topic[]
  discussionboard_board_settings discussionboard_board_settings[]
  discussionboard_board_archive discussionboard_board_archive[]
  discussionboard_thread discussionboard_thread[]
  discussionboard_setting discussionboard_setting[]

  @@unique([slug])
  @@index([created_by_user_id, created_at])
  @@index([is_archived])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [Board topic metadata] - Implements requirements from 02_discussionboard_functional_requirements.md (Board & Topic Configuration, Search & Navigation). Assigns granular topics to boards, enabling categorization of threads within each board. Strict 3NF. For example, a board 'Economics' may have topics like 'Macroeconomics', 'Policy'. Key relationships: belongs to board (N:1), referenced by threads (elsewhere). Special behaviors: topics can be soft-deleted/updated only by board managers/admins.
///
/// @namespace Boards
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_topic {
  //----
  // COLUMNS
  //----
  /// [Topic unique ID] - Atomic, unique identifier for topics. Used as foreign key in threads; ensures 3NF.
  id String @id @db.Uuid

  /// [Board FK] - Links each topic to parent board. Ensures referential integrity/strict normalization.
  board_id String @db.Uuid

  /// [Topic name] - Used in search and thread filtering.
  name String

  /// [Topic slug/unique key] - For URL/route navigation, unique per board.
  slug String

  /// [Topic description] - Explains what belongs under this topic.
  description String

  /// [Topic creation timestamp] - For audit and management.
  created_at DateTime @db.Timestamptz

  /// [Last updated timestamp] - For tracking metadata changes.
  updated_at DateTime @db.Timestamptz

  /// [Soft deletion timestamp] - Set if topic is soft-deleted, else null.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_discussionboard_topic_board discussionboard_board @relation(fields: [board_id], references: [id], onDelete: Cascade)

  discussionboard_thread discussionboard_thread[]

  @@unique([board_id, slug])
  @@index([board_id, name])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [Board settings/configuration] - Implements board-level config management. Stores all settings in a normalized, versioned structure. Required for audit and snapshot patterns: don't keep settings directly on board, but as a separate, replaceable object. For example, a settings change saves a new row, board points to latest. Key relationships: 1:N with boards (each board references current), can track settings history. Special: settings never deleted but always versioned.
///
/// @namespace Boards
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_board_settings {
  //----
  // COLUMNS
  //----
  /// [Settings unique ID] - Row identifier for versioned settings, linked by board.current_settings_id.
  id String @id @db.Uuid

  /// [Board FK] - Refers to the board these settings apply to. Maintains referential integrity.
  board_id String @db.Uuid

  /// [Who changed the settings] - For audit logging; may be nullable for system-generated changes.
  modified_by_user_id String? @db.Uuid

  /// [Post permission flag] - Whether users (vs only moderators/admins) can post.
  can_users_post Boolean

  /// [Default topic for new threads] - Null for boards w/o default topic.
  default_topic_id String? @db.Uuid

  /// [Minimum post length] - Business constraint. Example: 20.
  min_post_length Int @db.Integer

  /// [Maximum post length] - Board's content length policy. Example: 10000.
  max_post_length Int @db.Integer

  /// [Image upload toggle] - Board-level configuration; not usage data.
  allow_image_uploads Boolean

  /// [File attachment toggle] - Permission for uploads only.
  allow_file_attachments Boolean

  /// [Settings version number] - Implements versioning for settings; strictly atomic for 3NF.
  settings_version Int @db.Integer

  /// [When settings take effect] - For audit/time-based rollback.
  effective_at DateTime @db.Timestamptz

  /// [Settings creation timestamp] - For change log/audit compliance.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_discussionboard_board_settings_board discussionboard_board @relation(fields: [board_id], references: [id], onDelete: Cascade)
  fk_discussionboard_board_settings_modified_by_user discussionboard_user? @relation(fields: [modified_by_user_id], references: [id], onDelete: Cascade)

  @@index([modified_by_user_id])

  @@unique([board_id, settings_version])
  @@index([board_id, created_at])
}

/// [Board archive/audit snapshot] - Implements archival, historicization, and audit policies per requirements. Captures state of a board at the moment of archival for compliance, reference, and rollback. Maintains normalization by recording only atomic metadata (no thread/post data). For example, keeps board name/description, archived_at, who archived, and corresponding snapshot. Key relationships: belongs to discussionboard_board (N:1), links to archived_by user (moderator/admin) for traceability. Special: board can have multiple archival records; system logs when/who archived for compliance.
///
/// @namespace Boards
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_board_archive {
  //----
  // COLUMNS
  //----
  /// [Archive record unique ID] - Globally unique; allows multiple archives for same board. Each archive stores atomic/canonical data.
  id String @id @db.Uuid

  /// [Board FK] - References the board being archived.
  board_id String @db.Uuid

  /// [Who archived] - Links to user (moderator/admin) responsible. Maintains normalization/3NF.
  archived_by_user_id String @db.Uuid

  /// [Archival timestamp] - When the board was archived for audit/compliance.
  archived_at DateTime @db.Timestamptz

  /// [Board name at time of archive] - Historical metadata snapshot.
  name_snapshot String

  /// [Board description at time of archive] - Historical description.
  description_snapshot String

  /// [Board slug at time of archive] - Snapshot of the slug.
  slug_snapshot String

  //----
  // RELATIONS
  //----
  fk_discussionboard_board_archive_board discussionboard_board @relation(fields: [board_id], references: [id], onDelete: Cascade)
  fk_discussionboard_board_archive_archived_by_user discussionboard_user @relation(fields: [archived_by_user_id], references: [id], onDelete: Cascade)

  @@index([archived_by_user_id])

  @@index([board_id, archived_at])
  @@index([name_snapshot(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([description_snapshot(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-03-threads_posts.prisma:
/// [Discussion Thread Model] - This implements thread-level requirements from the 'Posting & Content Management' and 'Functional Requirements' sections. 
///
/// Supports organization and grouping of conversations on the board. Each thread is created by a user, belongs to a board, has a topic, and acts as a container for posts (with one or more root posts, but typically just one as an initial post). Maintains 3NF compliance by separating the concept of a thread from its posts, users, and board/category settings. 
///
/// For example, used to display topic lists or aggregate posts under a discussion. 
///
/// Key relationships: references discussionboard_user (creator), discussionboard_board (location), discussionboard_topic (optional topical classification), and has many posts.
/// Special behaviors: only creators or mods/admins can edit/delete, soft deletion by flag, archival by board policies, unique constraint on slug per board for SEO routing.
///
/// @namespace ThreadsPosts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_thread {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - Implements unique identification for each thread. Guarantees row uniqueness, supports foreign key relations, and underpins normalization.
  id String @id @db.Uuid

  /// [Board Relationship] - Implements mapping of threads to their parent board based on requirement to organize discussions. Atomic field sustaining 3NF by foreign key separation. Example: Maps thread to "Economic Policy" board.
  board_id String @db.Uuid

  /// [Topic Relationship] - Optional link to board-level topics, supporting requirement for topic-based filtering and navigation. Maintains normalization by referencing discrete topic entity. Example: Thread about 'Inflation' links to that topic. Nullable if no classification.
  topic_id String? @db.Uuid

  /// [Creator Relationship] - Thread creator, implementing traceability and audit requirements. Atomic field referencing user entity; critical for moderation and permission enforcement. Example: Thread started by user #42.
  created_by_user_id String @db.Uuid

  /// [Deleted By Relationship] - Optional link to the user who deleted (soft-deleted) the thread, implementing recoverability and moderation trail policies. Maintains normalization; null if not deleted.
  deleted_by_user_id String? @db.Uuid

  /// [Thread Title] - Implements requirement for titling threads. Atomic string; not pre-computed. Used for display and search. Example: "Fiscal Policy Reforms 2025".
  title String

  /// [Slug for SEO/URL] - Friendly identifier for URLs; unique per board. Supports requirement for discoverable, navigable threads. Example: "fiscal-policy-reforms-2025".
  slug String

  /// [Pin Status] - Whether thread is pinned by mods/admins. Atomic field; no aggregation. Example: True for important or announcement threads.
  is_pinned Boolean

  /// [Lock Status] - Whether thread is locked to further posts or comments. Atomic flag for moderation and content rules. Example: Thread closed after heated debate.
  is_locked Boolean

  /// [Soft Deletion Flag] - Marks thread as deleted for recoverability/retention policies. Maintains normalization by flag, not record removal.
  is_deleted Boolean

  /// [Creation Timestamp] - When thread was created. Implements audit and timeline requirements. Atomic, non-aggregated.
  created_at DateTime @db.Timestamptz

  /// [Last Update Timestamp] - When thread was last edited (metadata, not posts). Ensures normalization and audit trail.
  updated_at DateTime @db.Timestamptz

  /// [Deletion Timestamp] - When thread was deleted (soft delete). Null if not deleted. Supports recoverability and retention policies.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  threads_board discussionboard_board @relation(fields: [board_id], references: [id], onDelete: Cascade)
  threads_topic discussionboard_topic? @relation(fields: [topic_id], references: [id], onDelete: Cascade)
  threads_created_by_user discussionboard_user @relation("discussionboard_thread_of_created_by_user_id", fields: [created_by_user_id], references: [id], onDelete: Cascade)
  threads_deleted_by_user discussionboard_user? @relation("discussionboard_thread_of_deleted_by_user_id", fields: [deleted_by_user_id], references: [id], onDelete: Cascade)

  discussionboard_post discussionboard_post[]
  discussionboard_follows discussionboard_follows[]
  discussionboard_follow discussionboard_follow[]

  @@index([topic_id])
  @@index([deleted_by_user_id])

  @@unique([board_id, slug])
  @@index([board_id, created_at])
  @@index([created_by_user_id])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [Discussion Post Model] - Implements post/article-level requirements from 'Posting & Content Management'. 
///
/// Represents an individual post within a thread (can be root post or a reply/child post if needed in future evolution). Each post is authored by a user, belongs to a thread, and can have attachments and comments. Maintains 3NF by atomic separation from user, thread, and attachment entities.
///
/// For example, used to render primary content when viewing a thread. 
///
/// Key relationships: owns attachments and comments, references thread and author. 
/// Special behaviors: authorship tracked for permissions, posts can be soft-deleted and edited, immutable audit trail via snapshots outside regular table, moderate only by proper roles.
///
/// @namespace ThreadsPosts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_post {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - Unique identifier for each post, ensuring normalization and integrity.
  id String @id @db.Uuid

  /// [Thread Relationship] - Associates post to its parent thread per functional/posting requirements. Maintains normalized mapping; critical for display and retrieval.
  thread_id String @db.Uuid

  /// [Author Relationship] - User who posted, supporting authorship tracking and permissions. Maintains atomic separation for normalization.
  created_by_user_id String @db.Uuid

  /// [Deleted By Relationship] - User who deleted/soft-deleted this post for moderation/audit. Null if not deleted, sustaining compliance with recoverable deletion.
  deleted_by_user_id String? @db.Uuid

  /// [Post Body] - Implements primary content field for posting. Atomic text, not aggregated.
  content String

  /// [Edit Flag] - True if post was edited post-creation, supporting audit/notification requirements. Not a computed field.
  is_edited Boolean

  /// [Soft Deletion Flag] - Discovers post as deleted/restorable for mod trail and retention. Not summary/aggregated.
  is_deleted Boolean

  /// [Created Timestamp] - When post was made, supporting audit/history.
  created_at DateTime @db.Timestamptz

  /// [Last Update Timestamp] - Last content or metadata update; for audit/logging.
  updated_at DateTime @db.Timestamptz

  /// [Optional Deletion Timestamp] - When post was soft-deleted. Null if not deleted. Supports compliance/recovery policies.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  posts_thread discussionboard_thread @relation(fields: [thread_id], references: [id], onDelete: Cascade)
  posts_created_by_user discussionboard_user @relation("discussionboard_post_of_created_by_user_id", fields: [created_by_user_id], references: [id], onDelete: Cascade)
  posts_deleted_by_user discussionboard_user? @relation("discussionboard_post_of_deleted_by_user_id", fields: [deleted_by_user_id], references: [id], onDelete: Cascade)

  discussionboard_post_attachment discussionboard_post_attachment[]
  discussionboard_comment discussionboard_comment[]
  discussionboard_likes discussionboard_likes[]
  discussionboard_bookmarks discussionboard_bookmarks[]
  discussionboard_reports discussionboard_reports[]
  discussionboard_like discussionboard_like[]
  discussionboard_bookmark discussionboard_bookmark[]
  discussionboard_report discussionboard_report[]
  discussionboard_moderation_action discussionboard_moderation_action[]
  discussionboard_notification discussionboard_notification[]

  @@index([deleted_by_user_id])

  @@index([thread_id, created_at])
  @@index([created_by_user_id])
  @@index([content(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [Post Attachment Model] - Implements file/image/document upload requirements for posts. 
///
/// Each attachment links to a single post; tracks metadata (filename, mimetype, size, URL). Atomic, normalized design (no file or image fields in posts directly). 
///
/// Used for rendering post media or downloads. 
///
/// Key relationships: references post and uploader. File URLs and metadata not pre-calculated, in 3NF.
///
/// Special behaviors: Files can be soft-deleted (removable), post deletion cascades to attachment retention policy.
///
/// @namespace ThreadsPosts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_post_attachment {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - Uniquely identifies each attachment, supporting normalized file management.
  id String @id @db.Uuid

  /// [Post Relationship] - Maps attachment to associated post. Maintains normalized structure: no file/image fields directly on posts.
  post_id String @db.Uuid

  /// [Uploader Relationship] - User who uploaded file, supporting audit/ownership requirements. Normalized to enable user-centric queries.
  uploaded_by_user_id String @db.Uuid

  /// [Original Filename] - Required for display, download, reference. Not derived or calculated; atomic.
  filename String

  /// [MIME Type] - Filetype field for best-effort validation. E.g. 'image/png', 'application/pdf'.
  mimetype String

  /// [File Size] - Atomic storage of file size (bytes); for quota enforcement and cleanup policies.
  size_bytes Int @db.Integer

  /// [Serving URL] - Download or CDN URL for attachment access. Fully qualified. Not derived.
  url String @db.VarChar(80000)

  /// [Soft Delete Flag] - Soft-deletion to facilitate recoverability and audit. Not summary, not computed.
  is_deleted Boolean

  /// [Upload Timestamp] - Time of upload, for audit trail and listing order.
  uploaded_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  attachments_post discussionboard_post @relation(fields: [post_id], references: [id], onDelete: Cascade)
  attachments_uploaded_by_user discussionboard_user @relation(fields: [uploaded_by_user_id], references: [id], onDelete: Cascade)

  @@index([post_id])
  @@index([uploaded_by_user_id])
  @@index([filename(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [Comment Model] - Implements 'Commenting & Community Interaction' requirements by representing discrete, atomic user comments on posts. Comments belong to posts and are authored by users (not just anonymous). Replies can be chained by parent comment, but hierarchy is 1 step only to avoid complex tree management in normalized tables. 
///
/// For example, used for post discussion display or thread stacking. 
///
/// Key relationships: references post, user, optional parent comment (self-reference). 
/// Special behaviors: soft deletable, moderate-able by role rules, edit history tracked by snapshots if needed, unique constraint on (post_id, parent_comment_id, created_at) for rendering order and duplicated prevention.
///
/// @namespace ThreadsPosts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_comment {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - Unique comment identification, 3NF compliant.
  id String @id @db.Uuid

  /// [Post Relationship] - Links comment to post, satisfying atomicity and performance for viewing post's discussion.
  post_id String @db.Uuid

  /// [Author Relationship] - User who wrote this comment. Allows author queries, enforces role and moderation logic.
  created_by_user_id String @db.Uuid

  /// [Parent Comment Relationship] - Optional self-reference, implements 1-level reply to another comment (threaded view). Null if top-level.
  parent_comment_id String? @db.Uuid

  /// [Deleted by User Reference] - User who soft deleted the comment, for moderation and audit. Null if not deleted.
  deleted_by_user_id String? @db.Uuid

  /// [Comment Body] - Core content field for comment. Atomic, not computed.
  content String

  /// [Edit Flag] - Indicates if comment was edited after posting; supports audit log, not computed.
  is_edited Boolean

  /// [Soft Delete Flag] - Shows comment as deleted/restorable, for recoverability and compliance.
  is_deleted Boolean

  /// [Creation Timestamp] - When comment was posted.
  created_at DateTime @db.Timestamptz

  /// [Update Timestamp] - Last edit, if ever, for audit.
  updated_at DateTime @db.Timestamptz

  /// [Optional Deletion Timestamp] - Soft delete policy compliance; null if not deleted.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  comments_post discussionboard_post @relation(fields: [post_id], references: [id], onDelete: Cascade)
  comments_created_by_user discussionboard_user @relation("discussionboard_comment_of_created_by_user_id", fields: [created_by_user_id], references: [id], onDelete: Cascade)
  comments_parent_comment discussionboard_comment? @relation("recursive", fields: [parent_comment_id], references: [id], onDelete: Cascade)
  comments_deleted_by_user discussionboard_user? @relation("discussionboard_comment_of_deleted_by_user_id", fields: [deleted_by_user_id], references: [id], onDelete: Cascade)

  recursive discussionboard_comment[] @relation("recursive")
  discussionboard_likes discussionboard_likes[]
  discussionboard_reports discussionboard_reports[]
  discussionboard_like discussionboard_like[]
  discussionboard_report discussionboard_report[]
  discussionboard_moderation_action discussionboard_moderation_action[]
  discussionboard_notification discussionboard_notification[]

  @@index([parent_comment_id])
  @@index([deleted_by_user_id])

  @@unique([post_id, parent_comment_id, created_at])
  @@index([post_id])
  @@index([created_by_user_id])
  @@index([content(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-04-interactions.prisma:
/// [Like tracking] - Implements the 'like' interaction requirement from the requirements document. This table records every like event by users on posts or comments, supporting community feedback, engagement analysis, and individual liking history. Fully normalized: one row per event, referencing user and content only by ID. Used for showing whether a user liked content and for aggregate like calculation in materialized views. Enforces uniqueness per target to prevent duplicate likes.
///
/// @namespace Interactions
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_likes {
  //----
  // COLUMNS
  //----
  /// [Unique like record identifier] - Required for event traceability and 1NF/3NF compliance. A UUID for each like, used for audit and deletion.
  id String @id @db.Uuid

  /// [User who performed like] - Links to discussionboard_user. Required for tracking who liked the content. Enforces relational integrity.
  user_id String @db.Uuid

  /// [Liked post] - Set if liking a post (nullable so likes can refer to comment alternatively).
  post_id String? @db.Uuid

  /// [Liked comment] - Set if liking a comment (nullable if liking a post instead).
  comment_id String? @db.Uuid

  /// [Like timestamp] - When the like occurred. Used for recency and audit logging.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  user discussionboard_user @relation(fields: [user_id], references: [id], onDelete: Cascade)
  post discussionboard_post? @relation(fields: [post_id], references: [id], onDelete: Cascade)
  comment discussionboard_comment? @relation(fields: [comment_id], references: [id], onDelete: Cascade)

  @@unique([user_id, post_id])
  @@unique([user_id, comment_id])
  @@index([post_id, created_at])
  @@index([comment_id, created_at])
}

/// [Bookmark tracking] - Implements the 'bookmark' feature for users to save posts for later. Ensures normalized structure (one row per unique bookmark event). Used to restore bookmarks, display user's saved list, and drive notification preferences. Uniqueness enforced to one bookmark per user/post combination.
///
/// @namespace Interactions
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_bookmarks {
  //----
  // COLUMNS
  //----
  /// [Bookmark record identifier] - For audit and deletion, 1NF/3NF compliance.
  id String @id @db.Uuid

  /// [Bookmarking user] - References discussionboard_user for normalized representation. Enforces permission constraints and relationship tracking.
  user_id String @db.Uuid

  /// [Bookmarked post] - References discussionboard_post, strictly normalized.
  post_id String @db.Uuid

  /// [Timestamp when bookmark was created] - Used for restoring display order, cleaning up expired bookmarks, and auditing.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  user discussionboard_user @relation(fields: [user_id], references: [id], onDelete: Cascade)
  post discussionboard_post @relation(fields: [post_id], references: [id], onDelete: Cascade)

  @@index([post_id])

  @@unique([user_id, post_id])
  @@index([created_at])
}

/// [Follow entity] - Implements the 'follow' relationship, used when a user follows another user or thread (for notifications/engagement). Strictly normalized (no rolled-up data). Supports polymorphic following via nullable target fields, allowing the user to follow a thread or another user, but not both simultaneously. Used for notification triggers. Uniqueness enforced for every (follower, target) combination.
///
/// @namespace Interactions
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_follows {
  //----
  // COLUMNS
  //----
  /// [Follow record identifier] - Used for tracing follow relationships and for deletion operations.
  id String @id @db.Uuid

  /// [The user who follows] - Always set; links to discussionboard_user.
  follower_user_id String @db.Uuid

  /// [The user being followed] - Set if following a user, null otherwise.
  followed_user_id String? @db.Uuid

  /// [The thread being followed] - Set if following a thread (alternative to user).
  followed_thread_id String? @db.Uuid

  /// [Follow timestamp] - When the follow was registered.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  follower_user discussionboard_user @relation("discussionboard_follows_of_follower_user_id", fields: [follower_user_id], references: [id], onDelete: Cascade)
  followed_user discussionboard_user? @relation("discussionboard_follows_of_followed_user_id", fields: [followed_user_id], references: [id], onDelete: Cascade)
  followed_thread discussionboard_thread? @relation(fields: [followed_thread_id], references: [id], onDelete: Cascade)

  @@index([followed_user_id])
  @@index([followed_thread_id])

  @@unique([follower_user_id, followed_user_id])
  @@unique([follower_user_id, followed_thread_id])
  @@index([created_at])
}

/// [Report entity] - Records user reporting actions against posts or comments, supporting moderation workflow and abuse handling. Reports are strictly normalized, representing individual reporting events per user/content. Integrated with moderation review pipelines and reporting history. Enforces per-user per-target uniqueness.
///
/// @namespace Interactions
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_reports {
  //----
  // COLUMNS
  //----
  /// [Unique report identifier] - Supports event traceability, audit, and moderation history.
  id String @id @db.Uuid

  /// [Reporting user] - Identifies the user who created the report. Fulfills traceability and audit requirements.
  reporting_user_id String @db.Uuid

  /// [Reported post] - Set only if the report targets a post (null otherwise).
  post_id String? @db.Uuid

  /// [Reported comment] - Set if the report targets a comment (null otherwise).
  comment_id String? @db.Uuid

  /// [Reason provided for reporting] - Free-text entry, enables moderation analysis and audit. Atomic primitive, not interpreted summary. For substring search and workflow status filtering.
  reason String

  /// [Report status] - Indicates workflow state ('pending','reviewed', etc), enables moderator dashboard filtering. Stored as atomic value only.
  status String

  /// [When report was created] - Used for recency and workflow ordering.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  reporting_user discussionboard_user @relation(fields: [reporting_user_id], references: [id], onDelete: Cascade)
  post discussionboard_post? @relation(fields: [post_id], references: [id], onDelete: Cascade)
  comment discussionboard_comment? @relation(fields: [comment_id], references: [id], onDelete: Cascade)

  discussionboard_report_histories discussionboard_report_histories[]

  @@index([post_id])
  @@index([comment_id])

  @@unique([reporting_user_id, post_id])
  @@unique([reporting_user_id, comment_id])
  @@index([status, created_at])
  @@index([reason(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [Report Action History] - Captures the audit trail of actions by moderators/admins in response to reports. This normalized model supports full history for appeals, transparency, and compliance. Strictly records actions, their chronology, and which actor (moderator/admin) took the action. Multiple histories may exist per report, one per action taken.
///
/// @namespace Interactions
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_report_histories {
  //----
  // COLUMNS
  //----
  /// [Action record ID] - Unique event tracking per report durability and audit.
  id String @id @db.Uuid

  /// [Which report this action is attached to] - Immediate event linkage, provides workflow traceability.
  report_id String @db.Uuid

  /// [Moderator handling action] - Set when handled by moderator role, null otherwise. Enables actor history, permission checks.
  moderator_id String? @db.Uuid

  /// [Admin handling action] - Set when handled by admin role, null otherwise.
  admin_id String? @db.Uuid

  /// [Workflow event/action taken] - e.g. 'acknowledged', 'dismissed', 'user_banned', atomic and minimal for normalization.
  action String

  /// [Context/notes for action] - Free-text moderator/admin input for justification and context. Strictly atomic.
  action_detail String

  /// [When action was taken] - For ordering and timeliness reporting. Strictly atomic.
  acted_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  report discussionboard_reports @relation(fields: [report_id], references: [id], onDelete: Cascade)
  moderator discussionboard_moderator? @relation(fields: [moderator_id], references: [id], onDelete: Cascade)
  admin discussionboard_admin? @relation(fields: [admin_id], references: [id], onDelete: Cascade)

  @@index([report_id, acted_at])
  @@index([moderator_id, acted_at])
  @@index([admin_id, acted_at])
}

/// [Like tracking] - This implements the 'like' interaction requirement from the requirements document.
///
/// This table records every like event by users on posts or comments, enabling user feedback and engagement metrics. One row per atomic like event, strictly normalized: each like references only a user and either a post or a comment (never both). Used to check if a user liked given content and for materialized view aggregation. Enforcement: Only one like per user per target is allowed. Cascade delete on content/user removal. Fully compliant with 3NF (no calculated/aggregate fields).
///
/// @namespace Interactions
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_like {
  //----
  // COLUMNS
  //----
  /// [Unique like record identifier] - Implements normalized tracking and supports audit and deletion. Required, atomic, non-null.
  id String @id @db.Uuid

  /// [User performing the like] - Links to discussionboard_user. Required for event attribution. Enforces referential integrity. 3NF compliant.
  user_id String @db.Uuid

  /// [Liked post] - Nullable. If set, like is for a post (not a comment). 3NF by not embedding content data. Cascade on post deletion.
  post_id String? @db.Uuid

  /// [Liked comment] - Nullable. If set, like is for a comment (not a post). 3NF by only referencing atomic keys. Cascade on comment deletion.
  comment_id String? @db.Uuid

  /// [Timestamp] - When the like occurred. Atomic event time for audit and ordering. 3NF compliant field.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  user discussionboard_user @relation(fields: [user_id], references: [id], onDelete: Cascade)
  post discussionboard_post? @relation(fields: [post_id], references: [id], onDelete: Cascade)
  comment discussionboard_comment? @relation(fields: [comment_id], references: [id], onDelete: Cascade)

  @@unique([user_id, post_id])
  @@unique([user_id, comment_id])
  @@index([post_id, created_at])
  @@index([comment_id, created_at])
}

/// [Bookmark tracking] - Implements the user bookmark feature (saving posts for later) per requirements. Each row represents one user's bookmark event for a post, strictly normalized (3NF). Enables restoring/postordering user bookmarks and cleaning up after deletion. No precomputed/cached fields. User and post references only. Enforces uniqueness for each user/post pair.
///
/// @namespace Interactions
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_bookmark {
  //----
  // COLUMNS
  //----
  /// [Bookmark record identifier] - Enables event tracking, deletion, and compliance with normalization (3NF). Required, unique per row.
  id String @id @db.Uuid

  /// [Bookmarking user] - References discussionboard_user. Strict referential integrity and event attribution.
  user_id String @db.Uuid

  /// [Bookmarked post] - References discussionboard_post, maintains strict atomic linkage to content.
  post_id String @db.Uuid

  /// [Timestamp] - When the bookmark was made. Used for ordering, cleanup, and audit history. 3NF, non-derived.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  user discussionboard_user @relation(fields: [user_id], references: [id], onDelete: Cascade)
  post discussionboard_post @relation(fields: [post_id], references: [id], onDelete: Cascade)

  @@index([post_id])

  @@unique([user_id, post_id])
  @@index([created_at])
}

/// [Follow relationship] - Implements the 'follow' user journey, supporting both user follows and thread follows. Each row is a distinct atomic follow event (3NF/strict normalization). Users can follow either another user or a thread, never both in the same row. Used for notification triggers, engagement analytics, and checking mutual follows. Deleting a followed target removes related follows (cascade).
///
/// @namespace Interactions
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_follow {
  //----
  // COLUMNS
  //----
  /// [Follow record identifier] - Unique ID for follow event, enables audit and normalized join operations.
  id String @id @db.Uuid

  /// [User who follows] - Required. Links to discussionboard_user. Reference for engagement & notification triggers.
  follower_user_id String @db.Uuid

  /// [User being followed] - Nullable. Set if the target is another user, null if thread.
  followed_user_id String? @db.Uuid

  /// [Thread being followed] - Nullable. Set if the user follows a thread, null if target is user.
  followed_thread_id String? @db.Uuid

  /// [Timestamp] - When the follow was created. Used for UI order and engagement analytics.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  follower discussionboard_user @relation("discussionboard_follow_of_follower_user_id", fields: [follower_user_id], references: [id], onDelete: Cascade)
  followed_user discussionboard_user? @relation("discussionboard_follow_of_followed_user_id", fields: [followed_user_id], references: [id], onDelete: Cascade)
  followed_thread discussionboard_thread? @relation(fields: [followed_thread_id], references: [id], onDelete: Cascade)

  @@index([followed_user_id])
  @@index([followed_thread_id])

  @@unique([follower_user_id, followed_user_id])
  @@unique([follower_user_id, followed_thread_id])
  @@index([created_at])
}

/// [Report tracking] - Implements the content report feature. Each row is a normalized user report of a post or comment (audit, moderation, and workflow purposes). User can report only one (post or comment) per event. Enforces uniqueness per target per user. Used for showing if a report is already filed and for moderator workflow queues. 3NF, no aggregation/calculation.
///
/// @namespace Interactions
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_report {
  //----
  // COLUMNS
  //----
  /// [Report identifier] - Unique ID for event logging and audit. Normalization: atomic and primary for 1NF/3NF.
  id String @id @db.Uuid

  /// [Reporting user] - Required. Who created the report. Referential integrity for moderation/journey tracing.
  reporting_user_id String @db.Uuid

  /// [Reported post] - Nullable. Set if reporting a post. Cascade on post deletion. 3NF compliance by key-only.
  post_id String? @db.Uuid

  /// [Reported comment] - Nullable. Set if reporting a comment, cascade on deletion. 3NF by key-only linkage.
  comment_id String? @db.Uuid

  /// [Report reason] - Atomic text (3NF), records what the user stated. No summary/aggregate. Supports moderation audit and workflow.
  reason String

  /// [Current report status] - Workflow indicator (e.g., 'pending', 'reviewed'). 3NF: atomic, not derived.
  status String

  /// [Timestamp] - When report filed. For recency, audit, and moderator queue ordering. Not derived.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  reporting_user discussionboard_user @relation(fields: [reporting_user_id], references: [id], onDelete: Cascade)
  post discussionboard_post? @relation(fields: [post_id], references: [id], onDelete: Cascade)
  comment discussionboard_comment? @relation(fields: [comment_id], references: [id], onDelete: Cascade)

  discussionboard_report_history discussionboard_report_history[]
  discussionboard_moderation_action discussionboard_moderation_action[]
  discussionboard_notification discussionboard_notification[]

  @@index([post_id])
  @@index([comment_id])

  @@unique([reporting_user_id, post_id])
  @@unique([reporting_user_id, comment_id])
  @@index([status, created_at])
  @@index([reason(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [Report action history] - Implements detailed action trails for each moderator/admin action on a report. Strictly normalized, records only who, what, when, and which report. Supports appeals, auditing, and transparency per requirements. Each row: one action per event, never precomputed or summarized. Used for report resolution chronology, not for dashboard summary (done in views only).
///
/// @namespace Interactions
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_report_history {
  //----
  // COLUMNS
  //----
  /// [Action record identifier] - Atomic, primary (1NF/3NF), tracks every moderation/admin workflow event attached to a report.
  id String @id @db.Uuid

  /// [Target report] - Required linkage for all actions. Cascade on report deletion. 3NF atomic foreign key.
  report_id String @db.Uuid

  /// [Moderator handling action] - Nullable link to moderator, if not admin. Key for authority audit trail. 3NF: atomic link only.
  moderator_id String? @db.Uuid

  /// [Admin handling action] - Nullable link to admin, if not moderator. Key for audit trail. 3NF: atomic.
  admin_id String? @db.Uuid

  /// [Workflow action type] - Atomic string (e.g., 'acknowledged', 'banned user') for audit. No derivations, strictly event-based.
  action String

  /// [Context/Note] - Moderator/admin input. Used for appeals and audit. Atomic by event. Not aggregated.
  action_detail String

  /// [Timestamp] - When action taken, atomic. Used for audit chronology and analytics. 3NF rule: not derived.
  acted_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  report discussionboard_report @relation(fields: [report_id], references: [id], onDelete: Cascade)
  moderator discussionboard_moderator? @relation(fields: [moderator_id], references: [id], onDelete: Cascade)
  admin discussionboard_admin? @relation(fields: [admin_id], references: [id], onDelete: Cascade)

  @@index([report_id, acted_at])
  @@index([moderator_id, acted_at])
  @@index([admin_id, acted_at])
}

schemas.schema-05-moderation.prisma:
/// Moderation Actions - This implements the moderation action tracking requirement from the Functional Requirements and Business Rules documents, specifically for documenting all interventions by moderators or admins.
///
/// Records every moderation event (edit, hide, delete, warn, ban, restore, etc.) performed on posts, comments, or user accounts to ensure a complete audit trail. Maintains 3NF compliance by splitting the core action event from any additional notes or ban details (captured in related tables). For example, each time a moderator deletes or edits a post, an action is recorded here.
///
/// Key relationships: Links to the acting moderator/admin, the target user (if applicable), the affected post/comment, and the report triggering this action (if present).
/// Special behaviors: Enforces normalized structure; only atomic, non-derived data allowed. Relies on foreign keys for relating to users, posts, comments, and reports. No duplication of action details; rich detail via relation tables.
///
/// @namespace Moderation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_moderation_action {
  //----
  // COLUMNS
  //----
  /// Primary key - Unique identifier for each moderation action record. Implements uniqueness and normalized referencing as required by 3NF. For example, used to retrieve or cross-reference specific moderation activities.
  id String @id @db.Uuid

  /// Actor Moderator/Admin - References the user (moderator/admin) performing the action. Implements responsibility traceability requirement from moderation rules. Ensures normalized, non-redundant representation with atomic foreign key. For example, used to determine which moderator enforced a ban or edited a post.
  actor_moderator_id String @db.Uuid

  /// Target User - References the user affected by this moderation action, if applicable (e.g., ban, warning). Implements business auditability and precise incident mapping. Nullable because not all actions target a user (e.g., post deletion may not specify a user directly).
  target_user_id String? @db.Uuid

  /// Affected Post - Optionally links to the post affected by this moderation action. Implements requirement for direct content-moderation tracking. Nullable as not all actions affect posts (could affect comments or users only).
  post_id String? @db.Uuid

  /// Affected Comment - Optionally links to the comment affected by the moderation action. Ensures content-level traceability. Nullable since some actions may not involve comments.
  comment_id String? @db.Uuid

  /// Linked Report - Optionally associates this action with a triggering user report. Fulfills requirement for moderation workflow traceability. Nullable if the action was not prompted by a report (e.g., proactive moderation).
  report_id String? @db.Uuid

  /// Type of Moderation Action - Implements the audit logging requirement. Business meaning: which kind of moderation was done (e.g., 'edit', 'delete', 'warn', 'ban', 'restore'). Ensures normalization by storing a single action type per event. For example, 'ban' when a user is banned.
  action_type String

  /// Moderation Reason/Note - Documents the reason for this moderation action. Implements the business traceability requirement from reporting and audit logging rules. Ensures normalization by keeping rationale separate from user and content records. For example, 'Spam detected' or 'Offensive language'.
  action_reason String

  /// Moderation Action Timestamp - Records when the moderation action was performed. Implements audit logging and recovery requirement. Maintains normalization as every action gets a single timestamp.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  actor_moderator discussionboard_user @relation("discussionboard_moderation_action_of_actor_moderator_id", fields: [actor_moderator_id], references: [id], onDelete: Cascade)
  target_user discussionboard_user? @relation("discussionboard_moderation_action_of_target_user_id", fields: [target_user_id], references: [id], onDelete: Cascade)
  post discussionboard_post? @relation(fields: [post_id], references: [id], onDelete: Cascade)
  comment discussionboard_comment? @relation(fields: [comment_id], references: [id], onDelete: Cascade)
  report discussionboard_report? @relation(fields: [report_id], references: [id], onDelete: Cascade)

  discussionboard_ban discussionboard_ban?
  discussionboard_moderator_note discussionboard_moderator_note[]

  @@index([post_id])
  @@index([comment_id])
  @@index([report_id])

  @@unique([actor_moderator_id, created_at, action_type])
  @@index([target_user_id, action_type])
}

/// User Ban Records - Implements the ban/timeout handling requirements from the Moderation Features and Business Rules. 
///
/// Maintains a normalized, atomic record of each user ban, with duration, moderator, and reasons stored independently for robust traceability. Strictly normalized (3NF), all ban details are atomic, with external links to users and the moderating actor. Example: each time a user is banned (temporary or permanent), a distinct record captures specifics.
///
/// Key relationships: Links to the affected user, imposing moderator/admin, and the associated moderation action (for logic traceability).
/// Special behaviors: Prohibits redundancy; if ban is lifted/restored, a separate moderation action is created and linked in the action table.
///
/// @namespace Moderation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_ban {
  //----
  // COLUMNS
  //----
  /// Primary key - Unique identifier for the ban record. Required for normalized, referenceable ban tracking.
  id String @id @db.Uuid

  /// Banned User - Reference to the user being banned. Implements business rule for precise accountability. Atomic, normalized field. For example, used to display active bans for a user.
  user_id String @db.Uuid

  /// Imposing Moderator/Admin - Reference to the moderator/admin that imposed the ban. Implements responsibility traceability. Normalized, non-redundant. For example, used in reporting patterns in moderation activity.
  moderator_id String @db.Uuid

  /// Related Moderation Action - Links this ban to the underlying moderation action that initiated it. Fulfills normalized structure and audit trail requirements. For example, cross-references why and how the ban was imposed.
  moderation_action_id String @db.Uuid

  /// Ban Start Timestamp - When the ban/timeout begins. Implements requirement for precise timing. Maintains normalization by only representing the atomic start date/time.
  start_at DateTime @db.Timestamptz

  /// Ban End Timestamp - When the ban/timeout ends (nullable for permanent bans). Implements normalized design by allowing indefinite bans (null end date). For example, set to null for permanent bans.
  end_at DateTime? @db.Timestamptz

  /// Ban Reason - Human-readable reason for ban. Implements auditability requirement. Normalized, atomic field. Example: 'Repeated rule violation'.
  ban_reason String

  //----
  // RELATIONS
  //----
  user discussionboard_user @relation("discussionboard_ban_of_user_id", fields: [user_id], references: [id], onDelete: Cascade)
  moderator discussionboard_user @relation("discussionboard_ban_of_moderator_id", fields: [moderator_id], references: [id], onDelete: Cascade)
  moderation_action discussionboard_moderation_action @relation(fields: [moderation_action_id], references: [id], onDelete: Cascade)

  @@unique([user_id, start_at])
  @@unique([moderation_action_id])
  @@index([moderator_id])
}

/// Moderator System Notes - Implements the system-logged note-taking requirements from the Moderation Features section in Functional Requirements and Business Rules.
///
/// Maintains atomic, normalized moderator notes about specific actions, users, or incidents for future reference or compliance. Each note is linked to its author (moderator/admin) and can be associated with any related moderation action or user, upholding 3NF by splitting extra narrative/context data from core event/action records. Example: a moderator leaves an internal explanation for why a complex decision was made.
///
/// Key relationships: Links to the authoring moderator, optionally to a user or moderation action. Can be used for system auditing or internal collaboration.
/// Special behaviors: Multiple notes per action/user permitted. Cannot directly trigger external changes, only stores commentary or rationale.
///
/// @namespace Moderation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_moderator_note {
  //----
  // COLUMNS
  //----
  /// Primary key - Unique note identifier. Implements normalized storage per note instance.
  id String @id @db.Uuid

  /// Author Moderator/Admin - The user (moderator/admin) writing the note.  Implements traceability and accountability requirements. For example, used in reports to show note authorship.
  author_id String @db.Uuid

  /// Related Moderation Action - Optionally links a note to a specific moderation action (if applicable). Implements auditability and contextual requirements for notes about actions. Nullable, as not all notes relate to a particular action.
  related_action_id String? @db.Uuid

  /// Target User - Optionally links a note to a particular user (e.g., as rationale for ongoing watchlist status). Implements traceability for user-centric notes. Nullable; note can be general or related to action only.
  target_user_id String? @db.Uuid

  /// Note Body - The content of the system note. Implements audit/compliance requirements and internal communication needs. Maintains atomic, normalized storage per note instance. For example, describes decision rationale.
  note_body String

  /// Creation Timestamp - When the note was authored. Implements audit/trace requirements. Normalized since each note has exactly one creation timestamp.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  author discussionboard_user @relation("discussionboard_moderator_note_of_author_id", fields: [author_id], references: [id], onDelete: Cascade)
  related_action discussionboard_moderation_action? @relation(fields: [related_action_id], references: [id], onDelete: Cascade)
  target_user discussionboard_user? @relation("discussionboard_moderator_note_of_target_user_id", fields: [target_user_id], references: [id], onDelete: Cascade)

  @@index([related_action_id])

  @@index([author_id, created_at])
  @@index([target_user_id])
}

schemas.schema-06-notifications.prisma:
/// [Notification record] - This implements the user notification delivery requirement from the functional requirements (Section 7, Notifications & User Engagement).
///
/// Stores individual notification events delivered or pending for users. Each row records a specific notification destined for a user, including what triggered it (reply, like, mention, report resolution), the related entities (such as post/comment/report), and the unread/read status. This supports granular alert delivery and tracking.
///
/// Maintains 3NF compliance by:
/// - Referencing related entities via foreign keys only (no denormalized summary fields)
/// - All notification metadata is atomic (type, status, timestamps, actor)
///
/// For example, a user receives a notification when someone replies to their post. This record contains which user, which post, what type of event, and whether it was read.
///
/// Key relationships: references user, optional links to post/comment/report.
/// Special behaviors: notifications are marked as read/unread; purged after retention period if needed.
///
/// @namespace Notifications
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_notification {
  //----
  // COLUMNS
  //----
  /// [Primary key] - Implements requirement for unique notification identification.
  ///
  /// Uniquely identifies this notification record in the system. Ensures normalization as every notification is atomic and unambiguous. Used for queries, updates, and deletion.
  id String @id @db.Uuid

  /// [Notification recipient] - Implements the requirement to deliver notifications to specific users.
  ///
  /// Links this notification to the recipient user. Ensures 3NF by referencing user by ID only. Used to filter notifications for a user.
  user_id String @db.Uuid

  /// [Notification actor] - Implements the requirement to specify who triggered the notification action.
  ///
  /// Optionally references the user who caused the notification (e.g., someone who replied/liked/reported). Optional for system-generated notifications.
  actor_id String? @db.Uuid

  /// [Related post] - Provides linkage to the post related to the notification, e.g., reply/like events.
  ///
  /// Referential integrity ensures 3NF and atomicity. For example, when a post is liked.
  post_id String? @db.Uuid

  /// [Related comment] - Optionally links to the comment related to the notification.
  ///
  /// Atomic linkage per notification (never multiple at once). Maintains normalization.
  comment_id String? @db.Uuid

  /// [Related report] - Optionally links this notification to a user report, such as a moderator's response.
  ///
  /// Ensures traceability for moderation workflows. Maintains normalization.
  report_id String? @db.Uuid

  /// [Notification type] - Implements requirement for type-specific notification handling.
  ///
  /// Defines what kind of notification this is (e.g., 'reply', 'like', 'mention', 'report_resolved', 'system_message'). Follows atomic value requirement for normalization. For example, 'reply' if someone replied to your post.
  notification_type String

  /// [Notification message content] - Implements requirement to inform the user in context.
  ///
  /// Stores the localized/user-facing message. 3NF ensured as all content is atomic and directly mapped to the notification.
  content String

  /// [Read status] - Implements requirement to track notification visibility for each user.
  ///
  /// Indicates whether the notification has been marked as read. Normalized per (notification, user) tuple.
  is_read Boolean

  /// [Created at] - Timestamp for when the notification was created.
  ///
  /// Provides audit and chronological sorting. Required for retention, purging, and notification order.
  created_at DateTime @db.Timestamptz

  /// [Read at timestamp] - When the user marked this notification as read.
  ///
  /// Null until user reads notification. Enables analytics and notification clearing.
  read_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  user_discussionboard_notification discussionboard_user @relation("discussionboard_notification_of_user_id", fields: [user_id], references: [id], onDelete: Cascade)
  actor_discussionboard_notification discussionboard_user? @relation("discussionboard_notification_of_actor_id", fields: [actor_id], references: [id], onDelete: Cascade)
  post_discussionboard_notification discussionboard_post? @relation(fields: [post_id], references: [id], onDelete: Cascade)
  comment_discussionboard_notification discussionboard_comment? @relation(fields: [comment_id], references: [id], onDelete: Cascade)
  report_discussionboard_notification discussionboard_report? @relation(fields: [report_id], references: [id], onDelete: Cascade)

  @@index([actor_id])
  @@index([post_id])
  @@index([comment_id])
  @@index([report_id])

  @@unique([user_id, notification_type, post_id, comment_id, report_id])
  @@index([user_id, created_at])
  @@index([user_id, is_read])
  @@index([content(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [Notification preference] - Implements the requirement for user-configurable notification settings from Section 7 (Notification system).
///
/// Stores each user's preference on which types of notifications they want to receive and how (real-time, email, etc). One row per user per notification type. This allows granular opt-in/out and supports both web and email notification channels.
///
/// Maintains 3NF compliance:
/// - Each setting record is atomic: (user, type, channel)
/// - No redundant/precalculated data
///
/// Example: User disables email notifications for likes, keeps web notifications for replies.
///
/// Key relationships: links to user, each notification type is discrete.
/// Special behaviors: critical system notifications may not be opt-out; enforced in application logic.
///
/// @namespace Notifications
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_notification_setting {
  //----
  // COLUMNS
  //----
  /// [Primary key] - Implements unique identification of each notification setting.
  ///
  /// Atomic identifier for updating/deleting settings efficiently.
  id String @id @db.Uuid

  /// [Setting owner] - Links to user who owns this notification preference.
  ///
  /// Maintains 3NF by referencing only user ID.
  user_id String @db.Uuid

  /// [Notification type] - Specifies which type this setting applies to (e.g., 'reply', 'like', etc).
  ///
  /// Atomic and fully normalized. Enforces specific per-type setting.
  notification_type String

  /// [Notification channel] - Defines the delivery method for this setting (e.g., 'web', 'email', 'sms').
  ///
  /// Each setting only covers one channel. Maintains normalized design.
  channel String

  /// [Enable/disable] - Toggles this notification type per channel for the user.
  ///
  /// No transitive dependency: True or false for this row only.
  /// Example: Disables email notifications for likes.
  is_enabled Boolean

  //----
  // RELATIONS
  //----
  user_discussionboard_notification_setting discussionboard_user @relation(fields: [user_id], references: [id], onDelete: Cascade)

  @@unique([user_id, notification_type, channel])
  @@index([user_id, notification_type])
}

schemas.schema-07-audit_logs.prisma:
/// [Audit Log Table] - This implements requirements from 02_discussionboard_functional_requirements.md (Section 10, Audit & Logging), 03_discussionboard_business_rules_and_user_journeys.md, and 04_discussionboard_user_roles_and_permissions.md relating to full system auditing. 
///
/// Records every critical action taken on the system (such as account changes, posts, moderation, bans, settings changes, etc.) for traceability and compliance. Maintains 3NF compliance by only storing atomic data for each log event, referencing users and actors as foreign keys without aggregation or summary fields. For example, used when an admin deletes a post or a moderator issues a ban—each such action creates a discrete log entry with timestamp, actor, and related object/user references.
///
/// Key relationships: references users (actors), and potentially affected entities (by uuid). Links to event types and device/session info for forensic investigation.
/// Special behaviors: Immutable once created—no update allowed; only appended and, optionally, soft deleted via deleted_at.
///
/// @namespace AuditLogs
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_audit_log {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - Implements unique audit log identification. Ensures each entry is uniquely identifiable and supports normalization by not repeating log information elsewhere.
  id String @id @db.Uuid

  /// [Action Performer] - Links to discussionboard_user. Captures which user (including moderator/admin) performed the audited action. Ensures normalization by referencing actors by ID, not duplicating profile data. For example, when a moderator bans a user, their actor_id is stored here.
  actor_id String @db.Uuid

  /// [Action Type] - Describes the performed action such as 'delete_post', 'ban_user', 'edit_thread', 'change_settings', etc., directly mapping to system business rules. Normalized as atomic string for each event instance. Not a foreign key; main for filtering and search.
  action String

  /// [Target Entity Type] - Indicates type of the entity affected (e.g., 'post', 'user', 'thread', 'comment', 'setting'). Maintains atomic textual data for normalization (no repeated structure).
  target_type String

  /// [Target Entity ID] - Optional. References affected entity's id (such as post, user, or comment). Nullable if not applicable. Not a foreign key for normalization; just to identify the affected object generically.
  target_id String? @db.Uuid

  /// [Extended Metadata] - Optional JSON-encoded string for arbitrary detail, e.g., old_value, new_value, IP address. Remains atomic/normalized as single field—no denormalization.
  metadata String?

  /// [Timestamp] - When the audited action occurred. Provides temporal context, supports querying, and maintains 3NF compliance.
  created_at DateTime @db.Timestamptz

  /// [Soft Delete Timestamp] - Optional. When present, marks entry as deleted but physically retained, satisfying business retention policy requirements.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  actor discussionboard_user @relation(fields: [actor_id], references: [id], onDelete: Cascade)

  @@index([actor_id, created_at])
  @@index([action, target_type])
  @@index([metadata(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [System Event Log] - Implements audit, analytics, and system monitoring requirements from 02_discussionboard_functional_requirements.md (Section 10), supporting platform diagnostics. 
///
/// Captures key events not directly tied to user-initiated actions—such as automated job completion, system errors, scheduled cleanups, and background workflow triggers. Maintains full normalization by using discrete, non-overlapping fields and not aggregating or summarizing outcomes. For example, logs a routine backup, failed job, or batch archival event.
///
/// Key relationships: not typically directly foreign-keyed to users but records context such as event type, status, and timing.
/// Special behaviors: Read-only after creation; soft deletion allowed for retention management.
///
/// @namespace AuditLogs
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_system_event {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - Unique identifier for system event log entry, ensuring 3NF and auditability.
  id String @id @db.Uuid

  /// [Event Type] - Category of system event (e.g. 'backup', 'error', 'prune', 'stats_flush'). Stores normalized event code string.
  event_type String

  /// [Status] - State of the event: e.g., 'success', 'error', 'pending'. Normalized string field—no repeated meanings.
  event_status String

  /// [Details] - Optional. JSON-encoded extra context such as error messages, job metadata. Maintains normalization as atomic blob.
  details String?

  /// [Occurrence Time] - When the event was logged. Maintains normalization and supports time range analytics.
  created_at DateTime @db.Timestamptz

  /// [Soft Delete Timestamp] - Optional. When set, indicates removal from system queries but kept for retention requirements.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@index([event_type, created_at])
  @@index([details(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-08-utility.prisma:
/// [Discussion Board Setting] - This implements configuration management requirements, as evidenced in the requirements document (see "Board & Topic Configuration", "Functional Requirements" section, and referenced in "Admin account management").
///
/// Business explanation: Represents configurable settings applicable to the platform or to specific boards, such as features toggles, text limits, moderation rules, or security options. Maintains 3NF compliance by separating atomic configuration options from boards or user roles, allowing settings to evolve without redundancy. For example, an admin can adjust allowed image upload size or enable/disable guest comments for all or particular boards.
///
/// Key relationships: Possible future relation to discussionboard_board (via board_id) for board-scoped settings. Current settings can be global (no board) or board-specific.
/// Special behaviors: Unique constraint for (board_id, key) to avoid duplicate keys per board. Settings are not deleted but soft-deleted for audit trails.
///
/// @namespace Utility
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_setting {
  //----
  // COLUMNS
  //----
  /// [Unique identifier for board setting] - Implements the identification requirement for each setting entry. Ensures normalization by serving as the sole PK. For example, referenced for audit logging and updates.
  id String @id @db.Uuid

  /// [Optional board association] - Implements granularity of settings per board. Nullable; null indicates a global (platform-wide) setting. For example, if board_id set, restricts this setting's effect to that board.
  board_id String? @db.Uuid

  /// [Setting key] - Implements key-value settings, e.g., 'max_post_length', 'allow_guests'. Ensures normalization by having atomic keys. For example, referenced by system to look up value for 'image_upload_size'.
  key String

  /// [Setting value] - The value of the setting, stored as a string for uniformity. Ensures normalization by keeping data atomic and allowing flexible, typed interpretation in code. For example, 'true', '5000', '20MB'.
  value String

  /// [Setting description] - Describes the purpose of this setting. Ensures clarity and normalization (no denormalized context). For example, 'Maximum allowed characters in a post'.
  description String?

  /// [Creation timestamp] - Implements audit trail requirement. Ensures normalized audit logging. For example, to trace when setting was added.
  created_at DateTime @db.Timestamptz

  /// [Last modification timestamp] - For audit/logging, when setting was last changed. 3NF-compliant as no calculated content. For example, system checks for setting changes.
  updated_at DateTime @db.Timestamptz

  /// [Soft deletion timestamp] - For logical deletion, implementing audit, not physical removal. 3NF-compliant (atomic). For example, admins may undelete settings.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  board discussionboard_board? @relation(fields: [board_id], references: [id], onDelete: Cascade)

  @@unique([board_id, key])
  @@index([key])
}

/// [Tag Management] - This implements tagging and topic-classification requirements from the requirements document (referenced in 'Search & Navigation', 'Thread & Post Management').
///
/// Business explanation: Represents tags available for posts/threads, enabling categorization for searching and filtering. Maintains 3NF by representing each tag as an atomic entity. For example, when users add a 'macroeconomics' tag to a thread to make it discoverable for others interested in the topic.
///
/// Key relationships: May be assigned to posts, threads, or topics (via associative/junction tables elsewhere).
/// Special behaviors: Enforces case-insensitive uniqueness; tags can be enabled/disabled (soft-delete pattern, not removed for audit).
///
/// @namespace Utility
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_tag {
  //----
  // COLUMNS
  //----
  /// [Unique identifier for tag] - Implements identity for each tag. Required for normalization and reference by post/tag relations. For example, audit logs can reference this ID.
  id String @id @db.Uuid

  /// [Display name of tag] - Implements tag search and assignment. Ensures atomic value; 3NF compliance. For example, 'macroeconomics', 'election-2025'.
  name String

  /// [Display color(hex)] - Customization for user interface, 3NF ensured. For example, '#FF0000' for a 'hot topic' tag.
  color String?

  /// [Tag description] - Optional, clarifies tag use. Ensures atomic, 3NF. For example, 'General discussions on monetary policy.'
  description String?

  /// [Active flag] - Whether tag is assignable. Implements tag management rules. Ensures atomicity. For example, disables tag from user assignment without deletion.
  enabled Boolean

  /// [Creation timestamp] - Fulfills audit/logging requirements. 3NF compliant; not calculated. For example, admins filter tags by creation date.
  created_at DateTime @db.Timestamptz

  /// [Last update timestamp] - For tag updates/audit trail. Not denormalized. For example, tag renaming is tracked.
  updated_at DateTime @db.Timestamptz

  /// [Soft deletion timestamp] - Supports undelete/soft-delete. Ensures normalization. For example, disable tag, keep history.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([name])
  @@index([enabled])
}

/// [Discussion Board Search Index] - Implements the advanced/keyword search requirements ('Search & Navigation', 'Functional Requirements').
///
/// Business explanation: Caches/facilitates full-text and fuzzy search for posts/threads/comments/tags in a performant manner. Maintains 3NF by storing only normalized references and atomic fields; NO cached, denormalized or precomputed data (summary views to be handled by materialized views only). For example, this powers quick retrieval when user searches 'fiscal stimulus' or 'climate policy'.
///
/// Key relationships: References source type and source id (e.g., post, comment, thread); implemented as generic index for extensibility.
/// Special behaviors: Indexed string for text search, with GIN/trigram index for fuzzy matching. No summary or statistics, just reference and plain content.
///
/// @namespace Utility
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_search_index {
  //----
  // COLUMNS
  //----
  /// [Unique search index entry ID] - Implements PK/identity for each search index. Enables normalization and reference tracing. For example, needed for maintenance/audit log.
  id String @id @db.Uuid

  /// [Indexed source type] - Implements extensibility (e.g., 'post','thread','comment','tag'). Ensures all index entries refer to atomic entity type. For example, enables post- and thread-specific searches.
  source_type String

  /// [Referenced entity ID] - FK to the indexed entity. 3NF-compliant; atomic reference. For example, ties to post/thread being indexed.
  source_id String @db.Uuid

  /// [Indexed content] - Implements full-text search storage. Atomic per 3NF. For example, stores plain text from posts/comments for searching.
  indexed_text String

  /// [Index creation timestamp] - For maintenance, audit logging, and search freshness. 3NF-compliant; not calculated. For example, enables purging stale entries.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@index([source_type, source_id])
  @@index([indexed_text(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.main.prisma:
generator client {
  provider        = "prisma-client-js"
  previewFeatures = ["postgresqlExtensions", "views"]
  binaryTargets   = ["native"]
}
datasource db {
  provider   = "postgresql"
  url        = env("DATABASE_URL")
  extensions = []
}
generator markdown {
  provider = "prisma-markdown"
