import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoard";
import type { IBoardArchive } from "@ORGANIZATION/PROJECT-api/lib/structures/IBoardArchive";
import type { IPageIBoardArchive } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIBoardArchive";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate listing board archive snapshots with advanced filtering, pagination, and error handling, as invoked by an admin.
 *
 * This test sequence ensures that the endpoint PATCH /discussionboard/boards/archives:
 *  - Properly returns all created archive snapshots with no filters
 *  - Accurately supports filtering by board_id, archived_by_user_id, and archived_at
 *  - Enforces pagination mechanics (limit, page, and meta-information)
 *  - Returns a 400 error for invalid UUID filter values
 *  - Yields an empty data set with valid pagination when filters match nothing
 *
 * Steps:
 * 1. Create a new discussion board (required for creating archive snapshots)
 * 2. Create multiple board archive snapshots for the board, varying timestamps and archiver user ids
 * 3. Query all archives with no filters - expect all created to appear
 * 4. Query filtering by board_id - expect only this board's archives
 * 5. Query filtering by archived_by_user_id - expect only relevant archives
 * 6. Query filtering by archived_at - expect only matching archive
 * 7. Query with pagination and confirm paging meta/data consistency
 * 8. Query with invalid board_id (not uuid) - expect error 400
 * 9. Query with unmatched board_id - expect zero items, but valid pagination meta
 */
export async function test_api_discussionboard_test_list_board_archives_with_filters_and_pagination_as_admin(connection: api.IConnection) {
  // 1. Create a discussion board
  const newBoard = await api.functional.discussionboard.boards.post(connection, {
    body: {
      name: RandomGenerator.paragraph()(),
      slug: RandomGenerator.alphabets(10),
      description: RandomGenerator.paragraph()(),
    } satisfies IDiscussionboardBoard.ICreate,
  });
  typia.assert(newBoard);

  // 2. Create several board archive snapshots at different times and by possibly different users
  const adminUserIds = [
    typia.random<string & tags.Format<'uuid'>>(),
    typia.random<string & tags.Format<'uuid'>>(),
  ];
  const archiveTimestamps = [
    new Date(Date.now() - 1000 * 60 * 60 * 24 * 2).toISOString(),
    new Date(Date.now() - 1000 * 60 * 60 * 24).toISOString(),
    new Date().toISOString(),
  ];
  const archiveSnapshots = [];
  for (let i = 0; i < 3; ++i) {
    const createdArchive = await api.functional.discussionboard.boards.archives.post(connection, {
      body: {
        board_id: newBoard.id,
        archived_by_user_id: adminUserIds[i % 2],
        archived_at: archiveTimestamps[i],
        name_snapshot: newBoard.name + ` (v${i+1})`,
        description_snapshot: newBoard.description,
        slug_snapshot: newBoard.slug + `-v${i+1}`,
      } satisfies IBoardArchive.ICreate,
    });
    typia.assert(createdArchive);
    archiveSnapshots.push(createdArchive);
  }

  // 3. Retrieve all archives (no filters)
  {
    const resp = await api.functional.discussionboard.boards.archives.patch(connection, {
      body: {},
    });
    typia.assert(resp);
    // Should contain all our created archives at minimum
    const createdIds = archiveSnapshots.map(a => a.id);
    TestValidator.predicate("all created archives present")(
      createdIds.every(id => resp.data.some(r => r.id === id))
    );
  }

  // 4. Filter by board_id
  {
    const resp = await api.functional.discussionboard.boards.archives.patch(connection, {
      body: {
        board_id: newBoard.id,
      },
    });
    typia.assert(resp);
    TestValidator.equals("only filtered board's archives return")(
      resp.data.map(r => r.board_id)
    )(
      resp.data.map(_ => newBoard.id)
    );
    TestValidator.predicate("all board_ids match")(
      resp.data.every(r => r.board_id === newBoard.id)
    );
  }

  // 5. Filter by archived_by_user_id (test both admin ids used)
  for (const adminId of adminUserIds) {
    const expectedIds = archiveSnapshots.filter(a => a.archived_by_user_id === adminId).map(a => a.id);
    const resp = await api.functional.discussionboard.boards.archives.patch(connection, {
      body: {
        archived_by_user_id: adminId,
      },
    });
    typia.assert(resp);
    TestValidator.predicate("archiver matches filter")(
      resp.data.every(r => r.archived_by_user_id === adminId)
    );
    TestValidator.predicate("expected archives present")(
      expectedIds.every(id => resp.data.some(r => r.id === id))
    );
  }

  // 6. Filter by archived_at (timestamp of first archive)
  {
    const filterAt = archiveSnapshots[0].archived_at;
    const resp = await api.functional.discussionboard.boards.archives.patch(connection, {
      body: {
        archived_at: filterAt,
      },
    });
    typia.assert(resp);
    TestValidator.equals("single archive for timestamp")(
      resp.data.map(r => r.id)
    )(
      archiveSnapshots.filter(r => r.archived_at === filterAt).map(r => r.id)
    );
  }

  // 7. Pagination test: limit=2, fetch at least first two pages
  {
    const allResp = await api.functional.discussionboard.boards.archives.patch(connection, {
      body: {
        limit: 2,
        page: 1,
      },
    });
    typia.assert(allResp);
    TestValidator.equals("pagination limit")(
      allResp.data.length
    )(
      Math.min(2, allResp.pagination.records)
    );
    if (allResp.pagination.pages > 1) {
      const page2Resp = await api.functional.discussionboard.boards.archives.patch(connection, {
        body: {
          limit: 2,
          page: 2,
        },
      });
      typia.assert(page2Resp);
      TestValidator.equals("pagination page number")(page2Resp.pagination.current)(2);
    }
  }

  // 8. Invalid filter (bad board_id uuid) should throw 400 error
  await TestValidator.error("invalid board_id uuid error")(() =>
    api.functional.discussionboard.boards.archives.patch(connection, {
      body: {
        board_id: "invalid-uuid-value",
      },
    })
  );

  // 9. Filter matches nothing (valid uuid not present)
  {
    const noMatchId = typia.random<string & tags.Format<'uuid'>>();
    const resp = await api.functional.discussionboard.boards.archives.patch(connection, {
      body: {
        board_id: noMatchId,
      },
    });
    typia.assert(resp);
    TestValidator.equals("zero results for non-existent id")(resp.data.length)(0);
    TestValidator.predicate("pagination meta present")(!!resp.pagination);
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { IBoardArchive } from "@ORGANIZATION/PROJECT-api/lib/structures/IBoardArchive";
import type { IPageIBoardArchive } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIBoardArchive";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Verify that non-privileged (regular) user accounts cannot access board archive listing endpoints.
 *
 * Business context:
 * - Only privileged users (moderators or admins) should be able to access the board archive list
 *   via the /discussionboard/boards/archives PATCH endpoint.
 * - This test ensures that attempts from a regular registered user result in permission denial or
 *   appropriate forbidden/error responses.
 *
 * Process:
 * 1. Register a regular (non-privileged) user for the discussion board.
 * 2. Attempt to access the board archive listing endpoint as this user.
 * 3. Verify that the endpoint throws an error (e.g., 403 Forbidden or equivalent).
 */
export async function test_api_discussionboard_test_list_board_archives_forbidden_for_non_privileged_user(
  connection: api.IConnection,
) {
  // 1. Register a regular user (non-privileged)
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userPassword = typia.random<string & tags.Format<"password">>();
  const user = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: userEmail,
      password: userPassword,
      displayName: RandomGenerator.name(),
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(user);

  // 2. Attempt to list board archives as a regular user - expecting error (permission denied)
  await TestValidator.error("board archive list forbidden for regular user")(
    async () => {
      await api.functional.discussionboard.boards.archives.patch(connection, {
        body: {},
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoard";
import type { IBoardArchive } from "@ORGANIZATION/PROJECT-api/lib/structures/IBoardArchive";

/**
 * Validate retrieval of board archive snapshot details by archive ID, including not found edge case.
 *
 * This test ensures that a board archive snapshot, once created for a specific board, can be retrieved with all details via its unique archive ID. It also validates correct 404 error handling when attempting to retrieve a non-existent archive. Both positive and negative flows are covered for completeness and audit requirements.
 *
 * Steps:
 * 1. Create a new board as an admin/moderator using api.functional.discussionboard.boards.post.
 * 2. Create an archive snapshot for this board via api.functional.discussionboard.boards.archives.post, snapshotting the current state of the board.
 *    - Use the board's id and admin id for the archive creation payload as needed.
 * 3. Fetch the archive snapshot by its id using api.functional.discussionboard.boards.archives.getById and check that all archive details are correct and match the archive creation response.
 * 4. Attempt to fetch a board archive with a random, non-existent archive id and ensure that a 404 not found error is thrown (use TestValidator.error for this case).
 */
export async function test_api_discussionboard_test_get_board_archive_details_success_and_not_found(
  connection: api.IConnection,
) {
  // 1. Create a new board as admin/moderator
  const boardInput: IDiscussionboardBoard.ICreate = {
    name: RandomGenerator.paragraph()(),
    slug: RandomGenerator.alphaNumeric(10),
    description: RandomGenerator.content()()(),
  };
  const createdBoard = await api.functional.discussionboard.boards.post(connection, { body: boardInput });
  typia.assert(createdBoard);

  // 2. Create a board archive snapshot for this board
  const archiveInput: IBoardArchive.ICreate = {
    board_id: createdBoard.id,
    archived_by_user_id: typia.random<string & tags.Format<'uuid'>>(), // Simulates admin/moderator user
    archived_at: new Date().toISOString(),
    name_snapshot: createdBoard.name,
    description_snapshot: createdBoard.description,
    slug_snapshot: createdBoard.slug,
  };
  const archive = await api.functional.discussionboard.boards.archives.post(connection, { body: archiveInput });
  typia.assert(archive);

  // 3. Fetch the archive by its id and validate all details match exactly
  const fetchedArchive = await api.functional.discussionboard.boards.archives.getById(connection, { id: archive.id });
  typia.assert(fetchedArchive);
  TestValidator.equals("archive id")(fetchedArchive.id)(archive.id);
  TestValidator.equals("board id")(fetchedArchive.board_id)(archiveInput.board_id);
  TestValidator.equals("archived_by_user_id")(fetchedArchive.archived_by_user_id)(archiveInput.archived_by_user_id);
  TestValidator.equals("archived_at")(fetchedArchive.archived_at)(archiveInput.archived_at);
  TestValidator.equals("name_snapshot")(fetchedArchive.name_snapshot)(archiveInput.name_snapshot);
  TestValidator.equals("description_snapshot")(fetchedArchive.description_snapshot)(archiveInput.description_snapshot);
  TestValidator.equals("slug_snapshot")(fetchedArchive.slug_snapshot)(archiveInput.slug_snapshot);

  // 4. Attempt fetching with a non-existent archive id and expect a 404 error
  await TestValidator.error("not found for random archive id")(async () => {
    await api.functional.discussionboard.boards.archives.getById(connection, { id: typia.random<string & tags.Format<'uuid'>>() });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoard";
import type { IBoardArchive } from "@ORGANIZATION/PROJECT-api/lib/structures/IBoardArchive";

/**
 * Validate the creation of a board archive snapshot for audit/rollback and error handling.
 *
 * This test ensures a board snapshot (archive) can be properly created for compliance and rollback, and that the system robustly rejects invalid creation attempts.
 *
 * Steps:
 * 1. Create a valid discussion board to be archived (simulate as admin/moderator).
 * 2. Create a valid board archive snapshot referencing the board, with current metadata and archiver (admin) id and timestamp.
 * 3. Verify the archive is returned, matching all fields submitted.
 * 4. Attempt to create a board archive referencing a non-existent board—expect error.
 * 5. Attempt to omit required fields from payload—expect compilation error (not runtime testable).
 * 6. Attempt to duplicate a board archive (same board id + timestamp)—expect duplicate/concurrency error.
 * 7. For all negative cases, validate appropriate HTTP/business logic error (400/409).
 */
export async function test_api_discussionboard_test_create_board_archive_snapshot_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. Create a valid discussion board to archive
  const boardInput: IDiscussionboardBoard.ICreate = {
    name: RandomGenerator.alphabets(10),
    slug: RandomGenerator.alphaNumeric(12),
    description: RandomGenerator.paragraph()(),
  };
  const board = await api.functional.discussionboard.boards.post(connection, {
    body: boardInput,
  });
  typia.assert(board);

  // 2. Prepare valid archive snapshot input (simulate archiver as random UUID user)
  const archiveInput: IBoardArchive.ICreate = {
    board_id: board.id,
    archived_by_user_id: typia.random<string & tags.Format<"uuid">>(),
    archived_at: new Date().toISOString(),
    name_snapshot: board.name,
    description_snapshot: board.description,
    slug_snapshot: board.slug,
  };
  const archive = await api.functional.discussionboard.boards.archives.post(connection, {
    body: archiveInput,
  });
  typia.assert(archive);
  // Ensure fields match input
  TestValidator.equals("archive board")(archive.board_id)(archiveInput.board_id);
  TestValidator.equals("archiver user")(archive.archived_by_user_id)(archiveInput.archived_by_user_id);
  TestValidator.equals("archive timestamp")(archive.archived_at)(archiveInput.archived_at);
  TestValidator.equals("name")(archive.name_snapshot)(board.name);
  TestValidator.equals("desc")(archive.description_snapshot)(board.description);
  TestValidator.equals("slug")(archive.slug_snapshot)(board.slug);

  // 3. Invalid: Board reference does not exist
  const badInput1: IBoardArchive.ICreate = {
    ...archiveInput,
    board_id: typia.random<string & tags.Format<"uuid">>()
  };
  await TestValidator.error("non-existent board id")(() =>
    api.functional.discussionboard.boards.archives.post(connection, { body: badInput1 }),
  );

  // 4. Negative test for missing required field is not implemented; such tests would cause compilation errors and are omitted as per type-safe e2e policy.

  // 5. Invalid: Duplicate archive for same board/timestamp
  await TestValidator.error("duplicate archive (same board id/timestamp)")(() =>
    api.functional.discussionboard.boards.archives.post(connection, { body: archiveInput }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { IDiscussionboardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoard";
import type { IBoardArchive } from "@ORGANIZATION/PROJECT-api/lib/structures/IBoardArchive";
import type { IDiscussionboardBoardArchive } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoardArchive";

/**
 * Validate updating of a board archive snapshot and all relevant constraints.
 *
 * This test ensures:
 * - Admin/moderator can update archive snapshot fields (name, description, slug, archived_by_user_id, archived_at)
 * - Result reflects updates
 * - Update fails for invalid archived_by_user_id (non-existent or non-admin)
 * - Update fails for non-existent archive id (404)
 * - Update forbidden for non-privileged users
 *
 * Business Steps:
 * 1. Register admin user
 * 2. Register regular user
 * 3. Create a new board as admin
 * 4. Create an archive snapshot for the board as admin
 * 5. Update archive snapshot fields, check update reflected
 * 6. Attempt update with archived_by_user_id = non-admin (should fail if permissions enforced on ref)
 * 7. Attempt update with non-existent user id (should fail)
 * 8. Attempt update with non-existent archive id (should 404)
 * 9. Switch to regular user and try update, expect forbidden
 */
export async function test_api_discussionboard_test_update_board_archive_success_and_constraints(
  connection: api.IConnection,
) {
  // --- 1. Register admin (moderator) user ---
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin: IDiscussionboardUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: adminEmail,
      password: "AdminPassword123!",
      displayName: "ModeratorA",
      isActive: true
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(admin);

  // --- 2. Register regular user ---
  const userEmail = typia.random<string & tags.Format<"email">>();
  const user: IDiscussionboardUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: userEmail,
      password: "UserPassword123!",
      displayName: "RegularB",
      isActive: true
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(user);

  // --- 3. Create a new board as admin ---
  const boardSlug = RandomGenerator.alphaNumeric(10);
  const board: IDiscussionboardBoard = await api.functional.discussionboard.boards.post(connection, {
    body: {
      name: "Test Board for Archive",
      slug: boardSlug,
      description: "Discussion board for archive E2E test."
    } satisfies IDiscussionboardBoard.ICreate,
  });
  typia.assert(board);

  // --- 4. Create a board archive snapshot as admin ---
  const archive: IBoardArchive = await api.functional.discussionboard.boards.archives.post(connection, {
    body: {
      board_id: board.id,
      archived_by_user_id: admin.id,
      archived_at: new Date().toISOString(),
      name_snapshot: board.name,
      description_snapshot: board.description,
      slug_snapshot: board.slug
    } satisfies IBoardArchive.ICreate,
  });
  typia.assert(archive);

  // --- 5. Update archive snapshot fields ---
  const updatedName = board.name + " Updated";
  const updatedDescription = board.description + " [Modified.]";
  const updatedSlug = board.slug + "-upd";
  const updatedAt = new Date(Date.now() + 10000).toISOString();
  const result: IDiscussionboardBoardArchive = await api.functional.discussionboard.boards.archives.putById(connection, {
    id: archive.id,
    body: {
      name_snapshot: updatedName,
      description_snapshot: updatedDescription,
      slug_snapshot: updatedSlug,
      archived_by_user_id: admin.id,
      archived_at: updatedAt
    } satisfies IDiscussionboardBoardArchive.IUpdate,
  });
  typia.assert(result);
  TestValidator.equals("archive name updated")(result.name_snapshot)(updatedName);
  TestValidator.equals("archive description updated")(result.description_snapshot)(updatedDescription);
  TestValidator.equals("archive slug updated")(result.slug_snapshot)(updatedSlug);
  TestValidator.equals("archive archived_by_user_id updated")(result.archived_by_user_id)(admin.id);
  TestValidator.equals("archive archived_at updated")(result.archived_at)(updatedAt);

  // --- 6. Attempt update with archived_by_user_id = regular user id ---
  TestValidator.error("update should fail when archived_by_user_id is a regular, non-admin user")(
    async () => {
      await api.functional.discussionboard.boards.archives.putById(connection, {
        id: archive.id,
        body: {
          archived_by_user_id: user.id,
        } satisfies IDiscussionboardBoardArchive.IUpdate,
      });
    }
  );

  // --- 7. Attempt update with non-existent user id ---
  TestValidator.error("update should fail with non-existent user id")(
    async () => {
      await api.functional.discussionboard.boards.archives.putById(connection, {
        id: archive.id,
        body: {
          archived_by_user_id: typia.random<string & tags.Format<"uuid">>(),
        } satisfies IDiscussionboardBoardArchive.IUpdate,
      });
    }
  );

  // --- 8. Attempt update to non-existent archive id ---
  TestValidator.error("update should fail with 404 for non-existent archive id")(
    async () => {
      await api.functional.discussionboard.boards.archives.putById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
        body: {
          name_snapshot: "Dummy",
        } satisfies IDiscussionboardBoardArchive.IUpdate,
      });
    }
  );

  // --- 9. Try update as non-privileged user (regular user) ---
  // There is no explicit login API, so simulate identity by creating user and attempting as is (API may infer current connection privileges)
  // Attempt the update
  TestValidator.error("forbidden for non-privileged user attempting update")(
    async () => {
      // Optionally, if a real role switch connection was possible, set headers; here, just try as created user
      await api.functional.discussionboard.boards.archives.putById(connection, {
        id: archive.id,
        body: {
          name_snapshot: "Should Not Update",
        } satisfies IDiscussionboardBoardArchive.IUpdate,
      });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { IDiscussionboardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoard";
import type { IBoardArchive } from "@ORGANIZATION/PROJECT-api/lib/structures/IBoardArchive";

/**
 * 게시판 아카이브(스냅샷) 삭제(soft-delete) 정상 및 엣지 케이스 통합 E2E 테스트
 *
 * - 관리자(권한) 유저가 게시판과 아카이브를 생성 후 아카이브를 삭제.
 * - 이후 삭제된 id로 재삭제·비존재 id 삭제, 권한 없는 계정 삭제 등 오류 검증.
 *
 * 테스트 시나리오:
 * 1. 관리자(권한자) 계정 생성
 * 2. 게시판 생성
 * 3. 아카이브(스냅샷) 생성(관리자 권한으로)
 * 4. 관리자 권한으로 정상 삭제 수행(soft-delete)
 * 5. 삭제 후 동일 id 재삭제 시도 → 404 Not Found 등 오류 확인
 * 6. 임의의 없는 id로 삭제 시도 → 404 Not Found 오류 확인
 * 7. 비권한(일반) 유저 계정으로 삭제 시도 → 권한 오류(Forbidden 등) 확인
 *
 * (참고: 실제 권한 인증/role switching API 미정의 시 connection 컨텍스트 상태 기준)
 */
export async function test_api_discussionboard_test_delete_board_archive_success_and_edge_cases(
  connection: api.IConnection,
) {
  // 1. 관리자(권한자) 유저 계정 생성
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = typia.random<string & tags.Format<"password">>();
  const adminUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      displayName: RandomGenerator.name(),
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(adminUser);

  // 2. 게시판 생성
  const boardName = RandomGenerator.paragraph()(1);
  const boardSlug = RandomGenerator.alphaNumeric(8);
  const boardDescription = RandomGenerator.paragraph()(2);
  const board = await api.functional.discussionboard.boards.post(connection, {
    body: {
      name: boardName,
      slug: boardSlug,
      description: boardDescription,
    } satisfies IDiscussionboardBoard.ICreate,
  });
  typia.assert(board);

  // 3. 아카이브(스냅샷) 생성
  const archiveAt = new Date().toISOString();
  const boardArchive = await api.functional.discussionboard.boards.archives.post(connection, {
    body: {
      board_id: board.id,
      archived_by_user_id: adminUser.id,
      archived_at: archiveAt,
      name_snapshot: board.name,
      description_snapshot: board.description,
      slug_snapshot: board.slug,
    } satisfies IBoardArchive.ICreate,
  });
  typia.assert(boardArchive);

  // 4. 정상 삭제(soft-delete, 관리자 권한)
  await api.functional.discussionboard.boards.archives.eraseById(connection, {
    id: boardArchive.id,
  });

  // 5. 삭제된 아카이브 id로 재삭제 시도 → 404 오류
  await TestValidator.error("재삭제시 404 not found")(() =>
    api.functional.discussionboard.boards.archives.eraseById(connection, {
      id: boardArchive.id,
    }),
  );

  // 6. 존재하지 않는 랜덤 id로 삭제 시도 → 404 오류
  await TestValidator.error("존재하지 않는 id 삭제시 404")(() =>
    api.functional.discussionboard.boards.archives.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    }),
  );

  // 7. 비권한(일반) 유저 계정 생성 및 삭제 시도(권한 오류)
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userPassword = typia.random<string & tags.Format<"password">>();
  const user = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: userEmail,
      password: userPassword,
      displayName: RandomGenerator.name(),
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(user);

  // (권한 전환/role switching API 없음 가정. 일반 계정 context로 삭제 시도 처리 - 실제 인증 분리는 향후 확장)
  await TestValidator.error("비권한 유저 deleting 시 권한 오류 발생")(() =>
    api.functional.discussionboard.boards.archives.eraseById(connection, {
      id: boardArchive.id,
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardReport";
import type { IPageIDiscussionboardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardReport";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate paginated and filtered listing of discussion board reports.
 *
 * This test covers listing with various filters (status, target type, reporting user, creation date). It ensures correct pagination metadata and business logic. Error scenarios are checked for invalid filters and pagination. Role-based access or cross-user checks are omitted due to the lack of relevant user/role-switching APIs and are documented in comments below.
 *
 * 1. Seed the system with diverse reports (different users, statuses, target types).
 * 2. Query with filters and pagination, validate expected records and meta.
 * 3. Attempt invalid queries and expect 400 errors.
 * 4. Check empty queries yield correct empty results and metadata.
 * 5. Role/permission tests skipped (cannot switch users/roles).
 */
export async function test_api_discussionboard_test_list_reports_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Seed system with a variety of reports for robust filter/pagination validity
  const report1 = await api.functional.discussionboard.reports.post(connection, { body: { post_id: typia.random<string & tags.Format<"uuid">>(), comment_id: null, reason: "spam", status: "pending", } });
  typia.assert(report1);
  const report2 = await api.functional.discussionboard.reports.post(connection, { body: { post_id: null, comment_id: typia.random<string & tags.Format<"uuid">>(), reason: "abuse", status: "reviewed", } });
  typia.assert(report2);
  const report3 = await api.functional.discussionboard.reports.post(connection, { body: { post_id: typia.random<string & tags.Format<"uuid">>(), comment_id: null, reason: "duplicate", status: "pending", } });
  typia.assert(report3);

  // Additionally mutate status for diversity
  const updatedReport2 = await api.functional.discussionboard.reports.putById(connection, {
    id: report2.id, body: { status: "resolved" }
  });
  typia.assert(updatedReport2);

  // 2. Query: filter by status, post_id, reporter, reason, with pagination
  {
    const page1 = await api.functional.discussionboard.reports.patch(connection, {
      body: {
        status: "pending",
        post_id: report1.post_id,
        page: 1,
        limit: 2,
      }
    });
    typia.assert(page1);
    TestValidator.predicate("Has correct report(s) with pending status")(
      page1.data.every((r) => r.status === "pending" && r.post_id === report1.post_id)
    );
    TestValidator.equals("pagination limit")(page1.pagination.limit)(2);
  }
  {
    const page2 = await api.functional.discussionboard.reports.patch(connection, {
      body: {
        status: "resolved",
        comment_id: report2.comment_id,
        page: 1,
        limit: 1,
      }
    });
    typia.assert(page2);
    TestValidator.predicate("Has only resolved status reports for given comment")(
      page2.data.every((r) => r.status === "resolved" && r.comment_id === report2.comment_id)
    );
    TestValidator.equals("pagination limit")(page2.pagination.limit)(1);
    TestValidator.predicate("records <= limit")(page2.data.length <= 1);
  }
  {
    // Filter by reporting_user_id
    const page3 = await api.functional.discussionboard.reports.patch(connection, {
      body: {
        reporting_user_id: report1.reporting_user_id,
        page: 1,
        limit: 10,
      }
    });
    typia.assert(page3);
    TestValidator.predicate("Only reports by reporter 1")(
      page3.data.every((r) => r.reporting_user_id === report1.reporting_user_id)
    );
  }
  {
    // Filter by created_from and created_to (date range test)
    const createdFrom = report3.created_at;
    const createdTo = report3.created_at;
    const page4 = await api.functional.discussionboard.reports.patch(connection, {
      body: {
        created_from: createdFrom,
        created_to: createdTo,
        page: 1,
        limit: 10,
      },
    });
    typia.assert(page4);
    TestValidator.predicate("Date filter range hits reports")(
      page4.data.every((r) => r.created_at >= createdFrom && r.created_at <= createdTo)
    );
  }
  {
    // Filter by reason full text
    const page5 = await api.functional.discussionboard.reports.patch(connection, {
      body: {
        reason: "duplicate",
        page: 1,
        limit: 5,
      },
    });
    typia.assert(page5);
    TestValidator.predicate("Correct reason filter")(
      page5.data.every((r) => typeof r.reason === "string" && r.reason.includes("duplicate"))
    );
  }

  // 3. Invalid filter fields (expect error)
  await TestValidator.error("Invalid status filter throws")(() =>
    api.functional.discussionboard.reports.patch(connection, {
      body: {
        status: "not-a-real-status",
        page: 1,
        limit: 1,
      },
    })
  );

  await TestValidator.error("Negative limit throws")(() =>
    api.functional.discussionboard.reports.patch(connection, {
      body: {
        limit: -5,
        page: 1,
      },
    })
  );

  await TestValidator.error("Excessively high page throws")(() =>
    api.functional.discussionboard.reports.patch(connection, {
      body: {
        page: 100000,
        limit: 1,
      },
    })
  );

  // 4. No results found (empty list, correct meta)
  {
    const emptyRes = await api.functional.discussionboard.reports.patch(connection, {
      body: {
        status: "pending",
        post_id: typia.random<string & tags.Format<"uuid">>(), // random, won't match seed
        page: 1,
        limit: 1,
      },
    });
    typia.assert(emptyRes);
    TestValidator.equals("empty result")(emptyRes.data.length)(0);
    TestValidator.predicate("pagination meta still present")(
      typeof emptyRes.pagination.current === "number" &&
        typeof emptyRes.pagination.pages === "number" &&
        typeof emptyRes.pagination.limit === "number" &&
        typeof emptyRes.pagination.records === "number"
    );
  }

  // 5. Role/permission tests omitted - cannot simulate different users or roles due to API limits.
}

