import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IDiscussionboardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardReport";

/**
 * Test creating a new report for both a post and a comment on the discussion board.
 *
 * Steps and validations:
 * 1. Authenticate as a normal user (since the API requires authentication).
 * 2. Create a post (required for a valid report target).
 * 3. Create a comment (required for alternate reporting scenario).
 * 4. Create a valid report on the post (should succeed) with only post_id and a valid reason.
 * 5. Create a valid report on the comment (should succeed) with only comment_id and a valid reason.
 * 6. Attempt to create a report providing BOTH post_id and comment_id (should fail validation / error).
 * 7. Attempt to create a report with NEITHER post_id nor comment_id (should fail validation / error).
 * 8. Attempt to make a duplicate report (same user, same post or comment) (should return 409 or similar conflict error).
 * 9. Attempt to create a report on a non-existent or deleted post/comment (should return not found or forbidden error).
 * 10. Attempt to create a report when NOT authenticated (should be rejected as unauthorized).
 *
 * The purpose of this test is to verify correct enforcement of business rules around content reporting:
 * - User must be authenticated
 * - Must specify exactly ONE of {post_id, comment_id}
 * - Duplicate reports by same user not allowed
 * - Target content must exist
 * - Unauthorized users cannot create reports
 *
 * All API side effects are validated both via successful type assertions and via error case handling (TestValidator.error etc).
 */
export async function test_api_discussionboard_test_create_report_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. Assume the connection is already authenticated for positive cases

  // 2. Create a valid post for reporting
  const thread_id = typia.random<string & tags.Format<"uuid">>();
  const postContent = RandomGenerator.paragraph()();
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: {
      thread_id,
      content: postContent,
    },
  });
  typia.assert(post);

  // 3. Create a valid comment (alternate reporting target)
  const user_id = typia.random<string & tags.Format<"uuid">>();
  const commentContent = RandomGenerator.paragraph()();
  const comment = await api.functional.discussionboard.comments.post(connection, {
    body: {
      post_id: post.id,
      created_by_user_id: user_id,
      content: commentContent,
    },
  });
  typia.assert(comment);

  // 4. Create a valid report for the post (post_id only)
  const reasonPost = "Inappropriate content";
  const reportOnPost = await api.functional.discussionboard.reports.post(connection, {
    body: {
      post_id: post.id,
      comment_id: null,
      reason: reasonPost,
    },
  });
  typia.assert(reportOnPost);

  // 5. Create a valid report for the comment (comment_id only)
  const reasonComment = "Spam";
  const reportOnComment = await api.functional.discussionboard.reports.post(connection, {
    body: {
      post_id: null,
      comment_id: comment.id,
      reason: reasonComment,
    },
  });
  typia.assert(reportOnComment);

  // 6. Attempt to create a report with BOTH post_id and comment_id
  await TestValidator.error("Both post_id & comment_id should fail")(() =>
    api.functional.discussionboard.reports.post(connection, {
      body: {
        post_id: post.id,
        comment_id: comment.id,
        reason: "Should not allow both",
      },
    }),
  );

  // 7. Attempt to create a report with NEITHER post_id nor comment_id
  await TestValidator.error("Neither post_id nor comment_id should fail")(() =>
    api.functional.discussionboard.reports.post(connection, {
      body: {
        reason: "Should not allow neither",
      },
    }),
  );

  // 8. Attempt duplicate report on post
  await TestValidator.error("Duplicate report (post) should fail")(() =>
    api.functional.discussionboard.reports.post(connection, {
      body: {
        post_id: post.id,
        comment_id: null,
        reason: reasonPost,
      },
    }),
  );

  // 9. Attempt duplicate report on comment
  await TestValidator.error("Duplicate report (comment) should fail")(() =>
    api.functional.discussionboard.reports.post(connection, {
      body: {
        post_id: null,
        comment_id: comment.id,
        reason: reasonComment,
      },
    }),
  );

  // 10. Attempt to report a non-existent post
  await TestValidator.error("Nonexistent post should fail")(() =>
    api.functional.discussionboard.reports.post(connection, {
      body: {
        post_id: typia.random<string & tags.Format<"uuid">>(),
        comment_id: null,
        reason: "Nonexistent post",
      },
    }),
  );

  // 11. Attempt to report a non-existent comment
  await TestValidator.error("Nonexistent comment should fail")(() =>
    api.functional.discussionboard.reports.post(connection, {
      body: {
        post_id: null,
        comment_id: typia.random<string & tags.Format<"uuid">>(),
        reason: "Nonexistent comment",
      },
    }),
  );

  // 12. Attempt report as unauthorized user (clear auth headers to simulate unauthenticated state)
  const unauthConnection: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error("Unauthenticated user should be rejected")(() =>
    api.functional.discussionboard.reports.post(unauthConnection, {
      body: {
        post_id: post.id,
        comment_id: null,
        reason: "Should be rejected",
      },
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardReport";

/**
 * Test permission-aware update of a discussion board report's status and mutable fields.
 *
 * This E2E test verifies:
 *  - That report updates (status/reason/post_id/comment_id) are only possible for permitted roles
 *  - That unauthorized update attempts are rejected
 *  - That business logic restricts only certain fields to be patched
 *  - That updates on deleted or non-existent reports throw errors
 *
 * Steps:
 * 1. Create a report as setup
 * 2. Update status/reason as (simulated) moderator/admin – expect success
 * 3. Update allowed fields as (simulated) reporting user – expect permitted changes
 * 4. Attempt forbidden update as unauthorized user (simulated if possible) – expect error
 * 5. Delete report and attempt update – expect error
 * 6. Update a non-existent report id – expect error
 *
 * Note: Role switching and user authentication cannot be implemented if API provides no such endpoints – actual permission check coverage may be limited by SDK. Test steps rely on the existing API contract and test for observable effects.
 */
export async function test_api_discussionboard_test_update_report_status_and_fields_with_permission_handling(
  connection: api.IConnection,
) {
  // 1. Create a report to work with
  let created: IDiscussionboardReport = await api.functional.discussionboard.reports.post(connection, {
    body: typia.random<IDiscussionboardReport.ICreate>(),
  });
  typia.assert(created);

  // 2. Try to update as 'moderator/admin' (simulated by using test connection)
  const updatePayload1: IDiscussionboardReport.IUpdate = {
    status: 'reviewed',
    reason: 'Reviewed by moderator',
  };
  const updated1 = await api.functional.discussionboard.reports.putById(connection, {
    id: created.id,
    body: updatePayload1,
  });
  typia.assert(updated1);
  TestValidator.equals('update status')(updated1.status)('reviewed');
  TestValidator.equals('update reason')(updated1.reason)('Reviewed by moderator');

  // 3. Try to update as reporting user (simulated: since only one connection/context available)
  //    Assume user can update the reason, but not the status.
  const updatePayload2: IDiscussionboardReport.IUpdate = {
    reason: 'Reporter correcting reason',
  };
  const updated2 = await api.functional.discussionboard.reports.putById(connection, {
    id: created.id,
    body: updatePayload2,
  });
  typia.assert(updated2);
  TestValidator.equals('update reason by owner')(updated2.reason)('Reporter correcting reason');
  // If backend allows owner to change the status, this is a gap in business logic; else should fail. Here only reason is changed.

  // 4. Attempt update as unauthorized user (simulate by manipulating input, since no auth context)
  //    This is not fully testable without user identity switching, so document as untestable if no API for it.
  //    For demonstration, attempt to update an unrelated field or invalid payload and expect error.
  await TestValidator.error('unauthorized update should fail')(async () => {
    await api.functional.discussionboard.reports.putById(connection, {
      id: typia.random<string & tags.Format<'uuid'>>(), // unrelated report
      body: {
        status: 'unauthorized',
        reason: 'Should not work',
      },
    });
  });

  // 5. Delete report and attempt update; should produce error
  await api.functional.discussionboard.reports.eraseById(connection, { id: created.id });
  await TestValidator.error('update after delete should fail')(async () => {
    await api.functional.discussionboard.reports.putById(connection, {
      id: created.id,
      body: { status: 'postdelete' },
    });
  });

  // 6. Try to update non-existent report id
  await TestValidator.error('update non-existent report should fail')(async () => {
    await api.functional.discussionboard.reports.putById(connection, {
      id: typia.random<string & tags.Format<'uuid'>>(),
      body: { status: 'ghost' },
    });
  });
  // Note: Audit log/workflow validation not possible unless exposed through API/SDK.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
