 *
 * This function validates the permissions and error scenarios for the DELETE /discussionboard/reports/{id} endpoint:
 * 1. Creates a new report using the public Report API (as an assumed reporter).
 * 2. Deletes the report as the reporter (success expected; report should be gone post-deletion).
 * 3. Tests deletion of the same report again—should fail with error (already deleted resource).
 * 4. Tests deletion of a non-existent report (random UUID)—should fail with error response.
 *
 * Due to the limited API surface, steps for moderator/admin actions,
 * enforcing guest/unauthorized user context, or verifying audit log behavior cannot be performed here.
 *
 * All operations are checked for expected success or error (using TestValidator.error on failure branches).
 */
export async function test_api_discussionboard_test_delete_report_by_authorized_and_unauthorized_users(
  connection: api.IConnection,
) {
  // 1. Create a report (simulate as the authenticated reporter)
  const report = await api.functional.discussionboard.reports.post(connection, {
    body: typia.random<IDiscussionboardReport.ICreate>(),
  });
