import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardSearchIndex } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSearchIndex";
import type { IPageIDiscussionboardSearchIndex } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardSearchIndex";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate paginated and filtered listing of search index entries.
 *
 * This test ensures that retrieving a paginated list of search index records with 
 * filter criteria (e.g., source_type set to 'post' and indexed_text containing a specific keyword)
 * returns correct results and pagination metadata. It simulates the workflow for admin/diagnostic UI.
 *
 * Steps:
 * 1. Create multiple search index entries with varying source_type ('post', 'thread', etc.)
 *    and indexed_text (some matching a target keyword, some not). This sets up a dataset
 *    for effective filtering and pagination.
 * 2. Search with valid filter: source_type = 'post' and indexed_text contains the keyword.
 *    Use a small page size (e.g., 2) to force pagination.
 * 3. Verify:
 *    - All returned records have source_type === 'post' and indexed_text contains the keyword.
 *    - Returned page size matches limit; pagination metadata are correct.
 *    - Can walk all result pages and collect all matches with no duplication.
 *    - Negative search with a gibberish keyword returns zero.
 */
export async function test_api_discussionboard_test_list_search_indices_with_valid_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Data Setup: Create a realistic dataset for filtering/paging
  const keyword = RandomGenerator.alphaNumeric(10);
  // 5 search_indices with source_type 'post' AND keyword in indexed_text
  for (let i = 0; i < 5; ++i) {
    await api.functional.discussionboard.searchIndices.post(connection, {
      body: {
        source_type: "post",
        source_id: typia.random<string & tags.Format<"uuid">>(),
        indexed_text: `Important ${keyword} message #${i}`,
      },
    });
  }
  // 3 with source_type 'post', but random text (no keyword)
  for (let i = 0; i < 3; ++i) {
    await api.functional.discussionboard.searchIndices.post(connection, {
      body: {
        source_type: "post",
        source_id: typia.random<string & tags.Format<"uuid">>(),
        indexed_text: RandomGenerator.paragraph()(),
      },
    });
  }
  // 2 with different source_type, but *do* contain keyword
  for (let i = 0; i < 2; ++i) {
    await api.functional.discussionboard.searchIndices.post(connection, {
      body: {
        source_type: "comment",
        source_id: typia.random<string & tags.Format<"uuid">>(),
        indexed_text: `Admin ${keyword} log #${i}`,
      },
    });
  }

  // 2. Search for 'post' indices containing the keyword, page 1, limit 2
  const pageLimit = 2;
  const firstPage = await api.functional.discussionboard.searchIndices.patch(connection, {
    body: {
      source_type: "post",
      indexed_text: keyword,
      page: 1,
      limit: pageLimit,
    },
  });
  typia.assert(firstPage);
  TestValidator.equals("page limit")(firstPage.pagination.limit)(pageLimit);
  TestValidator.equals("page current")(firstPage.pagination.current)(1);
  // All records should have "post" and include keyword
  for (const item of firstPage.data) {
    TestValidator.equals("source_type")(item.source_type)("post");
    TestValidator.predicate("indexed_text contains keyword")(item.indexed_text.includes(keyword));
  }
  TestValidator.predicate("data length <= limit")(firstPage.data.length <= pageLimit);

  // Saving the total result count
  const totalCount = firstPage.pagination.records;
  TestValidator.predicate("totalCount at least 5")(totalCount >= 5);
  const totalPages = firstPage.pagination.pages;

  // 3. Walk all pages; collect and ensure all unique IDs are covered
  const seen = new Set<string>();
  let matchCount = 0;
  for (let page = 1; page <= totalPages; ++page) {
    const pageResp = await api.functional.discussionboard.searchIndices.patch(connection, {
      body: {
        source_type: "post",
        indexed_text: keyword,
        page,
        limit: pageLimit,
      },
    });
    for (const idx of pageResp.data) {
      TestValidator.equals("source_type")(idx.source_type)("post");
      TestValidator.predicate("indexed_text contains keyword")(idx.indexed_text.includes(keyword));
      if (!seen.has(idx.id)) {
        seen.add(idx.id);
        matchCount++;
      }
    }
  }
  TestValidator.equals("unique match count matches totalCount")(matchCount)(totalCount);

  // 4. Negative test: query with a never-matching keyword should return zero
  const negative = await api.functional.discussionboard.searchIndices.patch(connection, {
    body: {
      source_type: "post",
      indexed_text: "__no_such_keyword__",
      page: 1,
      limit: pageLimit,
    },
  });
  TestValidator.equals("empty data")(negative.data.length)(0);
  TestValidator.equals("empty records")(negative.pagination.records)(0);
  TestValidator.equals("empty pages")(negative.pagination.pages)(0);
}

