 *
 * This test simulates the lifecycle for correcting a search index record. It validates that updates to fields such as indexed_text and source_type are reflected in the record and that repeated or empty updates are safe and effective.
 *
 * Steps:
 * 1. Create a new search index entry via POST /discussionboard/searchIndices to establish initial content.
 * 2. Update the entry (PUT /discussionboard/searchIndices/{id}) to change indexed_text and source_type, verifying both the mutation and ID retention.
 * 3. Perform another partial update (indexed_text only) to ensure correct partial mutation.
 * 4. Perform an update with no fields (edge case), confirming no unwanted changes.
 */
export async function test_api_discussionboard_test_update_search_index_with_valid_changes(
  connection: api.IConnection,
) {
  // 1. Create a search index entry to be updated
  const createInput: IDiscussionboardSearchIndex.ICreate = {
    source_type: "post",
    source_id: typia.random<string & tags.Format<"uuid">>(),
    indexed_text: "Original content to be indexed for search.",
  };
  const created = await api.functional.discussionboard.searchIndices.post(connection, { body: createInput });
  typia.assert(created);

  // 2. Update indexed_text and source_type
  const updateInput: IDiscussionboardSearchIndex.IUpdate = {
    indexed_text: "Updated indexed text for correction.",
    source_type: "thread",
  };
  const updated = await api.functional.discussionboard.searchIndices.putById(connection, {
    id: created.id,
    body: updateInput,
  });
  typia.assert(updated);
  // Confirm that changes took effect and id was unchanged
