  const partialUpdate: IDiscussionboardSearchIndex.IUpdate = {
    indexed_text: "Second update to indexed text only.",
  };
  const secondUpdated = await api.functional.discussionboard.searchIndices.putById(connection, {
    id: created.id,
    body: partialUpdate,
  });
  typia.assert(secondUpdated);
  TestValidator.equals("id still retained")(secondUpdated.id)(created.id);
  TestValidator.equals("indexed_text updated again")(secondUpdated.indexed_text)(partialUpdate.indexed_text);
  TestValidator.equals("source_type remains after no change")(secondUpdated.source_type)(updateInput.source_type);

