  const noOpUpdate: IDiscussionboardSearchIndex.IUpdate = {};
  const noOpResult = await api.functional.discussionboard.searchIndices.putById(connection, {
    id: created.id,
    body: noOpUpdate,
  });
  typia.assert(noOpResult);
  TestValidator.equals("id no-op")(noOpResult.id)(created.id);
  TestValidator.equals("indexed_text remains same after no-op")(noOpResult.indexed_text)(secondUpdated.indexed_text);
  TestValidator.equals("source_type remains same after no-op")(noOpResult.source_type)(secondUpdated.source_type);
}

