    source_id: typia.random<string & tags.Format<"uuid">>(),
  };

  // 3. Attempt the update and assert that error is thrown
  await TestValidator.error("Should return not found for invalid discussionboard_search_index ID")(
    async () => {
      await api.functional.discussionboard.searchIndices.putById(connection, {
        id: nonExistentId,
        body: updatePayload,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardSearchIndex } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSearchIndex";

/**
 * Validate that immutable fields cannot be updated in a discussion board search index record.
 *
 * Business context:
 * - The search index has immutable fields such as 'id' and 'created_at', which must not be changed via an update operation.
 *
 * Test Steps:
 * 1. Create a search index entry using the POST endpoint to obtain a valid record with a unique id.
 * 2. Attempt to update the record using the PUT endpoint, updating only allowed mutable fields (e.g., source_type, source_id, indexed_text).
 * 3. Validate after update that the immutable fields ('id', 'created_at') remain unchanged in the response, confirming proper enforcement of immutability.
 * 4. Optionally, repeat step 2 with another valid mutation to ensure all mutable fields can be changed and immutables are still preserved.
 */
export async function test_api_discussionboard_test_update_search_index_with_immutable_field(
  connection: api.IConnection,
) {
  // 1. Create a valid search index record
  const baseIndex = await api.functional.discussionboard.searchIndices.post(connection, {
    body: {
      source_type: "post",
      source_id: typia.random<string & tags.Format<"uuid">>(),
      indexed_text: "Original indexed content for fulltext search"
    } satisfies IDiscussionboardSearchIndex.ICreate
  });
  typia.assert(baseIndex);

  // 2. Try updating mutable fields only
  const newText = "Updated search index text";
  const updated = await api.functional.discussionboard.searchIndices.putById(connection, {
    id: baseIndex.id,
    body: {
      indexed_text: newText,
      source_type: "thread",
      source_id: typia.random<string & tags.Format<"uuid">>()
    } satisfies IDiscussionboardSearchIndex.IUpdate
  });
  typia.assert(updated);

  // 3. Validate that immutable fields remain unchanged after update
  TestValidator.equals("id remains unchanged")(updated.id)(baseIndex.id);
  TestValidator.equals("created_at remains unchanged")(updated.created_at)(baseIndex.created_at);

  // 4. Mutable fields actually update
  TestValidator.equals("indexed_text updated")(updated.indexed_text)(newText);
  TestValidator.equals("source_type updated")(updated.source_type)("thread");
  // source_id assigned to new value
  TestValidator.equals("source_id updated")(updated.source_id)(updated.source_id);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardSearchIndex } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSearchIndex";

/**
 * Validate deletion of a Discussion Board Search Index entry by valid ID.
 *
 * This test ensures that an existing search index entry can be deleted successfully via the DELETE endpoint, and confirms that
 * the deleted entry is no longer accessible. This is essential for maintaining the accuracy and relevance of the searchable
 * indices, preventing stale or erroneous entries from polluting search results.
 *
 * Steps:
 * 1. Create a new search index entry (using the POST endpoint).
 * 2. Delete the created search index entry using its ID via the DELETE endpoint.
 * 3. Verify API response confirms successful deletion (response.deleted === true, response.id matches, etc.).
 * 4. (Negative verification) Attempt to delete the same index again and confirm that API responds appropriately to non-existent id.
 * 5. (Optional, if possible) Try to access the deleted index and confirm it is no longer accessible (would require a GET endpoint, so omit if endpoint does not exist).
 */
export async function test_api_discussionboard_searchIndices_test_delete_search_index_by_valid_id(
  connection: api.IConnection,
) {
  // 1. Create a new search index entry
  const createInput: IDiscussionboardSearchIndex.ICreate = {
    source_type: "post",
    source_id: typia.random<string & tags.Format<"uuid">>(),
    indexed_text: "Test entry for deletion"
  };
  const created = await api.functional.discussionboard.searchIndices.post(connection, {
    body: createInput,
  });
  typia.assert(created);

  // 2. Delete the created search index entry
  const deleteResult = await api.functional.discussionboard.searchIndices.eraseById(connection, {
    id: created.id,
  });
  typia.assert(deleteResult);
  TestValidator.equals("Deleted id matches created id")(deleteResult.id)(created.id);
  TestValidator.equals("Delete confirmation")(deleteResult.deleted)(true);

  // 3. Negative: Try deleting the same index again, expecting an error since it no longer exists
  await TestValidator.error("Cannot delete already deleted index")(
    async () => {
      await api.functional.discussionboard.searchIndices.eraseById(connection, {
        id: created.id,
      });
    }
  );

  // 4. Optional GET verification is omitted as there isn't a GET endpoint provided in available functions.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
