import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardSearchIndex } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSearchIndex";

/**
 * Test deletion of a search index by an invalid (non-existent) ID.
 *
 * This test ensures that when attempting to delete a search index entry with an ID that does not exist:
 *   - The API responds with an appropriate not found error (such as a 404 response, deleted: false, and a message)
 *   - There are no side effects to existing records
 *   - The response payload structure is validated
 *
 * Edge case: Uses a randomly generated, valid UUID that is very unlikely to exist.
 *
 * Steps:
 * 1. Generate a random UUID that does not correspond to any real search index entry
 * 2. Attempt to delete the search index entry with that ID using the eraseById endpoint
 * 3. Assert that the response indicates deletion failed (deleted=false), that a message is present, and that the response echoes the requested ID
 * 4. Validate response structure with typia.assert
 */
export async function test_api_discussionboard_searchIndices_eraseById_invalidId_returns_not_found(
  connection: api.IConnection,
) {
  // 1. Generate a non-existent (random/new) UUID
  const invalidId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();

  // 2. Attempt to delete using the invalid/non-existent ID
  const result = await api.functional.discussionboard.searchIndices.eraseById(connection, { id: invalidId });
  typia.assert(result);

  // 3. Validate that deletion did NOT happen and that the response reflects it
  TestValidator.equals("deletion did not occur for invalid ID")(result.deleted)(false);
  TestValidator.predicate("response contains a not found or error message")(
