import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IDiscussionboardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardReport";
import type { IPageIDiscussionboardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardReport";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate report list/search (discussionboard_report) with filters, pagination, and permission boundaries.
 *
 * This test checks the report search/listing endpoint for:
 *  - Filtering by reporter, content-target (post/comment), status, and creation date
 *  - Pagination correctness for meta (current, limit, records, pages) and multiple result pages
 *  - Permission enforcement (non-privileged users only see their own reports, admins/mods see all)
 *  - Error/validation response for invalid filter criteria (bad status, malformed dates)
 *
 * Steps:
 * 1. Register users for different roles (admin, moderator, users)
 * 2. Create posts and comments
 * 3. File multiple reports of both types (posts/comments), across users, with various reasons/status
 * 4. Test search cases:
 *    - Filter by reporting_user_id
 *    - Filter by target (post_id/comment_id)
 *    - Filter by status (valid/invalid)
 *    - Filter by date range (created_from/created_to)
 *    - Pagination with small limit
 *    - Combined filters (user+status+date)
 *    - Check that permission boundaries prevent regular users from seeing others' reports
 *    - Check admin/moderator see all
 * 5. Assert returned records match filters, pagination meta is correct, errors for invalid queries
 */
export async function test_api_discussionboard_test_list_reports_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Register users with different roles
  const adminUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "Admin!234",
      displayName: "AdminUser",
      avatarUrl: undefined,
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(adminUser);

  const moderatorUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "Mod!234",
      displayName: "Moderator",
      avatarUrl: undefined,
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(moderatorUser);

  const normalUser1 = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "User1!234",
      displayName: "NormalUser1",
      avatarUrl: undefined,
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(normalUser1);

  const normalUser2 = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "User2!234",
      displayName: "NormalUser2",
      avatarUrl: undefined,
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(normalUser2);

  // 2. Create posts (authored by different users)
  const threadId = typia.random<string & tags.Format<"uuid">>();

  const post1 = await api.functional.discussionboard.posts.post(connection, {
    body: {
      thread_id: threadId,
      content: "Test post 1 content",
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post1);

  const post2 = await api.functional.discussionboard.posts.post(connection, {
    body: {
      thread_id: threadId,
      content: "Test post 2 content",
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post2);

  // 3. Create comments (on post1 only)
  const comment1 = await api.functional.discussionboard.comments.post(connection, {
    body: {
      post_id: post1.id,
      created_by_user_id: normalUser1.id,
      content: "Comment from user1",
    } satisfies IDiscussionboardComment.ICreate,
  });
  typia.assert(comment1);

  const comment2 = await api.functional.discussionboard.comments.post(connection, {
    body: {
      post_id: post1.id,
      created_by_user_id: normalUser2.id,
      content: "Comment from user2",
    } satisfies IDiscussionboardComment.ICreate,
  });
  typia.assert(comment2);

  // 4. Submit reports: mix of post/comment, two per user, different reasons/status
  const allReports = [] as IDiscussionboardReport[];

  const report1 = await api.functional.discussionboard.report.post(connection, {
    body: {
      reporting_user_id: normalUser1.id,
      post_id: post1.id,
      comment_id: null,
      reason: "Spam in post1 by user1",
      status: "pending",
      created_at: new Date().toISOString(),
    },
  });
  typia.assert(report1);
  allReports.push(report1);

  const report2 = await api.functional.discussionboard.report.post(connection, {
    body: {
      reporting_user_id: normalUser2.id,
      post_id: post2.id,
      comment_id: null,
      reason: "Harassment in post2 by user2",
      status: "reviewed",
      created_at: new Date(Date.now() - 86400000).toISOString(), // 1 day ago
    },
  });
  typia.assert(report2);
  allReports.push(report2);

  // Comment reports
  const report3 = await api.functional.discussionboard.report.post(connection, {
    body: {
      reporting_user_id: normalUser1.id,
      post_id: null,
      comment_id: comment2.id,
      reason: "Abusive language by user2",
      status: "pending",
      created_at: new Date().toISOString(),
    },
  });
  typia.assert(report3);
  allReports.push(report3);

  const report4 = await api.functional.discussionboard.report.post(connection, {
    body: {
      reporting_user_id: normalUser2.id,
      post_id: null,
      comment_id: comment1.id,
      reason: "Trolling by user1",
      status: "reviewed",
      created_at: new Date(Date.now() - 172800000).toISOString(), // 2 days ago
    },
  });
  typia.assert(report4);
  allReports.push(report4);

  // 5. Filter tests – basic: by reporter id
  for (const user of [normalUser1, normalUser2]) {
    const userReports = allReports.filter(r => r.reporting_user_id === user.id);
    const res = await api.functional.discussionboard.report.patch(connection, {
      body: {
        reporting_user_id: user.id,
        post_id: null,
        comment_id: null,
        status: null,
        reason: null,
        created_from: null,
        created_to: null,
        page: 1,
        limit: null,
      },
    });
    typia.assert(res);
    TestValidator.equals(`report count for ${user.displayName}`)(res.data.length)(userReports.length);
    for (const rep of res.data) {
      TestValidator.equals(`report owned by ${user.displayName}`)(rep.reporting_user_id)(user.id);
    }
  }

  // 6. Filter by status
  for (const status of ["pending", "reviewed"]) {
    const expected = allReports.filter(r => r.status === status);
    const out = await api.functional.discussionboard.report.patch(connection, {
      body: {
        reporting_user_id: null,
        post_id: null,
        comment_id: null,
        status,
        reason: null,
        created_from: null,
        created_to: null,
        page: 1,
        limit: null,
      },
    });
    typia.assert(out);
    for (const rep of out.data) {
      TestValidator.equals(`report status ${status}`)(rep.status)(status);
    }
    TestValidator.equals(`# status=${status}`)(out.data.length)(expected.length);
  }

  // 7. Filter by post and comment id
  const filterCases = [
    { key: "post_id", value: post1.id, kind: "post" },
    { key: "post_id", value: post2.id, kind: "post" },
    { key: "comment_id", value: comment1.id, kind: "comment" },
    { key: "comment_id", value: comment2.id, kind: "comment" },
  ];
  for (const test of filterCases) {
    const input: IDiscussionboardReport.IRequest = {
      reporting_user_id: null,
      post_id: test.key === "post_id" ? test.value : null,
      comment_id: test.key === "comment_id" ? test.value : null,
      status: null,
      reason: null,
      created_from: null,
      created_to: null,
      page: 1,
      limit: null,
    };
    const expected = allReports.filter(r => (r[test.key as "post_id" | "comment_id"] ?? null) === test.value);
    const res = await api.functional.discussionboard.report.patch(connection, { body: input });
    typia.assert(res);
    TestValidator.equals(`reports for ${test.kind} ${test.value}`)(res.data.length)(expected.length);
    for (const rep of res.data) {
      TestValidator.equals(`correct ${test.kind} id`)((rep as any)[test.key])(test.value);
    }
  }

  // 8. Date range filter (created_from, created_to, edge inclusiveness)
  const now = new Date();
  const yesterday = new Date(Date.now() - 86400000);
  const twoDaysAgo = new Date(Date.now() - 172800000);
  {
    // inclusive of oldest
    const res1 = await api.functional.discussionboard.report.patch(connection, {
      body: {
        reporting_user_id: null,
        post_id: null,
        comment_id: null,
        status: null,
        reason: null,
        created_from: twoDaysAgo.toISOString(),
        created_to: yesterday.toISOString(),
        page: 1,
        limit: null,
      },
    });
    typia.assert(res1);
    for (const rep of res1.data) {
      TestValidator.predicate("created_in_range")(new Date(rep.created_at) >= twoDaysAgo && new Date(rep.created_at) <= yesterday);
    }
  }
  {
    // inclusive of newest
    const res2 = await api.functional.discussionboard.report.patch(connection, {
      body: {
        reporting_user_id: null,
        post_id: null,
        comment_id: null,
        status: null,
        reason: null,
        created_from: yesterday.toISOString(),
        created_to: now.toISOString(),
        page: 1,
        limit: null,
      },
    });
    typia.assert(res2);
    for (const rep of res2.data) {
      TestValidator.predicate("created_in_range")(new Date(rep.created_at) >= yesterday && new Date(rep.created_at) <= now);
    }
  }

  // 9. Pagination test: limit 2 (should split results)
  const pagedRes1 = await api.functional.discussionboard.report.patch(connection, {
    body: {
      reporting_user_id: null,
      post_id: null,
      comment_id: null,
      status: null,
      reason: null,
      created_from: null,
      created_to: null,
      page: 1,
      limit: 2,
    },
  });
  typia.assert(pagedRes1);
  TestValidator.equals("limit matches")(pagedRes1.data.length)(2);
  TestValidator.equals("meta limit")(pagedRes1.pagination.limit)(2);
  TestValidator.equals("total count")(pagedRes1.pagination.records)(allReports.length);
  const pagedRes2 = await api.functional.discussionboard.report.patch(connection, {
    body: {
      reporting_user_id: null,
      post_id: null,
      comment_id: null,
      status: null,
      reason: null,
      created_from: null,
      created_to: null,
      page: 2,
      limit: 2,
    },
  });
  typia.assert(pagedRes2);
  TestValidator.equals("meta page")(pagedRes2.pagination.current)(2);
  // Exclude already found in page 1
  for (const rep of pagedRes2.data) {
    let found = false;
    for (const rep1 of pagedRes1.data) {
      if (rep.id === rep1.id) found = true;
    }
    TestValidator.equals("no overlap between pages")(found)(false);
  }

  // 10. Combined filters (e.g., user+status)
  {
    const targetUser = normalUser1;
    const targetStatus = "pending";
    const expected = allReports.filter(r => r.reporting_user_id === targetUser.id && r.status === targetStatus);
    const res = await api.functional.discussionboard.report.patch(connection, {
      body: {
        reporting_user_id: targetUser.id,
        post_id: null,
        comment_id: null,
        status: targetStatus,
        reason: null,
        created_from: null,
        created_to: null,
        page: 1,
        limit: null,
      },
    });
    typia.assert(res);
    TestValidator.equals("combined filter count")(res.data.length)(expected.length);
    for (const rep of res.data) {
      TestValidator.equals("right user and status")(rep.reporting_user_id)(targetUser.id);
      TestValidator.equals("right user and status")(rep.status)(targetStatus);
    }
  }

  // 11. Check permission: Ensure only own reports for normalUser1
  // (simulate by using normalUser1's id)
  // Since we lack real auth API, at least check via id filter
  {
    const permittedIds = allReports.filter(r => r.reporting_user_id === normalUser1.id).map(r => r.id);
    const res = await api.functional.discussionboard.report.patch(connection, {
      body: {
        reporting_user_id: normalUser1.id,
        post_id: null,
        comment_id: null,
        status: null,
        reason: null,
        created_from: null,
        created_to: null,
        page: 1,
        limit: null,
      },
    });
    typia.assert(res);
    for (const rep of res.data) {
      TestValidator.predicate("visible only for self")(permittedIds.includes(rep.id));
    }
  }

  // 12. Validation error: unknown status
  TestValidator.error("unknown status should fail")(async () => {
    await api.functional.discussionboard.report.patch(connection, {
      body: {
        reporting_user_id: null,
        post_id: null,
        comment_id: null,
        status: "invalid_status",
        reason: null,
        created_from: null,
        created_to: null,
        page: 1,
        limit: null,
      },
    });
  });

  // 13. Validation error: malformed date range
  TestValidator.error("date format should fail")(async () => {
    await api.functional.discussionboard.report.patch(connection, {
      body: {
        reporting_user_id: null,
        post_id: null,
        comment_id: null,
        status: null,
        reason: null,
        created_from: "not-a-date",
        created_to: null,
        page: 1,
        limit: null,
      },
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
