import type { IDiscussionboardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardReport";

/**
 * Validate report details fetch for authorized and unauthorized users, as well as error handling.
 *
 * This test verifies:
 * 1. Registering a report author, an unrelated regular user, and a privileged user (simulate mod/admin).
 * 2. Author creates a discussion post in a thread.
 * 3. Author creates a report on the post.
 * 4. Fetching the report as the author returns all metadata and matches the original creation input.
 * 5. Fetch as privileged user also returns the full report details.
 * 6. Fetch as an unrelated user triggers forbidden (403) error.
 * 7. Fetch with a non-existent report ID triggers a not found (404) error.
 *
 * Authorization, privilege, and audit log checks are limited to what the DTOs and API allow (no real role or session switch), so user context switching is simulated.
 */
export async function test_api_discussionboard_test_get_report_details_success_and_not_found(
  connection: api.IConnection,
) {
  // 1. Register users
  const authorEmail = typia.random<string & tags.Format<"email">>();
  const authorPassword = "P@ssw0rd42";
  const author = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: authorEmail,
      password: authorPassword,
      displayName: RandomGenerator.name(),
      isActive: true,
    },
  });
  typia.assert(author);

  const unrelatedEmail = typia.random<string & tags.Format<"email">>();
  const unrelatedPassword = "QweRty123*";
  const unrelatedUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: unrelatedEmail,
      password: unrelatedPassword,
      displayName: RandomGenerator.name(),
      isActive: true,
    },
  });
  typia.assert(unrelatedUser);

  const privilegedEmail = typia.random<string & tags.Format<"email">>();
  const privilegedPassword = "Adm!nP@ss122";
  const privilegedUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: privilegedEmail,
      password: privilegedPassword,
      displayName: RandomGenerator.name(),
      isActive: true,
    },
  });
  typia.assert(privilegedUser);

  // 2. Author creates a post
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const postContent = RandomGenerator.paragraph()();
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: {
      thread_id: threadId,
      content: postContent,
    },
  });
  typia.assert(post);

  // 3. Author creates a report on the post
  const reportReason = "Inappropriate content";
  const reportCreateBody = {
    post_id: post.id,
    reason: reportReason,
  } satisfies IDiscussionboardReport.ICreate;
  const report = await api.functional.discussionboard.report.post(connection, {
    body: reportCreateBody,
  });
  typia.assert(report);

  // 4. Fetch as author (should succeed)
  const fetchedByAuthor = await api.functional.discussionboard.report.getById(connection, { id: report.id });
  typia.assert(fetchedByAuthor);
  TestValidator.equals("report.id")(fetchedByAuthor.id)(report.id);
  TestValidator.equals("reporting_user")(fetchedByAuthor.reporting_user_id)(author.id);
  TestValidator.equals("post_id")(fetchedByAuthor.post_id)(post.id);
  TestValidator.equals("reason")(fetchedByAuthor.reason)(reportReason);
