/**
 * Validate reporting workflow for posts and comments in the discussion board with comprehensive permission and validation checks.
 *
 * This test covers:
 * 1. Creation of two users: a reporter and an author
 * 2. Author creates a post (and a comment under it)
 * 3. Reporter issues a report on the author's post
 * 4. Verifies that duplicate reports are rejected (409)
 * 5. Checks for input validation failures (both/neither ids: 400)
 * 6. Confirms unauthenticated attempts are rejected (401/403)
 * 7. Tests for reporting non-existent post/comment (404)
 *
 * Steps:
 * 1. Register author and reporter users, assert their creation
 * 2. Author creates a post in a dummy thread (simulate thread id)
 * 3. Author creates a comment under their own post
 * 4. Reporter (simulated via new connection) issues a report on the post, expect 'pending' status
 * 5. Repeat the report (duplicate) as same reporter on same post, expect error (409)
 * 6. Attempt to report both post_id/comment_id simultaneously, expect error (400)
 * 7. Attempt to report with neither post_id nor comment_id, expect error (400)
 * 8. Simulate unauthenticated attempt (reset headers), expect error (401/403)
 * 9. Report using a non-existent post and comment id, expect error (404)
 */
export async function test_api_discussionboard_test_create_report_on_post_and_comment_with_duplicate_and_permission_checks(
  connection: api.IConnection,
) {
  // 1. Register author user
  const author = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<'email'>>(),
      password: 'TestPass!123',
      displayName: RandomGenerator.name(),
      isActive: true,
    },
  });
  typia.assert(author);

  // 2. Register reporter user
  const reporter = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<'email'>>(),
      password: 'TestPass!123',
      displayName: RandomGenerator.name(),
      isActive: true,
    },
  });
  typia.assert(reporter);

  // 3. Author creates a post (simulate valid thread id)
  const threadId: string & tags.Format<'uuid'> = typia.random<string & tags.Format<'uuid'>>();
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: {
      thread_id: threadId,
      content: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(post);

  // 4. Author creates a comment under the post
  const comment = await api.functional.discussionboard.comments.post(connection, {
    body: {
      post_id: post.id,
      created_by_user_id: author.id,
      content: RandomGenerator.content()()(),
    },
  });
  typia.assert(comment);

  // 5. Reporter issues a report targeting the post
  const report1 = await api.functional.discussionboard.report.post(connection, {
    body: {
      post_id: post.id,
      reason: 'This post violates community guidelines.',
    },
  });
  typia.assert(report1);
  TestValidator.equals('report status is pending')(report1.status)('pending');

  // 6. Attempt to submit a duplicate report (same reporter, same post)
  await TestValidator.error('duplicate post report returns conflict')(async () => {
    await api.functional.discussionboard.report.post(connection, {
      body: {
        post_id: post.id,
        reason: 'Reporting as duplicate.',
      },
    });
  });

  // 7. Both post_id and comment_id together: should fail (400)
  await TestValidator.error('report with both post_id and comment_id fails')(async () => {
    await api.functional.discussionboard.report.post(connection, {
      body: {
        post_id: post.id,
        comment_id: comment.id,
        reason: 'Ambiguous target',
      },
    });
  });

  // 8. Neither post_id nor comment_id: should fail (400)
  await TestValidator.error('report with neither post_id nor comment_id fails')(async () => {
    await api.functional.discussionboard.report.post(connection, {
      body: {
        reason: 'No target specified',
      },
    });
  });

  // 9. Unauthenticated request (simulate by dropping headers)
  const unauthConnection: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error('unauthenticated reporting denied')(async () => {
    await api.functional.discussionboard.report.post(unauthConnection, {
      body: {
        post_id: post.id,
        reason: 'Test unauthenticated access',
      },
    });
  });

  // 10. Report a non-existent post (should 404)
  await TestValidator.error('report against non-existent post fails')(async () => {
    await api.functional.discussionboard.report.post(connection, {
      body: {
        post_id: typia.random<string & tags.Format<'uuid'>>(),
        reason: 'Invalid post target',
      },
    });
  });

  // 11. Report a non-existent comment (should 404)
  await TestValidator.error('report against non-existent comment fails')(async () => {
    await api.functional.discussionboard.report.post(connection, {
      body: {
        comment_id: typia.random<string & tags.Format<'uuid'>>(),
        reason: 'Invalid comment target',
      },
    });
  });
}

