  const userAdmin = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "adminPW123!@#" as string & tags.Format<"password">,
      displayName: "admin_" + RandomGenerator.name(),
    },
  });
  typia.assert(userAdmin);

  // 2. Create a threadId (mock/placeholder: no API to create thread, so just generate it)
  const threadId = typia.random<string & tags.Format<"uuid">>();

  // 3. Regular user creates a post
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: {
      thread_id: threadId,
      content: RandomGenerator.paragraph()(),
    },
