  TestValidator.error("author forbidden to update status")(
    async () =>
      api.functional.discussionboard.report.putById(connection, {
        id: report.id,
        body: {
          status: "pending", // trying to change status as author
        },
      }),
  );

  // 8. Attempt to set a forbidden field (not defined in schema) – should produce a 400 error. TypeScript prevents adding undefined fields, but test the scenario.
  TestValidator.error("reject field not in schema")(
    async () =>
      api.functional.discussionboard.report.putById(connection, {
        id: report.id,
        // @ts-expect-error
        body: { fakeField: "value" },
      }),
  );

  // 9. Update non-existent report id (should produce 404 error)
  TestValidator.error("404 not found - non-existent report")(
    async () =>
      api.functional.discussionboard.report.putById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
        body: {
          reason: "any",
        },
      }),
  );
  // 10. Delete API not available; skipped.
  // 11. Business/audit hooks are out of E2E scope with given API; validate returned shape only.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
