/**
 * Test report deletion authorization and error conditions for discussion board reports.
 *
 * This E2E test covers the following scenarios:
 *   1. The report author can delete their own report.
 *   2. A moderator or admin can delete any report (authorization).
 *   3. A different normal user (not the author) CANNOT delete someone else’s report (expect 403 forbidden).
 *   4. Deleting a non-existent or already deleted report returns 404 not found.
 *   5. (As implementable) Check that once deleted, the report cannot be retrieved again (i.e., confirming side-effect).
 *
 * Assumptions:
 * - There is no explicit login/auth endpoint; user context/permissions simulated by creating separate user accounts and passing them as creator on actions.
 * - Admin/moderator creation is via user creation with isActive flag; no explicit admin role field exists in DTOs, so must only demonstrate via allowed actions.
 *
 * Steps:
 * 1. Create three users: reporter, moderatorAdmin, and strangerUser.
 * 2. Reporter creates a post.
 * 3. Reporter creates a report about the post.
 * 4. Stranger tries to delete the report => expect 403 forbidden.
 * 5. Moderator deletes the report => should succeed (test assumes moderator has permissions, or simulate as necessary).
 * 6. Attempt to delete with reporter (should now fail, as already gone) => expect 404 not found.
 * 7. Attempt to delete with moderator again (should fail too) => expect 404 not found.
 *
 * (NOTE: Since there is no search/detail endpoint for reports, step 5 checks absence only through DELETE error handling.)
 */
export async function test_api_discussionboard_test_delete_report_author_and_admin_permissions_not_found_case(
  connection: api.IConnection,
) {
  // 1. Create three users: reporter, moderator/admin, and stranger.
  const reporter = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "TestPassword1!",
      displayName: "Reporter",
      isActive: true,
    },
  });
  typia.assert(reporter);

  const moderator = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "AdminPassword1!",
      displayName: "Moderator",
      isActive: true,
    },
  });
  typia.assert(moderator);

  const stranger = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "StrangerPassword1!",
      displayName: "Stranger",
      isActive: true,
    },
  });
  typia.assert(stranger);

  // 2. Reporter creates a post
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: {
      thread_id: typia.random<string & tags.Format<"uuid">>(), // assume valid/random thread
      content: "This is a post to be reported.",
    },
  });
  typia.assert(post);

  // 3. Reporter creates a report against the post
  const report = await api.functional.discussionboard.report.post(connection, {
    body: {
      reporting_user_id: reporter.id,
      post_id: post.id,
      comment_id: null,
      reason: "Spam or abuse",
      status: "pending",
      created_at: new Date().toISOString(),
    },
  });
  typia.assert(report);

  // 4. Stranger tries to delete the report (should fail: 403)
  await TestValidator.error("stranger cannot delete other's report")(
    async () =>
      api.functional.discussionboard.report.eraseById(connection, {
        id: report.id,
      })
  );

  // 5. Moderator deletes the report (should succeed)
  await api.functional.discussionboard.report.eraseById(connection, {
    id: report.id,
  });

  // 6. Reporter tries to delete again (now gone => 404)
  await TestValidator.error("cannot delete already deleted report (404)")(
    async () =>
      api.functional.discussionboard.report.eraseById(connection, {
        id: report.id,
      })
  );

  // 7. Moderator tries to delete again (404)
  await TestValidator.error("moderator cannot delete already deleted report")(
    async () =>
      api.functional.discussionboard.report.eraseById(connection, {
        id: report.id,
      })
  );

  // 8. Try to delete a random (non-existent) report
  await TestValidator.error("nonexistent report returns 404")(
    async () =>
      api.functional.discussionboard.report.eraseById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
      })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { IDiscussionboardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAdmin";
import type { IPageIDiscussionboardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardAdmin";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate admin assignment list retrieval with various filter and pagination parameters.
 *
 * Tests the process of creating users, assigning admin privileges, and retrieving admin assignments using multiple filtering, paging, and permission scenarios. Validates that admin roles are listed and filtered correctly, pagination/meta fields are accurate, sorting works as expected, and permission boundaries are enforced for non-admins.
 *
 * Step-by-step:
 * 1. Create two normal users (userA, userB)
 * 2. Create an admin user (admin)
 * 3. Assign both userA and userB as admins at different times using the admin account
 * 4. As admin:
 *    - List admin assignments (no filter), expect both users assigned
 *    - Filter by userA, expect only userA
 *    - Filter by userB, expect only userB
 *    - Use pagination (limit=1), verify meta and data
 *    - Use sorting (desc by assigned_at), verify order
 * 5. As non-admin (userA), verify permission enforcement (should fail to retrieve)
 */
export async function test_api_discussionboard_test_list_admin_assignments_with_filtering_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create two normal users (userA, userB)
  const userA = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<'email'>>(),
      password: 'test1234!',
      displayName: RandomGenerator.name(),
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(userA);
  const userB = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<'email'>>(),
      password: 'test1234!',
      displayName: RandomGenerator.name(),
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(userB);

  // 2. Create an admin user
  const admin = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<'email'>>(),
      password: 'adminpass1!',
      displayName: RandomGenerator.name(),
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(admin);

  // 3. Assign admin to userA and userB (at different times)
  const assignedAtA = new Date(Date.now() - 60 * 1000).toISOString(); // 1 min ago
  const adminAssignmentA = await api.functional.discussionboard.admins.post(connection, {
    body: {
      user_id: userA.id,
      assigned_by_admin_id: admin.id,
      assigned_at: assignedAtA,
    } satisfies IDiscussionboardAdmin.ICreate,
  });
  typia.assert(adminAssignmentA);
  const assignedAtB = new Date().toISOString();
  const adminAssignmentB = await api.functional.discussionboard.admins.post(connection, {
    body: {
      user_id: userB.id,
      assigned_by_admin_id: admin.id,
      assigned_at: assignedAtB,
    } satisfies IDiscussionboardAdmin.ICreate,
  });
  typia.assert(adminAssignmentB);

  // 4-1. As admin, list admins with no filter: expect both userA and userB assignments exist
  let result = await api.functional.discussionboard.admins.patch(connection, {
    body: {} satisfies IDiscussionboardAdmin.IRequest,
  });
  typia.assert(result);
  TestValidator.predicate('both user assignments appear')(
    result.data.some(r => r.user_id === userA.id) &&
      result.data.some(r => r.user_id === userB.id),
  );

  // 4-2. Filter by userA
  result = await api.functional.discussionboard.admins.patch(connection, {
    body: { user_id: userA.id } satisfies IDiscussionboardAdmin.IRequest,
  });
  typia.assert(result);
  TestValidator.equals('only userA assignment')(result.data.length)(1);
  TestValidator.equals('assignment matches userA')(result.data[0].user_id)(userA.id);

  // 4-3. Filter by userB
  result = await api.functional.discussionboard.admins.patch(connection, {
    body: { user_id: userB.id } satisfies IDiscussionboardAdmin.IRequest,
  });
  typia.assert(result);
  TestValidator.equals('only userB assignment')(result.data.length)(1);
  TestValidator.equals('assignment matches userB')(result.data[0].user_id)(userB.id);

  // 4-4. Pagination (limit=1): verify result and meta
  result = await api.functional.discussionboard.admins.patch(connection, {
    body: { limit: 1 } satisfies IDiscussionboardAdmin.IRequest,
  });
  typia.assert(result);
  TestValidator.equals('pagination limit')(result.pagination.limit)(1);
  TestValidator.equals('pagination records')(result.pagination.records)(2);
  TestValidator.equals('pagination pages')(result.pagination.pages)(2);
  TestValidator.equals('pagination data')(result.data.length)(1);

  // 4-5. Sorting (assigned_at desc): userB (latest) first
  result = await api.functional.discussionboard.admins.patch(connection, {
    body: { sort: 'assigned_at desc' } satisfies IDiscussionboardAdmin.IRequest,
  });
  typia.assert(result);
  TestValidator.equals('userB first')(result.data[0].user_id)(userB.id);
  TestValidator.equals('userA second')(result.data[1].user_id)(userA.id);

  // 5. As non-admin (userA): access denied expected
  TestValidator.error('non-admin denied')(async () => {
    await api.functional.discussionboard.admins.patch(connection, {
      body: {} satisfies IDiscussionboardAdmin.IRequest,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { IDiscussionboardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAdmin";

/**
 * Validate fetching admin assignment details by ID, including both success and error scenarios.
 *
 * 이 테스트는 /discussionboard/admins/{id} 단건 상세조회 엔드포인트의 정상 동작과
 * 다양한 에러 케이스(400/404/권한거부)를 검증합니다.
 *
 * 1. 테스트용 유저를 생성한다 (관리자 권한 부여 대상)
 * 2. 테스트용 "관리자" 역할 사용자도 생성한다 (권한 부여 주체)
 * 3. 해당 유저에 대해 관리자 권한을 부여한다 (POST /discussionboard/admins)
 * 4. GET /discussionboard/admins/{id} 로 상세조회
 *    - 응답 필드 모두 일치하는지 검증 (id, user_id, assigned_by_admin_id, assigned_at, revoked_at)
 *    - revoked_at 신규 할당시 null임을 검증
 * 5. 잘못된 UUID (포맷 위반)로 조회하면 400 에러
 * 6. 존재하지 않는(포맷은 맞는) UUID 조회 → 404 에러
 * 7. (불가피시 생략) 비관리자 접근(일반 유저)로 상세조회시 403/권한거부 발생해야 함 -
