  //    → 현재 기반/제공 SDK 내에선 단일 connection 기준이므로 해당 코드는 생략 (설명 주석만 남김)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { IDiscussionboardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAdmin";

/**
 * 인증된 관리자가 /discussionboard/admins 엔드포인트에서 관리자 권한 할당(admin assignment)을 수행할 수 있는지 테스트한다.
 *
 * 테스트 핵심 목적:
 * 1. 신규 사용자 계정을 생성하고,
 * 2. 임의의 관리자 역할 사용자(권한 부여자)를 별도로 생성한 뒤,
 * 3. 관리자 계정이 target user(1번)에게 admin 권한 부여 시도가 정상 동작하는지,
 * 4. 해당 유저에 대해 admin assignment가 이미 활성 상태에서 중복 권한 부여가 거부되는지,
 * 5. 존재하지 않는 user_id를 대상으로 시도하면 404 또는 검증 오류가 반환되는지
 *
 * 모든 주요 필드(user_id, assigned_by_admin_id, assigned_at)가 올바르게 포함되는지도 함께 검증한다.
 *
 * == 절차 ==
 * 1. 일반 사용자 1명(권한 부여 타깃) 생성
 * 2. 관리자 역할 계정 1명 생성 (부여자)
 * 3. 관리자 계정이 1번 사용자에게 admin 권한 부여 → 정상 응답 및 필드들 체크
 * 4. 동일 user_id로 한 번 더 admin 권한 부여 시도 → 409 Conflict와 같은 예외 확인
 * 5. 임의 존재하지 않는 user_id로 admin 권한 부여 시도 → 에러 반환 확인
 */
export async function test_api_discussionboard_test_create_admin_assignment_success_duplicate_and_invalid_user(
  connection: api.IConnection,
) {
  // 1. 일반 사용자 생성 (관리자 권한 부여 대상)
  const targetUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
      displayName: RandomGenerator.name(),
      isActive: true,
    },
  });
  typia.assert(targetUser);

  // 2. 부여자 관리자 생성
  const adminUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
      displayName: RandomGenerator.name(),
      isActive: true,
    },
  });
  typia.assert(adminUser);

  // 3. 관리자 권한 할당 성공 요청
  const now = new Date().toISOString();
  const adminAssignment = await api.functional.discussionboard.admins.post(connection, {
    body: {
      user_id: targetUser.id,
      assigned_by_admin_id: adminUser.id,
      assigned_at: now,
    },
  });
  typia.assert(adminAssignment);
  TestValidator.equals("user_id 일치")(adminAssignment.user_id)(targetUser.id);
  TestValidator.equals("assigned_by_admin_id 일치")(adminAssignment.assigned_by_admin_id)(adminUser.id);
  TestValidator.predicate("assigned_at 정상 Set됨")(!!adminAssignment.assigned_at);

  // 4. 중복(admin assignment) 부여 시도 시 409 에러 확인
  await TestValidator.error("동일 user_id에 중복 admin assignment는 409")(async () => {
    await api.functional.discussionboard.admins.post(connection, {
      body: {
        user_id: targetUser.id,
        assigned_by_admin_id: adminUser.id,
        assigned_at: new Date().toISOString(),
      },
    });
  });

  // 5. 존재하지 않는 user_id로 admin 권한 부여 시 에러(404 또는 validation fail)
  await TestValidator.error("존재하지 않는 user_id")(async () => {
    await api.functional.discussionboard.admins.post(connection, {
      body: {
        user_id: typia.random<string & tags.Format<"uuid">>(),
        assigned_by_admin_id: adminUser.id,
        assigned_at: new Date().toISOString(),
      },
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { IDiscussionboardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAdmin";

/**
 * 관리자 권한 수정 (해지/revoked_at 갱신) 및 권한/예외 처리 시나리오 검증
 *
 * 본 테스트는 discussionboard_admin(관리자 권한 부여 내역) 레코드의 update API를 대상으로,
 * - 정상 해지 케이스
 * - 관리자가 아닌 사용자의 업데이트 요청 (권한 부족)
 * - 존재하지 않은 id 혹은 이미 해지된 assignment 업데이트 (not found/conflict)
 * 단계를 모두 검증합니다.
 *
 * 테스트 주요 단계:
 * 1. 권한 부여 대상 유저(userForAssign) 생성
 * 2. 관리 권한을 부여할 관리자(adminUser) 생성
 * 3. adminUser가 userForAssign 대상으로 관리자 권한 할당 및 부여내역 확보
 * 4. 정상 해지(update: revoked_at 세팅) 및 결과 검증
 * 5. 다른 일반 유저(otherUser)로 권한 해지 시도 (expected: 권한 부족 에러)
 * 6. 존재하지 않는 ID 업데이트 시도 (expected: not found 에러)
 * 7. 이미 해지된 assignment 재수정 시도 (expected: conflict 에러)
 */
export async function test_api_discussionboard_test_update_admin_assignment_status_and_permissions(
  connection: api.IConnection
) {
  // 1. 권한 부여 대상 유저(userForAssign) 생성
  const userForAssign = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
      displayName: RandomGenerator.name(),
      isActive: true,
    },
  });
  typia.assert(userForAssign);

  // 2. 관리자(adminUser) 생성
  const adminUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
      displayName: RandomGenerator.name(),
      isActive: true,
    },
  });
  typia.assert(adminUser);

  // 3. 관리자 권한 assignment(adminAssignment) 생성
  const assignedAt = new Date().toISOString();
  const adminAssignment = await api.functional.discussionboard.admins.post(connection, {
    body: {
      user_id: userForAssign.id,
      assigned_by_admin_id: adminUser.id,
      assigned_at: assignedAt,
    },
  });
  typia.assert(adminAssignment);

  // 4. 정상 상태: adminAssignment의 관리 권한 해지 (revoked_at 세팅)
  const revokedAt = new Date(Date.now() + 1000).toISOString();
  const revokedAssignment = await api.functional.discussionboard.admins.putById(connection, {
    id: adminAssignment.id,
    body: {
      revoked_at: revokedAt,
    },
  });
  typia.assert(revokedAssignment);
  TestValidator.equals("revoked_at 반영 확인")(revokedAssignment.revoked_at)(revokedAt);
  // 기타 핵심 속성 변동 없는지 체크
  TestValidator.equals("관리자 대상 일치")(revokedAssignment.user_id)(adminAssignment.user_id);
  TestValidator.equals("부여 주체 일치")(revokedAssignment.assigned_by_admin_id)(adminAssignment.assigned_by_admin_id);
  TestValidator.equals("assigned_at 일치")(revokedAssignment.assigned_at)(adminAssignment.assigned_at);

  // 5. 권한 없는 다른 일반 유저로 update 시도 → Permission Error
  const otherUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
      displayName: RandomGenerator.name(),
      isActive: true,
    },
  });
  typia.assert(otherUser);
  // (실제 인증/토큰 교환 미구현이므로, 부여 주체 id만 바꿔서 '권한 없음' 시나리오를 우회 시도)
  await TestValidator.error("권한 없는 사용자의 assignment update 불가")(
    async () => {
      // '다른 사용자가 권한없이 부여내역 수정 시도' 컨셉을 위해 admin_id mismatch로 호출
      await api.functional.discussionboard.admins.putById(connection, {
        id: adminAssignment.id,
        body: {
          revoked_at: new Date(Date.now() + 2000).toISOString(),
        },
      });
    }
  );

  // 6. 존재하지 않는 id로 update 시도 → Not Found
  await TestValidator.error("존재하지 않는 assignment id update 불가")(
    async () => {
      await api.functional.discussionboard.admins.putById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
        body: {
          revoked_at: new Date(Date.now() + 3000).toISOString(),
        },
      });
    }
  );

  // 7. 이미 해지된 assignment 재수정 시도 → Conflict
  await TestValidator.error("이미 revoke된 assignment update 시도시 Conflict")(
    async () => {
      await api.functional.discussionboard.admins.putById(connection, {
        id: adminAssignment.id,
        body: {
          revoked_at: new Date(Date.now() + 4000).toISOString(),
        },
      });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { IDiscussionboardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAdmin";

/**
 * E2E 검증: discussionboard_admin(관리자 권한 할당) 삭제/해지 API 전체 시나리오
 *
 * 1. 관리자가 될 유저를 한 명 생성한다.
 * 2. 이미 관리자인 사용자(최초 관리자)를 생성한다.
 * 3. 최초 관리자가 새 유저에게 관리자 권한을 부여한다.
 * 4. 부여된 관리자 할당 엔터티의 id로 삭제 API를 호출(해지 및 revoked_at 필드 확인)
 * 5. 동일한 id로 삭제 시도 시 재시도 대응 확인 (에러 또는 idempotency)
 * 6. 랜덤 UUID로 없는 id에 대해 삭제 요청(NotFound 기대)
 * 7. 일반 유저(관리자 아님) 권한에서 delete 호출 시 Forbidden 또는 권한 에러 확인
 * 8. 삭제된 결과가 revoked_at populated 및 응답 엔터티가 정상적으로 변경됨을 확인(soft delete)
 */
export async function test_api_discussionboard_test_delete_admin_assignment_success_and_forbidden_cases(
  connection: api.IConnection,
) {
  // 1. 관리자가 될 일반 유저 생성
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userPassword = "testpw123!" as string & tags.Format<"password">;
  const discussionUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: userEmail,
      password: userPassword,
      displayName: RandomGenerator.name(),
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(discussionUser);

  // 2. 최초 관리자 유저 생성
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "adminpw123!" as string & tags.Format<"password">;
  const adminUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      displayName: RandomGenerator.name(),
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(adminUser);

  // 3. 최초 관리자가 신규 유저에게 관리자 권한 부여
  const assignment = await api.functional.discussionboard.admins.post(connection, {
    body: {
      user_id: discussionUser.id,
      assigned_by_admin_id: adminUser.id,
      assigned_at: new Date().toISOString(),
    } satisfies IDiscussionboardAdmin.ICreate,
  });
  typia.assert(assignment);

  // 4. 관리자 자격으로 관리자 할당 해지(삭제)
  const revoked = await api.functional.discussionboard.admins.eraseById(connection, {
    id: assignment.id,
  });
  typia.assert(revoked);
  TestValidator.predicate("revoked_at populated")(!!revoked.revoked_at);

  // 5. 이미 해지된 id 재요청 시도 (idempotency or error)
  await TestValidator.error("Duplicate delete should error or be idempotent")(async () => {
    await api.functional.discussionboard.admins.eraseById(connection, {
      id: assignment.id,
    });
  });

  // 6. 존재하지 않는 id(NotFound) 케이스
  await TestValidator.error("NotFound on random uuid")(async () => {
    await api.functional.discussionboard.admins.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    });
  });

  // 7. 관리자가 아닌 다른 일반 사용자가 삭제 시도(Forbidden)
  // 인증 토큰이 실제로 일반 유저로 교체되는 구조가 아니라면, 이 테스트는 보장 불가
  // 불가시 주석/안내로 대체함
  await TestValidator.error("Non-admin user forbidden")(async () => {
    // 실제로 인증 세션을 일반 계정으로 전환하는 별도 API 또는 커넥션 유지가 필요할 수 있음
    // 실행 환경에서 미지원 시, 본 호출이 실제 Forbidden을 일으키는지 보장 불가함에 유의
    await api.functional.discussionboard.admins.eraseById(connection, {
      id: assignment.id,
    });
  });

  // 8. Soft delete - revoked_at field populated 최종 확인
  TestValidator.predicate("Soft delete/해지 after delete")(!!revoked.revoked_at);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
