/**
 * Validate update (PUT) operations on report history entries, enforcing permissions, immutability, and error handling.
 *
 * Business context: Report history logs are managed by moderators/admins and must ensure audit traceability.
 * Corrections are allowed only within platform policy (e.g., correction window, errata). Operations must be rejected for unauthorized actors, finalized/locked records, or invalid IDs.
 *
 * Workflow:
 * 1. File a new report so that history actions have context.
 * 2. As a moderator, create a report history entry attached to the new report (action: "acknowledged").
 * 3. Perform a permitted update (PUT) to action and detail fields and verify the returned object reflects changes.
 * 4. Test forbidden updates:
 *    a. Simulate acting as a different (non-actor) user and attempt edit (should return 403/409 error).
 *    b. Attempt update on a non-existent report history entry (should return 404 error).
 *
 * Result: Only allowed corrections are accepted. Permissions enforced. Errors reported as designed.
 */
export async function test_api_discussionboard_test_update_report_history_log_success_and_permissions(
  connection: api.IConnection,
) {
  // 1. File a report to provide context
  const report = await api.functional.discussionboard.reports.post(connection, {
    body: typia.random<IDiscussionboardReport.ICreate>(),
  });
  typia.assert(report);

  // 2. Create a report history entry as moderator
  const initHistory = await api.functional.discussionboard.reportHistory.post(connection, {
    body: {
      report_id: report.id,
      moderator_id: typia.random<string & tags.Format<"uuid">>(),
      admin_id: null,
      action: "acknowledged",
      action_detail: "review started",
      acted_at: new Date().toISOString(),
    } satisfies IDiscussionboardReportHistory.ICreate,
  });
  typia.assert(initHistory);

  // 3. Update mutable fields (permitted/actor). Change "action" and "action_detail"
  const updateBody = {
    action: "user_banned",
    action_detail: "Upon review of logs and prior offenses, user banned.",
  } satisfies IDiscussionboardReportHistory.IUpdate;
  const updated = await api.functional.discussionboard.reportHistory.putById(connection, {
    id: initHistory.id,
    body: updateBody,
  });
  typia.assert(updated);
  TestValidator.equals("action updated")(updated.action)(updateBody.action);
  TestValidator.equals("detail updated")(updated.action_detail)(updateBody.action_detail);

  // 4.a. Forbidden: Attempt put as a different moderator (simulated; permission error expected)
  TestValidator.error("forbidden update by non-actor moderator")(() =>
    api.functional.discussionboard.reportHistory.putById(connection, {
      id: initHistory.id,
      body: {
        action: "dismissed",
        action_detail: "Unauthorised amendment attempt.",
      } satisfies IDiscussionboardReportHistory.IUpdate,
    })
  );

  // 4.b. Forbidden: Attempt to edit non-existent entry (random uuid)
  TestValidator.error("update non-existent history entry gives 404")(() =>
    api.functional.discussionboard.reportHistory.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: {
        action: "errata",
        action_detail: "Trying to update missing record for validation.",
      } satisfies IDiscussionboardReportHistory.IUpdate,
    })
  );
}

