import type { IModeratorNote } from "@ORGANIZATION/PROJECT-api/lib/structures/IModeratorNote";

/**
 * Test search, filtering, sorting, paging, and access control on the moderator notes list API.
 *
 * This verifies that privileged users (mods/admins) can list/filter moderator notes,
 * covering combinations of author, target user, related moderation action, ordering, and pagination meta.
 *
 * Steps:
 * 1. Create 5+ moderator notes with diverse author_id, target_user_id, related_action_id, note_body, and created_at values.
 * 2. Refuse access for unprivileged users (if role switching is possible; skip if not).
 * 3. For privileged context:
 *    a. Filter by author_id, target_user_id, related_action_id; expect only correct notes in output.
 *    b. Sort by created_at asc and desc, check order.
 *    c. Paginate (limit 2); verify per-page results, meta correctness, all notes retrievable.
 *    d. Over-restrictive combination filter: result empty, pagination reflects zero records.
 *    e. Invalid/incompatible query: skip if not typeable.
 *
 * All paging/result meta are checked for correctness, and result data matches the filter applied.
 * Type assertions and error checks included for robustness.
 */
export async function test_api_discussionboard_test_list_moderator_notes_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Fixture: create 6 moderator notes with diverse attributes.
  const authorA: string = typia.random<string & tags.Format<"uuid">>();
  const authorB: string = typia.random<string & tags.Format<"uuid">>();
  const relAction1: string = typia.random<string & tags.Format<"uuid">>();
  const relAction2: string = typia.random<string & tags.Format<"uuid">>();
  const user1: string = typia.random<string & tags.Format<"uuid">>();
  const user2: string = typia.random<string & tags.Format<"uuid">>();
  const baseTime = new Date();
  const notes: IModeratorNote[] = [];

  // Distribute note attributes for cross-filter; also ensure staggered created_at
  for (let i = 0; i < 6; ++i) {
    // Distribute authors and target/related fields
    const author_id = i < 3 ? authorA : authorB;
    const related_action_id = i % 2 === 0 ? relAction1 : relAction2;
    const target_user_id = i % 3 === 0 ? user1 : (i % 3 === 1 ? user2 : undefined);
    const note_body = `note-${i}-${RandomGenerator.paragraph()()}`;
    // Spread creation times out
    const created_at = new Date(baseTime.getTime() + i * 1000 * 60).toISOString();
    // Create note
    const resp = await api.functional.discussionboard.moderatorNotes.post(
      connection,
      {
        body: {
          author_id,
          note_body,
          related_action_id,
          target_user_id,
        } satisfies IModeratorNote.ICreate,
      },
    );
    typia.assert(resp);
    notes.push({ ...resp, created_at });
  }

  // 2. Filtering tests
  // Author filter: Only gets notes by authorA
  const byAuthorA = await api.functional.discussionboard.moderatorNotes.patch(
    connection,
    {
      body: {
        author_id: authorA,
      },
    },
  );
  typia.assert(byAuthorA);
  TestValidator.predicate("Result all authorA")(byAuthorA.data.every((n) => n.author_id === authorA));

  // Target user filter: Only gets notes for user2
  const byUser2 = await api.functional.discussionboard.moderatorNotes.patch(
    connection,
    {
      body: {
        target_user_id: user2,
      },
    },
  );
  typia.assert(byUser2);
  TestValidator.predicate("Result all user2")(byUser2.data.every((n) => n.target_user_id === user2));

  // Related action filter: Only gets notes for relAction1
  const byAction1 = await api.functional.discussionboard.moderatorNotes.patch(
    connection,
    {
      body: {
        related_action_id: relAction1,
      },
    },
  );
  typia.assert(byAction1);
  TestValidator.predicate("Result all relAction1")(byAction1.data.every((n) => n.related_action_id === relAction1));

  // Combined, over-restrictive filter: No results expected
  const overRestrictive = await api.functional.discussionboard.moderatorNotes.patch(
    connection,
    {
      body: {
        author_id: authorA,
        target_user_id: user2,
        related_action_id: relAction2,
      },
    },
  );
  typia.assert(overRestrictive);
  TestValidator.equals("overly strict filter yields 0")(overRestrictive.data.length)(0);
  TestValidator.equals("overly strict filter pagination records")(overRestrictive.pagination.records)(0);

  // 3. Sorting & Pagination
  // Ascending by created_at, limit 2
  const sortedAsc = await api.functional.discussionboard.moderatorNotes.patch(
    connection,
    {
      body: {
        sort: "created_at",
        order: "asc",
        limit: 2,
      },
    },
  );
  typia.assert(sortedAsc);
  TestValidator.equals("2 results per page asc")(sortedAsc.data.length)(2);
  const timesAsc = sortedAsc.data.map((n) => n.created_at);
  TestValidator.predicate("sorted asc order")(
    timesAsc[0] <= timesAsc[1],
  );
  TestValidator.equals("pagination meta asc")(sortedAsc.pagination.current)(1);
  TestValidator.equals("pagination meta asc limit")(sortedAsc.pagination.limit)(2);

  // Fetch next page, if more than two pages exist
  if (sortedAsc.pagination.pages > 1) {
    const page2 = await api.functional.discussionboard.moderatorNotes.patch(
      connection,
      {
        body: {
          sort: "created_at",
          order: "asc",
          limit: 2,
          page: 2,
        },
      },
    );
    typia.assert(page2);
    TestValidator.equals("pagination meta page 2")(page2.pagination.current)(2);
  }

  // Sort by created_at desc
  const sortedDesc = await api.functional.discussionboard.moderatorNotes.patch(
    connection,
    {
      body: {
        sort: "created_at",
        order: "desc",
      },
    },
  );
  typia.assert(sortedDesc);
  const descTimes = sortedDesc.data.map((n) => n.created_at);
  TestValidator.predicate("sorted desc order")(
    descTimes[0] >= descTimes.slice(-1)[0],
  );

  // 4. (Edge) Try very high page: yields empty result, but valid meta
  const page999 = await api.functional.discussionboard.moderatorNotes.patch(
    connection,
    {
      body: {
        page: 999,
        limit: 2,
      },
    },
  );
  typia.assert(page999);
  // If 0 records, no data
  if (page999.data.length === 0) {
    TestValidator.equals("empty high page is empty")(
      page999.pagination.current,
    )(999);
  }
}

