import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IModeratorNote } from "@ORGANIZATION/PROJECT-api/lib/structures/IModeratorNote";

/**
 * Test updating moderator/admin note content and reference fields.
 *
 * This E2E test verifies that authorized users (moderators/admins) can update the body (note_body), related moderation action, and target user references of an existing moderator note—while ensuring immutable fields (author_id) remain unchanged. It further covers edge and error cases such as reference field clearing and updates on non-existent notes.
 *
 * Business rationale: Moderator notes are part of audit/compliance records. Permitting updates for content/references meets errata and clarification needs, but the system must not allow authorship changes for audit integrity. All changes must be persisted and reflected in subsequent queries.
 *
 * Steps:
 * 1. Create a moderator note with all relevant fields (author, references)
 * 2. Update the note, changing note_body, related_action_id, and target_user_id
 * 3. Verify updates: note_body and references updated, author_id unchanged
 * 4. Null out references (set related_action_id and target_user_id to null) and confirm null persistence
 * 5. Try an idempotent update: write same values, assert no extraneous changes
 * 6. Attempt update of non-existent note – expect API/business error
 */
export async function test_api_discussionboard_test_update_moderator_note_content_and_references_by_authorized_user(
  connection: api.IConnection
) {
  // 1. Create moderator note
  const inputAuthorId = typia.random<string & tags.Format<"uuid">>();
  const inputNote: IModeratorNote.ICreate = {
    author_id: inputAuthorId,
    note_body: "Initial audit rationale by moderator.",
    related_action_id: typia.random<string & tags.Format<"uuid">>(),
    target_user_id: typia.random<string & tags.Format<"uuid">>(),
  };
  const created = await api.functional.discussionboard.moderatorNotes.post(connection, { body: inputNote });
  typia.assert(created);

  // 2. Update: change body, both references
  const updatePatch: IModeratorNote.IUpdate = {
    note_body: "Updated note body – clarification or amendment.",
    related_action_id: typia.random<string & tags.Format<"uuid">>(),
    target_user_id: typia.random<string & tags.Format<"uuid">>(),
  };
  const updated = await api.functional.discussionboard.moderatorNotes.putById(connection, {
    id: created.id,
    body: updatePatch,
  });
  typia.assert(updated);

  // 3. Assert update success
  TestValidator.equals("id unchanged after update")(updated.id)(created.id);
  TestValidator.equals("author_id is immutable on update")(updated.author_id)(inputAuthorId);
  TestValidator.equals("note_body updated")(updated.note_body)(updatePatch.note_body);
  TestValidator.equals("related_action_id updated")(updated.related_action_id)(updatePatch.related_action_id);
  TestValidator.equals("target_user_id updated")(updated.target_user_id)(updatePatch.target_user_id);

  // 4. Clear references by setting nullable fields to null
  const nullRefsPatch: IModeratorNote.IUpdate = {
    note_body: "Note body – clearing references.",
    related_action_id: null,
    target_user_id: null,
  };
  const clearedRefs = await api.functional.discussionboard.moderatorNotes.putById(connection, {
    id: created.id,
    body: nullRefsPatch,
  });
  typia.assert(clearedRefs);
  TestValidator.equals("references nulled")(clearedRefs.related_action_id)(null);
  TestValidator.equals("references nulled")(clearedRefs.target_user_id)(null);
  TestValidator.equals("author_id still immutable")(clearedRefs.author_id)(inputAuthorId);

  // 5. Idempotency: reapply same values – should succeed and persist
  const idempotentPatch: IModeratorNote.IUpdate = { ...nullRefsPatch };
  const idempotentUpdate = await api.functional.discussionboard.moderatorNotes.putById(connection, {
    id: created.id,
    body: idempotentPatch,
  });
  typia.assert(idempotentUpdate);
  TestValidator.equals("note body unchanged")(idempotentUpdate.note_body)(nullRefsPatch.note_body);
  TestValidator.equals("references remain null")(idempotentUpdate.related_action_id)(null);
  TestValidator.equals("references remain null")(idempotentUpdate.target_user_id)(null);

  // 6. Error case: update non-existent note by random id
  const randomId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("should fail for non-existent id")(async () => {
    await api.functional.discussionboard.moderatorNotes.putById(connection, {
      id: randomId,
      body: {
        note_body: "Trying to update a note that doesn't exist.",
      },
    });
  });
}

