import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IModeratorNote } from "@ORGANIZATION/PROJECT-api/lib/structures/IModeratorNote";

/**
 * 모더레이터 노트 삭제(delete) 기능 E2E 테스트
 *
 * - 작성자(모더레이터)와 관리자(Admin)가 모더레이터 노트를 정상적으로 soft-delete(삭제)할 수 있는지 검증합니다.
 * - 삭제 후 일반/비권한 사용자는 해당 노트 상세/검색/목록에서 접근할 수 없어야 하고,
 *   감사/감찰 규정에 따라 Admin은 삭제된 노트를 볼 수 있을 수 있음을 언급합니다.
 *
 * [업무 및 Validation 시나리오]
 * 1. 모더레이터 유저가 moderator note를 생성한다.
 * 2. 해당 유저(작성자)가 노트를 삭제한다 → 정상 soft-delete 및 반환 필드 검증
 * 3. 이미 삭제된 노트에 대해 재삭제 시도하면 에러가 발생해야 한다.
 * 4. 권한 없는 유저가 노트 삭제 시도를 할 경우, 권한에러가 발생해야 한다.
 * 5. Admin 역할이 노트를 생성 후 삭제를 수행 → 정상 삭제 검증
 * 6. 삭제 후에도 정책상 Admin에게 노트가 노출되는지 등은 목록/상세/검색 API 도입시 별도 추가 검증할 것
 *
 * 실제 환경은 인증 또는 토큰 기반이지만, 현 제공 API에서는 author_id 임의 지정으로 역할만 대리 구현함을 명시한다.
 */
export async function test_api_discussionboard_test_delete_moderator_note_by_author_and_by_admin(
  connection: api.IConnection,
) {
  // 1. 모더레이터(MODERATOR) 역할의 user id 준비 및 note 데이터 생성
  const moderatorId: string = typia.random<string & tags.Format<"uuid">>();
  const noteBody: string = "Moderator generated test note.";
  const note = await api.functional.discussionboard.moderatorNotes.post(connection, {
    body: {
      author_id: moderatorId,
      note_body: noteBody,
      related_action_id: null,
      target_user_id: null,
    } satisfies IModeratorNote.ICreate,
  });
  typia.assert(note);
  TestValidator.equals("author id 일치")(note.author_id)(moderatorId);

  // 2. 동일 author(작성자)로 soft-delete 시도
  const deletedByAuthor = await api.functional.discussionboard.moderatorNotes.eraseById(connection, { id: note.id });
  typia.assert(deletedByAuthor);
  TestValidator.equals("삭제된 note id 일치")(deletedByAuthor.id)(note.id);
  TestValidator.equals("삭제 author id 일치")(deletedByAuthor.author_id)(note.author_id);

  // 3. 이미 삭제된 note 재삭제 시도시 에러 발생 검증
  await TestValidator.error("이미 삭제된 노트 재삭제시 에러")(
    async () => {
      await api.functional.discussionboard.moderatorNotes.eraseById(connection, { id: note.id });
    },
  );

  // 4. 권한 없는 user(다른 임의 uuid)로 note 삭제 시도시 에러 발생 기대
