import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardReport";
import type { IDiscussionboardReportHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardReportHistory";
import type { IPageIDiscussionboardReportHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardReportHistory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Moderation/report history listing with search and pagination validation.
 *
 * This test validates that only authorized moderator or admin accounts can fetch a paginated,
 * filtered list of report history records. The following workflow is conducted:
 *
 * 1. Create a report (via /discussionboard/reports) to establish a report to relate report histories to.
 * 2. Add two report history events (via /discussionboard/reportHistories POST) for that report, with different actors/actions/dates.
 * 3. As a moderator admin (or assumed privileged connection), fetch paged list of all report histories for that report ID (should include both).
 * 4. Repeat search with filters on moderator_id, action, date range – verify correct subset is returned.
 * 5. Provide a filter that yields no results (invalid action or non-matching date).
 * 6. Provide invalid filters (e.g., bad types for IDs) – expect 400 error.
 * 7. Simulate unauthorized access (remove/alter token or use wrong role) – expect 403 error.
 * 8. For each successful response, verify data array contents match expected IDs/actions/actors; verify that metadata fields in 'pagination' are present and correct.
 * 9. All report history record fields required for auditing are present in each entry.
 */
export async function test_api_discussionboard_test_list_report_histories_with_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create a report for baseline
  const report = await api.functional.discussionboard.reports.post(connection, {
    body: typia.random<IDiscussionboardReport.ICreate>()
  });
  typia.assert(report);
  // 2. Add two report histories with distinct actors/actions/dates
  const now = new Date();
  const modId = typia.random<string & tags.Format<"uuid">>();
  const adminId = typia.random<string & tags.Format<"uuid">>();
  const firstHistory = await api.functional.discussionboard.reportHistories.post(connection, {
    body: {
      report_id: report.id,
      moderator_id: modId,
      admin_id: null,
      action: "acknowledged",
      action_detail: "Mod acknowledged initial report.",
      acted_at: now.toISOString(),
    } satisfies IDiscussionboardReportHistory.ICreate
  });
  typia.assert(firstHistory);
  const nextDate = new Date(+now + 5*60000).toISOString(); // +5 minutes
  const secondHistory = await api.functional.discussionboard.reportHistories.post(connection, {
    body: {
      report_id: report.id,
      moderator_id: null,
      admin_id: adminId,
      action: "user_banned",
      action_detail: "Admin banned offending user.",
      acted_at: nextDate,
    } satisfies IDiscussionboardReportHistory.ICreate
  });
  typia.assert(secondHistory);
  // 3. Pagination: Fetch all histories for this report
  let res = await api.functional.discussionboard.reportHistories.patch(connection, {
    body: { report_id: report.id, page: 1, limit: 10 } satisfies IDiscussionboardReportHistory.IRequest,
  });
  typia.assert(res);
  // Confirm both records are present
  TestValidator.equals("history count")(res.data.length)(2);
  const ids = res.data.map(x => x.id);
  TestValidator.predicate("all expected history IDs present")(ids.includes(firstHistory.id) && ids.includes(secondHistory.id));
  // Check audit fields and pagination metadata
  for(const rec of res.data) {
    TestValidator.predicate("record has id")(!!rec.id);
    TestValidator.predicate("record has report_id")(rec.report_id === report.id);
    TestValidator.predicate("has action/action_detail/acted_at")(!!rec.action && !!rec.action_detail && !!rec.acted_at);
  }
  TestValidator.equals("pagination meta:")(res.pagination.limit)(10);
  TestValidator.equals("pagination meta:")(res.pagination.current)(1);
  // 4. Filter by moderator_id (should match only firstHistory)
  res = await api.functional.discussionboard.reportHistories.patch(connection, {
    body: { moderator_id: modId, report_id: report.id } satisfies IDiscussionboardReportHistory.IRequest
  });
  typia.assert(res);
  TestValidator.equals("moderated only")(res.data.length)(1);
  TestValidator.equals("mod history present")(res.data[0].id)(firstHistory.id);
  // 5. Filter by action (admin only)
  res = await api.functional.discussionboard.reportHistories.patch(connection, {
    body: { action: "user_banned", report_id: report.id } satisfies IDiscussionboardReportHistory.IRequest
  });
  typia.assert(res);
  TestValidator.equals("admin filtered only")(res.data.length)(1);
  TestValidator.equals("admin history present")(res.data[0].id)(secondHistory.id);
  // 6. Date range filter (edge window: filter after secondHistory time should give no results)
  res = await api.functional.discussionboard.reportHistories.patch(connection, {
    body: { report_id: report.id, acted_from: new Date(+now + 600000).toISOString() } satisfies IDiscussionboardReportHistory.IRequest
  });
  typia.assert(res);
  TestValidator.equals("empty when filtered after window")(res.data.length)(0);
  // 7. Invalid filter (bad uuid format): expect 400
  await TestValidator.error("bad uuid triggers 400 error")(async () => {
    await api.functional.discussionboard.reportHistories.patch(connection, {
      body: { moderator_id: "not-a-uuid", report_id: report.id } as any // would cause server/type error
    });
  });
  // 8. Simulate unauthorized (connection header tamper or wrong role): expect 403
  // NOTE: In real-world E2E you would log out/switch user/deauth the connection, but we simulate w/ simulate flag.
  const unauthorizedConn = { ...connection, headers: { Authorization: "Bearer invalid" } };
  await TestValidator.error("unauthorized triggers 403 error")(async () => {
    await api.functional.discussionboard.reportHistories.patch(unauthorizedConn, {
      body: { report_id: report.id }
    });
  });
}

