import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { IDiscussionboardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoard";
import type { IPageIDiscussionboardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardBoard";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate listing of boards with pagination and filters as an admin
 *
 * This test covers the ability for an admin to retrieve a paginated and filtered list of discussion boards, confirming that:
 * - Correct board metadata (and only metadata) is returned
 * - Pagination meta is always included and accurately reflects the result set
 * - Filtering via board name and archive status works as intended (within DTO/SDK limitation)
 * - Invalid filter/pagination fields cause a 400 error
 * - Over-paginated requests return empty results with correct meta
 * - A filter with no matching records returns an empty array and valid meta
 * - Only admin users can access this endpoint; normal/unauthenticated users receive a permission error
 *
 * Steps:
 * 1. Create an admin user (for authentication)
 * 2. Create several boards with varying attributes (for filter tests)
 * 3. As admin, retrieve first page with limit N, verify meta & that correct boards are returned
 * 4. Filter by name fragment, verify only matching boards are returned
 * 5. Filter by is_archived true/false, verify correct results (to the extent supported by API/DTO)
 * 6. Request a page past the last, verify empty data & correct meta
 * 7. Use invalid filter/pagination (e.g. negative page, unsupported field), expect 400 error
 * 8. Use a filter that matches nothing, verify empty list and correct meta
 * 9. Attempt access as non-admin, verify permission error
 */
export async function test_api_discussionboard_test_list_boards_with_pagination_and_filters_as_admin(
  connection: api.IConnection,
) {
  // 1. Create admin user
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin: IDiscussionboardUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: adminEmail,
      password: "adminPassword123",
      displayName: RandomGenerator.name(),
      isActive: true,
      // avatarUrl omitted (optional)
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(admin);

  // 2. Create several boards for filter tests
  const boards: IDiscussionboardBoard[] = [];
  for (const [name, isArchived] of [
    ["Alpha Board", false],
    ["Beta Discussion", true],
    ["Gamma Forum", false],
    ["Delta Chat", false],
  ] as const) {
    const board = await api.functional.discussionboard.boards.post(connection, {
      body: {
        name,
        slug: name.toLowerCase().replace(/\s/g, "-"),
        description: RandomGenerator.paragraph()(),
      } satisfies IDiscussionboardBoard.ICreate,
    });
    typia.assert(board);
    boards.push(board);
  }

  // 3. Paginated fetch, limit 2
  {
    const resp = await api.functional.discussionboard.boards.patch(connection, {
      body: {
        page: 1,
        limit: 2,
      } satisfies IDiscussionboardBoard.IRequest,
    });
    typia.assert(resp);
    TestValidator.equals("meta present")(typeof resp.pagination)("object");
    TestValidator.equals("correct # boards")(resp.data.length)(2);
  }

  // 4. Filter by board name fragment
  {
    const fragment = "Alpha";
    const resp = await api.functional.discussionboard.boards.patch(connection, {
      body: {
        page: 1,
        limit: 10,
        name: fragment
      } satisfies IDiscussionboardBoard.IRequest,
    });
    typia.assert(resp);
    TestValidator.predicate("all returned names contain fragment")(
      resp.data.every(b => b.name.includes(fragment))
    );
  }

  // 5. Filter by archive status
  {
    for (const status of [true, false]) {
      const resp = await api.functional.discussionboard.boards.patch(connection, {
        body: {
          page: 1,
          limit: 10,
          is_archived: status
        } satisfies IDiscussionboardBoard.IRequest,
      });
      typia.assert(resp);
      TestValidator.predicate("all returned match is_archived")(
        resp.data.every(b => b.is_archived === status)
      );
    }
  }

  // 6. Over-paginated request
  {
    const resp = await api.functional.discussionboard.boards.patch(connection, {
      body: {
        page: 100,
        limit: 10,
      } satisfies IDiscussionboardBoard.IRequest,
    });
    typia.assert(resp);
    TestValidator.equals("empty data for over-page")(resp.data.length)(0);
  }

  // 7. Invalid fields - negative page
  {
    await TestValidator.error("invalid page")(() =>
      api.functional.discussionboard.boards.patch(connection, {
        body: {
          page: -1,
          limit: 2,
        } satisfies IDiscussionboardBoard.IRequest,
      })
    );
  }

  // 8. Filter matches nothing
  {
    const resp = await api.functional.discussionboard.boards.patch(connection, {
      body: {
        page: 1,
        limit: 10,
        name: "NO_BOARD_MATCHES_THIS_STRING"
      } satisfies IDiscussionboardBoard.IRequest,
    });
    typia.assert(resp);
    TestValidator.equals("no match is empty")(resp.data.length)(0);
  }

  // 9. Attempt as another (non-admin) user
  {
    const user: IDiscussionboardUser = await api.functional.discussionboard.users.post(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: "userPassword123",
        displayName: RandomGenerator.name(),
        isActive: true,
      } satisfies IDiscussionboardUser.ICreate,
    });
    typia.assert(user);
    await TestValidator.error("non-admin access denied")(() =>
      api.functional.discussionboard.boards.patch(connection, {
        body: {
          page: 1,
          limit: 2,
        } satisfies IDiscussionboardBoard.IRequest,
      })
    );
  }
}

