/**
 * Test retrieving the full metadata of a specific discussion board as an admin.
 *
 * Validates that when an admin creates a board and fetches it by ID, the API returns all atomic board metadata fields
 * (id, name, slug, description, is_archived, created_at, updated_at, etc.) properly populated, and does not include
 * unrelated child entities (threads, topics). Also verifies that field values match those at creation where expected.
 *
 * Steps:
 * 1. Create an admin user account (ensures authorization for board setup and fetch)
 * 2. Create a discussion board as admin
 * 3. Fetch the board by ID as admin
 * 4. Assert all atomic metadata fields are present and correct
 * 5. Assert no child entities (threads/topics) leak into the response
 */
export async function test_api_discussionboard_test_fetch_board_details_as_admin(
  connection: api.IConnection,
) {
  // 1. Create admin user
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: adminEmail,
      password: "SecurePw1!",
      displayName: "AdminUser",
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(adminUser);

  // 2. Create a discussion board
  const boardInput: IDiscussionboardBoard.ICreate = {
    name: "Test Board",
    slug: `board-${Date.now()}`,
    description: "This board is created by admin for detail API test.",
  };
  const createdBoard: IDiscussionboardBoard = await api.functional.discussionboard.boards.post(connection, {
    body: boardInput,
  });
  typia.assert(createdBoard);

  // 3. Fetch the board by ID as admin
  const fetchedBoard: IDiscussionboardBoard = await api.functional.discussionboard.boards.getById(connection, {
    id: createdBoard.id,
  });
  typia.assert(fetchedBoard);

  // 4. Assert all atomic metadata fields are present and correct
  TestValidator.equals("board id matches")(fetchedBoard.id)(createdBoard.id);
  TestValidator.equals("board name matches")(fetchedBoard.name)(boardInput.name);
  TestValidator.equals("board slug matches")(fetchedBoard.slug)(boardInput.slug);
  TestValidator.equals("board description matches")(fetchedBoard.description)(boardInput.description);
  TestValidator.predicate("is_archived present and boolean")(typeof fetchedBoard.is_archived === "boolean");
  TestValidator.predicate("created_at present and ISO 8601")(typeof fetchedBoard.created_at === "string" && fetchedBoard.created_at.length >= 10);
  TestValidator.predicate("updated_at present and ISO 8601")(typeof fetchedBoard.updated_at === "string" && fetchedBoard.updated_at.length >= 10);
  if ("deleted_at" in fetchedBoard)
    TestValidator.predicate("deleted_at, if present, is string or null")(
      fetchedBoard.deleted_at === null || typeof fetchedBoard.deleted_at === "string"
    );
  if ("created_by_user_id" in fetchedBoard)
    TestValidator.predicate("created_by_user_id, if present, is string or null")(
      fetchedBoard.created_by_user_id === null || typeof fetchedBoard.created_by_user_id === "string"
    );

  // 5. Assert no presence of threads/topics in atomic board fetch
  if ("threads" in fetchedBoard || "topics" in fetchedBoard) {
    throw new Error("Atomic board fetch response must not include 'threads' or 'topics' properties.");
  }
}

