import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { IDiscussionboardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoard";

/**
 * Test updating a discussion board's metadata as an admin - verifies board update, slug uniqueness, and immutability of non-editable fields.
 *
 * Business context:
 * - Only admin can update a board's metadata (name, slug, description, is_archived).
 * - Attempt updates on a pre-created board; ensure only mutable fields change, slug uniqueness is enforced, and all API contracts hold.
 *
 * Steps:
 * 1. Create an admin user (dependency)
 * 2. Create the target board (dependency)
 * 3. Update the board's metadata (change name, slug, description, is_archived)
 * 4. Verify that the update response matches expected changes
 * 5. Slug uniqueness: revert slug, then attempt duplicate slug update (should throw)
 * 6. Confirm that only the mutable fields are changed (immutables and nullables untouched)
 */
export async function test_api_discussionboard_test_update_board_with_valid_data_as_admin(
  connection: api.IConnection,
) {
  // 1. Create admin user
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const adminPassword = 'AdminP@ssw0rd!';
  const admin = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      displayName: RandomGenerator.name(),
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(admin);

  // 2. Create board (target for update)
  const boardSlug = RandomGenerator.alphaNumeric(8);
  const board = await api.functional.discussionboard.boards.post(connection, {
    body: {
      name: RandomGenerator.paragraph()(1),
      slug: boardSlug,
      description: RandomGenerator.paragraph()(2),
    } satisfies IDiscussionboardBoard.ICreate,
  });
  typia.assert(board);

  // 3. Update board metadata
  const updatedName = RandomGenerator.paragraph()(1);
  const updatedSlug = RandomGenerator.alphaNumeric(8);
  const updatedDescription = RandomGenerator.paragraph()(2);
  const updatedArchived = !board.is_archived;

  const updated = await api.functional.discussionboard.boards.putById(connection, {
    id: board.id,
    body: {
      name: updatedName,
      slug: updatedSlug,
      description: updatedDescription,
      is_archived: updatedArchived,
    } satisfies IDiscussionboardBoard.IUpdate,
  });
  typia.assert(updated);

  // 4. Assert that fields are correctly updated
  TestValidator.equals('board name updated')(updated.name)(updatedName);
  TestValidator.equals('board slug updated')(updated.slug)(updatedSlug);
  TestValidator.equals('board description updated')(updated.description)(updatedDescription);
  TestValidator.equals('is_archived toggled')(updated.is_archived)(updatedArchived);

  // 5. Assert non-editable/nullable fields unchanged
  TestValidator.equals('id not changed')(updated.id)(board.id);
  TestValidator.equals('created_by_user_id not changed')(updated.created_by_user_id)(board.created_by_user_id);
  TestValidator.equals('deleted_at not changed')(updated.deleted_at)(board.deleted_at);

  // 6. Slug uniqueness: create another board, revert slug, then fail on duplicate
  const anotherBoardSlug = RandomGenerator.alphaNumeric(8);
  const anotherBoard = await api.functional.discussionboard.boards.post(connection, {
    body: {
      name: RandomGenerator.paragraph()(1),
      slug: anotherBoardSlug,
      description: RandomGenerator.paragraph()(2),
    } satisfies IDiscussionboardBoard.ICreate,
  });
  typia.assert(anotherBoard);

  // Revert updated board's slug to previous unique value (should succeed)
  const reverted = await api.functional.discussionboard.boards.putById(connection, {
    id: board.id,
    body: {
      slug: boardSlug,
    },
  });
  typia.assert(reverted);
  TestValidator.equals('board slug reverted')(reverted.slug)(boardSlug);

  // Attempt to update slug to anotherBoard's slug (should error with uniqueness violation)
  await TestValidator.error('duplicate slug should fail')(async () => {
    await api.functional.discussionboard.boards.putById(connection, {
      id: board.id,
      body: {
        slug: anotherBoardSlug,
      },
    });
  });
}

