 * does not cause incorrect changes to board data.
 *
 * Business context: Slugs are used in board URLs for SEO and navigation, so they must remain unique. Admins or automation
 * must not be able to assign a slug already taken by another board. A failed update to a duplicate slug should leave all
 * data intact.
 *
 * Steps:
 * 1. Register an admin user (since only admins can create/update boards).
 * 2. Create two boards with unique names and slugs.
 * 3. Attempt to update board A's slug to board B's slug via PUT /discussionboard/boards/{id}. Expect a conflict error.
 * 4. Verify that both board A and B retain their original slugs and no change is made due to the failed update.
 */
export async function test_api_discussionboard_test_update_board_with_duplicate_slug(
  connection: api.IConnection,
) {
  // 1. Register an admin user (simulate; no explicit admin flag on DTO, but boards are admin-only)
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword = "P@ssw0rd!";
  const admin = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      displayName: RandomGenerator.name(),
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(admin);

  // 2. Create two unique boards
  const slugA = RandomGenerator.alphaNumeric(10);
  const slugB = RandomGenerator.alphaNumeric(10) + "b"; // Ensure different
  const boardA = await api.functional.discussionboard.boards.post(connection, {
    body: {
      name: RandomGenerator.name(),
      slug: slugA,
      description: RandomGenerator.paragraph()(),
    } satisfies IDiscussionboardBoard.ICreate,
  });
  typia.assert(boardA);
  const boardB = await api.functional.discussionboard.boards.post(connection, {
    body: {
      name: RandomGenerator.name(),
      slug: slugB,
      description: RandomGenerator.paragraph()(),
    } satisfies IDiscussionboardBoard.ICreate,
  });
  typia.assert(boardB);

  // 3. Try to update boardA's slug to duplicate value (slugB). Expect API error (validation or conflict)
  await TestValidator.error("duplicate slug conflict")(() =>
    api.functional.discussionboard.boards.putById(connection, {
      id: boardA.id,
      body: {
        slug: boardB.slug,
      } satisfies IDiscussionboardBoard.IUpdate,
    })
  );

  // 4. Validate that previous board info is unchanged (local variable check since API has no board GET endpoint)
  TestValidator.equals("Board A slug unchanged")(boardA.slug)(slugA);
  TestValidator.equals("Board B slug unchanged")(boardB.slug)(slugB);
}

