/**
 * Test listing discussion threads with invalid filter parameters to ensure API validation.
 *
 * This test case demonstrates that the /discussionboard/threads PATCH endpoint strictly enforces
 * schema validation for incoming filter/search requests. It ensures that both the presence of
 * non-existent properties and incorrect property data types in the request body result in a
 * 400 Bad Request error, and the request is rejected, maintaining contract integrity.
 *
 * This test is important for solidifying input validation boundaries: it prevents untyped or
 * loosely-validated queries from reaching business logic, protects internal data consistency,
 * and upholds a trustworthy API for consumers. It tests server-side runtime validation—not
 * TypeScript compile-time errors.
 *
 * Steps:
 * 1. Register a user to act as an authenticated context, using /discussionboard/users (POST).
 * 2. Test PATCH /discussionboard/threads with:
 *    a. An extra non-existent property
 *    b. A known property with the wrong data type
 * 3. Assert both attempts trigger 400 validation errors.
 *    (Do not validate error body, just that the error occurs at runtime.)
 */
export async function test_api_discussionboard_test_search_threads_with_invalid_parameters(
  connection: api.IConnection,
) {
  // 1. Register a valid user (required context)
  const user = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
