  await TestValidator.error("should reject non-existent parameter")(() =>
    api.functional.discussionboard.threads.patch(connection, {
      // Intentionally insert 'foo' (not in schema) to provoke runtime validation error
      body: { foo: "bar" } as any,
    }),
  );

  // 2b. Attempt to filter threads using wrong data type: order_by expects string/null, supply a number
  await TestValidator.error("should reject wrong data type for property")(() =>
