import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { IDiscussionboardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoard";
import type { IDiscussionboardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThread";

/**
 * 토론 스레드 ID로 전체 세부 정보를 조회하는 E2E 테스트입니다.
 *
 * - 실제 사용자가 토론 thread를 만들고(thread 생성), 해당 thread의 id로 상세 내용을 GET API로 조회하면,
 *   반환된 값이 thread 생성 시 정보 및 시스템 자동 생성 메타데이터(생성일, 생성자 등)를 정확히 반영하는지 검증합니다.
 * - Thread 생성 및 조회 권한이 있는 정상 사용자 시나리오를 가정합니다.
 *
 * 테스트 단계:
 * 1. 신규 사용자를 등록한다.
 * 2. 등록된 사용자가 새로운 Discussion Board(게시판)를 생성한다.
 * 3. 위 게시판에 속하게 thread를 생성한다.
 * 4. thread의 id로 상세 조회 API를 호출한다.
 * 5. 조회 결과 주요 필드 및 시스템 부여(생성자, 날짜 등) 메타데이터까지 모두 동일한지 검증한다.
 */
export async function test_api_discussionboard_test_get_thread_details_by_id_when_thread_exists(
  connection: api.IConnection,
) {
  // 1. 사용자 계정 등록
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userPassword = typia.random<string & tags.Format<"password">>();
  const userDisplayName = RandomGenerator.name();
  const user = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: userEmail,
      password: userPassword,
      displayName: userDisplayName,
      isActive: true,
    },
  });
  typia.assert(user);

  // 2. 게시판(Discussion Board) 생성
  const boardName = RandomGenerator.paragraph()(3);
  const boardSlug = RandomGenerator.alphaNumeric(8).toLowerCase();
  const boardDescription = RandomGenerator.paragraph()(1);
  const board = await api.functional.discussionboard.boards.post(connection, {
    body: {
      name: boardName,
      slug: boardSlug,
      description: boardDescription,
    },
  });
  typia.assert(board);

  // 3. Thread 생성 (해당 board에 등록)
  const threadTitle = RandomGenerator.paragraph()(1);
  const threadSlug = RandomGenerator.alphaNumeric(10).toLowerCase();
  const threadCreateInput = {
    board_id: board.id,
    title: threadTitle,
    slug: threadSlug,
    is_pinned: false,
    is_locked: false,
  } satisfies IDiscussionboardThread.ICreate;
  const createdThread = await api.functional.discussionboard.threads.post(connection, {
    body: threadCreateInput,
  });
  typia.assert(createdThread);

  // 4. 생성한 Thread를 id로 상세 조회
  const fetchedThread = await api.functional.discussionboard.threads.getById(connection, {
    id: createdThread.id,
  });
  typia.assert(fetchedThread);

  // 5. 주요 필드 및 메타데이터 값 동등 검증
  TestValidator.equals("id matches")(fetchedThread.id)(createdThread.id);
  TestValidator.equals("board_id matches")(fetchedThread.board_id)(createdThread.board_id);
  TestValidator.equals("title matches")(fetchedThread.title)(createdThread.title);
  TestValidator.equals("slug matches")(fetchedThread.slug)(createdThread.slug);
  TestValidator.equals("is_pinned matches")(fetchedThread.is_pinned)(createdThread.is_pinned);
  TestValidator.equals("is_locked matches")(fetchedThread.is_locked)(createdThread.is_locked);

  // 시스템이 자동 부여하는 메타데이터 및 상태 검증
  TestValidator.equals("created_by_user_id matches")(fetchedThread.created_by_user_id)(createdThread.created_by_user_id);
  TestValidator.equals("created_at ISO8601")(typeof fetchedThread.created_at === "string" && fetchedThread.created_at.length > 0)(true);
  TestValidator.equals("updated_at ISO8601")(typeof fetchedThread.updated_at === "string" && fetchedThread.updated_at.length > 0)(true);
  TestValidator.equals("is_deleted 초기값 false")(fetchedThread.is_deleted)(false);
  TestValidator.equals("deleted_at null or undefined")(fetchedThread.deleted_at == null)(true);
  TestValidator.equals("topic_id null or undefined")(fetchedThread.topic_id == null)(true);
  TestValidator.equals("deleted_by_user_id null or undefined")(fetchedThread.deleted_by_user_id == null)(true);
}

