/**
 * Validate that thread creation fails in an archived board.
 *
 * This test ensures the business rule: when a board is archived (is_archived), creation of new threads must be rejected.
 *
 * Steps:
 * 1. Create a discussionboard_user who attempts the thread creation.
 * 2. Create a discussionboard_board (forum) using valid parameters.
 * 3. Update the board so it is in an archived state (set is_archived=true).
 * 4. Attempt to create a thread on this board as the user - expect a runtime error/business rejection and no thread creation.
 *
 * Validates that system enforces posting restrictions for archived boards.
 */
export async function test_api_discussionboard_test_create_thread_in_locked_or_archived_board(connection: api.IConnection) {
  // 1. Create the user who will attempt to create the thread
  const user = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(12),
      displayName: RandomGenerator.name(),
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(user);

  // 2. Create a new board
  const board = await api.functional.discussionboard.boards.post(connection, {
    body: {
      name: RandomGenerator.paragraph()(1),
      slug: RandomGenerator.alphaNumeric(12),
      description: RandomGenerator.paragraph()(),
    } satisfies IDiscussionboardBoard.ICreate,
  });
  typia.assert(board);

  // 3. Archive the board by updating its is_archived flag
