    id: board.id,
    body: {
      is_archived: true,
    } satisfies IDiscussionboardBoard.IUpdate,
  });
  typia.assert(archivedBoard);
  TestValidator.equals("archived flag")(archivedBoard.is_archived)(true);

  // 4. Attempt to create a thread in an archived board - should raise an error
  await TestValidator.error("cannot post in archived board")(async () => {
    await api.functional.discussionboard.threads.post(connection, {
      body: {
        board_id: archivedBoard.id,
        title: RandomGenerator.paragraph()(1),
        slug: RandomGenerator.alphaNumeric(10),
      } satisfies IDiscussionboardThread.ICreate,
    });
  });
}

