/**
 * Validate unique slug enforcement for threads within a discussion board.
 *
 * This E2E test ensures that the API does not allow two threads with the same slug within the same board,
 * enforcing unambiguous navigation and preventing URL or thread collisions.
 *
 * Steps:
 * 1. Register a new user (required for board & thread creation).
 * 2. Create a board as that user.
 * 3. Create a thread in that board with a known slug.
 * 4. Attempt to create a second thread in the same board with the same slug (should fail).
 * 5. Optionally, create a thread in a different board with the same slug (should succeed), confirming uniqueness is board-scoped.
 */
export async function test_api_discussionboard_test_create_thread_with_duplicate_slug(
  connection: api.IConnection,
) {
  // 1. Register a new user
  const userInput: IDiscussionboardUser.ICreate = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "Pa$$w0rd!",
    displayName: RandomGenerator.name(),
  };
  const user = await api.functional.discussionboard.users.post(connection, { body: userInput });
  typia.assert(user);

  // 2. Create a board as that user
  const boardSlug = RandomGenerator.alphaNumeric(16);
  const boardInput: IDiscussionboardBoard.ICreate = {
    name: RandomGenerator.paragraph()(1),
    slug: boardSlug,
    description: RandomGenerator.content()(1)(1),
  };
  const board = await api.functional.discussionboard.boards.post(connection, { body: boardInput });
  typia.assert(board);

  // 3. Create a thread in that board with a known slug
  const threadSlug = RandomGenerator.alphaNumeric(12);
  const threadInput: IDiscussionboardThread.ICreate = {
    board_id: board.id,
    title: "Original thread title",
    slug: threadSlug,
  };
  const thread1 = await api.functional.discussionboard.threads.post(connection, { body: threadInput });
  typia.assert(thread1);

  // 4. Attempt to create a second thread in the same board with the same slug (should fail)
  const threadInputDuplicate: IDiscussionboardThread.ICreate = {
    board_id: board.id,
    title: "Duplicate slug thread title",
    slug: threadSlug, // Same slug as previous
  };
  await TestValidator.error("Should not allow duplicate thread slug in the same board")(
    async () => {
      await api.functional.discussionboard.threads.post(connection, { body: threadInputDuplicate });
