  // 5. As owner, lock the thread
  await api.functional.discussionboard.threads.putById(connection, {
    id: thread.id,
    body: { is_locked: true } satisfies IDiscussionboardThread.IUpdate,
  });

  // 6. Try to update locked thread (should fail)
  TestValidator.error("Locked thread update forbidden")(
    async () => {
      await api.functional.discussionboard.threads.putById(connection, {
        id: thread.id,
        body: { title: "Edit while locked" } satisfies IDiscussionboardThread.IUpdate,
      });
    },
  );

  // 7. Simulate thread deletion (system-managed is_deleted flag); then test update after deletion
  // (Direct delete API is not present, so step is limited to input simulation)
