import type { IDiscussionboardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThread";

/**
 * 비소유자, 잠금(locked), 삭제된(soft delete) 상태 및 존재하지 않는 id에 대해 토론 스레드 삭제 시 의도대로 금지/에러 반환 동작을 검증한다.
 *
 * - 비소유자 권한 없는 삭제 forbidden
 * - 잠금상태 스레드 forbidden
 * - 이미 삭제된 스레드 삭제 not found/conflict
 * - 무효 id 삭제 not found
 *
 * 모든 예외 케이스에서 TestValidator.error(...)를 사용해 에러가 실제 발생하는지 검증한다.
 * 실제 사용자의 로그인 세션/토큰 분리는 API에서는 미제공이라, 각 유저별 로직을 구분해 논리적으로 시나리오를 표현한다.
 *
 * [테스트 단계]
 * 1. 스레드 소유자 A, 비소유자 B 각각 회원가입
 * 2. Board 1개 생성
 * 3. A로 스레드 1개 생성
 * 4. 비소유자 B가 삭제 시도: 일반/잠금/삭제됨/없는 id 모두 error 검증
 *    (is_locked 상태 변화는 update API로, 삭제는 eraseById API로 처리)
 */
export async function test_api_discussionboard_test_delete_thread_by_non_owner_or_when_locked(
  connection: api.IConnection,
) {
  // 1. 스레드 소유자 A 회원가입
  const userAEmail = typia.random<string & tags.Format<"email">>();
  const userA = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: userAEmail,
      password: "TestPassw0rd!",
      displayName: RandomGenerator.name(),
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(userA);

  // 2. 비소유자 B 회원가입
  const userBEmail = typia.random<string & tags.Format<"email">>();
  const userB = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: userBEmail,
      password: "TestPassw0rd!",
      displayName: RandomGenerator.name(),
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(userB);

  // 3. Board 1개 생성
  const board = await api.functional.discussionboard.boards.post(connection, {
    body: {
      name: RandomGenerator.name(),
      slug: RandomGenerator.alphaNumeric(12),
      description: RandomGenerator.paragraph()(),
    } satisfies IDiscussionboardBoard.ICreate,
  });
  typia.assert(board);

  // 4. A가 스레드 1개 생성
  const thread = await api.functional.discussionboard.threads.post(connection, {
    body: {
      board_id: board.id,
      title: RandomGenerator.paragraph()(),
      slug: RandomGenerator.alphaNumeric(12),
    } satisfies IDiscussionboardThread.ICreate,
  });
  typia.assert(thread);

  // 5. 비소유자 B가 일반 스레드 삭제 시도 → forbidden 검증
  TestValidator.error("비소유자 삭제 forbidden")(() =>
    api.functional.discussionboard.threads.eraseById(connection, {
      id: thread.id,
    }),
  );

  // 6. 스레드 잠금(is_locked) 상태로 변경
  const locked = await api.functional.discussionboard.threads.putById(connection, {
    id: thread.id,
    body: { is_locked: true } satisfies IDiscussionboardThread.IUpdate,
  });
  typia.assert(locked);

  // 잠금 스레드 삭제 시도 → forbidden
  TestValidator.error("비소유자 잠금 스레드 삭제 forbidden")(() =>
    api.functional.discussionboard.threads.eraseById(connection, {
      id: thread.id,
    }),
  );

  // 7. (테스트를 위해) 소유자 A가 실제 삭제 처리
  await api.functional.discussionboard.threads.eraseById(connection, {
    id: thread.id,
  });

  // 이미 삭제된 스레드 삭제 시도 → not found/conflict
  TestValidator.error("이미 삭제된 스레드 삭제 not found/conflict")(() =>
    api.functional.discussionboard.threads.eraseById(connection, {
      id: thread.id,
    }),
  );

  // 8. 존재하지 않는 임의 uuid로 삭제 시도 → not found
  TestValidator.error("존재하지 않는 id 삭제 not found")(() =>
    api.functional.discussionboard.threads.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
