 * - Only moderators/admins can create moderation actions (permission enforcement)
 * - All required fields must be present and valid (400 errors for validation issues)
 * - References to real users/posts are needed (invalid refs = error)
 * - Successful creation returns correct moderation action details/metadata
 *
 * Step-by-step:
 * 1. Register 3 users: Admin, Moderator, Regular User
 * 2. Create a post using the regular user (target of moderation)
 * 3. Admin creates a moderation action for the post (success)
 * 4. Regular user tries to create a moderation action (fail/403)
 * 5. Moderator creates a moderation action (success)
 * 6. Try to create moderation action referencing non-existent user (fail/400)
 */
export async function test_api_discussionboard_test_create_moderation_action_success_and_validation(
  connection: api.IConnection,
) {
  // 1. Register users (admin, moderator, regular user)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: adminEmail,
      password: "adminSecret123!",
