      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(admin);

  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: moderatorEmail,
      password: "moderatorSecret123!",
      displayName: "Moderator User",
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(moderator);

  const regularUserEmail = typia.random<string & tags.Format<"email">>();
  const regularUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: regularUserEmail,
      password: "regularSecret123!",
      displayName: "Regular User",
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(regularUser);

  // 2. Regular user creates a post (for content to moderate)
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: {
      thread_id: threadId,
      content: "This is the post content to be moderated.",
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // 3. Admin creates a moderation action targeting user/post (success)
  const moderationAction = await api.functional.discussionboard.moderationActions.post(connection, {
    body: {
      actor_moderator_id: admin.id,
      target_user_id: regularUser.id,
      post_id: post.id,
      comment_id: null,
      report_id: null,
      action_type: "delete",
      action_reason: "User violated guidelines in post.",
