  TestValidator.equals("post_id")(moderationAction.post_id)(post.id);
  TestValidator.equals("target_user_id")(moderationAction.target_user_id)(regularUser.id);
  TestValidator.equals("action_type")(moderationAction.action_type)("delete");
  TestValidator.equals("action_reason")(moderationAction.action_reason)("User violated guidelines in post.");

  // 4. Regular user tries to create moderation action (fail/403)
  TestValidator.error("Regular user cannot create moderation action")(
    async () => {
      await api.functional.discussionboard.moderationActions.post(connection, {
        body: {
          actor_moderator_id: regularUser.id,
          target_user_id: null,
          post_id: post.id,
          comment_id: null,
          report_id: null,
          action_type: "restore",
          action_reason: "Trying to escalate privilege.",
        } satisfies IDiscussionboardModerationAction.ICreate,
      });
    }
  );

  // 5. Moderator creates a moderation action (success)
  const modAction = await api.functional.discussionboard.moderationActions.post(connection, {
    body: {
      actor_moderator_id: moderator.id,
      target_user_id: regularUser.id,
      post_id: post.id,
      comment_id: null,
      report_id: null,
      action_type: "warn",
      action_reason: "Warning for off-topic content.",
    } satisfies IDiscussionboardModerationAction.ICreate,
  });
