  TestValidator.equals("actor_moderator_id")(modAction.actor_moderator_id)(moderator.id);
  TestValidator.equals("action_type")(modAction.action_type)("warn");
  TestValidator.equals("action_reason")(modAction.action_reason)("Warning for off-topic content.");

  // 6. Non-existent target_user_id (fail/400)
  TestValidator.error("Non-existent user id for target_user_id should 400")(
    async () => {
      await api.functional.discussionboard.moderationActions.post(connection, {
        body: {
          actor_moderator_id: moderator.id,
          target_user_id: typia.random<string & tags.Format<"uuid">>(),
          post_id: post.id,
          comment_id: null,
          report_id: null,
          action_type: "ban",
          action_reason: "Attempt to ban a non-existent user.",
        } satisfies IDiscussionboardModerationAction.ICreate,
      });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
