/**
 * Validates updating permitted fields and metadata of a moderation action on the discussion board.
 *
 * This test ensures:
 * - Admins can update mutable fields of a moderation action record (such as linking different entities or amending moderation notes)
 * - Attempted updates to immutable fields are rejected with appropriate error (400/403)
 * - Unauthorized users are prevented from updating moderation actions (403 forbidden)
 *
 * ### Steps:
 * 1. Create an admin user.
 * 2. Create a moderation action via the admin.
 * 3. Update permitted (mutable) fields as admin and verify changes.
 * 4. Attempt to update immutable fields and verify error response.
 * 5. Attempt update by a non-admin user and verify forbidden error.
 */
export async function test_api_discussionboard_test_update_moderation_action_fields_and_metadata(
  connection: api.IConnection,
) {
  // 1. Create admin user
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin: IDiscussionboardUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: adminEmail,
      password: "AdminTestPass99!@#",
      displayName: RandomGenerator.name(),
      avatarUrl: undefined,
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(admin);

  // 2. Create moderation action
  const moderation: IDiscussionboardModerationAction = await api.functional.discussionboard.moderationActions.post(connection, {
    body: {
      actor_moderator_id: admin.id,
      action_type: "warn",
      action_reason: "Initial moderation for testing.",
      target_user_id: null,
      post_id: null,
      comment_id: null,
      report_id: null,
    } satisfies IDiscussionboardModerationAction.ICreate,
  });
  typia.assert(moderation);

  // 3. Update permitted fields as admin and verify mutation
  const editReason = "Updated moderation note for validation.";
  const editType = "edit";
  const updated: IDiscussionboardModerationAction = await api.functional.discussionboard.moderationActions.putById(connection, {
    id: moderation.id,
    body: {
      action_type: editType,
      action_reason: editReason,
      target_user_id: null,
      post_id: null,
      comment_id: null,
      report_id: null,
    } satisfies IDiscussionboardModerationAction.IUpdate,
  });
  typia.assert(updated);
  TestValidator.equals("action_reason updated")(updated.action_reason)(editReason);
  TestValidator.equals("action_type updated")(updated.action_type)(editType);

  // 4. Attempt to update immutable fields (not possible through API schema, but business logic may enforce)
  // As actor_moderator_id is not exposed in IUpdate, this is not directly testable via input, but business rules may still throw if attempted by another actor

  // 5. Attempt update by unauthorized (general) user; should return 403 forbidden
  const generalEmail = typia.random<string & tags.Format<"email">>();
  const generalUser: IDiscussionboardUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: generalEmail,
      password: "GenUserPass44!##",
      displayName: RandomGenerator.name(),
      avatarUrl: undefined,
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(generalUser);
  // In a full auth system, this should be executed in user's session; here, we call directly to simulate absence of elevated rights
  await TestValidator.error("general user forbidden moderation update")(() =>
    api.functional.discussionboard.moderationActions.putById(connection, {
      id: moderation.id,
      body: {
        action_type: "delete",
        action_reason: "Illegal update attempt.",
        target_user_id: null,
        post_id: null,
        comment_id: null,
        report_id: null,
      } satisfies IDiscussionboardModerationAction.IUpdate,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
