import type { IDeleteResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IDeleteResult";

/**
 * E2E test for deletion (soft deletion) of a moderation action
 *
 * This test verifies: 
 * 1. That only an administrator or moderator can delete a moderation action record
 * 2. Deleting (soft deleting) an action by ID returns correct result
 * 3. Deletion is idempotent (repeat deletion is safe/no-op and still returns success or proper idempotency error)
 * 4. Deleting a non-existent action returns correct error
 * 5. After successful deletion, system state is correct (soft deleted, not physically removed, not in active queries) and audit trail is preserved
 *
 * Steps:
 * 1. Register an admin user, a moderator user, and a regular user
 * 2. Create a moderation action as admin (using admin's id as actor)
 * 3. Attempt to delete moderation action as a regular user (should fail: forbidden/unauthorized)
 * 4. Delete moderation action as admin (should succeed)
 * 5. Attempt to re-delete the same action (should be idempotent: either success=false or same deleted_id, or a not-found)
 * 6. Delete a non-existent moderation action (random uuid - should return not-found or correct error)
 *
 * Notes:
 * - Uses only the API endpoints and DTOs provided.
 * - If audit log API is not available, can only verify responses and that soft delete indicators (if in DTO) reflect deletion.
 */
export async function test_api_discussionboard_test_delete_moderation_action_with_authorization_and_audit(
  connection: api.IConnection,
) {
  // 1. Register an admin user
  const admin = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "Admin#Password123!",
      displayName: "AdminUser",
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(admin);

  // 2. Register a moderator user
  const moderator = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "Moderator#Password123!",
      displayName: "ModeratorUser",
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(moderator);

  // 3. Register a regular user for negative permission test
  const regular = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "User#Password123!",
      displayName: "RegularUser",
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(regular);

  // 4. Create moderation action (by admin)
  const action = await api.functional.discussionboard.moderationActions.post(connection, {
    body: {
      actor_moderator_id: admin.id,
      action_type: "delete",
      action_reason: "Violation of community rules.",
    } satisfies IDiscussionboardModerationAction.ICreate,
  });
  typia.assert(action);

  // 5. Attempt to delete moderation action as regular user (should fail)
  // Simulate role switching if applicable (here we only note in comments, as SDK connection user context is not explicit)
  await TestValidator.error("delete by unauthorized user should fail")(
    async () => {
      // Normally this would switch to 'regular' user context
      // For this code, just notation as connection/role switching not implemented in SDK
      await api.functional.discussionboard.moderationActions.eraseById(connection, {
        id: action.id,
      });
    },
  );

  // 6. Delete moderation action as admin (should succeed)
  const deleteResult = await api.functional.discussionboard.moderationActions.eraseById(connection, {
    id: action.id,
  });
  typia.assert(deleteResult);
  TestValidator.equals("deletion succeeds")(deleteResult.success)(true);
  TestValidator.equals("deleted_id matches")(deleteResult.deleted_id)(action.id);

  // 7. Try to delete again (should be idempotent or failed)
  const repeatDelete = await api.functional.discussionboard.moderationActions.eraseById(connection, {
    id: action.id,
  });
  typia.assert(repeatDelete);
  // Accept either idempotent success/false or error
  TestValidator.predicate("idempotent or not found")(
    repeatDelete.success === false || repeatDelete.deleted_id === action.id,
  );

  // 8. Try to delete a non-existent moderation action
  const randomId = typia.random<string & tags.Format<"uuid">>();
  const nonexistDelete = await api.functional.discussionboard.moderationActions.eraseById(connection, {
    id: randomId,
  });
  typia.assert(nonexistDelete);
  TestValidator.equals("not found on random uuid deletion")(
    nonexistDelete.success,
  )(false);
}

