  // 2. admin이 여러 유저에 역할/케이스별로 assignment 생성
  const now = new Date();
  const assignments = [
    // adminUser: admin 부여(활성)
    {
      user_id: adminUser.id,
      assigned_by_admin_id: adminUser.id,
      role: "admin",
      assigned_at: now.toISOString(),
      revoked_at: null,
    },
    // moderatorUser: moderator 부여(활성)
    {
      user_id: moderatorUser.id,
      assigned_by_admin_id: adminUser.id,
      role: "moderator",
      assigned_at: new Date(now.getTime() - 60000).toISOString(),
