    },
    // normalUser: user 부여(활성)
    {
      user_id: normalUser.id,
      assigned_by_admin_id: adminUser.id,
      role: "user",
      assigned_at: new Date(now.getTime() - 120000).toISOString(),
      revoked_at: null,
    },
    // normalUser: moderator 롤 과거 부여 후 해지
    {
      user_id: normalUser.id,
      assigned_by_admin_id: adminUser.id,
      role: "moderator",
      assigned_at: new Date(now.getTime() - 180000).toISOString(),
      revoked_at: new Date(now.getTime() - 60000).toISOString(),
    },
