  );

  // 4. role별 필터: moderator
  result = await api.functional.discussionboard.roleAssignments.patch(connection, {
    body: { role: "moderator", page: 1 },
  });
  typia.assert(result);
  TestValidator.predicate("role filter matches only moderator role")(
    result.data.every((r) => r.role === "moderator"),
  );

  // 5. 활성/해지별 상태 필터
  // a) 활성(미해지)
  let statusActive = await api.functional.discussionboard.roleAssignments.patch(connection, {
    body: { is_revoked: false, page: 1 },
  });
  typia.assert(statusActive);
  TestValidator.predicate("is_revoked=false returns only active assignments")(
    statusActive.data.every((r) => !r.revoked_at),
  );
  // b) 해지된 것만 반환
  let statusRevoked = await api.functional.discussionboard.roleAssignments.patch(connection, {
    body: { is_revoked: true, page: 1 },
  });
  typia.assert(statusRevoked);
  TestValidator.predicate("is_revoked=true returns only revoked assignments")(
    statusRevoked.data.every((r) => r.revoked_at !== null && r.revoked_at !== undefined),
  );

  // 6. 페이징/정렬(limit/page/sort)
  const limit = 2;
  const sorted = await api.functional.discussionboard.roleAssignments.patch(connection, {
    body: { sort: "assigned_at desc", limit, page: 1 },
  });
  typia.assert(sorted);
  TestValidator.equals("paging limit correct")(sorted.data.length)(Math.min(limit, sorted.pagination.records));

  // 7. 존재하지 않는 user_id
  const unknownUser = typia.random<string & tags.Format<"uuid">>();
  const emptyResult = await api.functional.discussionboard.roleAssignments.patch(connection, {
    body: { user_id: unknownUser, page: 1 },
  });
  typia.assert(emptyResult);
  TestValidator.equals("not found user_id returns empty array")(emptyResult.data.length)(0);
  TestValidator.equals("not found user_id returns pagination record 0")(emptyResult.pagination.records)(0);

  // 8. 없는 페이지/limit
  const outOfBounds = await api.functional.discussionboard.roleAssignments.patch(connection, {
    body: { page: 100, limit, user_id: adminUser.id },
  });
  typia.assert(outOfBounds);
  TestValidator.equals("out-of-bounds page returns empty array")(outOfBounds.data.length)(0);

  // 9. 잘못된 page 파라미터(음수)
  await TestValidator.error("invalid page parameter triggers error")(async () => {
    await api.functional.discussionboard.roleAssignments.patch(connection, {
      body: { page: -1 },
    });
  });

  // 10. 타입 위반/없는 필드(불가) → 타입상 구현 불가, omit
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { IDiscussionboardRoleAssignment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardRoleAssignment";

/**
 * 토론 게시판 역할 할당 상세 정보 조회 E2E 테스트.
 *
 * - 관리자(admin)가 실제 존재하는 역할 할당(assignment) id로 상세정보를 정상 요청 시 정확한 정보가 반환되는지 검증
 * - 존재하지 않는 랜덤 id로 요청하면 404 Not Found 에러가 발생하는지 검증
 * - 일반 사용자가 접근했을 때 권한 거부(가능 시)를 검증; API의 실제 인증/권한 정책에 따라 추가 가능
 *
 * 테스트 세부 단계
 * 1. 관리자 계정 생성 (discussionboard/users POST)
 * 2. 일반 유저 계정 생성 (discussionboard/users POST)
 * 3. 관리자가 일반유저에게 'moderator' 역할 할당 생성 (discussionboard/roleAssignments POST)
 * 4. 관리자가 방금 생성한 역할 할당 id로 상세조회 (정상 반환)
 * 5. 존재하지 않는 랜덤 UUID로 상세조회 요청 후 404 오류 검증
 * 6. (가능 시) 일반유저로 접근 시도 시 권한 거부 여부 확인
 */
export async function test_api_discussionboard_test_get_role_assignment_success_and_not_found(
  connection: api.IConnection,
) {
  // 1. 관리자 계정 생성
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "test-Admin1!";
  const admin: IDiscussionboardUser = await api.functional.discussionboard.users.post(
    connection,
    {
      body: {
        email: adminEmail,
        password: adminPassword,
        displayName: RandomGenerator.name(),
        isActive: true,
      } satisfies IDiscussionboardUser.ICreate,
    },
  );
  typia.assert(admin);

  // 2. 일반 유저 계정 생성
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userPassword = "test-User1!";
  const user: IDiscussionboardUser = await api.functional.discussionboard.users.post(
    connection,
    {
      body: {
        email: userEmail,
        password: userPassword,
        displayName: RandomGenerator.name(),
        isActive: true,
      } satisfies IDiscussionboardUser.ICreate,
    },
  );
  typia.assert(user);

  // 3. 관리자가 일반유저에게 'moderator' 역할 부여
  const assignment: IDiscussionboardRoleAssignment = await api.functional.discussionboard.roleAssignments.post(
    connection,
    {
      body: {
        user_id: user.id,
        assigned_by_admin_id: admin.id,
        role: "moderator",
        assigned_at: new Date().toISOString(),
        // revoked_at 필드는 기본 null (생략 or 명시적으로 null 지정)
      } satisfies IDiscussionboardRoleAssignment.ICreate,
    },
  );
  typia.assert(assignment);

  // 4. 역할 할당 상세 정보 성공 조회
  const detail: IDiscussionboardRoleAssignment = await api.functional.discussionboard.roleAssignments.getById(
    connection,
    { id: assignment.id },
  );
  typia.assert(detail);
  TestValidator.equals("id 일치")(detail.id)(assignment.id);
  TestValidator.equals("user_id 일치")(detail.user_id)(assignment.user_id);
  TestValidator.equals("assigned_by_admin_id 일치")(detail.assigned_by_admin_id)(assignment.assigned_by_admin_id);
  TestValidator.equals("role 일치")(detail.role)(assignment.role);
  TestValidator.equals("assigned_at 일치")(detail.assigned_at)(assignment.assigned_at);
  TestValidator.equals("revoked_at 일치")(detail.revoked_at)(assignment.revoked_at ?? null);

  // 5. 랜덤 UUID로 조회 시 404 오류 검증
  await TestValidator.error("존재하지 않는 id 404")(async () => {
    await api.functional.discussionboard.roleAssignments.getById(
      connection,
      { id: typia.random<string & tags.Format<"uuid">>() },
    );
  });

  // 6. (구현 가능 시) 일반 유저 권한 거부 테스트는 실제 인증 정책 연계 필요 (현 환경서 미구현)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { IDiscussionboardRoleAssignment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardRoleAssignment";

/**
 * 역할 할당 생성 E2E 시나리오 (성공, 중복, 잘못된 입력, 권한 제한, 역할 승격/강등 감사)
 *
 * 이 테스트는 다음의 시나리오를 검증합니다:
 * 1. 관리자로서 일반 유저에게 moderator 권한을 부여 (성공)
 * 2. 동일 권한 중복 할당 시도(활성 중, 실패)
 * 3. 잘못된 입력: 존재하지 않는 user_id, role 누락, assigned_at 형식 오류 (각각 400 오류 예상)
 * 4. 권한 제한: 비관리자 유저가 권한 할당 시도 (실패, 권한 거부)
 * 5. 역할 escalation과 demotion: admin, user 간 변동이 지원되고 모든 이력이 감사(Journal)로 남음
 *
 * 주요 검증 포인트:
 * - 실제 유효 유저/관리자 등록 → 역할 할당 API 호출 → 예상 결과 검증
 * - 에러 조건: 중복, 입력값 결함, 권한 없는 사용자 접근 등
 * - 역할 변경 이력(승격/강등)이 정상적으로 기록되는지 검증
 */
export async function test_api_discussionboard_test_create_role_assignment_success_duplicate_and_invalid_inputs(
  connection: api.IConnection,
) {
  // 1. 관리자(admin) 계정과 일반 유저 등록
  const adminReg = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "StrongP4ss!Admin",
      displayName: RandomGenerator.name(),
      isActive: true,
    },
  });
  typia.assert(adminReg);

  const userReg = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "OrdinaryP4ss!User",
      displayName: RandomGenerator.name(),
      isActive: true,
    },
  });
  typia.assert(userReg);

  // 2. 관리자가 유저에게 역할(moderator) 부여
  const nowIso = new Date().toISOString();
  const assignmentBody = {
    user_id: userReg.id,
    assigned_by_admin_id: adminReg.id,
    role: "moderator",
    assigned_at: nowIso
  } satisfies IDiscussionboardRoleAssignment.ICreate;

  const roleAssignment = await api.functional.discussionboard.roleAssignments.post(connection, { body: assignmentBody });
  typia.assert(roleAssignment);

  TestValidator.equals("user_id matches")(roleAssignment.user_id)(userReg.id);
  TestValidator.equals("assigned_by_admin_id matches")(roleAssignment.assigned_by_admin_id)(adminReg.id);
  TestValidator.equals("role matches")(roleAssignment.role)("moderator");
  TestValidator.equals("assigned_at matches")(roleAssignment.assigned_at)(nowIso);
  TestValidator.equals("role still active")(roleAssignment.revoked_at)(null);

  // 3. 동일 역할 활성 상태 재할당 시도 → 실패 검증
  TestValidator.error("Duplicate active assignment should fail")(
    async () => {
      await api.functional.discussionboard.roleAssignments.post(connection, {
        body: assignmentBody,
      });
    }
  );

  // 4. 잘못된 입력 (validation error):
  // 4-1. 존재하지 않는 user_id
  TestValidator.error("Non-existent user_id should fail")(
    async () => {
      await api.functional.discussionboard.roleAssignments.post(connection, {
        body: {
          ...assignmentBody,
          user_id: typia.random<string & tags.Format<"uuid">>(), // 실제 등록 안된 UUID
        },
      });
    }
  );
  // 4-2. role 누락 (as any 제한적 허용)
  TestValidator.error("Missing role should fail")(
    async () => {
      const { role, ...rest } = assignmentBody;
      await api.functional.discussionboard.roleAssignments.post(connection, {
        body: rest as any,
      });
    }
  );
  // 4-3. assigned_at 잘못된 형식 (as any 제한적 허용)
  TestValidator.error("Malformed assigned_at should fail")(
    async () => {
      await api.functional.discussionboard.roleAssignments.post(connection, {
        body: {
          ...assignmentBody,
          assigned_at: "invalid-date-format",
        } as any,
      });
    }
  );

  // 5. 비관리자에 의한 할당 시도 (권한 거부)
  const stranger = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "P4ss!Stranger",
      displayName: RandomGenerator.name(),
      isActive: true,
    },
  });
  typia.assert(stranger);

  TestValidator.error("Non-admin permission denied")(
    async () => {
      await api.functional.discussionboard.roleAssignments.post(connection, {
        body: {
          ...assignmentBody,
          assigned_by_admin_id: stranger.id,
        },
      });
    }
  );

  // 6. 역할 승격(admin), 강등(user) 이력 감사
  // 6-1. admin 역할 부여
  const roleAdmin = await api.functional.discussionboard.roleAssignments.post(connection, {
    body: {
      ...assignmentBody,
      role: "admin",
      assigned_at: new Date(Date.now() + 1000).toISOString(),
    },
  });
  typia.assert(roleAdmin);
  TestValidator.equals("role escalation")(roleAdmin.role)("admin");

  // 6-2. user로 강등
  const roleDemotion = await api.functional.discussionboard.roleAssignments.post(connection, {
    body: {
      ...assignmentBody,
      role: "user",
      assigned_at: new Date(Date.now() + 2000).toISOString(),
    },
  });
  typia.assert(roleDemotion);
  TestValidator.equals("role demotion")(roleDemotion.role)("user");
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
