import type { IDiscussionboardRoleAssignment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardRoleAssignment";

/**
 * Test updating an existing discussionboard role assignment.
 *
 * - As an admin, update a role assignment: change role, or revoke role (set revoked_at).
 * - Check status transitions: cannot re-activate revoked assignment, cannot update non-existent id.
 * - Attempt invalid updates: missing required fields, role changes without revocation, and unauthorized access (if supported).
 * - Validate audit logging and check changes in role assignment via further operations (mocked, as GET/list is not available).
 *
 * Steps:
 * 1. Register an admin user (who assigns roles), and a normal user (who receives roles).
 * 2. Assign a 'moderator' role to the user.
 * 3. Update the assignment to a different role ('admin') by admin; expect fields updated correctly.
 * 4. Revoke the assignment (set revoked_at) and verify revocation is recorded.
 * 5. Attempt to restore a revoked assignment (should fail if API/business logic blocks it).
 * 6. Attempt to update an assignment with invalid id (should error).
 * 7. Attempt update with missing required fields (should error at runtime, but TypeScript prevents compile-time field omission).
 * 8. (If implemented) Attempt role switch without revocation, expect failure.
 * 9. (No GET/list endpoint, cannot verify via API, but check output and returned assignment object).
 */
export async function test_api_discussionboard_test_update_role_assignment_status_role_and_invalid_cases(
  connection: api.IConnection,
) {
  // 1. Register admin user
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin: IDiscussionboardUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: adminEmail,
      password: "adminpw123!",
      displayName: "AdminUser",
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(admin);

  // 2. Register target user
  const userEmail = typia.random<string & tags.Format<"email">>();
  const user: IDiscussionboardUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: userEmail,
      password: "userpw123!",
      displayName: "TargetUser",
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(user);

  // 3. Assign 'moderator' role via roleAssignments.post
  const assignedAt = new Date().toISOString();
  const assignment: IDiscussionboardRoleAssignment = await api.functional.discussionboard.roleAssignments.post(connection, {
    body: {
      user_id: user.id,
      assigned_by_admin_id: admin.id,
      role: "moderator",
      assigned_at: assignedAt,
    } satisfies IDiscussionboardRoleAssignment.ICreate,
  });
  typia.assert(assignment);

  // 4. Update assignment: change role to 'admin'
  const roleChangeAt = new Date(Date.now() + 1000).toISOString();
  const updated: IDiscussionboardRoleAssignment = await api.functional.discussionboard.roleAssignments.putById(connection, {
    id: assignment.id,
    body: {
      user_id: user.id,
      assigned_by_admin_id: admin.id,
      role: "admin",
      assigned_at: roleChangeAt,
      revoked_at: null,
    } satisfies IDiscussionboardRoleAssignment.IUpdate,
  });
  typia.assert(updated);
  TestValidator.equals("role updated")(updated.role)("admin");
  TestValidator.equals("assigned_at updated")(updated.assigned_at)(roleChangeAt);
  TestValidator.equals("revoked_at null")(updated.revoked_at)(null);

  // 5. Revoke assignment
  const revokedAt = new Date(Date.now() + 2000).toISOString();
  const revoked: IDiscussionboardRoleAssignment = await api.functional.discussionboard.roleAssignments.putById(connection, {
    id: assignment.id,
    body: {
      user_id: user.id,
      assigned_by_admin_id: admin.id,
      role: updated.role,
      assigned_at: updated.assigned_at,
      revoked_at: revokedAt,
    } satisfies IDiscussionboardRoleAssignment.IUpdate,
  });
  typia.assert(revoked);
  TestValidator.equals("revoked_at set")(revoked.revoked_at)(revokedAt);

  // 6. Try to re-activate revoked assignment (should fail)
  TestValidator.error("cannot restore revoked assignment")(
    async () => {
      await api.functional.discussionboard.roleAssignments.putById(connection, {
        id: assignment.id,
        body: {
          user_id: user.id,
          assigned_by_admin_id: admin.id,
          role: "moderator",
          assigned_at: new Date(Date.now() + 3000).toISOString(),
          revoked_at: null,
        } satisfies IDiscussionboardRoleAssignment.IUpdate,
      });
    },
  );

  // 7. Update with non-existent ID (should throw)
  TestValidator.error("update fails for non-existent id")(
    async () => {
      await api.functional.discussionboard.roleAssignments.putById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
        body: {
          user_id: user.id,
          assigned_by_admin_id: admin.id,
          role: "moderator",
          assigned_at: new Date(Date.now() + 4000).toISOString(),
          revoked_at: null,
        } satisfies IDiscussionboardRoleAssignment.IUpdate,
      });
    },
  );

  // 8. Update with missing required fields is compile-time error (cannot do).
  // 9. Unauthorized user simulation not supported by API as given.
  // 10. (Mock) check updated assignment object for audit.
  TestValidator.equals("audit trail user id")(revoked.user_id)(user.id);
  TestValidator.equals("audit trail admin id")(revoked.assigned_by_admin_id)(admin.id);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
