import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { INotificationSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/INotificationSetting";
import type { IPageINotificationSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageINotificationSetting";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 알림 설정 목록 조회 (현재 인증된 사용자용) E2E 통합 시나리오
 *
 * - 회원가입 & 알림설정(여러 조합) 사전 생성 후 본인 데이터만 반환되는지 검증
 * - 필터(notification_type 등), 페이지네이션(limit) 옵션 정상작동 확인
 * - 타 user_id로 필터 또는 타 사용자 데이터 접근시 권한 에러 처리 검증
 * - 알림설정 없는 신규 유저로는 본인 데이터 목록이 비어있음도 확인
 *
 * 단계별 검증:
 * 1. 회원가입(유저A)
 * 2. 유저A에 대해 여러 알림설정(타입/채널콤보) 생성
 * 3. 알림설정 목록 기본조회 (본인 데이터만, 개수/내용 일치확인)
 * 4. notification_type 등 필터 적용 시 정상 필터링확인
 * 5. limit(페이지네이션) 적용시 개수 및 pagination meta 정상
 * 6. 알림설정 데이터 없는 유저(유저B) 신규생성시 → 빈목록/정상메타
 * 7. (인증/권한) 타 user_id로 접근 시 권한 에러
 */
export async function test_api_discussionboard_test_list_notification_settings_for_authenticated_user(
  connection: api.IConnection,
) {
  // 1. 회원가입 (테스트 유저A 생성)
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userPassword = typia.random<string & tags.Format<"password">>();
  const displayName = RandomGenerator.name();
  const user = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: userEmail,
      password: userPassword,
      displayName: displayName,
    },
  });
  typia.assert(user);

  // 2. 유저A의 알림설정 여러개(타입+채널 콤비) 생성
  const notificationTypes = ["reply", "like", "mention"];
  const channels = ["web", "email"];
  const settings: INotificationSetting[] = [];
  for (const type of notificationTypes) {
    for (const channel of channels) {
      const setting = await api.functional.discussionboard.notificationSettings.post(connection, {
        body: {
          user_id: user.id,
          notification_type: type,
          channel,
          is_enabled: true,
        } satisfies INotificationSetting.ICreate,
      });
      typia.assert(setting);
      settings.push(setting);
    }
  }

  // 3. 본인 알림설정 전체 목록 조회 (필터X)
  const allSettingsPage = await api.functional.discussionboard.notificationSettings.patch(connection, {
    body: {},
  });
  typia.assert(allSettingsPage);
  TestValidator.equals("총 알림설정 개수")(allSettingsPage.data.length)(settings.length);
  for (const setting of settings) {
    const matched = allSettingsPage.data.find(
      s => s.notification_type === setting.notification_type && s.channel === setting.channel,
    );
    TestValidator.predicate(`알림설정 ${setting.notification_type}/${setting.channel} 존재확인`)(!!matched);
    TestValidator.equals("is_enabled 일치")(matched?.is_enabled)(setting.is_enabled);
  }

  // 4. notification_type 단일 필터 검증
  const typeFilter = notificationTypes[0];
  const typeFilteredPage = await api.functional.discussionboard.notificationSettings.patch(connection, {
    body: { notification_type: typeFilter },
  });
  typia.assert(typeFilteredPage);
  TestValidator.predicate("notification_type 필터 데이터 일치")(
    typeFilteredPage.data.every(s => s.notification_type === typeFilter),
  );

  // 5. limit(페이지네이션) 동작 검증
  const paged = await api.functional.discussionboard.notificationSettings.patch(connection, {
    body: { limit: 2 },
  });
  typia.assert(paged);
  TestValidator.equals("limit 적용 데이터 개수")(paged.data.length)(2);
  TestValidator.equals("pagination.limit 메타 일치")(paged.pagination.limit)(2);

  // 6. 알림설정 없는 유저B 신규 가입 & 목록조회 (빈배열+메타)
  const userB = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
      displayName: RandomGenerator.name(),
    },
  });
  typia.assert(userB);
  // user_id 파라미터 없는 경우(현재 계정)만 반환, user_id 지정시 권한에러이므로(7번에서 커버) skip
  // (테스트환경에서 인증 전환 불가, 현실에서는 user_id 없이 인증상태로 재요청 필요)

  // 7. 타인 user_id로 필터: 권한 에러 시도
  await TestValidator.error("타 user_id 사용시 권한 거부")(
    async () =>
      await api.functional.discussionboard.notificationSettings.patch(connection, {
        body: { user_id: userB.id },
      }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { INotificationSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/INotificationSetting";

/**
 * Test retrieving a notification setting by its ID for the owner, and access/error cases.
 *
 * This test performs the following business steps:
 * 1. Register a user who will own a notification setting.
 * 2. Register a second user (for forbidden/error scenarios).
 * 3. Create a notification setting for the first user.
 * 4. As the owner (first user), retrieve the notification setting by ID and assert all expected details.
 * 5. Attempt to fetch a non-existing notification setting by a random UUID, expect a 404 error.
 * 6. As a different user, attempt to fetch the first user's notification setting by ID, expect a 403 error or forbidden response.
 *
 * Notes:
 * - Authentication context is initialized by user registration; there is no explicit login API.
 * - If connection switching is needed for authorization checks, ensure a fresh connection or correct token context per user; if not possible, document this as a limitation.
 */
export async function test_api_discussionboard_notificationSettings_test_get_notification_setting_by_id_for_owner(
  connection: api.IConnection,
) {
  // 1. Register owner user
  const ownerEmail = typia.random<string & tags.Format<"email">>();
  const ownerPassword = RandomGenerator.alphaNumeric(12);
  const owner: IDiscussionboardUser = await api.functional.discussionboard.users.post(
    connection,
    {
      body: {
        email: ownerEmail,
        password: ownerPassword,
        displayName: RandomGenerator.name(),
      } satisfies IDiscussionboardUser.ICreate,
    },
  );
  typia.assert(owner);

  // 2. Register another user for forbidden scenario
  const otherEmail = typia.random<string & tags.Format<"email">>();
  const otherPassword = RandomGenerator.alphaNumeric(12);
  const other: IDiscussionboardUser = await api.functional.discussionboard.users.post(
    connection,
    {
      body: {
        email: otherEmail,
        password: otherPassword,
        displayName: RandomGenerator.name(),
      } satisfies IDiscussionboardUser.ICreate,
    },
  );
  typia.assert(other);

  // 3. Create notification setting for owner
  const notifSettingInput = {
    user_id: owner.id,
    notification_type: RandomGenerator.pick(["reply", "like", "mention", "announcement"]),
    channel: RandomGenerator.pick(["web", "email", "sms"]),
    is_enabled: true,
  } satisfies INotificationSetting.ICreate;
  const notifSetting: INotificationSetting = await api.functional.discussionboard.notificationSettings.post(
    connection,
    {
      body: notifSettingInput,
    },
  );
  typia.assert(notifSetting);

  TestValidator.equals("user matches")(notifSetting.user_id)(owner.id);
  TestValidator.equals("notification_type matches")(notifSetting.notification_type)(notifSettingInput.notification_type);
  TestValidator.equals("channel matches")(notifSetting.channel)(notifSettingInput.channel);
  TestValidator.equals("is_enabled matches")(notifSetting.is_enabled)(notifSettingInput.is_enabled);

  // 4. Retrieve notification setting by ID as owner
  const fetched: INotificationSetting = await api.functional.discussionboard.notificationSettings.getById(
    connection,
    {
      id: notifSetting.id,
    },
  );
  typia.assert(fetched);
  TestValidator.equals("fetched record matches")(fetched)(notifSetting);

  // 5. Attempt retrieving a non-existing notification setting (expect 404)
  await TestValidator.error("non-existing notification setting (404)")(
    async () => {
      await api.functional.discussionboard.notificationSettings.getById(
        connection,
        {
          id: typia.random<string & tags.Format<"uuid">>(),
        },
      );
    },
  );

  // 6. Switch to 'other' user context and attempt forbidden fetch (if possible)
  // Note: If your SDK and test harness support switching authorization context, replace 'connection' below
  //       with a fresh connection for 'other' (e.g., after login or token impersonation)
  // Here, we reuse 'connection' assuming per-user context can be established via registration.
  await TestValidator.error("forbidden access to another user's notification setting")(
    async () => {
      // In a real test, swap to 'other' user's connection if possible
      await api.functional.discussionboard.notificationSettings.getById(
        connection,
        {
          id: notifSetting.id,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { INotificationSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/INotificationSetting";

/**
 * Validate creation and business rules for user notification settings on the discussion board.
 *
 * This test covers creation of per-user notification preference records, which control how users receive individual notification types (by channel). Only the owner themselves or an admin may create these settings. The test will:
 *
 * 1. Create a new user (via /discussionboard/users)
 * 2. Attempt to create a notification setting for this user with valid parameters, via /discussionboard/notificationSettings (valid notification_type, valid channel, enablement flag)
 * 3. Validate that the response matches the input (correct user, type, channel, is_enabled)
 * 4. Attempt to create the same notification setting again; expect a conflict error (duplicate tuple rejection)
 * 5. Attempt to create a setting for a non-existent user; expect error
 * 6. Attempt to create a setting with an unsupported notification_type; expect error
 * 7. Attempt to create a setting with an unsupported channel; expect error
 * 8. (If API supports it) Attempt to create a notification setting as an unauthorized actor; expect error
 */
export async function test_api_discussionboard_test_create_notification_setting_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Create user for whom settings will be created
  const user = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(12),
      displayName: RandomGenerator.name(),
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(user);

  // 2. Create valid notification setting record
  const input = {
    user_id: user.id,
    notification_type: "reply",
    channel: "web",
    is_enabled: true,
  } satisfies INotificationSetting.ICreate;
  const setting = await api.functional.discussionboard.notificationSettings.post(connection, {
    body: input,
  });
  typia.assert(setting);
  TestValidator.equals("user_id")(setting.user_id)(input.user_id);
  TestValidator.equals("notification_type")(setting.notification_type)(input.notification_type);
  TestValidator.equals("channel")(setting.channel)(input.channel);
  TestValidator.equals("is_enabled")(setting.is_enabled)(input.is_enabled);

  // 3. Attempt duplicate creation (should fail with conflict error)
  await TestValidator.error("duplicate notification setting conflicts")(() =>
    api.functional.discussionboard.notificationSettings.post(connection, { body: input }),
  );

  // 4. Attempt to create for non-existent user (should fail)
  await TestValidator.error("non-existent user ID fails")(() =>
    api.functional.discussionboard.notificationSettings.post(connection, {
      body: { ...input, user_id: typia.random<string & tags.Format<"uuid">>() },
    }),
  );

  // 5. Attempt invalid notification type (should fail)
  await TestValidator.error("invalid notification_type fails")(() =>
    api.functional.discussionboard.notificationSettings.post(connection, {
      body: { ...input, notification_type: "nonsense type" },
    }),
  );

  // 6. Attempt invalid channel (should fail)
  await TestValidator.error("invalid notification channel fails")(() =>
    api.functional.discussionboard.notificationSettings.post(connection, {
      body: { ...input, channel: "carrier pigeon" },
    }),
  );

  // 7. (If API supports) Attempt unauthorized creation (not feasible with given APIs, so omitted)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { INotificationSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/INotificationSetting";

/**
 * Validate updating notification settings by the owner and enforce business rules / access controls.
 *
 * This comprehensive E2E test validates all major behaviors for updating a notification setting:
 *
 * 1. The owner can update their notification setting's enabled state, type, and channel. Confirms updates are saved and reflected in the response.
 * 2. Attempting to update to a (user, type, channel) tuple that already exists triggers a conflict error.
 * 3. Updates by a non-owner (another user) are forbidden.
 * 4. Updates to a non-existent notification setting ID yield a not-found error.
 */
export async function test_api_discussionboard_notificationSettings_test_update_notification_setting_as_owner(
  connection: api.IConnection,
) {
  // 1. Create the owner user
  const ownerData = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "Password!123",
    displayName: RandomGenerator.name(),
    isActive: true,
  } satisfies IDiscussionboardUser.ICreate;
  const owner = await api.functional.discussionboard.users.post(connection, { body: ownerData });
  typia.assert(owner);

  // 2. Create another user (used to simulate forbidden case)
  const otherUserData = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "Password@456",
    displayName: RandomGenerator.name(),
    isActive: true,
  } satisfies IDiscussionboardUser.ICreate;
  const otherUser = await api.functional.discussionboard.users.post(connection, { body: otherUserData });
  typia.assert(otherUser);

  // 3. Create an original notification setting for the owner
  const originalSetting = {
    user_id: owner.id,
    notification_type: "reply",
    channel: "email",
    is_enabled: true,
  } satisfies INotificationSetting.ICreate;
  const original = await api.functional.discussionboard.notificationSettings.post(connection, { body: originalSetting });
  typia.assert(original);

  // 4. Owner updates the setting (change enabled state, channel, and type)
  const updateReq = {
    is_enabled: false,
    channel: "web",
    notification_type: "like",
  } satisfies INotificationSetting.IUpdate;
  const updated = await api.functional.discussionboard.notificationSettings.putById(connection, { id: original.id, body: updateReq });
  typia.assert(updated);
  TestValidator.equals("is_enabled updated")(updated.is_enabled)(false);
  TestValidator.equals("channel updated")(updated.channel)("web");
  TestValidator.equals("notification_type updated")(updated.notification_type)("like");
  TestValidator.equals("unchanged user_id")(updated.user_id)(owner.id);

  // 5. Create a second notification setting with a different tuple for conflict test
  const dupeSetting = {
    user_id: owner.id,
    notification_type: "conflict-test",
    channel: "sms",
    is_enabled: true,
  } satisfies INotificationSetting.ICreate;
  const dupe = await api.functional.discussionboard.notificationSettings.post(connection, { body: dupeSetting });
  typia.assert(dupe);

  // Now attempt to update the original to the dupe's type/channel combo (should fail uniqueness)
  const conflictUpdate = {
    is_enabled: false,
    channel: "sms",
    notification_type: "conflict-test",
  } satisfies INotificationSetting.IUpdate;
  await TestValidator.error("uniqueness (user, type, channel) conflict")(() =>
    api.functional.discussionboard.notificationSettings.putById(connection, { id: original.id, body: conflictUpdate })
  );

  // 6. Attempt update as non-owner (simulate with other user's context if possible)
  // For this test, simply call as is (assume API validates on context, or adapt per implementation)
  const forbiddenUpdate = { is_enabled: true } satisfies INotificationSetting.IUpdate;
  await TestValidator.error("forbidden for non-owner")(() =>
    api.functional.discussionboard.notificationSettings.putById(connection, { id: original.id, body: forbiddenUpdate })
  );

  // 7. Attempt update to a non-existent notification setting
  await TestValidator.error("not found for non-existent notification setting")(() =>
    api.functional.discussionboard.notificationSettings.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: { is_enabled: true } satisfies INotificationSetting.IUpdate,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { INotificationSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/INotificationSetting";

/**
 * E2E test: The owner of a notification setting can delete it and deletion is securely enforced.
 *
 * - When the owning user deletes their own notification setting, deletion should succeed silently (void response).
 * - Attempting to delete the same setting a second time should fail (404 not found).
 * - A different (non-owner) user must be forbidden (403) from deleting the owner's notification setting.
 * - This test uses two users and ensures type safety and business logic enforcement throughout.
 * - Audit/retention compliance checks can only be performed if the API surfaces such functionality; not in scope here.
 *
 * Steps:
 * 1. Create an owner user
 * 2. Owner creates a notification setting
 * 3. Owner deletes their notification setting (should succeed)
 * 4. Owner attempts to delete again (should get 404)
 * 5. Create another user (non-owner)
 * 6. Non-owner attempts to delete the original notification setting (should get 403 forbidden)
 */
export async function test_api_discussionboard_test_delete_notification_setting_by_owner(connection: api.IConnection) {
  // 1. Create an owner user for the notification setting
  const ownerEmail = typia.random<string & tags.Format<"email">>();
  const ownerPassword = RandomGenerator.alphaNumeric(12);
  const owner = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: ownerEmail,
      password: ownerPassword,
      displayName: RandomGenerator.name(),
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(owner);

  // 2. Create a notification setting for the owner
  const notificationSetting = await api.functional.discussionboard.notificationSettings.post(connection, {
    body: {
      user_id: owner.id,
      notification_type: "reply",
      channel: "web",
      is_enabled: true,
    } satisfies INotificationSetting.ICreate,
  });
  typia.assert(notificationSetting);

  // 3. Owner deletes their notification setting (should succeed)
  await api.functional.discussionboard.notificationSettings.eraseById(connection, {
    id: notificationSetting.id,
  });

  // 4. Attempt to delete again (should result in 404 error)
  await TestValidator.error("Deleting already-deleted notification setting should return 404")(
    async () => {
      await api.functional.discussionboard.notificationSettings.eraseById(connection, {
        id: notificationSetting.id,
      });
    },
  );

  // 5. Create another (non-owner) user
  const otherUserEmail = typia.random<string & tags.Format<"email">>();
  const otherUserPassword = RandomGenerator.alphaNumeric(12);
  const otherUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: otherUserEmail,
      password: otherUserPassword,
      displayName: RandomGenerator.name(),
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(otherUser);

  // 6. As non-owner, attempt to delete the owner's notification setting (should be 403 forbidden)
  await TestValidator.error("Non-owner cannot delete another user's notification setting (should return 403)")(
    async () => {
      await api.functional.discussionboard.notificationSettings.eraseById(connection, {
        id: notificationSetting.id,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IDiscussionboardPostAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPostAttachment";
import type { IPageIDiscussionboardPostAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardPostAttachment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test retrieving a paginated, filtered list of attachments for posts as an authorized user.
 *
 * This test covers the following end-to-end workflow:
 * 1. Register a user who will act as uploader.
 * 2. Create a discussion post (cannot control author via DTO; use returned created_by_user_id).
 * 3. Upload at least three attachments to the post with varying filenames and mimetypes.
 * 4. Retrieve a paginated list of attachments for this post/uploader combo (limit=2, two pages).
 * 5. Check that pagination metadata matches uploaded number and returned data belongs to the correct post/uploader.
 * 6. Filter by mimetype and validate the response only contains matching files.
 *
 * This test validates key business requirements:
 * - Filtering by uploader, post_id, and mimetype works as expected.
 * - Pagination and page rollover reflects data accurately.
 * - Returned attachment metadata matches those of the uploads.
 */
export async function test_api_discussionboard_test_list_post_attachments_with_valid_filters_and_pagination(connection: api.IConnection) {
  // 1. Register a new user (uploader)
  const uploaderEmail = typia.random<string & tags.Format<"email">>();
  const uploaderPassword = "Password!123";
  const uploaderDisplayName = RandomGenerator.name();

  const user = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: uploaderEmail,
      password: uploaderPassword,
      displayName: uploaderDisplayName,
      avatarUrl: undefined,
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(user);

  // 2. Create a post (cannot control author directly)
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: {
      thread_id: threadId,
      content: RandomGenerator.paragraph()(),
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // Use the returned post's created_by_user_id for attachment and filter
  const createdUserId = post.created_by_user_id;

  // 3. Upload at least 3 attachments with various metadata
  const attachmentInputs = [
    {
      filename: "document.pdf",
      mimetype: "application/pdf",
    },
    {
      filename: "photo1.png",
      mimetype: "image/png",
    },
    {
      filename: "presentation.pptx",
      mimetype: "application/vnd.openxmlformats-officedocument.presentationml.presentation",
    },
  ];
  const attachments: IDiscussionboardPostAttachment[] = [];
  for (const input of attachmentInputs) {
    const attachment = await api.functional.discussionboard.posts.attachments.post(connection, {
      body: {
        post_id: post.id,
        uploaded_by_user_id: createdUserId,
