/**
 * 게시글 첨부파일에 대한 메타데이터를 업로더(등록자)가 ID로 조회할 수 있는지 검증합니다.
 *
 * 이 시나리오의 목적은 실제 업로더가 직접 업로드한 첨부파일에 대해 GET API를 호출했을 때,
 * API가 올바른 메타데이터(파일명, 타입, 크기, 업로더, 등록 URL 등)를 반환하는지, 실제 업로드 정보와 일치하는지 확인하는 것입니다.
 *
 * 1. 유저 회원가입 (업로더 역할)
 *    - 고유 이메일/닉네임/패스워드 조합 사용
 *    - 가입에 성공하면 반환된 id 취득
 * 2. 게시글 생성
 *    - 등록된 유저ID로 post 작성 (thread_id는 랜덤 UUID 사용)
 *    - 생성된 post id 확보
 * 3. 첨부파일 업로드 (메타등록)
 *    - 위에서 얻은 post id, user id로 IDiscussionboardPostAttachment.ICreate 생성
 *    - 랜덤 파일명, mimetype, URL, 파일크기 등 지정
 *    - API호출 결과에서 attachment id 확보, 등록된 메타데이터 저장
 * 4. 첨부파일 단일조회 (GET by id)
 *    - 업로드한 첨부파일의 id로 GET 호출
 *    - 반환값의 각 필드가 업로드시 입력한 메타데이터와 일치하는지 검증
 *    - file name, mimetype, size, uploader id, post id, url 등이 정확히 동일해야 함
 */
export async function test_api_discussionboard_test_get_post_attachment_with_valid_id_by_uploader(
  connection: api.IConnection,
) {
  // 1. 회원가입 (업로더 생성)
  const userEmail: string = typia.random<string & tags.Format<"email">>();
  const password: string = typia.random<string & tags.Format<"password">>();
  const displayName: string = RandomGenerator.name();
  const createdUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: userEmail,
      password,
      displayName,
    },
  });
  typia.assert(createdUser);

  // 2. 게시글 생성 (업로더가 직접 등록)
  const threadId: string = typia.random<string & tags.Format<"uuid">>();
  const content: string = RandomGenerator.paragraph()();
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: {
      thread_id: threadId,
      content,
    },
  });
  typia.assert(post);

  // 3. 첨부파일(메타) 업로드
  const filename: string = RandomGenerator.alphaNumeric(10);
  const mimetype: string = RandomGenerator.pick([
    "image/png", "image/jpeg", "application/pdf", "text/plain"
  ]);
  const sizeBytes: number = typia.random<number & tags.Type<"int32">>();
  const url: string = `https://cdn.example.com/files/${RandomGenerator.alphaNumeric(20)}`;
  const attachmentInput = {
    post_id: post.id,
    uploaded_by_user_id: createdUser.id,
    filename,
    mimetype,
    size_bytes: sizeBytes,
    url,
  };
  const attachment = await api.functional.discussionboard.posts.attachments.post(connection, {
    body: attachmentInput,
  });
  typia.assert(attachment);

  // 4. 첨부파일 단건 메타 GET (by 업로더)
  const got = await api.functional.discussionboard.posts.attachments.getById(connection, {
    id: attachment.id,
  });
  typia.assert(got);

  // 업로드 정보가 정확히 보존되는지 각 필드별 확인
  TestValidator.equals("파일 id")(got.id)(attachment.id);
  TestValidator.equals("post id")(got.post_id)(post.id);
  TestValidator.equals("업로더 id")(got.uploaded_by_user_id)(createdUser.id);
  TestValidator.equals("파일명")(got.filename)(filename);
  TestValidator.equals("mimetype")(got.mimetype)(mimetype);
  TestValidator.equals("size_bytes")(got.size_bytes)(sizeBytes);
  TestValidator.equals("url")(got.url)(url);
  TestValidator.equals("삭제여부")(got.is_deleted)(false);
}

