  const displayName = RandomGenerator.name();
  const user = await api.functional.discussionboard.users.post(connection, {
    body: {
      email,
      password,
      displayName,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(user);

  // 2. (가상) 쓰레드ID로 게시글 작성: 실제 thread 존재 보장 불가시, 랜덤 UUID 사용
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: {
      thread_id: threadId,
      content: RandomGenerator.paragraph()(),
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // 3. 정책 초과(20MB) 첨부파일(메타) 데이터 준비
  const OVERSIZED_BYTES = 20 * 1024 * 1024; // 20MB (exceeds e.g. 5MB policy by far)
  const attachment = {
    post_id: post.id,
    uploaded_by_user_id: user.id,
    filename: "oversize_testfile.dat",
    mimetype: "application/octet-stream",
    size_bytes: OVERSIZED_BYTES,
    url: `https://cdn.test.local/oversize_testfile_${RandomGenerator.alphaNumeric(8)}.dat`,
  } satisfies IDiscussionboardPostAttachment.ICreate;

  // 4. 첨부파일 업로드 요청 → 서버 Validation Error 발생(e.g. 400/422)
  await TestValidator.error("첨부파일 용량 초과시 Validation Error 응답 확인")(
    async () => {
      await api.functional.discussionboard.posts.attachments.post(connection, {
        body: attachment,
      });
    },
  );
}

