/**
 * Validate the update of an attachment's metadata by its owner.
 *
 * This test covers the workflow for a user to update fields (filename, mimetype)
 * of their own post attachment. It verifies that the update is applied and
 * reflected in the response object.
 *
 * Workflow:
 * 1. Register a new user to act as attachment owner.
 * 2. Create a dummy thread (UUID) and a post authored by this user.
 * 3. Upload an attachment (file metadata) for the post.
 * 4. Update allowed metadata fields (filename, mimetype) of the attachment as owner.
 * 5. Check that the update is reflected in the returned object.
 */
export async function test_api_discussionboard_test_update_post_attachment_metadata_by_owner(
  connection: api.IConnection,
) {
  // 1. Register a new user to act as owner
  const email = typia.random<string & tags.Format<"email">>();
  const password = typia.random<string & tags.Format<"password">>();
  const user = await api.functional.discussionboard.users.post(connection, {
    body: {
      email,
      password,
      displayName: RandomGenerator.name(),
      isActive: true,
    },
  });
  typia.assert(user);

  // 2. Create a dummy thread (UUID) and create a post under it as the user
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: {
      thread_id: threadId,
      content: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(post);

  // 3. Upload a file attachment to the post as the owner
  const originalFilename = RandomGenerator.alphaNumeric(10) + ".pdf";
  const originalMimetype = "application/pdf";
  const attachment = await api.functional.discussionboard.posts.attachments.post(connection, {
    body: {
      post_id: post.id,
      uploaded_by_user_id: user.id,
      filename: originalFilename,
      mimetype: originalMimetype,
      size_bytes: typia.random<number & tags.Type<"int32">>(),
      url: "https://cdn.example.com/files/" + RandomGenerator.alphaNumeric(24),
    },
  });
  typia.assert(attachment);

  // 4. Update this attachment's filename and mimetype as the owner
  const newFilename = RandomGenerator.alphaNumeric(14) + ".png";
  const newMimetype = "image/png";
  const updated = await api.functional.discussionboard.posts.attachments.putById(connection, {
    id: attachment.id,
    body: {
      filename: newFilename,
      mimetype: newMimetype,
    },
