  // 5. Verify updated metadata is reflected
  TestValidator.equals("filename updated")(updated.filename)(newFilename);
  TestValidator.equals("mimetype updated")(updated.mimetype)(newMimetype);
  TestValidator.equals("post_id unchanged")(updated.post_id)(post.id);
  TestValidator.equals("uploaded_by_user_id unchanged")(updated.uploaded_by_user_id)(user.id);
}

