 *
 * 본 테스트는 사용자(업로더) 회원가입, 게시글 생성, 파일 첨부(attachment 등록),
 * 소프트 삭제 실제 수행 절차를 포함하며, 실제 업로더가 삭제 요청을 정상적으로 처리할 수 있음을 검증합니다.
 * 삭제 후에는 기본 사용자 뷰에서 attachment가 노출되지 않아야 하며,
 * 관리자는 감사/감별 목적으로 여전히 접근할 수 있어야 함도 고려합니다.
 *
 * 단계 요약:
 * 1. 사용자(업로더) 회원 가입 (등록)
 * 2. 게시글 생성 (thread_id: 새 uuid, created_by_user_id: 업로더)
 * 3. 게시글 첨부파일 등록 (post_id/업로더 직접 지정, random 파일 메타)
 * 4. 업로더의 권한으로 첨부파일 소프트 삭제 요청
 * 5. 삭제 응답 및 is_deleted 등 플래그/상태 확인
 * 6. (옵션) 일반 사용자에게는 attachment가 목록에서 숨겨지는지 논리적 검증
 * 7. (옵션) 관리자/감사 조회 시 감사 추적 용도로는 유지되는지 명세상 추론
 */
export async function test_api_discussionboard_test_delete_post_attachment_by_owner(
  connection: api.IConnection,
) {
  // 1. 사용자(업로더) 회원 가입
  const uploaderEmail = typia.random<string & tags.Format<"email">>();
  const uploaderPassword = RandomGenerator.alphaNumeric(10);
  const uploaderDisplayName = RandomGenerator.name();

  const uploader = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: uploaderEmail,
      password: uploaderPassword,
      displayName: uploaderDisplayName,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(uploader);

  // 2. 게시글 생성 (thread_id 가상, created_by_user_id: 업로더)
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: {
      thread_id: threadId,
      content: RandomGenerator.paragraph()(),
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // 3. 게시글 첨부파일 등록
  const attachment = await api.functional.discussionboard.posts.attachments.post(connection, {
    body: {
      post_id: post.id,
      uploaded_by_user_id: uploader.id,
      filename: RandomGenerator.alphaNumeric(8)+".png",
      mimetype: "image/png",
      size_bytes: typia.random<number & tags.Type<"int32"> & tags.Minimum<10> & tags.Maximum<1000000>>(),
      url: "https://dummy-cdn.com/"+RandomGenerator.alphaNumeric(12)+".png",
    } satisfies IDiscussionboardPostAttachment.ICreate,
  });
  typia.assert(attachment);

  // 4. 업로더 권한으로 첨부파일 소프트 삭제
  const deletedAttachment = await api.functional.discussionboard.posts.attachments.eraseById(connection, {
    id: attachment.id,
  });
  typia.assert(deletedAttachment);

  // 5. 삭제 상태 및 소유 확인
  TestValidator.equals("is_deleted flag after deletion")(deletedAttachment.is_deleted)(true);
  TestValidator.equals("deletedAttachment ID matches")(deletedAttachment.id)(attachment.id);
  TestValidator.equals("deletedAttachment uploader matches")(deletedAttachment.uploaded_by_user_id)(uploader.id);

  // (6,7. 첨부파일 목록/관리자 View 검증은 별도 API 필요. 본 시나리오에서는 spec 내 미구현.)
}

