import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardTag";
import type { IPageIDiscussionboardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardTag";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate the tag listing (search/filter/pagination) system in the discussion board.
 *
 * This test verifies that the tags retrieval endpoint correctly honors name substring search, enabled filtering,
 * and pagination controls. It creates multiple tags with distinctive name patterns.
 * Then it executes filtered search and pagination queries, verifying that the API's responses
 * contain only tags matching the given criteria, with correct pagination metadata.
 *
 * Steps:
 * 1. Bulk create several tags with varying names (all using a unique prefix to avoid DB cross-talk)
 * 2. Search by substring (ensure only tags whose name contains the search string are returned)
 * 3. Filter by enabled=true and enabled=false; verify returned tags match the filter state.
 * 4. Paginate the result set; check correct data, total counts, page/limit/pagination values.
 * 5. Query with a search or filter that matches nothing; ensure empty data and correct pagination.
 */
export async function test_api_discussionboard_test_list_tags_with_valid_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Bulk create tags with unique prefix
  const uniquePrefix = `auto-e2e-${RandomGenerator.alphaNumeric(8)}`;
  const ALL_TAG_CNT = 10;
  const createdTags = await ArrayUtil.asyncRepeat(ALL_TAG_CNT)(async (i) => {
    const tag = await api.functional.discussionboard.tags.post(connection, {
      body: {
        name: `${uniquePrefix}-${i}`,
        color: i % 2 === 0 ? `#ABC${i}` : null,
        description: i % 3 === 0 ? `Desc ${i}` : null,
      } satisfies IDiscussionboardTag.ICreate,
    });
    typia.assert(tag);
    return tag;
  });

  // 2. Search by substring: should match one or more created tags
  const substring = `${uniquePrefix}-1`;
  const searchResult = await api.functional.discussionboard.tags.patch(connection, {
    body: {
      search: substring,
    } satisfies IDiscussionboardTag.IRequest,
  });
  typia.assert(searchResult);
  TestValidator.predicate('substring filter matches')(searchResult.data.every(tag => tag.name.includes(substring)));

  // 3. Filter by enabled=true (should return enabled tags only)
  const enabledResult = await api.functional.discussionboard.tags.patch(connection, {
    body: { enabled: true } satisfies IDiscussionboardTag.IRequest,
  });
  typia.assert(enabledResult);
  TestValidator.predicate('all enabled')(enabledResult.data.every(tag => tag.enabled === true));

  // Filter by enabled=false (should return disabled tags only)
  const disabledResult = await api.functional.discussionboard.tags.patch(connection, {
    body: { enabled: false } satisfies IDiscussionboardTag.IRequest,
  });
  typia.assert(disabledResult);
  TestValidator.predicate('all disabled')(disabledResult.data.every(tag => tag.enabled === false));

  // 4. Pagination test: limit 4, page 3
  const limit = 4;
  const page = 3;
  const pagedResult = await api.functional.discussionboard.tags.patch(connection, {
    body: {
      limit: limit,
      page: page,
      sort_by: 'name',
      sort_order: 'asc',
      search: uniquePrefix,
    } satisfies IDiscussionboardTag.IRequest,
  });
  typia.assert(pagedResult);
  TestValidator.equals('pagination limit')(pagedResult.pagination.limit)(limit);
  TestValidator.equals('pagination current')(pagedResult.pagination.current)(page);
  TestValidator.equals('pagination data')(pagedResult.data.length)(Math.min(limit, pagedResult.pagination.records - limit * (page - 1)));

  // 5. No matches case
  const noneResult = await api.functional.discussionboard.tags.patch(connection, {
    body: { search: 'no-existing-tag-zzzz' } satisfies IDiscussionboardTag.IRequest,
  });
  typia.assert(noneResult);
  TestValidator.equals('no matches data')(noneResult.data.length)(0);
  TestValidator.equals('pagination no records')(noneResult.pagination.records)(0);
}

