import type { IDiscussionboardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardTag";
import type { IPageIDiscussionboardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardTag";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate the rejection of unsupported parameters in the discussion board tag listing API.
 *
 * This test ensures that when a client sends a PATCH request to /discussionboard/tags with a payload containing extra fields not present in the schema, the API returns a proper validation error (such as a 400 Bad Request), rather than silently ignoring the unknown parameter or accepting invalid data.
 *
 * Steps:
 * 1. Construct a base payload that matches IDiscussionboardTag.IRequest (e.g., { page: 1, limit: 5 }).
 * 2. Add an unsupported property (e.g., "fooBarUnknown": 123).
 * 3. Call api.functional.discussionboard.tags.patch with the invalid payload and assert a validation error occurs (TestValidator.error).
 * 4. Repeat for a common misspelling (e.g., "nmae" instead of "name").
 *
 * This test validates strict schema enforcement for tag listing filters, preventing both security risks (e.g. mass assignment) and accidental typo bugs.
 */
export async function test_api_discussionboard_test_list_tags_invalid_filter_parameter(
  connection: api.IConnection,
) {
  // 1. Construct a valid payload
  const validPayload: IDiscussionboardTag.IRequest = { page: 1, limit: 5 };

  // 2. Add an unsupported field (deliberate nonsense)
  const invalidPayload = { ...validPayload, fooBarUnknown: 123 } as any;

  // 3. Attempt request and expect a validation error
  await TestValidator.error("unsupported filter fields are rejected")(
    () =>
      api.functional.discussionboard.tags.patch(connection, {
        body: invalidPayload,
      }),
  );

  // 4. Try also with a common misspelling for a valid field
  const typoPayload = { ...validPayload, nmae: "typo-tag" } as any;
  await TestValidator.error("typo'd filter fields are rejected")(
    () =>
      api.functional.discussionboard.tags.patch(connection, {
        body: typoPayload,
      }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardTag";

/**
 * Validate fetching a discussion board tag by its valid ID.
 *
 * This test ensures that the API for retrieving tag details
 * from the discussionboard_tag table operates correctly when given a valid, non-deleted tag ID.
 * It validates that all tag properties (such as name, color, description, enabled state, and timestamps)
 * match the record which was just created, ensuring data consistency for tag management features in the UI or editing workflows.
 *
 * Steps:
 * 1. Create a new tag using the POST /discussionboard/tags API.
 * 2. Fetch the tag using GET /discussionboard/tags/{id} with the returned UUID from step 1.
 * 3. Validate that properties (name, color, description, enabled) match exactly what was created.
 * 4. Assert the response matches IDiscussionboardTag schema and is not soft-deleted (deleted_at null).
 */
export async function test_api_discussionboard_tags_getById(
  connection: api.IConnection,
) {
  // 1. Create a new tag
  const tagInput: IDiscussionboardTag.ICreate = {
    name: RandomGenerator.alphabets(8),
    color: "#" + (Math.floor(Math.random() * 0xffffff)).toString(16).padStart(6, "0"),
    description: RandomGenerator.content()()(),
  };
  const created: IDiscussionboardTag = await api.functional.discussionboard.tags.post(connection, { body: tagInput });
  typia.assert(created);

  // 2. Retrieve the tag by ID
  const output: IDiscussionboardTag = await api.functional.discussionboard.tags.getById(connection, { id: created.id });
  typia.assert(output);

  // 3. Validate properties match what was created and not soft-deleted
  TestValidator.equals("id")(output.id)(created.id);
  TestValidator.equals("name")(output.name)(created.name);
  TestValidator.equals("color")(output.color)(created.color);
  TestValidator.equals("description")(output.description)(created.description);
  TestValidator.equals("enabled exists and is true by default")(typeof output.enabled === "boolean") (true);
  TestValidator.equals("deleted_at is null for non-deleted tag")(output.deleted_at)(null);
}

