import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardTag";

/**
 * Validate creation of a new discussion board tag (discussionboard_tag).
 *
 * This test covers creation with required and optional fields, verifies system
 * fields on return, enforces case-insensitive name uniqueness, and checks that
 * null values for color and description are accepted.
 *
 * 1. Create a tag with only the required `name`. Assert returned fields have expected defaults.
 * 2. Create a tag with name, valid color (HEX), and description. Assert returned fields.
 * 3. Attempt to create a tag with the same name but different casing (should fail uniqueness check).
 * 4. Create tag with `color` as null and verify accepted.
 * 5. Create tag with `description` as null and verify accepted.
 */
export async function test_api_discussionboard_test_create_tag_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Create a tag with only required fields (name)
  const nameRequired: string = `API-Test-Tag-${RandomGenerator.alphaNumeric(8)}`;
  const createdRequired = await api.functional.discussionboard.tags.post(connection, {
    body: { name: nameRequired },
  });
  typia.assert(createdRequired);
  TestValidator.equals("name")(createdRequired.name)(nameRequired);
  TestValidator.equals("enabled")(createdRequired.enabled)(true);
  TestValidator.equals("color")(createdRequired.color)(undefined);
  TestValidator.equals("description")(createdRequired.description)(undefined);
  TestValidator.predicate("id is uuid")(!!createdRequired.id && createdRequired.id.length > 0);
  TestValidator.predicate("created_at ISO 8601")(!!createdRequired.created_at && !isNaN(Date.parse(createdRequired.created_at)));
  TestValidator.predicate("updated_at ISO 8601")(!!createdRequired.updated_at && !isNaN(Date.parse(createdRequired.updated_at)));

  // 2. Create tag with all fields (name, color, description)
  const nameAll: string = `API-Test-Tag-All-${RandomGenerator.alphaNumeric(8)}`;
  const colorHEX = "#44AAFF";
  const descriptionFull = "Tag for automated E2E testing.";
  const createdAll = await api.functional.discussionboard.tags.post(connection, {
    body: { name: nameAll, color: colorHEX, description: descriptionFull },
  });
  typia.assert(createdAll);
  TestValidator.equals("name")(createdAll.name)(nameAll);
  TestValidator.equals("color")(createdAll.color)(colorHEX);
  TestValidator.equals("description")(createdAll.description)(descriptionFull);
  TestValidator.equals("enabled")(createdAll.enabled)(true);
  TestValidator.predicate("id is uuid")(!!createdAll.id && createdAll.id.length > 0);
  TestValidator.predicate("created_at ISO 8601")(!!createdAll.created_at && !isNaN(Date.parse(createdAll.created_at)));

  // 3. Uniqueness: attempt same tag name with different casing
  await TestValidator.error("Case-insensitive name uniqueness")(() =>
    api.functional.discussionboard.tags.post(connection, {
      body: { name: nameRequired.toUpperCase() },
    })
  );

  // 4. color: null is accepted
  const nameNullColor: string = `API-Test-Tag-NullColor-${RandomGenerator.alphaNumeric(8)}`;
  const createdNullColor = await api.functional.discussionboard.tags.post(connection, {
    body: { name: nameNullColor, color: null },
  });
  typia.assert(createdNullColor);
  TestValidator.equals("name")(createdNullColor.name)(nameNullColor);
  TestValidator.equals("color")(createdNullColor.color)(null);
  TestValidator.equals("enabled")(createdNullColor.enabled)(true);

  // 5. description: null is accepted
  const nameNullDesc: string = `API-Test-Tag-NullDesc-${RandomGenerator.alphaNumeric(8)}`;
  const createdNullDesc = await api.functional.discussionboard.tags.post(connection, {
    body: { name: nameNullDesc, color: "#112233", description: null },
  });
  typia.assert(createdNullDesc);
  TestValidator.equals("name")(createdNullDesc.name)(nameNullDesc);
  TestValidator.equals("color")(createdNullDesc.color)("#112233");
  TestValidator.equals("description")(createdNullDesc.description)(null);
  TestValidator.equals("enabled")(createdNullDesc.enabled)(true);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardTag";

/**
 * Validate that the API rejects the creation of a discussion board tag whose name differs only by letter case from an existing one (e.g., 'News' vs 'news').
 *
 * Business context:
 * Case-insensitive uniqueness is enforced for tag names in the discussion board. This ensures clarity, avoids confusion, and prevents duplicate tags that appear different only by their capitalization.
 *
 * Test steps:
 * 1. Create a tag with the name 'News'.
 * 2. Attempt to create a tag with the name 'news' (only case differs).
 * 3. Confirm that the API throws a uniqueness error and that the second tag is not created.
 */
export async function test_api_discussionboard_test_create_tag_with_duplicate_name_case_insensitive(
  connection: api.IConnection,
) {
  // 1. Create the initial tag with name 'News'
  const tagName = "News";
  const initialTag = await api.functional.discussionboard.tags.post(connection, {
    body: {
      name: tagName,
      color: "#00FF99",
      description: "A tag for all news-related threads.",
    } satisfies IDiscussionboardTag.ICreate,
  });
  typia.assert(initialTag);
  TestValidator.equals("tag name matches")(initialTag.name)(tagName);

  // 2. Attempt to create another tag with 'news' (case difference only)
  await TestValidator.error("should enforce case-insensitive uniqueness for tag names")(
    async () => {
      await api.functional.discussionboard.tags.post(connection, {
        body: {
          name: "news", // same as 'News' but with different casing
          color: "#00FF99",
          description: "Attempt to create a duplicate tag with different case.",
        } satisfies IDiscussionboardTag.ICreate,
      });
    },
  );
}

