import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardTag";

/**
 * 토론 게시판 태그의 mutable 필드(이름, 색상, 사용/비사용 상태, 설명 등) 업데이트 E2E 테스트
 *
 * 기존에 존재하는 토론 게시판 태그의 일부 필드를 유효한 ID로 업데이트한 뒤,
 * 실제로 반영·저장되는지 검증한다. 또한 논리 삭제/타임스탬프 등 공통 프로퍼티의
 * 상태 일관성도 확인한다.
 *
 * [프로세스]
 * 1. 새로운 태그를 생성하여 id를 확보한다.
 * 2. name, color, description, enabled 등 변경 가능한 필드를 무작위 값으로 수정하여 해당 id로 update.
 * 3. 업데이트 결과로 반환된 객체의 값에 patch 내용이 제대로 반영되었는지 검증.
 * 4. 타임스탬프(created_at/updated_at) 존재 및 논리삭제 필드가 null임도 확인한다.
 */
export async function test_api_discussionboard_test_update_tag_fields_success(
  connection: api.IConnection,
) {
  // 1. 새로운 태그 생성
  const tagCreateInput = {
    name: RandomGenerator.alphabets(10),
    color: "#33AAEE",
    description: "처음 설명입니다.",
  } satisfies IDiscussionboardTag.ICreate;
  const createdTag = await api.functional.discussionboard.tags.post(connection, {
    body: tagCreateInput,
  });
  typia.assert(createdTag);

  // 2. 일부 mutable 필드 값 변경 후 update
  const updatePatch = {
    name: RandomGenerator.alphabets(12),
    color: "#CC8833",
    description: "수정 설명입니다.",
    enabled: !createdTag.enabled,
  } satisfies IDiscussionboardTag.IUpdate;
  const updatedTag = await api.functional.discussionboard.tags.putById(connection, {
    id: createdTag.id,
    body: updatePatch,
  });
  typia.assert(updatedTag);

  // 3. patch 값 반영 검증
  if (typeof updatePatch.name !== "undefined")
    TestValidator.equals("이름 수정됨")(updatedTag.name)(updatePatch.name);
  if (typeof updatePatch.color !== "undefined")
    TestValidator.equals("색상 수정됨")(updatedTag.color)(updatePatch.color);
  if (typeof updatePatch.description !== "undefined")
    TestValidator.equals("설명 수정됨")(updatedTag.description)(updatePatch.description);
  if (typeof updatePatch.enabled !== "undefined")
    TestValidator.equals("활성화 값 수정됨")(updatedTag.enabled)(updatePatch.enabled);

  // 4. 타임스탬프, 논리 삭제 검증
  TestValidator.predicate("생성일 존재")(!!updatedTag.created_at);
  TestValidator.predicate("수정일 존재")(!!updatedTag.updated_at);
  TestValidator.equals("논리 삭제 없음")(updatedTag.deleted_at)(null);
}

