import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardTag";

/**
 * Test deletion behavior for discussion board tags that have already been soft-deleted (logical deletion).
 *
 * This test ensures that attempting to delete a tag which is already soft-deleted results in a proper error or not-found response,
 * validating correct API idempotency and error handling for repeated delete operations.
 *
 * Steps:
 * 1. Create a new discussion board tag (using valid, unique name).
 * 2. Soft-delete (erase) the newly created tag by its ID.
 * 3. Attempt to delete the same tag again by ID.
 *    - The API should respond with a not found error or a response clearly indicating the tag cannot be deleted again.
 *    - Validate that repeated delete attempts are idempotent and handled gracefully, with no change in system state or errors as per API design.
 *    - (Edge case) No tag restoration occurs.
 * 4. Confirm that the second deletion attempt does not succeed and raises an error (using TestValidator.error).
 */
export async function test_api_discussionboard_test_delete_tag_already_deleted(connection: api.IConnection) {
  // 1. Create a new tag
  const tagInput: IDiscussionboardTag.ICreate = {
    name: RandomGenerator.alphaNumeric(12),
    color: "#" + RandomGenerator.alphaNumeric(6),
    description: RandomGenerator.paragraph()(),
  };
  const createdTag = await api.functional.discussionboard.tags.post(connection, {
    body: tagInput,
  });
  typia.assert(createdTag);
  TestValidator.equals("tag created name")(createdTag.name)(tagInput.name);

  // 2. Soft-delete the tag by id
  const deletedTag = await api.functional.discussionboard.tags.eraseById(connection, {
    id: createdTag.id,
  });
  typia.assert(deletedTag);
  // Should have deleted_at set
  TestValidator.predicate("tag deleted_at set")(!!deletedTag.deleted_at);
  TestValidator.equals("tag id after deletion")(deletedTag.id)(createdTag.id);

  // 3. Attempt to delete again, expect error.
  await TestValidator.error("second delete should fail or return not found")(async () => {
    await api.functional.discussionboard.tags.eraseById(connection, {
      id: createdTag.id,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IDiscussionboardBookmark } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBookmark";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionboardBookmark } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardBookmark";

/**
 * 북마크 목록/검색 필터와 페이지네이션/정렬/에러 처리 검증 E2E
 *
 * 본 테스트는 discussionboard_bookmarks PATCH API의 페이징, 다양한 검색 필터/post별/날짜구간별/정렬별 반환 정확성,
 * 본인 소유 북마크만 노출되는지, 에러/파라미터 유효성 등 실전 시나리오를 폭넓게 검증합니다.
 *
 * [순서]
 * 1. 유저 2명 생성
 * 2. 각 유저가 임의 thread_id 기반 여러 게시글 등록
 * 3. 서로의 게시글 중 일부를 각 유저가 북마크 등록
 * 4. 각 유저 세션으로 로그인, 북마크 목록 전체 및 post별/created_at range별/정렬별/페이지별 리스트, 메타정보 확인
 * 5. 유저마다 본인 소유 북마크만 노출되는지, 타유저 북마크 정보 접근이 막히는지 검증
 * 6. 페이지네이션, total, boundary, limit 정보가 정확히 반환되는지 체크
 * 7. 잘못된 page/limit, 모순 필터 조합 등 전송시 400 오류 응답을 검증
 */
export async function test_api_discussionboard_test_list_user_bookmarks_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. 유저 2명 생성
  const user1Email = typia.random<string & tags.Format<"email">>();
  const user2Email = typia.random<string & tags.Format<"email">>();
  const user1 = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: user1Email,
      password: "pwTest_1A!dA",
      displayName: RandomGenerator.name(),
    },
  });
  typia.assert(user1);
  const user2 = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: user2Email,
      password: "pwTest_2B!cB",
      displayName: RandomGenerator.name(),
    },
  });
  typia.assert(user2);

  // 2. 게시글 여러 개(Thread 2개 기준, 각 3개씩 등록)
  const thread1Id = typia.random<string & tags.Format<"uuid">>();
  const thread2Id = typia.random<string & tags.Format<"uuid">>();
  // user1: thread1 에 3개
  const posts1 = await Promise.all(
    ArrayUtil.repeat(3)(() =>
      api.functional.discussionboard.posts.post(connection, {
        body: {
          thread_id: thread1Id,
          content: RandomGenerator.content()()(),
        },
      }),
    ),
  );
  for (const post of posts1) typia.assert(post);
  // user2: thread2 에 3개
  const posts2 = await Promise.all(
    ArrayUtil.repeat(3)(() =>
      api.functional.discussionboard.posts.post(connection, {
        body: {
          thread_id: thread2Id,
          content: RandomGenerator.content()()(),
        },
      }),
    ),
  );
  for (const post of posts2) typia.assert(post);

  // 3. 각 유저가 서로의 게시글 일부를 북마크 등록 → user1은 posts2[0,1], user2는 posts1[1,2]
  const bookmark1_1 = await api.functional.discussionboard.bookmarks.post(connection, {
    body: { user_id: user1.id, post_id: posts2[0].id },
  });
  const bookmark1_2 = await api.functional.discussionboard.bookmarks.post(connection, {
    body: { user_id: user1.id, post_id: posts2[1].id },
  });
  const bookmark2_1 = await api.functional.discussionboard.bookmarks.post(connection, {
    body: { user_id: user2.id, post_id: posts1[1].id },
  });
  const bookmark2_2 = await api.functional.discussionboard.bookmarks.post(connection, {
    body: { user_id: user2.id, post_id: posts1[2].id },
  });
  for (const b of [bookmark1_1, bookmark1_2, bookmark2_1, bookmark2_2]) typia.assert(b);

  // 4. 각 유저(세션별)로 북마크 리스트/검색/필터/정렬/페이지네이션 테스트
  // 4-1. user1 본인 북마크 전체 반환
  let res1 = await api.functional.discussionboard.bookmarks.patch(connection, {
    body: { user_id: user1.id },
  });
  typia.assert(res1);
  TestValidator.equals("본인 북마크 개수")(res1.data.length)(2);
  res1.data.forEach(b => TestValidator.equals("user_id 일치")(b.user_id)(user1.id));
  // 4-2. user2 본인 북마크 전체
  let res2 = await api.functional.discussionboard.bookmarks.patch(connection, {
    body: { user_id: user2.id },
  });
  typia.assert(res2);
  TestValidator.equals("본인 북마크 개수")(res2.data.length)(2);
  res2.data.forEach(b => TestValidator.equals("user_id 일치")(b.user_id)(user2.id));
  // 4-3. post별 검색
  let res1Post = await api.functional.discussionboard.bookmarks.patch(connection, {
    body: { user_id: user1.id, post_id: posts2[0].id },
  });
  typia.assert(res1Post);
  TestValidator.equals("post별 검색")(res1Post.data.length)(1);
  TestValidator.equals("post_id 일치")(res1Post.data[0].post_id)(posts2[0].id);
  // 4-4. created_at range 필터(첫 북마크 ~ 마지막)
  const allCreated = [bookmark1_1, bookmark1_2, bookmark2_1, bookmark2_2].map(b => b.created_at).sort();
  let dateRange: [string, string] = [allCreated[0], allCreated[allCreated.length - 1]];
  let res1Date = await api.functional.discussionboard.bookmarks.patch(connection, {
    body: {
      user_id: user1.id,
      created_at_range: dateRange,
    },
  });
  typia.assert(res1Date);
  TestValidator.equals("date range filter 수")(res1Date.data.length)(2);

  // 4-5. 정렬(created_at desc)
  let res1Sort = await api.functional.discussionboard.bookmarks.patch(connection, {
    body: {
      user_id: user1.id,
      sort_by: "created_at",
    },
  });
  typia.assert(res1Sort);
  TestValidator.equals("정렬")(res1Sort.data.length)(2);
  let sorted = [...res1Sort.data].sort((a, b) => b.created_at.localeCompare(a.created_at));
  TestValidator.equals("created_at desc 정렬 확인")(res1Sort.data)(sorted);

  // 4-6. 페이지네이션(page/limit/meta)
  let res1Paging = await api.functional.discussionboard.bookmarks.patch(connection, {
    body: {
      user_id: user1.id,
      pagination: { page: 1, limit: 1 },
    },
  });
  typia.assert(res1Paging);
  TestValidator.equals("limit 적용")(res1Paging.data.length)(1);
  TestValidator.equals("pagination meta current")(res1Paging.pagination.current)(1);
  TestValidator.equals("pagination meta limit")(res1Paging.pagination.limit)(1);
  TestValidator.predicate("pagination meta total")(res1Paging.pagination.records >= 2);

  // 5. 타 유저 북마크 데이터 노출 없음(존재하지 않을 user_id로 쿼리시)
  let resNo = await api.functional.discussionboard.bookmarks.patch(connection, {
    body: { user_id: typia.random<string & tags.Format<"uuid">>() },
  });
  typia.assert(resNo);
  TestValidator.equals("타인 소유 북마크 없음")(resNo.data.length)(0);

  // 6. 잘못된 파라미터 (음수 페이지/limit, created_at_range 부족, page 초과 등) 시 400 오류
  await TestValidator.error("음수 page/limit 시 400 오류")(
    async () => {
      await api.functional.discussionboard.bookmarks.patch(connection, {
        body: { user_id: user1.id, pagination: { page: -1, limit: -5 } },
      });
    },
  );
  await TestValidator.error("page 초과시 400 오류")(
    async () => {
      await api.functional.discussionboard.bookmarks.patch(connection, {
        body: { user_id: user1.id, pagination: { page: 100, limit: 1 } },
      });
    },
  );
  await TestValidator.error("created_at_range 1개짜리 전달시 400 오류")(
    async () => {
      await api.functional.discussionboard.bookmarks.patch(connection, {
        body: { user_id: user1.id, created_at_range: [allCreated[0]] as any },
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IDiscussionboardBookmark } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBookmark";

/**
 * 북마크 상세 조회(소유자/권한/에러 응답) 시나리오 검증
 *
 * 1. 유저 A 회원가입(POST /discussionboard/users, role: A)
 * 2. 유저 B 회원가입(POST /discussionboard/users, role: B)
 * 3. 유저 A로 포스트 작성(POST /discussionboard/posts)
 * 4. 유저 B로 북마크 추가(POST /discussionboard/bookmarks)
 * 5. 유저 B가 본인 북마크 상세 정상 조회(정상: GET /discussionboard/bookmarks/:id)
 * 6. 존재하지 않는(uuid) 북마크 상세 조회(404)
 * 7. A유저가 남(B)의 북마크 상세 조회 시도(403)
 */
export async function test_api_discussionboard_bookmarks_test_get_bookmark_detail_owned_by_user(
  connection: api.IConnection,
) {
  // 1. 유저 A 회원가입
  const userAEmail = typia.random<string & tags.Format<"email">>();
  const userAResult = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: userAEmail,
      password: "Aa1!testapi", // 실 패스워드, 정책 준수(숫자/문자 특수문자 혼합 등)
      displayName: RandomGenerator.name(),
      avatarUrl: undefined,
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(userAResult);

  // 2. 유저 B 회원가입
  const userBEmail = typia.random<string & tags.Format<"email">>();
  const userBResult = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: userBEmail,
      password: "Bb2!testapi",
      displayName: RandomGenerator.name(),
      avatarUrl: undefined,
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(userBResult);

  // 3. 유저 A로 포스트 작성 (thread 직접 uuid 생성)
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const postByA = await api.functional.discussionboard.posts.post(connection, {
    body: {
      thread_id: threadId,
      content: RandomGenerator.content()()(),
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(postByA);

  // 4. 유저 B로 북마크 추가(본인 user_id 입력 필요, post_id는 위 포스트)
  // (B유저로 전환이 필요한 경우, 세션/토큰 기반에서는 로그인 과정이 필요하나 여기선 매핑만)
  const bookmarkByB = await api.functional.discussionboard.bookmarks.post(connection, {
    body: {
      user_id: userBResult.id,
      post_id: postByA.id,
    } satisfies IDiscussionboardBookmark.ICreate,
  });
  typia.assert(bookmarkByB);

  // 5. 유저 B가 본인 북마크 상세 정상 조회
  const fetchedBookmark = await api.functional.discussionboard.bookmarks.getById(connection, {
    id: bookmarkByB.id,
  });
  typia.assert(fetchedBookmark);
  // 필드 일치 검증
  TestValidator.equals("bookmark id 일치")(fetchedBookmark.id)(bookmarkByB.id);
  TestValidator.equals("user_id 일치")(fetchedBookmark.user_id)(bookmarkByB.user_id);
  TestValidator.equals("post_id 일치")(fetchedBookmark.post_id)(bookmarkByB.post_id);
  TestValidator.equals("created_at 있음")(typeof fetchedBookmark.created_at === "string")(true);

  // 6. 존재하지 않는 북마크 uuid로 상세 조회(404)
  const notExistBookmarkId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("존재하지 않는 북마크 id 상세조회시 404 반환")(
    async () => {
      await api.functional.discussionboard.bookmarks.getById(connection, {
        id: notExistBookmarkId,
      });
    },
  );

  // 7. 유저 A가 남(B)의 북마크 id로 상세 조회(403에러)
  // '권한 불가' - API 구현에 따라 403/404/미노출 처리할 경우 요구사항에 맞게 check(여기선 403 기준)
  // (실제 서비스라면 user role 토큰이 다르므로 접속/Authorization 정보 분기 필요)
  // 이 예시에서는 같은 connection에서 접근 가정하므로 오로지 값만 체크
  await TestValidator.error("남의 북마크 id 상세조회시 403 반환")(
    async () => {
      // A유저가 B유저 북마크 조회 시도
      await api.functional.discussionboard.bookmarks.getById(connection, {
        id: bookmarkByB.id,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IDiscussionboardBookmark } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBookmark";

/**
 * 인증 사용자의 단일 게시글 북마크 생성 및 정책 검증 테스트
 *
 * 목적/검증:
 * - 인증된 사용자가 특정 게시글을 북마크(즐겨찾기)할 때 정상적으로 등록되는지 검증
 * - 반환값에서 user_id와 post_id 매핑 및 타입 확인
 * - 동일 user+post 조합의 중복 북마크 시도 시 409(Conflict) 오류 발생
 * - 인증되지 않은 상태에서 북마크 시도 시 401 또는 403(Forbidden) 오류 발생 보장
 *
 * **테스트 시나리오:**
 * 1. 신규 사용자 계정 생성
 * 2. 게시글 작성(테스트용 thread_id와 내용, 작성자는 등록된 사용자)
 * 3. 북마크 생성 (정상)
 * 4. 중복 북마크 시도 (409 Conflict)
 * 5. 인증 없는 상태에서 북마크 시도 (401/403 Forbidden)
 */
export async function test_api_discussionboard_test_create_bookmark_for_unique_post_by_authenticated_user(
  connection: api.IConnection,
) {
  // 1. 신규 유저 생성
  const userInput: IDiscussionboardUser.ICreate = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "password1234!",
    displayName: RandomGenerator.name(),
    isActive: true,
  };
  const user = await api.functional.discussionboard.users.post(connection, { body: userInput });
  typia.assert(user);

  // 2. 게시글 생성(임의 thread_id/내용)
  const postInput: IDiscussionboardPost.ICreate = {
    thread_id: typia.random<string & tags.Format<"uuid">>(),
    content: RandomGenerator.paragraph()(),
  };
  const post = await api.functional.discussionboard.posts.post(connection, { body: postInput });
  typia.assert(post);

  // 3. 북마크 생성
  const bookmarkInput: IDiscussionboardBookmark.ICreate = {
    user_id: user.id,
    post_id: post.id,
  };
  const bookmark = await api.functional.discussionboard.bookmarks.post(connection, { body: bookmarkInput });
  typia.assert(bookmark);
  TestValidator.equals("user_id 연동")(bookmark.user_id)(user.id);
  TestValidator.equals("post_id 연동")(bookmark.post_id)(post.id);

  // 4. 동일 user+post 중복 북마크 시도 → 409
  await TestValidator.error("중복 북마크 409")(() =>
    api.functional.discussionboard.bookmarks.post(connection, { body: bookmarkInput }),
  );

  // 5. 인증 없는 상태 테스트(Authorization 토큰 제거)
  const { Authorization, ...headersWithoutAuth } = connection.headers ?? {};
  const noAuthConn: api.IConnection = {
    ...connection,
    headers: headersWithoutAuth,
  };
  await TestValidator.error("비로그인 북마크는 401/403")(async () =>
    api.functional.discussionboard.bookmarks.post(noAuthConn, { body: bookmarkInput }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
