import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IDiscussionboardBookmark } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBookmark";

/**
 * Test updating a bookmark by its owner and validate permission/uniqueness restrictions.
 *
 * This test exercises the following business flow:
 * 1. Register two users (UserA and UserB)
 * 2. UserA creates two posts (Post1, Post2)
 * 3. UserA bookmarks Post1 (Bookmark1)
 * 4. UserA updates Bookmark1 to point to Post2 (if allowed by schema)
 *    - Confirms the 'post_id' is updated in the bookmark
 *    - Attempts update with 'post_id: null' (should retain the value)
 * 5. UserB attempts to update UserA's bookmark (must be forbidden)
 * 6. Attempt to update a non-existent bookmark (should be 404)
 * 7. UserA bookmarks Post2 (Bookmark2), then attempts to update Bookmark1's post_id to that of Bookmark2 (must fail for unicity)
 *
 * Steps are validated with type assertions, business outcome checks, and proper error boundaries.
 */
export async function test_api_discussionboard_test_update_bookmark_metadata_by_owner(
  connection: api.IConnection,
) {
  // 1. Register UserA
  const userAInput = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "Test!1234",
    displayName: RandomGenerator.name(),
  } satisfies IDiscussionboardUser.ICreate;
  const userA = await api.functional.discussionboard.users.post(connection, { body: userAInput });
  typia.assert(userA);

  // Register UserB for permission/uniqueness checks
  const userBInput = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "Test!2345",
    displayName: RandomGenerator.name(),
  } satisfies IDiscussionboardUser.ICreate;
  const userB = await api.functional.discussionboard.users.post(connection, { body: userBInput });
  typia.assert(userB);

  // 2. UserA creates two posts (simulate thread_id as random uuid for each)
  const post1 = await api.functional.discussionboard.posts.post(connection, {
    body: {
      thread_id: typia.random<string & tags.Format<"uuid">>(),
      content: "First post by userA",
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post1);

  const post2 = await api.functional.discussionboard.posts.post(connection, {
    body: {
      thread_id: typia.random<string & tags.Format<"uuid">>(),
      content: "Second post by userA",
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post2);

  // 3. UserA bookmarks Post1
  const bookmark1 = await api.functional.discussionboard.bookmarks.post(connection, {
    body: {
      user_id: userA.id,
      post_id: post1.id,
    } satisfies IDiscussionboardBookmark.ICreate,
  });
  typia.assert(bookmark1);

  // 4. UserA attempts to update bookmark1 to point to Post2
  const updateBody = {
    post_id: post2.id,
  } satisfies IDiscussionboardBookmark.IUpdate;
  const updatedBookmark = await api.functional.discussionboard.bookmarks.putById(connection, {
    id: bookmark1.id,
    body: updateBody,
  });
  typia.assert(updatedBookmark);
  TestValidator.equals("updated post_id")(updatedBookmark.post_id)(post2.id);

  // 4b. Update with `post_id: null` (should keep last value)
  const updateNullBody = {
    post_id: null,
  } satisfies IDiscussionboardBookmark.IUpdate;
  const unchangedBookmark = await api.functional.discussionboard.bookmarks.putById(connection, {
    id: bookmark1.id,
    body: updateNullBody,
  });
  typia.assert(unchangedBookmark);
  TestValidator.equals("post_id unchanged after null update")(unchangedBookmark.post_id)(updatedBookmark.post_id);

  // 5. UserB should not be able to update Bookmark1: forbidden (403)
  // (Simulate as UserB by updating the user_id in body)
  await TestValidator.error("forbidden for other user")(
    async () =>
      await api.functional.discussionboard.bookmarks.putById(connection, {
        id: bookmark1.id,
        body: {
          post_id: post1.id,
        } satisfies IDiscussionboardBookmark.IUpdate,
      }),
  );

  // 6. Attempt to update a non-existent bookmark (random UUID): not found (404)
  await TestValidator.error("not found for unknown bookmark")(
    async () =>
      await api.functional.discussionboard.bookmarks.putById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
        body: {
          post_id: post1.id,
        } satisfies IDiscussionboardBookmark.IUpdate,
      }),
  );

  // 7. Unicity: UserA bookmarks Post2 as a second bookmark, update to duplicate pair should fail
  const bookmark2 = await api.functional.discussionboard.bookmarks.post(connection, {
    body: {
      user_id: userA.id,
      post_id: post2.id,
    } satisfies IDiscussionboardBookmark.ICreate,
  });
  typia.assert(bookmark2);
  await TestValidator.error("duplicate user+post pair not permitted")(
    async () =>
      await api.functional.discussionboard.bookmarks.putById(connection, {
        id: bookmark1.id,
        body: {
          post_id: post2.id,
        } satisfies IDiscussionboardBookmark.IUpdate,
      }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IDiscussionboardBookmark } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBookmark";
import type { IVoidResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IVoidResponse";

/**
 * 테스트: 북마크 소유자와 타인이 북마크를 삭제할 때의 권한 및 예외 처리를 검증합니다.
 *
 * 1. 두 명의 유저(소유자, 타인)를 각각 생성합니다.
 * 2. 북마크 할 게시글(post)을 생성합니다(별도의 thread_id로 생성).
 * 3. 소유자 유저가 해당 post를 북마크합니다.
 * 4. 소유자가 자신이 만든 북마크를 삭제(정상 성공).
 * 5. 같은 id로 삭제 재시도(404).
 * 6. 동일 post-id로 같은 유저가 다시 북마크 생성(정상 생성).
 * 7. 타 유저가 이 북마크를 삭제하려 시도(권한 없음: 403, ※API 토큰/인증 시스템 기능이 없으므로 실제 호출·검증 불가).
 * 8. 무작위(존재하지 않는) 북마크 id로 삭제(404).
 * 9. (지원하는 부가 API가 없으므로 post/user의 북마크 수량 검증은 생략)
 *
 * [검증 목적]
 * - 본인만 북마크를 삭제할 수 있고, 삭제 후 더블 딜리트·타인 딜리트는 허용되지 않음을 보장합니다.
 * - 삭제된 id는 재생성 가능하며, 이미 삭제된/없는 id는 404 반환
 * - 북마크 생성/삭제 flow의 정상성, 권한, 예외를 종합 검증합니다.
 */
export async function test_api_discussionboard_test_delete_bookmark_by_owner_and_unauthorized_users(
  connection: api.IConnection,
) {
  // 1. 테스트용 유저(북마크 소유자) 생성
  const ownerEmail = typia.random<string & tags.Format<"email">>();
  const ownerPassword = "TestP@ssw0rd1";
  const owner: IDiscussionboardUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: ownerEmail,
      password: ownerPassword,
      displayName: RandomGenerator.name(),
    },
  });
  typia.assert(owner);

  // 2. 테스트용 타 유저 생성(차단 검증 목적)
  const anotherEmail = typia.random<string & tags.Format<"email">>();
  const anotherPassword = "TestP@ssw0rd2";
  const another: IDiscussionboardUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: anotherEmail,
      password: anotherPassword,
      displayName: RandomGenerator.name(),
    },
  });
  typia.assert(another);

  // 3. 게시글(post) 생성 (thread_id 임의값 지정)
  const dummyThreadId = typia.random<string & tags.Format<"uuid">>();
  const post: IDiscussionboardPost = await api.functional.discussionboard.posts.post(connection, {
    body: {
      thread_id: dummyThreadId,
      content: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(post);

  // 4. 소유자 북마크 생성
  const bookmark: IDiscussionboardBookmark = await api.functional.discussionboard.bookmarks.post(connection, {
    body: {
      user_id: owner.id,
      post_id: post.id,
    },
  });
  typia.assert(bookmark);

  // 5. 소유자 북마크 삭제
  await api.functional.discussionboard.bookmarks.eraseById(connection, { id: bookmark.id });

  // 6. 같은 id로 삭제 재시도 - 404 기대
  await TestValidator.error("동일 id 재삭제 시 404")(async () => {
    await api.functional.discussionboard.bookmarks.eraseById(connection, { id: bookmark.id });
  });

  // 7. 북마크 삭제 후 동일 post-id로 다시 북마크 생성(정상 성공)
  const bookmarkAgain: IDiscussionboardBookmark = await api.functional.discussionboard.bookmarks.post(connection, {
    body: {
      user_id: owner.id,
      post_id: post.id,
    },
  });
  typia.assert(bookmarkAgain);

  // 8. 타유저가 본인것 아닌 북마크를 삭제하면 403 (※ 실제 토큰/인지 기능 없으므로 동작은 논리만 명시)
  // 본 테스트 인프라는 API 인증/토큰 컨텍스트 전환을 지원하지 않으므로, 여기에선 "에러 발생이 기대됨"만 기술
  await TestValidator.error("타유저의 삭제시 403")(async () => {
    // 실제 환경에선 another가 인증된 상태에서 아래 호출:
    // await api.functional.discussionboard.bookmarks.eraseById(connection, { id: bookmarkAgain.id });
  });

  // 9. 무작위/존재하지 않는 북마크 id로 삭제 요청(404 기대)
  await TestValidator.error("존재하지 않는 id 삭제시 404")(async () => {
    await api.functional.discussionboard.bookmarks.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IPageIDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test retrieval of a paginated, filtered list of comments with varied filter and pagination options, ensuring permission-respecting results for normal and moderator/admin roles.
 *
 * Validates:
 * - Filtering by post_id, created_by_user_id, is_deleted, pagination, and empty result handling.
 * - Regular user sees only not-deleted comments; admin/moderator scenario could not be simulated as no role/auth mechanism is exposed.
 * - Pagination limit/overflow and invalid parameter error handling.
 * - Ensures only valid implementable scenario coverage per provided API and DTO.
 *
 * Steps:
 * 1. Create a post (gather real post_id to filter).
 * 2. Create several comments by multiple users under post.
 * 3. Query with filters: by post, by user, by delete flag, and pagination/empty/error edge cases.
 */
export async function test_api_discussionboard_test_list_comments_with_various_filters_and_permissions(
  connection: api.IConnection,
) {
  // 1. Create a post to comment under
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: {
      thread_id: typia.random<string & tags.Format<"uuid">>(),
      content: RandomGenerator.content()()(),
    },
  });
  typia.assert(post);

  // 2. Create comments with different users and delete status
  const user1 = typia.random<string & tags.Format<"uuid">>();
  const user2 = typia.random<string & tags.Format<"uuid">>();

  const comment1 = await api.functional.discussionboard.comments.post(connection, {
    body: { post_id: post.id, created_by_user_id: user1, content: "User1 Comment 1" },
  });
  typia.assert(comment1);
  const comment2 = await api.functional.discussionboard.comments.post(connection, {
    body: { post_id: post.id, created_by_user_id: user2, content: "User2 Comment 1" },
  });
  typia.assert(comment2);
  const comment3 = await api.functional.discussionboard.comments.post(connection, {
    body: { post_id: post.id, created_by_user_id: user1, content: "User1 Comment 2" },
  });
  typia.assert(comment3);

  // 3. As a regular user: filter by post_id, expect only not-deleted comments
  const page1 = await api.functional.discussionboard.comments.patch(connection, {
    body: { post_id: post.id, page: 1, limit: 100 },
  });
  typia.assert(page1);
  for (const c of page1.data) TestValidator.equals("post_id matches")(c.post_id)(post.id);
  for (const c of page1.data) TestValidator.equals("is_deleted is false")(c.is_deleted)(false);

  // 4. Filter by created_by_user_id: only user1's non-deleted comments
  const pageByUser1 = await api.functional.discussionboard.comments.patch(connection, {
    body: { post_id: post.id, created_by_user_id: user1, page: 1, limit: 100 },
  });
  typia.assert(pageByUser1);
  for (const c of pageByUser1.data) TestValidator.equals("by user1")(c.created_by_user_id)(user1);
  for (const c of pageByUser1.data) TestValidator.equals("is_deleted is false")(c.is_deleted)(false);

  // 5. Empty result (invalid post_id)
  const pageEmpty = await api.functional.discussionboard.comments.patch(connection, {
    body: { post_id: typia.random<string & tags.Format<"uuid">>(), page: 1, limit: 100 },
  });
  typia.assert(pageEmpty);
  TestValidator.equals("empty data")(pageEmpty.data.length)(0);

  // 6. Pagination: limit=1
  const pageLimit1 = await api.functional.discussionboard.comments.patch(connection, {
    body: { post_id: post.id, limit: 1, page: 1 },
  });
  typia.assert(pageLimit1);
  TestValidator.predicate("limit=1")(pageLimit1.data.length <= 1);

  // 7. High page (empty page)
  const pageHigh = await api.functional.discussionboard.comments.patch(connection, {
    body: { post_id: post.id, page: 100, limit: 1 },
  });
  typia.assert(pageHigh);
  TestValidator.equals("empty page")(pageHigh.data.length)(0);

  // 8. Invalid pagination parameters: limit 0, negative page, too large limit
  for (const { page, limit } of [ { page: 0, limit: 10 }, { page: -1, limit: 10 }, { page: 1, limit: 1000 } ]) {
    await TestValidator.error(`bad pagination page=${page} limit=${limit}`)(async () => {
      await api.functional.discussionboard.comments.patch(connection, {
        body: { post_id: post.id, page, limit },
      });
    });
  }

  // is_deleted=true filter as regular user: likely always empty
  const deletedPage = await api.functional.discussionboard.comments.patch(connection, {
    body: { post_id: post.id, is_deleted: true, page: 1, limit: 20 },
  });
  typia.assert(deletedPage);
  for (const c of deletedPage.data) TestValidator.equals("is_deleted true")(c.is_deleted)(true);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";

/**
 * Test retrieving a single discussion board comment by its UUID with comprehensive access and existence checks.
 *
 * This test covers realistic resource and edge scenarios:
 * 1. Successfully retrieve a valid, visible comment.
 * 2. Attempt to retrieve a non-existent comment (expect 404 Not Found).
 * 3. Attempt to retrieve a comment using invalid UUID format (expect validation error).
 *
 * Due to current API/DTO limitations, scenarios involving user switching, comment deletion, role-based permissions, or moderator-only access cannot be implemented and are omitted.
 *
 * Steps:
 * 1. Create a post (dependency).
 * 2. Create a comment under the post.
 * 3. Retrieve the comment by its UUID: expect correct data.
 * 4. Attempt to retrieve a non-existent comment: expect 404 error.
 * 5. Attempt to retrieve a comment using invalid UUID format: expect validation error.
 */
export async function test_api_discussionboard_test_fetch_single_comment_with_access_and_existence_checks(
  connection: api.IConnection,
) {
  // 1. Create a post (dependency)
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: {
      thread_id: typia.random<string & tags.Format<"uuid">>(),
      content: RandomGenerator.paragraph()(),
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // 2. Create a comment under the post
  const comment = await api.functional.discussionboard.comments.post(connection, {
    body: {
      post_id: post.id,
      created_by_user_id: typia.random<string & tags.Format<"uuid">>(),
      content: RandomGenerator.paragraph()(),
    } satisfies IDiscussionboardComment.ICreate,
  });
  typia.assert(comment);

  // 3. Retrieve the comment by its UUID: expect success and content match
  const fetched = await api.functional.discussionboard.comments.getById(connection, {
    id: comment.id,
  });
  typia.assert(fetched);
  TestValidator.equals("fetched comment id matches")(fetched.id)(comment.id);
  TestValidator.equals("fetched comment content matches")(fetched.content)(comment.content);
  TestValidator.equals("fetched comment post linkage")(fetched.post_id)(post.id);

  // 4. Attempt to retrieve a non-existent comment: expect 404 error
  await TestValidator.error("not found - non-existent comment")(() =>
    api.functional.discussionboard.comments.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    }),
  );

  // 5. Attempt to retrieve a comment with invalid UUID format: expect validation error
  await TestValidator.error("validation error - invalid UUID format")(() =>
    api.functional.discussionboard.comments.getById(connection, {
      // Intentionally use an invalid UUID string
      id: "not-a-uuid" as string & tags.Format<"uuid">,
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";

/**
 * Validate comment creation API under the discussion board service.
 *
 * This test covers the following scenarios:
 * 1. Successful creation of a comment using valid post_id, legitimate user, and non-empty content.
 * 2. Failure when attempting to comment on a non-existent post (invalid post_id).
 * 3. Failure on missing content or too-short content, triggering validation errors.
 * 4. Attempting to reply to a non-existent parent comment (invalid parent_comment_id).
 * 5. Attempting to reply to a comment where the parent does not belong to the same post.
 * 6. Permission edge cases: posting as a banned user, or on a locked (non-open) post/thread, if applicable.
 * 7. Basic anti-spam/duplication: if system applies throttling or duplicate prevention
 * 8. Confirming audit behavior by checking the output and expected response structure
 *
 * Preparation steps include:
 * - Create a user (valid)
 * - Create a post with that user as author.
 *
 * Edge cases involving moderation, thread locking, or bans are simulated by altering input or properties.
 */
export async function test_api_discussionboard_test_create_comment_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. Create a valid user
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userPassword = typia.random<string & tags.Format<"password">>();
  const displayName = RandomGenerator.name();
  const user = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: userEmail,
      password: userPassword,
      displayName: displayName,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(user);

  // 2. Create a valid post (API sets author implicitly, only thread_id and content allowed)
  const postThreadId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: {
      thread_id: postThreadId,
      content: RandomGenerator.paragraph()(),
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // 3. Success: Create a top-level comment
  const commentContent = RandomGenerator.paragraph()();
  const comment = await api.functional.discussionboard.comments.post(connection, {
    body: {
      post_id: post.id,
      created_by_user_id: user.id,
      content: commentContent,
    } satisfies IDiscussionboardComment.ICreate,
  });
  typia.assert(comment);
  TestValidator.equals("comment post_id matches")(comment.post_id)(post.id);
  TestValidator.equals("comment user id matches")(comment.created_by_user_id)(user.id);
  TestValidator.equals("comment content matches")(comment.content)(commentContent);
  TestValidator.equals("is not deleted")(comment.is_deleted)(false);

  // 4. Success: Create a reply (child) comment
  const replyContent = RandomGenerator.paragraph()();
  const reply = await api.functional.discussionboard.comments.post(connection, {
    body: {
      post_id: post.id,
      created_by_user_id: user.id,
      parent_comment_id: comment.id,
      content: replyContent,
    } satisfies IDiscussionboardComment.ICreate,
  });
  typia.assert(reply);
  TestValidator.equals("reply parent")(reply.parent_comment_id)(comment.id);

  // 5. Negative: comment on invalid post_id
  await TestValidator.error("invalid post_id should fail")(() =>
    api.functional.discussionboard.comments.post(connection, {
      body: {
        post_id: typia.random<string & tags.Format<"uuid">>(), // likely no such post
        created_by_user_id: user.id,
        content: RandomGenerator.paragraph()(),
      },
    })
  );

  // 6. Negative: missing content
  await TestValidator.error("missing content should fail")(() =>
    api.functional.discussionboard.comments.post(connection, {
      body: {
        post_id: post.id,
        created_by_user_id: user.id,
        content: "",
      },
    })
  );

  // 7. Negative: content too short
  await TestValidator.error("too-short content should fail")(() =>
    api.functional.discussionboard.comments.post(connection, {
      body: {
        post_id: post.id,
        created_by_user_id: user.id,
        content: "a", // likely too short depending on min length
      },
    })
  );

  // 8. Negative: reply to non-existent comment
  await TestValidator.error("replying to non-existent comment fails")(() =>
    api.functional.discussionboard.comments.post(connection, {
      body: {
        post_id: post.id,
        created_by_user_id: user.id,
        content: RandomGenerator.paragraph()(),
