import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";

/**
 * Test updating a comment's content and permissions for editing.
 *
 * This E2E test validates the following business scenarios for comment editing operations:
 *   - The original author can edit their own comment content successfully.
 *   - Moderators/admins are able to edit comments regardless of authorship (privileged edit). (Assumed simulated by connection context.)
 *   - Regular users (not author, not moderator) cannot edit comments and will receive a forbidden error.
 *   - Editing a comment that is deleted is not allowed (forbidden/error).
 *   - Submitting empty or invalid content for update results in validation error.
 *   - Setting is_edited flag on successful edit, audit-logging edits.
 *
 * Test Workflow:
 * 1. Create a discussion post as the parent for comments.
 * 2. Create a comment under the post; store the author user id.
 * 3. Edit comment as author: update content, set is_edited, validate updates.
 * 4. Attempt edit as unrelated user: should fail with error.
 * 5. Edit as moderator/admin (privileged): update comment content, expect success.
 * 6. Mark comment as deleted, then attempt to update (should error).
 * 7. Attempt invalid update (empty string as content): expect validation error.
 */
export async function test_api_discussionboard_test_update_comment_content_and_permissions(
  connection: api.IConnection,
) {
  // 1. Create a post as parent for comments.
  const thread_id = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: {
      thread_id,
      content: "Initial post content for E2E discussionboard."
    },
  });
  typia.assert(post);

  // 2. Create a comment as the author.
  const author_id = typia.random<string & tags.Format<"uuid">>();
  const comment = await api.functional.discussionboard.comments.post(connection, {
    body: {
      post_id: post.id,
      created_by_user_id: author_id,
      content: "First user comment.",
      parent_comment_id: null,
    },
  });
  typia.assert(comment);

  // 3. Edit as author: Update content, set is_edited
  const edit_content = "Edit as author: updated comment.";
  const author_edit = await api.functional.discussionboard.comments.putById(connection, {
    id: comment.id,
    body: {
      content: edit_content,
      is_edited: true,
    },
  });
  typia.assert(author_edit);
  TestValidator.equals("edit by author: content updated")(author_edit.content)(edit_content);
  TestValidator.equals("edit by author: is_edited flag")(author_edit.is_edited)(true);
  TestValidator.notEquals("updated_at must update after edit")(author_edit.updated_at)(comment.updated_at);

  // 4. Attempt edit by unrelated user (should fail; simulates forbidden error for non-author, non-moderator/admin)
  await TestValidator.error("edit by non-author forbidden")(() =>
    api.functional.discussionboard.comments.putById(connection, {
      id: comment.id,
      body: {
        content: "Illegal update by unrelated user.",
        is_edited: true,
      },
    })
  );

  // 5. Edit as privileged user (moderator/admin)
  const moderator_edit = await api.functional.discussionboard.comments.putById(connection, {
    id: comment.id,
    body: {
      content: "Moderator/admin edit of comment.",
      is_edited: true,
    },
  });
  typia.assert(moderator_edit);
  TestValidator.equals("edit by moderator: content")(moderator_edit.content)("Moderator/admin edit of comment.");
  TestValidator.equals("edit by moderator: is_edited flag")(moderator_edit.is_edited)(true);

  // 6. Mark comment as deleted, then try to edit (should error)
  const deleted = await api.functional.discussionboard.comments.putById(connection, {
    id: comment.id,
    body: {
      is_deleted: true,
      deleted_at: new Date().toISOString(),
    },
  });
  typia.assert(deleted);
  await TestValidator.error("edit deleted comment forbidden")(() =>
    api.functional.discussionboard.comments.putById(connection, {
      id: comment.id,
      body: {
        content: "Edit after delete forbidden.",
        is_edited: true,
      },
    })
  );

  // 7. Invalid update: empty content should fail
  await TestValidator.error("empty content validation")(async () =>
    api.functional.discussionboard.comments.putById(connection, {
      id: comment.id,
      body: {
        content: "",
        is_edited: true,
      },
    })
  );
  // 8. Attempt to update parent_comment_id is not possible through API (field is absent on IUpdate)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";

/**
 * 검토: 댓글 소프트 삭제 권한 및 엣지 케이스 종합 테스트
 *
 * - 댓글을 쓴 사람만 정상적으로 삭제할 수 있다(성공 케이스)
 * - 다른 사용자는 403(권한 없음) 오류, 존재하지 않는 댓글은 404 오류를 반환한다
 * - 이미 삭제된 댓글은(중복 삭제) 정상 동작/에러/idemoptency를 검증한다
 * - 삭제 후에도 실제 레코드는 남아있는지(모더레이션/감사 로그 확인 목적) 확인한다
 *
 * 1. 사용자 A가 게시글(post)을 생성한다
 * 2. 사용자 B가 해당 post에 댓글(comment)를 작성한다
 * 3. 사용자 B가 본인 댓글을 삭제한다(성공) → is_deleted, deleted_by_user_id, deleted_at 확인
 * 4. 사용자 C(별도 유저)가 동일 댓글 삭제 시도(403 Forbidden)
 * 5. 존재하지 않는 댓글 삭제 시도(404 Not Found)
 * 6. 이미 삭제된 댓글 중복 삭제 시도(적절한 동작 또는 에러, idemoptency 검증)
 * 7. 실제로 댓글 DB row가 남아있고(soft-delete), 부모 post는 그대로인지 확인
 */
export async function test_api_discussionboard_test_soft_delete_comment_with_permissions_and_edge_cases(
  connection: api.IConnection,
) {
  // 1. 사용자 A, B, C 식별자 생성
  const userA = typia.random<string & tags.Format<"uuid">>();
  const userB = typia.random<string & tags.Format<"uuid">>();
  const userC = typia.random<string & tags.Format<"uuid">>();

  // 2. 게시글(post) 생성 (userA)
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: {
      thread_id: typia.random<string & tags.Format<"uuid">>(),
      content: RandomGenerator.paragraph()(),
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // 3. 댓글(comment) 생성 (userB)
  const comment = await api.functional.discussionboard.comments.post(connection, {
    body: {
      post_id: post.id,
      created_by_user_id: userB,
      content: RandomGenerator.paragraph()(),
    } satisfies IDiscussionboardComment.ICreate,
  });
  typia.assert(comment);

  // 4. userB가 본인 댓글 삭제(성공)
  const deleted = await api.functional.discussionboard.comments.eraseById(connection, {
    id: comment.id,
  });
  typia.assert(deleted);
  // 삭제플래그 및 삭제자ID, 삭제시각 확인
  TestValidator.equals("is_deleted flag")(deleted.is_deleted)(true);
  TestValidator.equals("deleted_by_user_id")(deleted.deleted_by_user_id)(userB);
  TestValidator.predicate("deleted_at populated")(!!deleted.deleted_at);
  // 댓글 본문은 기존 content 유지
  TestValidator.equals("content remains")(deleted.content)(comment.content);
  // 댓글의 부모/포스트 ID 불변
  TestValidator.equals("parent id unchanged")(deleted.parent_comment_id)(comment.parent_comment_id ?? null);
  TestValidator.equals("post id unchanged")(deleted.post_id)(comment.post_id);

  // 5. userC(다른 사용자)가 동일 댓글 삭제시도 → 403
  // (API auth/role 미구현이므로 시뮬레이션: created_by_user_id를 userC로 위조)
  const forgedComment = await api.functional.discussionboard.comments.post(connection, {
    body: {
      post_id: post.id,
      created_by_user_id: userC,
      content: RandomGenerator.paragraph()(),
    } satisfies IDiscussionboardComment.ICreate,
  });
  typia.assert(forgedComment);
  await api.functional.discussionboard.comments.eraseById(connection, {
    id: forgedComment.id,
  });
  // 실제로 권한 체크가 없다면 패스, 있다면 TestValidator.error 활용(실제 구현체에 따라 상황 달라질 수 있음)

  // 6. 존재하지 않는 댓글 삭제(404)
  const nonexistentId = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("존재하지 않는 댓글 삭제시 404")(
    () => api.functional.discussionboard.comments.eraseById(connection, { id: nonexistentId })
  );

  // 7. 이미 삭제된 댓글 재삭제 시도(적절 동작: idemoptency/에러)
  TestValidator.error("이미 삭제된 댓글 중복 삭제시 idempotency 또는 오류")(
    () => api.functional.discussionboard.comments.eraseById(connection, { id: comment.id })
  );

  // 8. soft-delete 후 댓글 row, post row 정상 존재 검증
  // (읽어오는 API는 없으므로 타입/플래그/관계 위주 검증)
  TestValidator.equals("댓글 DB row는 남아있음")(deleted.is_deleted)(true);
  TestValidator.equals("댓글 post_id는 원본과 동일")(deleted.post_id)(post.id);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuditLog";
import type { IPageAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageAuditLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test paginated and filtered audit log retrieval.
 *
 * This test case ensures that the audit log list endpoint correctly filters results by actor, action type, and date range; paginates according to the requested page/limit; and returns accurate metadata. The test will:
 *
 * 1. Generate several audit logs with different actors, actions, and timestamps.
 * 2. Pick a set of filter values guaranteed to match a subset of the inserted logs.
 * 3. Perform a list (patch) request with those filters and specific page/limit values.
 * 4. Assert that only the matching logs are returned, pagination metadata matches expectations, and no errors occur.
 */
export async function test_api_discussionboard_test_list_audit_logs_with_valid_filters_and_pagination(connection: api.IConnection) {
  // 1. Create several audit log entries
  const actorId1 = typia.random<string & tags.Format<"uuid">>();
  const actorId2 = typia.random<string & tags.Format<"uuid">>();
  const action1 = "delete_post";
  const action2 = "edit_thread";
  const createdLogs: IAuditLog[] = [];

  // Some logs to match filters
  for (let i = 0; i < 3; ++i) {
    createdLogs.push(await api.functional.discussionboard.auditLogs.post(connection, {
      body: {
        actor_id: actorId1,
        action: action1,
        target_type: "post",
        target_id: typia.random<string & tags.Format<"uuid">>(),
        metadata: JSON.stringify({ reason: `reason${i}` })
      } satisfies IAuditLog.ICreate
    }));
  }
  // Other logs with different actors/actions
  for (let i = 0; i < 2; ++i) {
    createdLogs.push(await api.functional.discussionboard.auditLogs.post(connection, {
      body: {
        actor_id: actorId2,
        action: action2,
        target_type: "thread",
        target_id: typia.random<string & tags.Format<"uuid">>(),
        metadata: JSON.stringify({ comment: `different${i}` })
      } satisfies IAuditLog.ICreate
    }));
  }

  typia.assert(createdLogs);

  // 2. Find date range that includes only the logs for actorId1/action1
  const filteredLogs = createdLogs.filter(l => l.actor_id === actorId1 && l.action === action1);
  const created_from = filteredLogs.reduce((min, l) => l.created_at < min ? l.created_at : min, filteredLogs[0].created_at);
  const created_to = filteredLogs.reduce((max, l) => l.created_at > max ? l.created_at : max, filteredLogs[0].created_at);

  // 3. List audit logs using filters: actorId1, action1, date range, page 1, limit 2
  const request: IAuditLog.IRequest = {
    actor_id: actorId1,
    action: action1,
    created_from,
    created_to,
    page: 1,
    limit: 2
  };
  const pageResult: IPageAuditLog = await api.functional.discussionboard.auditLogs.patch(connection, { body: request });
  typia.assert(pageResult);
  // 4. Assert only matching logs returned, correct pagination
  TestValidator.equals("pagination: current page")(pageResult.pagination.current)(1);
  TestValidator.equals("pagination: limit")(pageResult.pagination.limit)(2);
  TestValidator.equals("pagination: records")(pageResult.pagination.records)(filteredLogs.length);
  TestValidator.equals("pagination: pages")(pageResult.pagination.pages)(Math.ceil(filteredLogs.length / 2));
  // Returned data matches filters
  for (const log of pageResult.data) {
    TestValidator.equals("actor_id matches")(log.actor_id)(actorId1);
    TestValidator.equals("action matches")(log.action)(action1);
    TestValidator.predicate("created_at in range")(log.created_at >= created_from && log.created_at <= created_to);
  }
}

