/**
 * Validate that an audit log entry can be retrieved by its valid UUID
 * and that the data matches exactly what was created.
 *
 * This test ensures that:
 * - A new audit log entry is created (simulating admin action, as only admins should be able to perform these actions)
 * - The entry can then be fetched by its ID via the GET /discussionboard/auditLogs/{id} endpoint
 * - All fields in the response match exactly those that were stored upon creation
 *
 * Step-by-step process:
 * 1. Create a new audit log entry with random (but valid) data
 * 2. Fetch the audit log entry by its returned id (UUID)
 * 3. Assert that all fields in the API response match the values returned at creation
 */
export async function test_api_discussionboard_test_get_audit_log_by_valid_id(
  connection: api.IConnection,
) {
  // 1. Create an audit log entry (simulate as admin)
  const input: IAuditLog.ICreate = {
    actor_id: typia.random<string & tags.Format<"uuid">>(),
    action: "delete_post",
    target_type: "post",
    target_id: typia.random<string & tags.Format<"uuid">>(),
    metadata: JSON.stringify({ reason: "Spam", ip: "192.0.2.1" })
  };
  const created: IAuditLog = await api.functional.discussionboard.auditLogs.post(connection, {
    body: input,
  });
