import api from "@ORGANIZATION/PROJECT-api";
import type { IAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuditLog";

/**
 * Validate that a system admin can update the metadata property of an existing audit log entry.
 *
 * Audit logs are designed to ensure compliance and traceability, so only certain properties (metadata) can be modified. Actor, action, target, and creation timestamp are immutable.
 *
 * This test creates a new audit log entry, then uses the update endpoint to patch its metadata field. The test validates that:
 * 1. The response contains the updated metadata.
 * 2. Immutable fields (actor_id, action, target_type, target_id, created_at) remain unchanged after the update.
 *
 * Workflow:
 * 1. Create a new audit log entry with given details, capturing the returned full log entry (including its uuid).
 * 2. Update the log's metadata to a new value via the update (PUT) endpoint.
 * 3. Assert that the metadata in the response reflects the update, and all immutable fields are unchanged from the original creation.
 */
export async function test_api_discussionboard_auditLogs_test_update_audit_log_with_valid_patch(
  connection: api.IConnection,
) {
  // 1. Create a new audit log entry to update
  const createInput: IAuditLog.ICreate = {
    actor_id: typia.random<string & tags.Format<"uuid">>(),
    action: "ban_user",
    target_type: "user",
    target_id: typia.random<string & tags.Format<"uuid">>(),
    metadata: JSON.stringify({ before: { banned: false }, after: { banned: true } }),
  };
  const created: IAuditLog = await api.functional.discussionboard.auditLogs.post(
    connection, { body: createInput }
  );
  typia.assert(created);

  // 2. Update only the metadata field
  const updateInput: IAuditLog.IUpdate = {
    metadata: JSON.stringify({ after: { banned: true, bannedUntil: "2026-01-01" } }),
  };
  const updated: IAuditLog = await api.functional.discussionboard.auditLogs.putById(
    connection,
    {
      id: created.id,
      body: updateInput,
    },
  );
  typia.assert(updated);

  // 3. Validation: modifiable field changed, immutable fields unchanged
  TestValidator.equals("id remains unchanged")(updated.id)(created.id);
  TestValidator.equals("actor_id remains unchanged")(updated.actor_id)(created.actor_id);
  TestValidator.equals("action remains unchanged")(updated.action)(created.action);
  TestValidator.equals("target_type remains unchanged")(updated.target_type)(created.target_type);
  TestValidator.equals("target_id remains unchanged")(updated.target_id)(created.target_id);
  TestValidator.equals("created_at remains unchanged")(updated.created_at)(created.created_at);
  TestValidator.equals("updated metadata reflected")(updated.metadata)(updateInput.metadata);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuditLog";

/**
 * 감사 로그 엔트리의 불변 필드 업데이트 시도를 검증합니다.
 *
 * 이 테스트는 감사 로그(Audit Log) API가 actor_id, created_at와 같은 불변 필드에 대한 수정 시도를
 * 적절하게 거부하는지, 즉 비즈니스 규칙에 따라 허용되지 않는 필드 업데이트가 차단되는지를 확인합니다.
 *
 * [절차]
 * 1. 허용된 필드만 사용해 유효한 감사 로그 엔트리를 생성합니다.
 * 2. (정상 경로) metadata만 업데이트하는 요청을 보내 허용된 필드만 변경이 가능한지 확인합니다.
 *    - metadata 변경에 성공하며, actor_id와 created_at 등 불변 필드는 그대로임을 검증합니다.
 * 3. (비정상 경로) metadata 필드에 actor_id를 포함하도록 조작해, 불변 필드 변경을 암시하는 요청을 보냅니다.
 *    - 실제 API 구조상 metadata만 전달할 수 있으므로, business logic이 metadata 속 value에 불변 필드 변경
 *      시도를 감지하고 올바르게 거부(error)하는지 확인합니다.
 */
export async function test_api_discussionboard_test_update_audit_log_immutable_field_violation(
  connection: api.IConnection,
) {
  // 1. 감사 로그 엔트리 생성
  const initialLog = await api.functional.discussionboard.auditLogs.post(connection, {
    body: {
      actor_id: typia.random<string & tags.Format<"uuid">>(),
      action: "edit_thread",
      target_type: "thread",
      metadata: JSON.stringify({ foo: "bar" })
    } satisfies IAuditLog.ICreate,
  });
  typia.assert(initialLog);

  // 2. (정상 경로) metadata 변경 시도
  const updatedMetadata = JSON.stringify({ updated: true });
  const updatedLog = await api.functional.discussionboard.auditLogs.putById(connection, {
    id: initialLog.id,
    body: {
      metadata: updatedMetadata
    } satisfies IAuditLog.IUpdate,
  });
  typia.assert(updatedLog);
  // 불변 필드들은 변경되지 않았음을 확인
  TestValidator.equals("actor_id는 metadata 업데이트 후에도 변하지 않아야 함")(updatedLog.actor_id)(initialLog.actor_id);
  TestValidator.equals("created_at은 metadata 업데이트 후에도 변하지 않아야 함")(updatedLog.created_at)(initialLog.created_at);

  // 3. (비정상 경로) metadata 내에 actor_id 변조값 포함 후 update 시도 → 에러 발생해야 함
  const maliciousMetadata = JSON.stringify({ actor_id: typia.random<string & tags.Format<"uuid">>() });
  const forbiddenUpdate = async () => {
    await api.functional.discussionboard.auditLogs.putById(connection, {
      id: initialLog.id,
      body: {
        metadata: maliciousMetadata,
      } satisfies IAuditLog.IUpdate,
    });
  };
  await TestValidator.error("metadata 값에 actor_id 변조시 update는 거부되어야 한다")(forbiddenUpdate);
}

