import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { IDiscussionboardFollow } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardFollow";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionboardFollow } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardFollow";

/**
 * Validate listing of a user's follows with correct ownership and pagination, plus unauthorized error on unauthenticated attempt.
 *
 * This test ensures that:
 * - When a user creates multiple follow relationships (to both users and threads),
 *   listing (PATCH /discussionboard/follow) returns only their records, with correct
 *   pagination metadata. It also ensures that unauthenticated requests to list follows
 *   are denied.
 *
 * Test Steps:
 * 1. Register a new user via /discussionboard/users (which authenticates the session)
 * 2. As that user, create multiple follows (to other users, and to threads with random UUIDs)
 * 3. List follows with PATCH /discussionboard/follow using default pagination and filter (follower_user_id)
 *    - Assert only records of that user are returned
 *    - Assert pagination meta matches expected page/limit/record counts
 * 4. Attempt PATCH /discussionboard/follow as an unauthenticated user and assert unauthorized error
 */
export async function test_api_discussionboard_test_list_follows_with_default_pagination_and_ownership(
  connection: api.IConnection,
) {
  // 1. Register a new user (who will be our owner/follower)
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userPassword = "PW@123testX";
  const userDisplayName = RandomGenerator.name();
  const user = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: userEmail,
      password: userPassword,
      displayName: userDisplayName,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(user);

  // 2. Create several follow records: 3 user follows, 2 thread follows
  const createdFollows: IDiscussionboardFollow[] = [];

  // User-to-user follows
  for (let i = 0; i < 3; ++i) {
    const followee = await api.functional.discussionboard.users.post(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: "AAb1@pwX!#" + i,
        displayName: RandomGenerator.name(),
      } satisfies IDiscussionboardUser.ICreate,
    });
    typia.assert(followee);
    const followUser = await api.functional.discussionboard.follow.post(connection, {
      body: {
        follower_user_id: user.id,
        followed_user_id: followee.id,
        followed_thread_id: null,
      } satisfies IDiscussionboardFollow.ICreate,
    });
    typia.assert(followUser);
    createdFollows.push(followUser);
  }

  // User-to-thread follows (using random UUIDs for thread IDs, since thread creation is unavailable)
  for (let i = 0; i < 2; ++i) {
    const followThread = await api.functional.discussionboard.follow.post(connection, {
      body: {
        follower_user_id: user.id,
        followed_user_id: null,
        followed_thread_id: typia.random<string & tags.Format<"uuid">>(),
      } satisfies IDiscussionboardFollow.ICreate,
    });
    typia.assert(followThread);
    createdFollows.push(followThread);
  }

  // 3. List follows for the user (PATCH with just follower_user_id, default paging)
  const pageResult = await api.functional.discussionboard.follow.patch(connection, {
    body: {
      follower_user_id: user.id,
    } satisfies IDiscussionboardFollow.IRequest,
  });
  typia.assert(pageResult);
  // Assert every returned follow belongs to this user
  for (const follow of pageResult.data) {
    TestValidator.equals("Follow ownership")(follow.follower_user_id)(user.id);
  }
  // Pagination metadata assertions
  TestValidator.equals("Current page")(pageResult.pagination.current)(1);
  TestValidator.equals("Default limit")(pageResult.pagination.limit)(100);
  TestValidator.equals("Total records")(pageResult.pagination.records)(createdFollows.length);
  TestValidator.equals("Total pages")(pageResult.pagination.pages)(1);

  // 4. Unauthenticated attempt (clear headers)
  const anonymousConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error("Unauthenticated follow list denied")(async () => {
    await api.functional.discussionboard.follow.patch(anonymousConn, {
      body: { follower_user_id: user.id } satisfies IDiscussionboardFollow.IRequest,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { IDiscussionboardFollow } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardFollow";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionboardFollow } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardFollow";

/**
 * Validate the filtering, listing, and error handling for the follow list API (`PATCH /discussionboard/follow`).
 *
 * This scenario demonstrates filtering by followed_user_id, followed_thread_id, date range, and tests paging over-limit.
 *
 * Steps:
 * 1. Register an authenticated user (follower), at least two potential targets for following (user and "thread", simulated with another user ID).
 * 2. As the follower, create two follow relationships: one targeting a user, one "simulating" a thread by using a unique thread-id value.
 * 3. List follows filtered by followed_user_id, confirm only that follow appears.
 * 4. List follows filtered by followed_thread_id, confirm only that follow appears.
 * 5. List follows filtered by both (should yield empty), confirming filter AND logic.
 * 6. List follows with created_at_range covering/excluding records and verify proper inclusion/exclusion.
 * 7. List follows with default paging, then with an overlarge limit to trigger/validate paging errors.
 *
 * All responses must be validated for type, and filtering/paging correctness. Invalid paging requests should cause error (TestValidator.error).
 */
export async function test_api_discussionboard_test_list_follows_with_different_filters(connection: api.IConnection) {
  // 1. Register users
  const follower = await api.functional.discussionboard.users.post(connection, {body: {
    email: typia.random<string & tags.Format<'email'>>(),
    password: '1234' as string & tags.Format<'password'>,
    displayName: RandomGenerator.name(),
  } satisfies IDiscussionboardUser.ICreate});
  typia.assert(follower);
  const targetUser = await api.functional.discussionboard.users.post(connection, {body: {
    email: typia.random<string & tags.Format<'email'>>(),
    password: '1234' as string & tags.Format<'password'>,
    displayName: RandomGenerator.name(),
  } satisfies IDiscussionboardUser.ICreate});
  typia.assert(targetUser);
  // For thread-follow simulation, assume a random UUID representing a thread
  const threadId: string & tags.Format<'uuid'> = typia.random<string & tags.Format<'uuid'>>();

  // 2. Follower creates follow to targetUser
  const followUser = await api.functional.discussionboard.follow.post(connection, {body: {
    follower_user_id: follower.id,
    followed_user_id: targetUser.id,
    followed_thread_id: null,
  }});
  typia.assert(followUser);

  // 2b. Follower creates follow to "thread"
  const followThread = await api.functional.discussionboard.follow.post(connection, {body: {
    follower_user_id: follower.id,
    followed_user_id: null,
    followed_thread_id: threadId,
  }});
  typia.assert(followThread);

  // 3. List follows by followed_user_id only
  const listUser = await api.functional.discussionboard.follow.patch(connection, {body: {
    followed_user_id: targetUser.id,
  }});
  typia.assert(listUser);
  TestValidator.predicate('filter by followed_user_id returns only expected follow')(
    listUser.data.length === 1 && listUser.data[0].id === followUser.id
  );

  // 4. List follows by followed_thread_id only
  const listThread = await api.functional.discussionboard.follow.patch(connection, {body: {
    followed_thread_id: threadId,
  }});
  typia.assert(listThread);
  TestValidator.predicate('filter by followed_thread_id returns only expected follow')(
    listThread.data.length === 1 && listThread.data[0].id === followThread.id
  );

  // 5. Filter by both followed_user_id and followed_thread_id (should yield none)
  const listBoth = await api.functional.discussionboard.follow.patch(connection, {body: {
    followed_user_id: targetUser.id,
    followed_thread_id: threadId,
  }});
  typia.assert(listBoth);
  TestValidator.equals('combined filter returns no entries')(listBoth.data.length)(0);

  // 6. Filter by created_at_range (include only followUser and followThread)
  const createdAts = [new Date(followUser.created_at), new Date(followThread.created_at)].sort((a, b) => a.getTime() - b.getTime());
  const beforeAll = new Date(createdAts[0].getTime() - 1000).toISOString();
  const afterAll = new Date(createdAts[1].getTime() + 1000).toISOString();
  const listByDate = await api.functional.discussionboard.follow.patch(connection, {body: {
    created_at_range: [beforeAll, afterAll] as [string, string] & tags.MinItems<2> & tags.MaxItems<2>,
  }});
  typia.assert(listByDate);
  TestValidator.predicate('date filter includes both follows')(
    listByDate.data.some(item => item.id === followUser.id) &&
    listByDate.data.some(item => item.id === followThread.id)
  );
  // Now filter with non-matching range
  const listByWrongDate = await api.functional.discussionboard.follow.patch(connection, {body: {
    created_at_range: [
      (new Date('2000-01-01T00:00:00.000Z')).toISOString(),
      (new Date('2000-01-01T00:00:01.000Z')).toISOString()
    ] as [string, string] & tags.MinItems<2> & tags.MaxItems<2>,
  }});
  typia.assert(listByWrongDate);
  TestValidator.equals('non-matching date range returns none')(listByWrongDate.data.length)(0);

  // 7. List follows with overlimit page size - expect error
  await TestValidator.error('paging overlimit triggers error')(async () => {
    await api.functional.discussionboard.follow.patch(connection, {body: {
      pagination: {page: 1, limit: 1000000}
    }});
  });
}

