 * Test successful creation and conflict detection for following a thread.
 *
 * This test verifies a user's ability to follow a discussion thread via the API, and confirms that following the same thread twice is prevented. It covers user registration, thread creation, follow action, entity validation, and duplicate follow error handling.
 *
 * Steps:
 * 1. Register a discussion board user for authentication.
 * 2. Create a new discussion thread under some board (assuming board exists).
 * 3. POST /discussionboard/follow with followed_thread_id set, to follow the thread as the created user.
 * 4. Validate that the response returns correct follow entity details (follower_user_id, followed_thread_id, created_at, id).
 * 5. Attempt to follow the same thread again and expect a conflict error (duplicate follow is business rule violation).
 */
export async function test_api_discussionboard_test_create_follow_for_thread_success(
  connection: api.IConnection,
) {
  // 1. Register a user
  const email = typia.random<string & tags.Format<"email">>();
  const password = typia.random<string & tags.Format<"password">>();
  const displayName = RandomGenerator.name();
  const user = await api.functional.discussionboard.users.post(connection, {
    body: {
      email,
      password,
      displayName,
    },
  });
