 * 4. Create a different target user to switch the follow relation to.
 * 5. Update the follow record using PUT /discussionboard/follow/{id}, changing the followed_user_id to the new target user.
 * 6. Confirm the follow record is updated as expected in the response.
 */
export async function test_api_discussionboard_test_update_follow_notification_preferences_success(
  connection: api.IConnection,
