      password: typia.random<string & tags.Format<"password">>(),
      displayName: RandomGenerator.name(),
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(newTargetUser);

  // 5. Update the follow record: switch followed_user_id to new target
  const updated = await api.functional.discussionboard.follow.putById(connection, {
