import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { IDiscussionboardFollow } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardFollow";

/**
 * 다른 사용자가 생성한 follow 레코드는 소유자가 아니면 삭제할 수 없어야 함을 검증한다.
 *
 * [비즈니스 시나리오 및 검증 목적]
 * - 권한이 없는 사용자가 타인의 팔로우(follow) 기록을 삭제할 수 없게 막아야 한다.
 *
 * [검증 프로세스]
 * 1. 유저 A(팔로우 주인) 회원가입
 * 2. 유저 B(삭제 시도자) 회원가입
 * 3. 유저 A로 팔로우 레코드 생성 (팔로우 대상은 유저 B)
 * 4. 유저 B로 로그인/인증 컨텍스트 전환
 * 5. 유저 B가 유저 A가 소유한 follow 기록을 DELETE 요청 → 403 Forbidden(권한 없음) 오류를 발생시켜야 한다.
 *
 * (보조 사항: follow가 실제로 삭제되지 않았는지 목록/상세 API가 없으니 상태 검증은 생략)
 */
export async function test_api_discussionboard_test_delete_follow_forbidden_for_non_owner(connection: api.IConnection) {
  // 1. 유저 A(팔로우 주인) 회원가입
  const userAEmail = typia.random<string & tags.Format<'email'>>();
  const userA = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: userAEmail,
      password: 'Aa!12345',
      displayName: RandomGenerator.name(),
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(userA);

  // 2. 유저 B(삭제 시도자) 회원가입
  const userBEmail = typia.random<string & tags.Format<'email'>>();
  const userB = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: userBEmail,
      password: 'Bb!54321',
      displayName: RandomGenerator.name(),
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(userB);

  // === 아래에서 인증 컨텍스트는 테스트 프레임워크가 관리한다고 가정 ===
  // 3. 유저 A(주인) 것이므로, A context에서 팔로우 생성 (타겟: 유저 B)
  const followRecord = await api.functional.discussionboard.follow.post(connection, {
    body: {
      follower_user_id: userA.id,
      followed_user_id: userB.id,
      followed_thread_id: null,
    } satisfies IDiscussionboardFollow.ICreate,
  });
  typia.assert(followRecord);

  // 4~5. 유저 B로 context 전환 후, 유저 A가 만든 follow를 삭제하려 하면 권한 오류(403)
  // (TestValidator.error로 Forbidden 발생을 보장)
  await TestValidator.error('비소유자가 follow 삭제 시 403 Forbidden 반환')(async () => {
    await api.functional.discussionboard.follow.eraseById(connection, {
      id: followRecord.id,
    });
  });
}

