import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerator";
import type { IPageDiscussionboardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionboardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 모더레이터 배정 목록 조회의 필터/페이징/권한관리 기능 검증(E2E)
 *
 * - 관리자의 권한 하에, 다양한 유저와 여러 게시판에 모더레이터 배정을 여러 건 생성한다.
 * - 각 배정의 활성/비활성 상태, 소속 보드, 유저 등 다양한 속성을 부여한 뒤,
 * - PATCH /discussionboard/moderators를 통해
 *   1. 현직(활성) 모더레이터만 필터(activeOnly)
 *   2. 특정 board_id 기준 필터
 *   3. 특정 user_id 기준 필터
 *   등 다양한 조건으로 목록을 조회한다.
 * - 각 경우, 반환되는 pagination(페이지네이션) 구조와 목록(ISummary) 무결성, 필터 조건과 일치함을 검증한다.
 * - (선택) 비관리자 접근시에는 권한에러가 발생함을 TestValidator.error로 확인한다.
 */
export async function test_api_discussionboard_test_list_moderator_assignments_with_valid_filters(
  connection: api.IConnection,
) {
  // === 사전 데이터 준비 ===
  // 3명의 유저(유저A,B,C)와 2개의 보드(boardA, boardB)에 대해 아래와 같이 배정
  // 유저A: boardA, 활성
  // 유저B: boardA, 비활성(revoked)
  // 유저C: boardB, 활성
  // 플랫폼 전체(보드null) 유저D: 활성
  const adminId: string = typia.random<string & tags.Format<"uuid">>();

  // 개별 유저, 보드 UUID 생성
  const userA: string = typia.random<string & tags.Format<"uuid">>();
  const userB: string = typia.random<string & tags.Format<"uuid">>();
  const userC: string = typia.random<string & tags.Format<"uuid">>();
  const userD: string = typia.random<string & tags.Format<"uuid">>();
  const boardA: string = typia.random<string & tags.Format<"uuid">>();
  const boardB: string = typia.random<string & tags.Format<"uuid">>();

  // 1. 유저A - boardA, 활성(revoked_at: null)
  const modA = await api.functional.discussionboard.moderators.post(connection, {
    body: {
      user_id: userA,
      board_id: boardA,
      assigned_by_admin_id: adminId,
      assigned_at: new Date().toISOString(),
    } satisfies IDiscussionboardModerator.ICreate,
  });
  typia.assert(modA);

  // 2. 유저B - boardA, 비활성(revoked_at: now)
  const revokedAtB = new Date(Date.now() - 1000).toISOString();
  const modB = await api.functional.discussionboard.moderators.post(connection, {
    body: {
      user_id: userB,
      board_id: boardA,
      assigned_by_admin_id: adminId,
      assigned_at: new Date(Date.now() - 5000).toISOString(),
    } satisfies IDiscussionboardModerator.ICreate,
  });
  typia.assert(modB);
  // 비활성화(revoked 상태), 직접 revoked_at 할당 불가이므로 수정 불가 -> 테스트에선 비활성화된 레코드라고 간주(실제 Post는 always 활성)
  // enabled/disabled flag를 기능상 지원하지 않으므로, 실제 revoked 컬럼 변경 없이 테스트

  // 3. 유저C - boardB, 활성
  const modC = await api.functional.discussionboard.moderators.post(connection, {
    body: {
      user_id: userC,
      board_id: boardB,
      assigned_by_admin_id: adminId,
      assigned_at: new Date().toISOString(),
    } satisfies IDiscussionboardModerator.ICreate,
  });
  typia.assert(modC);

  // 4. 유저D - 플랫폼 전체, 활성(보드 null)
  const modPlatform = await api.functional.discussionboard.moderators.post(connection, {
    body: {
      user_id: userD,
      board_id: null,
      assigned_by_admin_id: adminId,
      assigned_at: new Date().toISOString(),
    } satisfies IDiscussionboardModerator.ICreate,
  });
  typia.assert(modPlatform);

  // === 목록 조회 및 검증 ===
  // 1. 활성 모더레이터만(activeOnly: true)
  const activeList = await api.functional.discussionboard.moderators.patch(connection, {
    body: {
      activeOnly: true,
    } satisfies IDiscussionboardModerator.IRequest,
  });
  typia.assert(activeList);
  TestValidator.predicate("pagination structure exists")(!!activeList.pagination && typeof activeList.pagination.current === "number");
  TestValidator.predicate("data is array")(Array.isArray(activeList.data));
  for (const it of activeList.data) {
    typia.assert(it);
    TestValidator.equals("활성 모더레이터만: revokedAt==null")(it.revokedAt)(null);
  }

  // 2. 특정보드(boardA) 기준
  const boardAList = await api.functional.discussionboard.moderators.patch(connection, {
    body: {
      boardId: boardA,
    } satisfies IDiscussionboardModerator.IRequest,
  });
  typia.assert(boardAList);
  for (const it of boardAList.data) {
    typia.assert(it);
    TestValidator.equals("boardId = boardA")(it.boardId)(boardA);
  }

  // 3. 특정유저(userC) 기준
  const userCList = await api.functional.discussionboard.moderators.patch(connection, {
    body: {
      userId: userC,
    } satisfies IDiscussionboardModerator.IRequest,
  });
  typia.assert(userCList);
  for (const it of userCList.data) {
    typia.assert(it);
    TestValidator.equals("userId = userC")(it.userId)(userC);
  }

  // 4. platform-wide(board==null) 필터는 스키마상 지원X. 요청시 boardId 미포함(또는 전체목록 수동 검색)만 허용됨.
  // 따라서 해당 테스트는 생략하거나, 전체목록에서 boardId==undefined/null 인 레코드를 별도 검증만

  // (선택) 비관리자/권한없음: 실제 동작 상황에서 admin이 아닌권한이면 TestValidator.error("비관리자 권한 에러")(...)
  // → 가상 connection 객체로 role을 교체하는데 필요한 명시적 login API가 제공되지 않는 환경에선 생략
}

