 *
 * - 관리자가 모더레이터 권한 할당(post) → 해당 UUID로 단건 조회(getById)
 * - 생성된 권한 레코드의 세부 정보가 모두 정상적으로 반환되는지 확인
 * - assigned_by_admin_id, assigned_at, user_id, board_id, revoked_at(필요시) 모든 주요 필드 포함 확인
 *
 * 테스트 과정:
 * 1. 관리자(또는 모더레이터) 권한으로 임의의 유저 및 게시판에 대해 모더레이터 권한 할당 엔터티를 생성한다.
 * 2. 반환된 ID(모더레이터 지정 레코드 UUID)로 상세 조회 API를 호출한다.
 * 3. 응답 필드들의 값이 create 시점과 일치하며, 주요 필드의 타입·값 정합성 및 누락 없이 제공되는지 확인한다.
 */
export async function test_api_discussionboard_test_get_moderator_assignment_detail_with_valid_id(
  connection: api.IConnection,
) {
  // 1. 테스트용 모더레이터 권한 할당 생성
  const createInput: IDiscussionboardModerator.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    board_id: typia.random<boolean>() ? typia.random<string & tags.Format<"uuid">>() : null,
    assigned_by_admin_id: typia.random<string & tags.Format<"uuid">>(),
    assigned_at: new Date().toISOString(),
  };
