  TestValidator.equals("id 일치")(found.id)(created.id);
  TestValidator.equals("user_id 일치")(found.user_id)(createInput.user_id);
  TestValidator.equals("board_id 일치")(found.board_id)(createInput.board_id ?? null);
  TestValidator.equals("assigned_by_admin_id 일치")(found.assigned_by_admin_id)(createInput.assigned_by_admin_id);
  TestValidator.equals("assigned_at 일치")(found.assigned_at)(createInput.assigned_at);
