import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerator";

/**
 * 모더레이터 할당 정보 편집(정상적으로 board_id 및 revoked_at 변경) E2E 테스트
 *
 * 이 테스트는 관리자가 기존 모더레이터 권한 할당 레코드를 정상적으로 갱신(예: board_id 변경, 권한 해지 revoked_at 지정 등)할 수 있는지를 검증합니다.
 * 사전 조건으로 새로운 할당 레코드를 직접 생성하며, 곧바로 속성 편집(수정)을 진행합니다.
 *
 * [테스트 절차]
 * 1. 모더레이터 권한 할당 생성 (선행 조건)
 *    - IDiscussionboardModerator.ICreate 를 사용, post API로 신규 할당
 * 2. 생성된 할당에 대해 board_id 및 revoked_at 필드를 putById API로 변경(수정)
 * 3. 응답 DTO에서 필드 변경 사항이 올바르게 반영되었는지 검증
 * 4. 추가로, 기존 유지되어야 할 필드(assigned_at 등)는 변화가 없는지도 확인 가능(필요시)
 */
export async function test_api_discussionboard_moderators_test_update_moderator_assignment_valid_update(
  connection: api.IConnection,
) {
  // 1. 모더레이터 할당 생성
  const createInput = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    board_id: typia.random<string & tags.Format<"uuid">>(),
    assigned_by_admin_id: typia.random<string & tags.Format<"uuid">>(),
    assigned_at: new Date().toISOString(),
  } satisfies IDiscussionboardModerator.ICreate;
  const created = await api.functional.discussionboard.moderators.post(connection, { body: createInput });
  typia.assert(created);

  // 2. board_id, revoked_at 수정
  const updateInput = {
    board_id: typia.random<string & tags.Format<"uuid">>(),
    revoked_at: new Date().toISOString(),
  } satisfies IDiscussionboardModerator.IUpdate;
  const updated = await api.functional.discussionboard.moderators.putById(connection, { id: created.id, body: updateInput });
  typia.assert(updated);

  // 3. 필드 정상 갱신 검증
  TestValidator.equals("board_id 변경됨")(updated.board_id)(updateInput.board_id);
  TestValidator.equals("revoked_at 변경됨")(updated.revoked_at)(updateInput.revoked_at);

  // 4. 유지되어야 할 값 확인(assigned_at 등은 변경되지 않아야 함)
  TestValidator.equals("assigned_at 동일")(updated.assigned_at)(created.assigned_at);
  TestValidator.equals("user_id 동일")(updated.user_id)(created.user_id);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerator";

/**
 * 이미 해지(revoked)된 모더레이터 지정 레코드는 불변(immutable)이 되어야 함을 검증
 *
 * - 관리자가 사용자(U)에게 모더레이터 권한을 최초 할당 → revoked_at 세팅(해지처리) →
 *   이후 같은 레코드에 추가 업데이트(board_id 등) 시도 시 정책상 실패(오류 응답)를 기대함
 *
 * 테스트 흐름:
 * 1. adminA가 userU에 모더레이터 권한 할당(생성)
 * 2. 해당 할당건을 revoked 상태로 갱신
 * 3. 이미 해지된 레코드에 속성(board_id 등) 추가 갱신 시도
 * 4. 3번 시도 시 API에서 conflict/불변성 관련 오류가 반환되는지 확인 (TestValidator.error 활용)
 */
export async function test_api_discussionboard_test_update_moderator_assignment_revoked_state(
  connection: api.IConnection,
) {
  // 1. 모더레이터 권한 최초 할당
  const adminId = typia.random<string & tags.Format<"uuid">>();
  const userId = typia.random<string & tags.Format<"uuid">>();
  const boardId = typia.random<string & tags.Format<"uuid">>();

  const assignment = await api.functional.discussionboard.moderators.post(connection, {
    body: {
      user_id: userId,
      board_id: boardId,
      assigned_by_admin_id: adminId,
      assigned_at: new Date().toISOString(),
    } satisfies IDiscussionboardModerator.ICreate,
  });
  typia.assert(assignment);

  // 2. 해당 권한을 revoked(해지) 처리
  const revokedAt = new Date(Date.now() + 10).toISOString();
  const revoked = await api.functional.discussionboard.moderators.putById(connection, {
    id: assignment.id,
    body: {
      revoked_at: revokedAt,
    } satisfies IDiscussionboardModerator.IUpdate,
  });
  typia.assert(revoked);
  TestValidator.equals("revoked_at 설정")(revoked.revoked_at)(revokedAt);

  // 3. 이미 해지된 레코드에 추가 속성(board_id 등) 갱신 시도(불변 정책 검증)
  await TestValidator.error("해지된 모더레이터 지정은 immutable이어야 함")(() =>
    api.functional.discussionboard.moderators.putById(connection, {
      id: assignment.id,
      body: {
        board_id: typia.random<string & tags.Format<"uuid">>(),
      } satisfies IDiscussionboardModerator.IUpdate,
    })
  );
}

