 *
 * 이 테스트는 관리자가 모더레이터 권한을 부여하고, 곧바로 해지(Delete, soft delete)하는 비즈니스 플로우를 검증한다.
 *
 * 1. admin이 특정 user를 platform 또는 board 단위로 모더레이터로 지정한다.
 * 2. 생성된 모더레이터 assignment의 id로 soft delete(권한 해지) 요청을 보낸다.
 * 3. 반환 결과의 revoked_at 값이 정상적으로 set되었는지, id 등 assignment 불변 필드가 정상 보존되는지 검증한다.
 * 4. 현재 제공 API 범위상 active 모더레이터 리스트 검증은 불가. revoked_at을 중심으로 권한 해지됨을 확인한다.
 */
export async function test_api_discussionboard_test_revoke_moderator_assignment_successful(
  connection: api.IConnection,
) {
  // 1. 모더레이터 권한 할당 생성
  const moderatorInput = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    board_id: null, // 전체 플랫폼 모더레이터 예시
    assigned_by_admin_id: typia.random<string & tags.Format<"uuid">>(),
    assigned_at: new Date().toISOString(),
  } satisfies IDiscussionboardModerator.ICreate;
  const assignment = await api.functional.discussionboard.moderators.post(connection, {
    body: moderatorInput,
  });
  typia.assert(assignment);

  // 2. 할당된 모더레이터 권한 해지 (soft delete)
  const revoked = await api.functional.discussionboard.moderators.eraseById(connection, {
    id: assignment.id,
  });
  typia.assert(revoked);

  // 3. 권한 해지 결과 검증
  TestValidator.equals("id 동일 여부")(revoked.id)(assignment.id);
  TestValidator.equals("권한 할당 상태 불변성")(revoked.user_id)(assignment.user_id);
  TestValidator.equals("보드 ID 일치")(revoked.board_id)(assignment.board_id);
  TestValidator.equals("할당자 ID 일치")(revoked.assigned_by_admin_id)(assignment.assigned_by_admin_id);
  TestValidator.equals("할당 일시 일치")(revoked.assigned_at)(assignment.assigned_at);
  // revoked_at: null이 아니어야 함(soft delete가 정상 동작), ISO8601 형식 체크
  TestValidator.predicate("revoked_at이 올바로 세팅됨")(
    typeof revoked.revoked_at === "string" && revoked.revoked_at.length > 0
  );
  // 부가적으로 revoked_at이 존재하면 active가 아님을 체크
  TestValidator.predicate("revoked_at 있으면 비활성")(
    !!revoked.revoked_at
  );
}

