/**
 * 비관리자 또는 모더레이터 자신은 모더레이터 권한을 해지(DB 삭제)할 수 없어야 함을 검증합니다.
 *
 * 이 테스트는 platform 관리자가 모더레이터(또는 board별 모더레이터)를 할당한 후,
 * 1. 일반 사용자(A)가 해지(delete) 시도를 했을 때,
 * 2. 해당 모더레이터 자신(B)이 해지(delete) 시도를 했을 때,
 * 모두 시스템이 권한 없음(Forbidden Error 등)을 반환해야 함을 검증합니다.
 * (단, 본 예시에서는 실제 계정 생성/세션전환을 직접 구현하는 API가 주어지지 않았으므로,
 * connection 객체가 각기 다른 권한 세션이라고 가정 후 delete 요청만 검증합니다.)
 *
 * 1. platform 관리자(admin) ID로 모더레이터 할당 레코드를 생성한다.
 * 2. 관리자가 아닌 일반 사용자(A)의 권한 connection으로 revoke(삭제) 시도를 하고
 *    TestValidator.error로 금지(forbidden)가 발생하는지 확인한다.
 * 3. 모더레이터 본인(B) 권한 connection으로도 동일하게 revoke(삭제) 시도시 forbidden 오류가 나는지 체크한다.
 */
export async function test_api_discussionboard_test_revoke_moderator_assignment_insufficient_permissions(connection: api.IConnection) {
  // 1. 관리자(admin) 권한으로 모더레이터 지정 레코드 생성
  const admin_id = typia.random<string & tags.Format<"uuid">>();
  const target_user_id = typia.random<string & tags.Format<"uuid">>();
  const now = new Date().toISOString();
  const record = await api.functional.discussionboard.moderators.post(connection, {
    body: {
      user_id: target_user_id,
      board_id: null,
      assigned_by_admin_id: admin_id,
      assigned_at: now
    } satisfies IDiscussionboardModerator.ICreate
  });
  typia.assert(record);

  // 2. 일반 사용자(A) 계정 세션(connection)에서 해지(삭제) 요청 시 권한 오류(forbidden)여야 함
  await TestValidator.error("일반 사용자 세션: revoke 시도는 forbidden 오류")(() =>
    api.functional.discussionboard.moderators.eraseById(connection, { id: record.id })
  );

  // 3. 해당 모더레이터(B) 계정 세션(connection)에서 해지(삭제) 요청 시 역시 forbidden 오류여야 함
  await TestValidator.error("모더레이터 세션: revoke 시도는 forbidden 오류")(() =>
    api.functional.discussionboard.moderators.eraseById(connection, { id: record.id })
  );
}

