/**
 * Test listing and searching board settings with valid filters, pagination, and sort order.
 *
 * This test ensures an admin receives only the settings that match applied filters, that pagination works as intended, and, if present, that sorting criteria are honored.
 * It exercises the API's ability to deliver correct settings records and page meta for realistic use-cases such as admin dashboard search/uplink.
 *
 * Steps:
 * 1. Create a board (to obtain a valid board_id foreign key for the settings)
 * 2. Create a corresponding settings record for that board
 * 3. List/search board settings using PATCH /discussionboard/boards/settings with meaningful filters:
 *    - Filter by board_id
 *    - Also filter by settings_version (for precise lookup)
 *    - Set pagination parameters (page 1, limit 10)
 * 4. Verify that each returned settings record matches the filters used
 * 5. Check that pagination meta fields are accurate and consistent with result data
 */
export async function test_api_discussionboard_board_settings_test_list_board_settings_with_valid_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create a board
  const board = await api.functional.discussionboard.boards.post(connection, {
    body: {
      name: RandomGenerator.name(),
      slug: RandomGenerator.alphaNumeric(10),
      description: RandomGenerator.paragraph()()
    },
  });
  typia.assert(board);

  // 2. Create a settings record for this board
  const settings = await api.functional.discussionboard.boards.settings.post(connection, {
    body: {
      board_id: board.id,
      can_users_post: true,
      min_post_length: 10,
      max_post_length: 1000,
      allow_image_uploads: true,
      allow_file_attachments: true,
      settings_version: 1,
      effective_at: new Date().toISOString(),
    },
  });
  typia.assert(settings);

  // 3. List/search board settings with targeted filters and pagination
  const listResponse = await api.functional.discussionboard.boards.settings.patch(connection, {
    body: {
      page: 1 as number & tags.Type<"int32"> & tags.JsonSchemaPlugin<{ format: "int32"; }>,
      limit: 10 as number & tags.Type<"int32"> & tags.JsonSchemaPlugin<{ format: "int32"; }>,
      board_id: board.id,
      settings_version: settings.settings_version as number & tags.Type<"int32"> & tags.JsonSchemaPlugin<{ format: "int32"; }>,
    },
  });
  typia.assert(listResponse);

  // 4. Validate: every result matches board_id and settings_version
  for (const s of listResponse.data) {
    TestValidator.equals("board_id matches")(s.board_id)(board.id);
    TestValidator.equals("settings_version matches")(s.settings_version)(settings.settings_version);
  }

  // 5. Validate pagination meta
  TestValidator.equals("current page == 1")(listResponse.pagination.current)(1);
  TestValidator.equals("limit == 10")(listResponse.pagination.limit)(10);
  TestValidator.predicate("at least one record returned")(listResponse.data.length >= 1);
  TestValidator.predicate("records >= data length")(listResponse.pagination.records >= listResponse.data.length);
  TestValidator.predicate("pages >= 1")(listResponse.pagination.pages >= 1);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
