import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IBoardSettings } from "@ORGANIZATION/PROJECT-api/lib/structures/IBoardSettings";

/**
 * 지원하지 않는 필터 필드 사용 시 400 오류를 반환하는지 검증 (PATCH /discussionboard/boards/settings)
 *
 * - 정상 필드만 포함된 요청: 200 OK 및 정상 응답
 * - 스키마에 없는 잘못된 필드 포함 요청: 400 Validation Error
 *   (Typescript에서 불가피하게 as any로 우회하여 런타임 객체에 임의 필드 주입)
 *
 * ## 테스트 순서
 * 1. schema에 정의된 필드(page, limit 등)만 있는 정상 입력→호출 시 200 OK, 결과 정상 (타입과 내용 assert)
 * 2. schema에 정의되지 않은 임의 필드(invalidFilterField 등) 추가→400 Validation Error가 발생하는지 TestValidator로 검증
 */
export async function test_api_discussionboard_test_list_board_settings_with_invalid_filters_returns_error(
  connection: api.IConnection,
) {
  // 1. 정상 필드만 있는 조건으로 목록 API 호출: 200 OK & 결과 타입, 형상 검증
  const normalInput = {
    page: 1,
    limit: 10,
  } satisfies IDiscussionboardBoardSettings.IRequest;
  const normalOutput = await api.functional.discussionboard.boards.settings.patch(connection, { body: normalInput });
  typia.assert(normalOutput);

  // 2. 스키마에 정의되지 않은 잘못된 필드 추가하여 호출 시 400 오류 확인
  // (런타임에만 발생하며, 타입 시스템 상 허용 불가이므로 as any로 우회)
  const invalidInput = { ...normalInput, invalidFilterField: "NOT_ALLOWED" } as any;
  await TestValidator.error("잘못된 필터 필드 사용 시 400 Validation Error가 발생해야 함")(
    async () => {
      await api.functional.discussionboard.boards.settings.patch(connection, { body: invalidInput });
    },
  );
}

