 * - 잘못된 ID, 실수 혹은 악의적인 접근에 대해 시스템이 안전하게 대응하는지, 관리자 권한이 제대로 적용되는지 확인하는 중요한 테스트입니다.
 *
 * 테스트 절차:
 * 1. 실제로 존재하지 않는 게시판 설정 엔트리의 ID(랜덤 UUID)를 생성합니다.
 * 2. 해당 ID로 eraseById API를 호출해 삭제를 시도합니다.
 * 3. API가 404 등 not found 에러(예: HttpError)로 응답하는지 확인합니다.
 * 4. 혹시라도 삭제에 성공하거나 404 외의 예기치 않은 응답이 오면 테스트를 실패로 처리합니다.
 */
export async function test_api_discussionboard_boards_settings_eraseById_test_delete_board_settings_nonexistent_id(
  connection: api.IConnection,
) {
  // 1. 존재하지 않는 게시판 설정 ID 생성 (랜덤 UUID)
  const fakeId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();

  // 2. 해당 ID로 삭제 시도 및 3. not found(404) 에러 검증
  await TestValidator.error("존재하지 않는 ID 삭제시 404 또는 not found 오류 반환해야 함")(
    async () => {
      await api.functional.discussionboard.boards.settings.eraseById(
        connection,
        {
          id: fakeId,
        },
      );
    },
  );
}

