 *
 * This test ensures that only users with administrative or explicit moderator privileges may delete discussion board settings entries. A regular (unauthorized) user will attempt to delete board settings for an existing board, and the expected result is a permission/authorization error.
 *
 * Steps:
 * 1. Create a new discussion board using admin privileges (simulated or assumed admin context, as only admins can create boards).
 * 2. Create a new board settings entry for the newly created board, again under admin privileges.
 * 3. Switch or simulate context to that of a regular user (without admin/mod permissions).
 * 4. Attempt to delete the settings entry using the regular user's context.
 * 5. Verify that an error is thrown, and specifically that it is a permission denied or unauthorized error (no need to check message, only that error occurs).
 */
export async function test_api_discussionboard_test_delete_board_settings_unauthorized_user(
  connection: api.IConnection,
) {
  // 1. Create board as admin (assumed admin context)
  const board = await api.functional.discussionboard.boards.post(connection, {
    body: {
