import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardLike";
import type { IPageIDiscussionboardLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardLike";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for filtering and paginating like events in a discussion board.
 *
 * Validates:
 * - Like search with user, post, comment filters
 * - Pagination and count/metadata
 * - Error handling for invalid or non-existent filters
 *
 * Process:
 * 1. Create two likes (one on a post, one on a comment)
 * 2. Run queries by various filter combinations and pagination
 * 3. Test error/edge cases (invalid IDs, pagination out of bounds)
 * 4. Assert results and metadata are as expected
 */
export async function test_api_discussionboard_test_list_likes_with_pagination_and_various_filters(
  connection: api.IConnection
) {
  // Step 1: Create two like records as the test user
  const user_id = typia.random<string & tags.Format<"uuid">>();
  const post_id = typia.random<string & tags.Format<"uuid">>();
  const comment_id = typia.random<string & tags.Format<"uuid">>();

  // Create like for a post
  const like_post = await api.functional.discussionboard.like.post(connection, {
    body: {
      user_id,
      post_id,
      comment_id: null,
    } satisfies IDiscussionboardLike.ICreate,
  });
  typia.assert(like_post);
  TestValidator.equals("like_post.user_id")(like_post.user_id)(user_id);
  TestValidator.equals("like_post.post_id")(like_post.post_id)(post_id);
  TestValidator.equals("like_post.comment_id")(like_post.comment_id)(null);

  // Create like for a comment
  const like_comment = await api.functional.discussionboard.like.post(connection, {
    body: {
      user_id,
      comment_id,
      post_id: null,
    } satisfies IDiscussionboardLike.ICreate,
  });
  typia.assert(like_comment);
  TestValidator.equals("like_comment.user_id")(like_comment.user_id)(user_id);
  TestValidator.equals("like_comment.comment_id")(like_comment.comment_id)(comment_id);
  TestValidator.equals("like_comment.post_id")(like_comment.post_id)(null);

  // Step 2: Query likes (no filters) - default pagination
  const page_all = await api.functional.discussionboard.like.patch(connection, {
    body: {} satisfies IDiscussionboardLike.IRequest,
  });
  typia.assert(page_all);
  TestValidator.predicate("page_all has data array")(Array.isArray(page_all.data));
  TestValidator.predicate("at least 2 likes found for created user")(
    page_all.data.some((v) => v.id === like_post.id) &&
      page_all.data.some((v) => v.id === like_comment.id)
  );

  // Step 2.1: Filter by user_id
  const page_user = await api.functional.discussionboard.like.patch(connection, {
    body: {
      user_id,
    } satisfies IDiscussionboardLike.IRequest,
  });
  typia.assert(page_user);
  TestValidator.predicate("only test user's likes")(
    page_user.data.every((v) => v.user_id === user_id)
  );

  // Step 2.2: Filter by post_id
  const page_post = await api.functional.discussionboard.like.patch(connection, {
    body: {
      post_id,
    } satisfies IDiscussionboardLike.IRequest,
  });
  typia.assert(page_post);
  TestValidator.predicate("post_id only returns post like or empty")(
    page_post.data.every((v) => v.post_id === post_id)
  );

  // Step 2.3: Filter by comment_id
  const page_comment = await api.functional.discussionboard.like.patch(connection, {
    body: {
      comment_id,
    } satisfies IDiscussionboardLike.IRequest,
  });
  typia.assert(page_comment);
  TestValidator.predicate("comment_id only returns comment like or empty")(
    page_comment.data.every((v) => v.comment_id === comment_id)
  );

  // Step 2.4: Pagination limit=1, page=2
  const page2 = await api.functional.discussionboard.like.patch(connection, {
    body: {
      user_id,
      limit: 1,
      page: 2,
    } satisfies IDiscussionboardLike.IRequest,
  });
  typia.assert(page2);
  TestValidator.equals("limit=1")(page2.pagination.limit)(1);
  TestValidator.equals("page=2")(page2.pagination.current)(2);
  TestValidator.predicate("data size 1 or 0")(page2.data.length <= 1);
  TestValidator.equals("records total >= 2")(page2.pagination.records >= 2)(true);

  // Step 2.5: Time range filter
  const now = new Date().toISOString();
  const from = like_post.created_at;
  const to = now;
  const page_time = await api.functional.discussionboard.like.patch(connection, {
    body: {
      from,
      to,
    } satisfies IDiscussionboardLike.IRequest,
  });
  typia.assert(page_time);
  TestValidator.predicate("from<=created_at<=to")(
    page_time.data.every((v) =>
      (!from || v.created_at >= from) &&
      (!to || v.created_at <= to)
    )
  );

  // Step 2.6: Combined filters (user_id + post_id)
  const page_combined = await api.functional.discussionboard.like.patch(connection, {
    body: {
      user_id,
      post_id,
    } satisfies IDiscussionboardLike.IRequest,
  });
  typia.assert(page_combined);
  TestValidator.predicate("combined filters")(
    page_combined.data.every(
      (v) => v.user_id === user_id && v.post_id === post_id
    )
  );

  // Step 3: Edge/error cases
  // 3.1: Non-existent post_id
  const non_existent_post_id = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("non-existent post_id")(() =>
    api.functional.discussionboard.like.patch(connection, {
      body: {
        post_id: non_existent_post_id,
      } satisfies IDiscussionboardLike.IRequest,
    })
  );
  // 3.2: Non-existent comment_id
  const non_existent_comment_id = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("non-existent comment_id")(() =>
    api.functional.discussionboard.like.patch(connection, {
      body: {
        comment_id: non_existent_comment_id,
      } satisfies IDiscussionboardLike.IRequest,
    })
  );
  // 3.3: Malformed (non-UUID) post_id
  TestValidator.error("malformed post_id")(() =>
    api.functional.discussionboard.like.patch(connection, {
      body: {
        post_id: "not-a-uuid" as unknown as string & tags.Format<"uuid">,
      } satisfies IDiscussionboardLike.IRequest,
    })
  );
  // 3.4: Pagination out of bounds (page > max)
  const big_page = 9999;
  const page_oob = await api.functional.discussionboard.like.patch(connection, {
    body: {
      user_id,
      page: big_page,
      limit: 1,
    } satisfies IDiscussionboardLike.IRequest,
  });
  typia.assert(page_oob);
  TestValidator.equals("empty when out of bounds")(page_oob.data.length)(0);

  // 3.5: Both post_id+comment_id set (allowed)
  const both = await api.functional.discussionboard.like.patch(connection, {
    body: {
      user_id,
      post_id,
      comment_id,
    } satisfies IDiscussionboardLike.IRequest,
  });
  typia.assert(both);
  TestValidator.predicate("combined post+comment returns subset")(
    both.data.every(
      (v) => v.user_id === user_id && v.post_id === post_id && v.comment_id === comment_id
    ) || both.data.length === 0
  );

  // 3.6: Omitted filters/nulls (should not error)
  const omit = await api.functional.discussionboard.like.patch(connection, {
    body: {
      user_id,
      post_id: null,
      comment_id: null,
    } satisfies IDiscussionboardLike.IRequest,
  });
  typia.assert(omit);
  TestValidator.predicate("omitted/nulls still valid")(
    omit.data.every((v) => v.user_id === user_id)
  );
}

