      comment_id: null,
    } satisfies IDiscussionboardLike.ICreate,
  });
  typia.assert(foreignLike);
  // Attempt to fetch as testUser (assuming connection context is testUser)
  await TestValidator.error("access to another user’s like forbidden or restricted")(() =>
