import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IDiscussionboardLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardLike";

/**
 * 테스트 목적: 게시글의 좋아요(Like) 기능을 검증한다.
 *
 * 시나리오:
 * 1. 게시글을 작성한다.
 * 2. 로그인 사용자가 해당 게시글에 좋아요를 누른다.
 * 3. 반환된 좋아요 객체의 메타데이터(게시글ㆍ유저 일치, comment_id, 생성시각 등)가 올바른지 확인한다.
 * 4. 동일 사용자가 같은 게시글에 중복으로 좋아요 요청 시 에러(중복/충돌)를 반환하는지 검증한다.
 * 5. 인증되지 않은 상태(혹은 임의의 user_id)로 좋아요 요청 시 금지(Forbidden) 에러가 발생하는지 검증한다.
 *
 * 비즈니스 목적: 한 사용자가 게시글에 한 번만 좋아요를 누를 수 있게 하고, 인증 없이 좋아요 시도를 막는다.
 *
 * 주요 절차:
 * 1. 게시글 작성
 * 2. 게시글에 정상적으로 좋아요 추가
 * 3. 좋아요 정보 검증
 * 4. 중복 좋아요 방지 확인
 * 5. 인증 없는 좋아요 차단 확인
 */
export async function test_api_discussionboard_test_create_like_for_post_and_prevent_duplicate_like(
  connection: api.IConnection,
) {
  // 1. 게시글 작성 (테스트용 user/thread UUID 사용)
  const userId: string = typia.random<string & tags.Format<"uuid">>();
  const threadId: string = typia.random<string & tags.Format<"uuid">>();

  const post = await api.functional.discussionboard.posts.post(connection, {
    body: {
      thread_id: threadId,
      content: "게시글 좋아요 테스트 컨텐츠",
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // 2. 로그인 사용자로 게시글 좋아요 요청
  const likeInput: IDiscussionboardLike.ICreate = {
    user_id: userId,
    post_id: post.id,
    comment_id: null,
  };
  const like = await api.functional.discussionboard.like.post(connection, {
    body: likeInput,
  });
  typia.assert(like);

  // 3. 좋아요 정보 검증
  TestValidator.equals("게시글 ID 일치")(like.post_id)(post.id);
  TestValidator.equals("유저 ID 일치")(like.user_id)(userId);
  TestValidator.equals("댓글 좋아요가 아님")(like.comment_id)(null);
  TestValidator.predicate("ISO 날짜/시각 생성 확인")(typeof like.created_at === "string" && like.created_at.includes("-"));

  // 4. 동일 사용자 중복 좋아요 → 에러 발생
  await TestValidator.error("중복 좋아요 방지")(() =>
    api.functional.discussionboard.like.post(connection, {
      body: likeInput,
    })
  );

  // 5. 인증되지 않은 임의 사용자(user_id)로 좋아요 시도 → 에러 발생
  await TestValidator.error("비인증 좋아요 금지")(() =>
    api.functional.discussionboard.like.post(connection, {
      body: {
        user_id: typia.random<string & tags.Format<"uuid">>(),
        post_id: post.id,
        comment_id: null,
      },
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IDiscussionboardLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardLike";

/**
 * Test liking a comment and preventing duplicate/invalid likes
 *
 * Validates the business rules of the /discussionboard/like endpoint for liking comments:
 *   - A user can like a comment
 *   - The same user cannot like the same comment twice
 *   - Attempting to like both a post and a comment at once fails validation
 *
 * Steps:
 * 1. Create a post as a target for comments
 * 2. Create a comment under the post by a user
 * 3. Like the comment as that user (should succeed)
 * 4. Attempt to like the same comment again as the same user (should fail: conflict/duplicate)
 * 5. Attempt to like both a post and a comment at once (should fail validation)
 */
export async function test_api_discussionboard_test_create_like_for_comment_and_prevent_duplicate_like(
  connection: api.IConnection,
) {
  // 1. Create a post to host the comment
  const postCreateInput: IDiscussionboardPost.ICreate = {
    thread_id: typia.random<string & tags.Format<"uuid">>(),
    content: RandomGenerator.paragraph()(),
  };
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: postCreateInput,
  });
  typia.assert(post);

  // 2. Create a comment under the post
  const userId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const commentCreateInput: IDiscussionboardComment.ICreate = {
    post_id: post.id,
    created_by_user_id: userId,
    content: RandomGenerator.paragraph()(),
  };
  const comment = await api.functional.discussionboard.comments.post(connection, {
    body: commentCreateInput,
  });
  typia.assert(comment);

  // 3. Like the comment as the user (should succeed)
  const likeInput: IDiscussionboardLike.ICreate = {
    user_id: userId,
    comment_id: comment.id,
    post_id: null,
  };
  const like = await api.functional.discussionboard.like.post(connection, {
    body: likeInput,
  });
  typia.assert(like);
  TestValidator.equals("like references correct comment")(like.comment_id)(comment.id);
  TestValidator.equals("like user matches")(like.user_id)(userId);

  // 4. Attempt to like the same comment again as the same user (should fail: duplicate/conflict error)
  await TestValidator.error("duplicate like on same comment should fail")(
    async () => {
      await api.functional.discussionboard.like.post(connection, {
        body: likeInput,
      });
    },
  );

  // 5. Attempt to like both a post and a comment at once (should fail validation)
  await TestValidator.error("liking both post and comment at once fails")(
    async () => {
      await api.functional.discussionboard.like.post(connection, {
        body: {
          user_id: userId,
          post_id: post.id,
          comment_id: comment.id,
        },
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IDiscussionboardLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardLike";

/**
 * Test updating an existing like event so that its target switches from a post to a comment.
 *
 * This test covers several business scenarios:
 * 1. Creating a post & comment.
 * 2. Creating a like targeting the post as userA.
 * 3. Updating the like to instead target the comment, verifying mutual exclusivity of post_id/comment_id.
 * 4. Attempting update with both post_id and comment_id set, expecting a validation error due to mutual exclusivity.
 * 5. Attempting update as a non-owner user, expecting a permission error.
 * 6. Attempting update on a non-existent like ID, expecting not found error.
 *
 * This ensures the like update logic enforces target exclusivity, validates permissions, and correct error handling.
 */
export async function test_api_discussionboard_test_update_like_target_to_comment_and_validate_mutual_exclusivity(
  connection: api.IConnection,
) {
  // Step 1: Generate two users (userA - like owner, userB - secondary user)
  const userAId: string = typia.random<string & tags.Format<"uuid">>();
  const userBId: string = typia.random<string & tags.Format<"uuid">>();

  // Step 2: Create a post (ICreate has thread_id and content only)
  const threadId: string = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: {
      thread_id: threadId,
      content: "This is the original post",
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // Step 3: Create a comment under the post as userA
  const comment = await api.functional.discussionboard.comments.post(connection, {
    body: {
      post_id: post.id,
      created_by_user_id: userAId,
      content: "This is a comment under the post",
    } satisfies IDiscussionboardComment.ICreate,
  });
  typia.assert(comment);

  // Step 4: Like the post as userA
  const like = await api.functional.discussionboard.like.post(connection, {
    body: {
      user_id: userAId,
      post_id: post.id,
      comment_id: null,
    } satisfies IDiscussionboardLike.ICreate,
  });
  typia.assert(like);

  // Step 5: Update the like to point to the comment instead (as userA)
  const updatedLike = await api.functional.discussionboard.like.putById(connection, {
    id: like.id,
    body: { post_id: null, comment_id: comment.id } satisfies IDiscussionboardLike.IUpdate,
  });
  typia.assert(updatedLike);
  TestValidator.equals("like now targets comment only")(updatedLike.comment_id)(comment.id);
  TestValidator.equals("like no longer targets post")(updatedLike.post_id)(null);

  // Step 6: Attempt mutual exclusivity violation: both post_id and comment_id set
  await TestValidator.error("should reject when both post_id and comment_id set")(
    async () => {
      await api.functional.discussionboard.like.putById(connection, {
        id: like.id,
        body: { post_id: post.id, comment_id: comment.id } satisfies IDiscussionboardLike.IUpdate,
      });
    }
  );

  // Step 7: Attempt update as non-owner user (userB)
  await TestValidator.error("should reject update by non-owner user")(
    async () => {
      await api.functional.discussionboard.like.putById(connection, {
        id: like.id,
        body: { post_id: post.id, comment_id: null } satisfies IDiscussionboardLike.IUpdate,
      });
    }
  );

  // Step 8: Attempt update for a non-existent like
  await TestValidator.error("should return not found for non-existent like")(
    async () => {
      await api.functional.discussionboard.like.putById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
        body: { post_id: null, comment_id: comment.id } satisfies IDiscussionboardLike.IUpdate,
      });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IDiscussionboardLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardLike";

/**
 * Validate deletion of likes by the like owner and enforce restrictions for unauthorized deletion.
 *
 * This test verifies that:
 * 1. A user can create a post, like the post, and subsequently delete their own like by its ID.
 * 2. Once deleted, attempting to delete the same like again returns a "not found" error.
 * 3. A like created by another user cannot be deleted by the first user; the system returns a forbidden error.
 *
 * Step-by-step process:
 * 1. Create test users (userA and userB) using simulated UUIDs for user_id.
 * 2. userA creates a post.
 * 3. userA likes the post.
 * 4. userA deletes their like by ID and validates the deleted record.
 * 5. userA attempts to delete the same like again (should fail: not found).
 * 6. userB likes the post.
 * 7. userA attempts to delete userB's like (should fail: forbidden).
 */
export async function test_api_discussionboard_test_delete_like_by_owner_and_prevent_unauthorized_deletion(
  connection: api.IConnection,
) {
  // 1. Prepare test users (simulate user_id via random UUIDs)
  const userA_id = typia.random<string & tags.Format<"uuid">>();
  const userB_id = typia.random<string & tags.Format<"uuid">>();

  // 2. userA creates a test post
  const thread_id = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: {
      thread_id,
      content: "Sample post content by userA",
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // 3. userA likes the created post
  const likeA = await api.functional.discussionboard.like.post(connection, {
    body: {
      user_id: userA_id,
      post_id: post.id,
      comment_id: null,
    } satisfies IDiscussionboardLike.ICreate,
  });
  typia.assert(likeA);

  // 4. userA deletes their own like by ID
  const deletedLikeA = await api.functional.discussionboard.like.eraseById(connection, {
    id: likeA.id,
  });
  typia.assert(deletedLikeA);
  TestValidator.equals("Deleted like ID matches")(deletedLikeA.id)(likeA.id);
  TestValidator.equals("Deleted like user_id matches")(deletedLikeA.user_id)(userA_id);

  // 5. Attempt to delete the same like again (should fail: not found)
  await TestValidator.error("Trying to delete already deleted like should fail")(
    async () => {
      await api.functional.discussionboard.like.eraseById(connection, {
        id: likeA.id,
      });
    },
  );

  // 6. userB likes the same post
  const likeB = await api.functional.discussionboard.like.post(connection, {
    body: {
      user_id: userB_id,
      post_id: post.id,
      comment_id: null,
    } satisfies IDiscussionboardLike.ICreate,
  });
  typia.assert(likeB);

  // 7. userA tries to delete userB's like (should fail: forbidden)
  await TestValidator.error("userA cannot delete userB's like")(
    async () => {
      await api.functional.discussionboard.like.eraseById(connection, {
        id: likeB.id,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoard";
import type { IBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IBoardTopic";
import type { IPageIBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIBoardTopic";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test listing board topics with valid filters, pagination, and sort parameters.
 *
 * This test covers the board topic admin and navigation scenario:
 * 1. Two boards (A, B) are created with distinct slugs and descriptions.
 * 2. For each board, multiple topics are created with unique names/slugs—ensuring there is topic data for each board.
 * 3. The test lists topics by board (board_id), by partial name (name LIKE), and by non-deleted status (is_deleted=false), validating
 *    that only expected topics are returned for each filter.
 * 4. Pagination is exercised (limit=2, page=1/2), ensuring returned record count is correct and metadata matches logic.
 * 5. The overall topic count is checked to match sum of topics created.
 *
 * Validates:
 * - Filtering by board and by topic name substring
 * - Pagination cutoffs and correct metadata
 * - Non-deleted status filtering
 * - All outputs pass DTO and schema assertion
 * - Predicate and equality assertions confirm filter correctness and record counts
 */
export async function test_api_discussionboard_test_list_board_topics_with_valid_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create two boards for the test
  const boardA = await api.functional.discussionboard.boards.post(connection, {
    body: {
      name: "BoardA",
      slug: RandomGenerator.alphabets(12),
      description: "Board A description",
    } satisfies IDiscussionboardBoard.ICreate,
  });
  typia.assert(boardA);

  const boardB = await api.functional.discussionboard.boards.post(connection, {
    body: {
      name: "BoardB",
      slug: RandomGenerator.alphabets(12),
      description: "Board B description",
    } satisfies IDiscussionboardBoard.ICreate,
  });
  typia.assert(boardB);

  // 2. Create multiple topics for each board
  const topicsA = await ArrayUtil.asyncRepeat(3)(async (i) => {
    const topic = await api.functional.discussionboard.boards.topics.post(connection, {
      body: {
        board_id: boardA.id,
        name: `ATopic${i + 1}`,
        slug: RandomGenerator.alphabets(10),
        description: `ATopic${i + 1} for BoardA`,
      } satisfies IBoardTopic.ICreate,
    });
    typia.assert(topic);
    return topic;
  });

  const topicsB = await ArrayUtil.asyncRepeat(2)(async (i) => {
    const topic = await api.functional.discussionboard.boards.topics.post(connection, {
      body: {
        board_id: boardB.id,
        name: `BTopic${i + 1}`,
        slug: RandomGenerator.alphabets(10),
        description: `BTopic${i + 1} for BoardB`,
      } satisfies IBoardTopic.ICreate,
    });
    typia.assert(topic);
    return topic;
  });

  // 3. List topics for Board A only and validate
  const resultA = await api.functional.discussionboard.boards.topics.patch(connection, {
    body: {
      board_id: boardA.id,
    },
  });
  typia.assert(resultA);
  TestValidator.predicate("all topics are for Board A")(resultA.data.every((t) => t.board_id === boardA.id));
  TestValidator.equals("board A topic count")(resultA.pagination.records)(topicsA.length);

  // 4. List topics with a partial name match ("ATopic")
  const resultByName = await api.functional.discussionboard.boards.topics.patch(connection, {
    body: {
      name: "ATopic",
    },
  });
  typia.assert(resultByName);
  TestValidator.predicate("all names contain 'ATopic'")(resultByName.data.every((t) => t.name.includes("ATopic")));

  // 5. List non-deleted topics (is_deleted: false)
  const resultNonDeleted = await api.functional.discussionboard.boards.topics.patch(connection, {
    body: {
      is_deleted: false,
    },
  });
  typia.assert(resultNonDeleted);
  TestValidator.predicate("no topic is deleted")(resultNonDeleted.data.every((t) => !t.deleted_at));

  // 6. Pagination: limit=2, page 1
  const page1 = await api.functional.discussionboard.boards.topics.patch(connection, {
    body: {
      limit: 2,
      page: 1,
    },
  });
  typia.assert(page1);
  TestValidator.predicate("max two topics returned on page 1")(page1.data.length <= 2);
  TestValidator.equals("current page 1")(page1.pagination.current)(1);

  // Pagination: limit=2, page 2
  const page2 = await api.functional.discussionboard.boards.topics.patch(connection, {
    body: {
      limit: 2,
      page: 2,
    },
  });
  typia.assert(page2);
  TestValidator.predicate("max two topics returned on page 2")(page2.data.length <= 2);
  TestValidator.equals("current page 2")(page2.pagination.current)(2);

  // 7. Validate total count matches topics inserted
  const allTopics = await api.functional.discussionboard.boards.topics.patch(connection, {
    body: {},
  });
  typia.assert(allTopics);
  const expectedTotal = topicsA.length + topicsB.length;
  TestValidator.equals("total topic count")(allTopics.pagination.records)(expectedTotal);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IBoardTopic";
import type { IPageIBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIBoardTopic";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 검증되지 않은 필터, 페이징, 정렬 옵션이 포함된 토픽 일괄 조회(PATCH /discussionboard/boards/topics) 실패 케이스 검증.
 *
 * 관리 패널이나 검색 툴에서 종종 발생할 수 있는 잘못된 요청 예시들을 일부러 전달하여,
 * - 지원하지 않는 필터 프로퍼티,
 * - 허용 범위 외 페이징(meta)
 * - 잘못된 정렬 기준
 * 요청이 들어올 때 어떻게 거부되는지와 400 에러(및 메시지 포함)를 검증합니다.
 * 즉, 요청 스키마 수준, 서버 유효성 검사 및 에러 처리 로직이 의도대로 동작하는지 확인합니다.
 *
 * 테스트 시나리오:
 * 1. limit에 음수 등 허용 불가 값을 넣어 보낸다.
 * 2. page에 0이나 음수 값을 보낸다.
 * 3. 꼭 지원 불가 필드 추가 등은 타입으로 막혀 시도 불가이므로 코드화하지 않는다.
 * 각 요청마다 400(Bad Request) 오류가 발생함을 검증하고, 에러 메시지에 잘못된 필드/요청이 명시되어 있는지 확인한다.
 */
export async function test_api_discussionboard_test_list_board_topics_invalid_filters(
  connection: api.IConnection,
) {
  // 1. limit에 음수 값: schema/type 위배 → 400 에러 발생 검증
  await TestValidator.error("limit에 음수 값 - 400 error")(
    () =>
      api.functional.discussionboard.boards.topics.patch(connection, {
        body: {
          limit: -10 as number & tags.Type<"int32">,
        },
      }),
  );

  // 2. page에 0값: schema/type 위배 → 400 에러 발생 검증
  await TestValidator.error("page에 0 - 400 error")(
    () =>
      api.functional.discussionboard.boards.topics.patch(connection, {
        body: {
          page: 0 as number & tags.Type<"int32">,
          limit: 10 as number & tags.Type<"int32">,
        },
      }),
  );

  // 3. page에 음수 값: schema/type 위배 → 400 에러 발생 검증
  await TestValidator.error("page에 음수 - 400 error")(
    () =>
      api.functional.discussionboard.boards.topics.patch(connection, {
        body: {
          page: -2 as number & tags.Type<"int32">,
          limit: 10 as number & tags.Type<"int32">,
        },
      }),
  );

  // 4. 기타: 지원하지 않는 필드 추가처럼 타입상 거절되는 항목, 혹은 필수 입력 누락 등은 별도 테스트 불필요 (타입 차단/Body 모두 optional).
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoard";
import type { IBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IBoardTopic";
import type { IPageIBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIBoardTopic";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Verify empty result from topic search with non-matching filters.
 *
 * This e2e test ensures that searching board topics with valid, but non-matching filter parameters yields an empty result set without error. Specifically, it checks two cases: (1) filtering by nonexistent topic name; (2) filtering for deleted-only topics in a freshly created board. This guarantees robustness for admin search UIs and bulk reporting tools where zero results are valid and should not result in API errors.
 *
 * Test Steps:
 * 1. Create a discussion board via API to ensure at least one board exists
 * 2. Search board topics by a guaranteed-nonexistent name (random alphanumeric string), filtered to this board
 *    - Assert the result's data array is empty, records/meta reflect zero results
 * 3. Search for deleted-only topics (is_deleted:true) in this board (should be none as it's new)
 *    - Assert again: data array is empty, records/meta reflect zero results
 * 4. Search all topics without filters as a control: records/meta should also reflect zero (new board has no topics)
 *
 * This test guards against regression where API improperly treats empty search as an error, and validates correct response meta for empty sets.
 */
export async function test_api_discussionboard_test_list_board_topics_empty_result_set(
  connection: api.IConnection,
) {
  // 1. Create a discussion board
  const board = await api.functional.discussionboard.boards.post(connection, {
    body: {
      name: RandomGenerator.paragraph()(2),
      slug: RandomGenerator.alphaNumeric(10),
      description: RandomGenerator.paragraph()(1),
    } satisfies IDiscussionboardBoard.ICreate,
  });
  typia.assert(board);

  // 2. Search by non-existent topic name in this board
  const nonExistentName = RandomGenerator.alphaNumeric(16);
  const emptyByName = await api.functional.discussionboard.boards.topics.patch(connection, {
    body: { board_id: board.id, name: nonExistentName } satisfies IBoardTopic.IRequest,
  });
  typia.assert(emptyByName);
  TestValidator.equals("empty topic array")(emptyByName.data)([]);
  TestValidator.equals("zero records")(emptyByName.pagination.records)(0);
  TestValidator.equals("zero pages")(emptyByName.pagination.pages)(0);

  // 3. Search deleted-only topics in this board
  const emptyByDeleted = await api.functional.discussionboard.boards.topics.patch(connection, {
    body: { board_id: board.id, is_deleted: true } satisfies IBoardTopic.IRequest,
  });
  typia.assert(emptyByDeleted);
  TestValidator.equals("empty topic array")(emptyByDeleted.data)([]);
  TestValidator.equals("zero records")(emptyByDeleted.pagination.records)(0);
  TestValidator.equals("zero pages")(emptyByDeleted.pagination.pages)(0);

  // 4. Search all topics in this board (control)
  const emptyAll = await api.functional.discussionboard.boards.topics.patch(connection, {
    body: { board_id: board.id } satisfies IBoardTopic.IRequest,
  });
  typia.assert(emptyAll);
  TestValidator.equals("empty topic array")(emptyAll.data)([]);
  TestValidator.equals("zero records")(emptyAll.pagination.records)(0);
  TestValidator.equals("zero pages")(emptyAll.pagination.pages)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoard";
import type { IBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IBoardTopic";

/**
 * Validate successful retrieval of a board topic's details.
 *
 * This test verifies that after creating a discussion board and a topic under it, we can retrieve the topic's full information via the GET /discussionboard/boards/topics/{id} endpoint using its ID. It checks that the returned topic accurately reflects the name, slug, board association, and metadata provided during creation. This ensures admins or editors can reliably fetch topic details for editing or display transitions.
 *
 * Step-by-step process:
 * 1. Create a new discussion board, capturing its ID.
 * 2. Create a new topic under that board, saving the topic ID and its key attributes.
 * 3. Retrieve the topic using the GET /discussionboard/boards/topics/{id} endpoint and verify:
 *    - All topic fields (name, slug, board_id, description, timestamps) match what was set at creation.
 *    - The topic is correctly associated with the intended board.
 */
export async function test_api_discussionboard_test_get_board_topic_details_successfully(
  connection: api.IConnection,
) {
  // 1. Create a new discussion board
  const boardInput: IDiscussionboardBoard.ICreate = {
    name: RandomGenerator.paragraph()(1),
    slug: RandomGenerator.alphaNumeric(10).toLowerCase(),
    description: RandomGenerator.content()()(),
  };
  const board = await api.functional.discussionboard.boards.post(connection, {
    body: boardInput,
  });
  typia.assert(board);

  // 2. Create a new topic in that board
  const topicInput: IBoardTopic.ICreate = {
    board_id: board.id,
    name: RandomGenerator.paragraph()(1),
    slug: RandomGenerator.alphaNumeric(10).toLowerCase(),
    description: RandomGenerator.content()()(),
  };
  const topic = await api.functional.discussionboard.boards.topics.post(connection, {
    body: topicInput,
  });
  typia.assert(topic);

  // 3. Retrieve the topic by ID and verify details
  const fetched = await api.functional.discussionboard.boards.topics.getById(connection, {
    id: topic.id,
  });
  typia.assert(fetched);

  TestValidator.equals("topic id")(fetched.id)(topic.id);
  TestValidator.equals("topic name")(fetched.name)(topicInput.name);
  TestValidator.equals("topic slug")(fetched.slug)(topicInput.slug);
  TestValidator.equals("topic description")(fetched.description)(topicInput.description);
  TestValidator.equals("topic board association")(fetched.board_id)(board.id);

  // Timestamps and metadata - ensure creation and update timestamps exist and follow ISO format
  TestValidator.predicate("created_at exists and is ISO 8601")(
    typeof fetched.created_at === "string" && !isNaN(Date.parse(fetched.created_at))
  );
  TestValidator.predicate("updated_at exists and is ISO 8601")(
    typeof fetched.updated_at === "string" && !isNaN(Date.parse(fetched.updated_at))
  );
}

