import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoard";
import type { IBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IBoardTopic";

/**
 * Validate the successful creation of a new board topic with valid data.
 *
 * This test ensures that an admin or moderator can add a topic to an existing board by submitting all required fields (name, slug, board_id, description) with unique values. The process requires first creating a parent board, then creating a new topic under that board. The topic must have a name and slug unique within that board. The API should respond with the new topic's detail, confirming field correctness and proper board association.
 *
 * Test Steps:
 * 1. Create a discussion board via /discussionboard/boards (dependency required for valid board_id).
 * 2. Generate unique topic name and slug.
 * 3. Create a new topic linked to the created board with /discussionboard/boards/topics.
 * 4. Validate the API response, checking all returned fields and association.
 */
export async function test_api_discussionboard_test_create_board_topic_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Create a parent discussion board
  const boardInput: IDiscussionboardBoard.ICreate = {
    name: `Board ${RandomGenerator.alphaNumeric(8)}`,
    slug: `board-${RandomGenerator.alphaNumeric(5).toLowerCase()}`,
    description: RandomGenerator.paragraph()(),
  };
  const board = await api.functional.discussionboard.boards.post(connection, {
    body: boardInput,
  });
  typia.assert(board);

  // 2. Generate topic name and slug unique for this board
  const topicName = `Topic ${RandomGenerator.alphaNumeric(8)}`;
  const topicSlug = `topic-${RandomGenerator.alphaNumeric(5).toLowerCase()}`;
  const topicInput: IBoardTopic.ICreate = {
    board_id: board.id,
    name: topicName,
    slug: topicSlug,
    description: RandomGenerator.paragraph()(),
  };

  // 3. Create topic under the created board
  const topic = await api.functional.discussionboard.boards.topics.post(connection, {
    body: topicInput,
  });
  typia.assert(topic);

  // 4. Validate the returned topic fields
  TestValidator.equals("board_id matches")(topic.board_id)(board.id);
  TestValidator.equals("topic name matches")(topic.name)(topicName);
  TestValidator.equals("topic slug matches")(topic.slug)(topicSlug);
  TestValidator.equals("topic description matches")(topic.description)(topicInput.description);
}

