 *
 * Business context: Each topic slug within a single board must be unique. Creating a topic with a slug
 * that already exists (even if the name/description differ) in the same board should be rejected
 * by the API, typically with a 409 Conflict or uniqueness error. This test ensures the system's
 * data integrity and prevents duplicate URL navigation or display issues.
 *
 * Process:
 * 1. Create a new board with random data to isolate the test context.
 * 2. Create an initial topic on that board with a chosen slug value (random per test).
 * 3. Attempt to create a second topic on the same board using the identical slug.
 * 4. Assert that the API throws an error (conflict/uniqueness), using TestValidator.error, and do not inspect the message.
 */
export async function test_api_discussionboard_test_create_board_topic_duplicate_slug(
  connection: api.IConnection,
) {
  // 1. Create a new discussion board
  const boardInput = {
    name: RandomGenerator.paragraph()(8),
    slug: RandomGenerator.alphaNumeric(12),
    description: RandomGenerator.paragraph()(20),
  } satisfies IDiscussionboardBoard.ICreate;
  const board = await api.functional.discussionboard.boards.post(connection, {
    body: boardInput,
  });
  typia.assert(board);

  // 2. Create a topic with an explicit slug
  const topicSlug = RandomGenerator.alphaNumeric(10);
  const firstTopicInput = {
    board_id: board.id,
    name: RandomGenerator.paragraph()(8),
    slug: topicSlug,
    description: RandomGenerator.paragraph()(15),
