import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoard";
import type { IBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IBoardTopic";

/**
 * Validate that creating a board topic fails with missing required fields.
 *
 * This E2E test ensures the backend API enforces validation for topic creation by rejecting requests that omit any required property. Each missing-field case should result in HTTP 400 (validation error).
 *
 * Test workflow:
 * 1. Create a valid board (to obtain a real board_id for dependent tests).
 * 2. Try to create a topic with:
 *    - a) All fields omitted (empty body)
 *    - b) Missing 'board_id'
 *    - c) Missing 'name'
 *    - d) Missing 'slug'
 *    - e) Missing 'description'
 * 3. For each input, verify the API returns a validation error (TestValidator.error).
 *
 * Note: The use of `{body: body as any}` is intentional here to bypass TypeScript's structural requirements, simulating what happens if a client submits incomplete/malformed input. This is ONLY appropriate in validation failure tests, never for real usage. Type safety is otherwise enforced throughout.
 */
export async function test_api_discussionboard_test_create_board_topic_missing_required_fields(
  connection: api.IConnection,
) {
  // 1. Create a valid board (to use its id for topic creation attempts)
  const validBoardInput: IDiscussionboardBoard.ICreate = {
    name: RandomGenerator.paragraph()(3),
    slug: RandomGenerator.alphaNumeric(10),
    description: RandomGenerator.paragraph()(2),
  };
  const board = await api.functional.discussionboard.boards.post(connection, {
    body: validBoardInput,
  });
  typia.assert(board);

  // 2. Prepare cases omitting each required field individually
  const invalidCases: Partial<IBoardTopic.ICreate>[] = [
    // a) All fields missing
    {},
    // b) Missing 'board_id'
    {
      name: RandomGenerator.paragraph()(1),
      slug: RandomGenerator.alphaNumeric(8),
      description: RandomGenerator.paragraph()(1),
    },
    // c) Missing 'name'
    {
      board_id: board.id,
      slug: RandomGenerator.alphaNumeric(8),
      description: RandomGenerator.paragraph()(1),
    },
    // d) Missing 'slug'
    {
      board_id: board.id,
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.paragraph()(1),
    },
    // e) Missing 'description'
    {
      board_id: board.id,
      name: RandomGenerator.paragraph()(1),
      slug: RandomGenerator.alphaNumeric(8),
    },
  ];

  // 3. For each invalid body, validate that the endpoint returns a validation error
  for (const [idx, body] of invalidCases.entries()) {
    await TestValidator.error(`topic creation fails for missing required field [case ${idx + 1}]`)(
      () =>
        api.functional.discussionboard.boards.topics.post(
          connection,
          // Forced type assertion ONLY for negative testing validation
          { body: body as any },
        ),
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoard";
import type { IBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IBoardTopic";

/**
 * Successfully update a board topic's metadata (name, slug, description).
 *
 * This test simulates an admin or moderator editing the topic's metadata to improve board organization. It validates that:
 *  - Mutable fields (name, slug, description) are changed as intended
 *  - Immutable fields (id, board_id, created_at, deleted_at) are unchanged
 *  - The updated_at field is properly advanced
 *
 * **Step-by-step process:**
 * 1. Create a new board with valid random data (name, slug, description)
 * 2. Create a topic belonging to that board, also with random initial metadata
 * 3. Prepare new random values and update the topic's name, slug, and description via a single PUT
 * 4. Check that the update succeeds; confirm all changed fields are correct and unchanged fields remain the same
 * 5. Ensure updated_at reflects a newer time than before
 */
export async function test_api_discussionboard_test_update_board_topic_successfully(
  connection: api.IConnection,
) {
  // 1. Create a new board for the test
  const boardInput: IDiscussionboardBoard.ICreate = {
    name: RandomGenerator.paragraph()(1),
    slug: RandomGenerator.alphaNumeric(10),
    description: RandomGenerator.content()(1)(1),
  };
  const board = await api.functional.discussionboard.boards.post(connection, { body: boardInput });
  typia.assert(board);

  // 2. Create a topic on the created board
  const topicInput: IBoardTopic.ICreate = {
    board_id: board.id,
    name: RandomGenerator.paragraph()(1),
    slug: RandomGenerator.alphaNumeric(10),
    description: RandomGenerator.content()(1)(1),
  };
  const topic = await api.functional.discussionboard.boards.topics.post(connection, { body: topicInput });
  typia.assert(topic);

  // 3. Prepare and send update with new name, slug, and description
  const newName = RandomGenerator.paragraph()(1);
  const newSlug = RandomGenerator.alphaNumeric(12);
  const newDescription = RandomGenerator.content()(1)(1);
  const updateInput: IBoardTopic.IUpdate = {
    name: newName,
    slug: newSlug,
    description: newDescription,
  };

  // 4. Update the topic by topic ID
  const updated = await api.functional.discussionboard.boards.topics.putById(connection, {
    id: topic.id,
    body: updateInput,
  });
  typia.assert(updated);

  // 5. Validate the update: fields are updated, immutable fields stable, and timestamp advanced
  TestValidator.equals("name updated")(updated.name)(newName);
  TestValidator.equals("slug updated")(updated.slug)(newSlug);
  TestValidator.equals("description updated")(updated.description)(newDescription);
  TestValidator.equals("same id")(updated.id)(topic.id);
  TestValidator.equals("same board_id")(updated.board_id)(topic.board_id);
  TestValidator.equals("created_at unchanged")(updated.created_at)(topic.created_at);
  TestValidator.predicate("updated_at is newer")(
    new Date(updated.updated_at).getTime() > new Date(topic.updated_at).getTime(),
  );
  TestValidator.equals("deleted_at unchanged")(updated.deleted_at ?? null)(topic.deleted_at ?? null);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IBoardTopic";

/**
 * Validate error handling when updating a board topic with a non-existent ID.
 *
 * This test attempts to update a discussion board topic using a UUID that does not correspond to any existing topic record in the system. The scenario verifies that the system responds with a 404 not found error, confirming correct resource existence checks during update operations.
 *
 * Steps:
 * 1. Generate a random topic ID (UUID) that is not present in the system (i.e., never created).
 * 2. Attempt to update this topic using the update endpoint and provide some arbitrary update payload.
 * 3. Confirm that the server responds with an error with a 404 not found status, indicating that non-existent resources cannot be updated.
 * 4. Assert that if any other error code or a successful response is returned, the test fails.
 */
export async function test_api_discussionboard_boards_topics_putById_test_update_board_topic_nonexistent_id(
  connection: api.IConnection,
) {
  // 1. Generate a random, non-existent topic ID
  const nonexistentId = typia.random<string & tags.Format<"uuid">>();

  // 2. Prepare arbitrary, valid update payload
  const updatePayload = {
    name: "Nonexistent Topic Name",
    slug: "nonexistent-slug",
    description: "Trying to update a topic that does not exist.",
  } satisfies IBoardTopic.IUpdate;

  // 3. Attempt update and expect a 404 error specifically
  await TestValidator.error("Updating non-existent topic should throw 404")(
    async () => {
      try {
        await api.functional.discussionboard.boards.topics.putById(connection, {
          id: nonexistentId,
          body: updatePayload,
        });
      } catch (err) {
        // Check that the error has a 404 status code
        if (
          typeof err === "object" &&
          err !== null &&
          "status" in err &&
          (err as { status?: unknown }).status === 404
        ) {
          throw err; // This is the correct, expected outcome
        }
        // If any other error or no error, intentionally fail the test
        throw new Error(
          `Expected 404 Not Found, but got: ${
            typeof err === "object" && err && "status" in err
              ? `status=${(err as any).status}`
              : String(err)
          }`,
        );
      }
      throw new Error("Update succeeded unexpectedly on non-existent topic ID");
    },
  );
}

