import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { INotification } from "@ORGANIZATION/PROJECT-api/lib/structures/INotification";
import type { IPageINotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageINotification";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Paginated and filterable notification listing E2E test.
 *
 * This test verifies that a user can fetch their notifications with various filters, pagination,
 * and sorting options—confirming only their relevant records are returned. It simulates real-world
 * use-cases for notification center features, user isolation, and edge handling of empty results.
 *
 * Steps:
 * 1. Register a discussionboard user (recipient of notifications)
 * 2. Create multiple notifications for this user, covering different types, and referencing random post/comment IDs where applicable
 * 3. Fetch all notifications for user, verify all are present and belong to them
 * 4. Fetch filtered notifications: by type, is_read
 * 5. Validate correct slicing/counts under pagination (page 2, limit 2)
 * 6. Fetch with filter that returns nothing to validate edge behavior and correct pagination metadata
 */
export async function test_api_discussionboard_test_list_notifications_with_valid_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Register a new user (recipient)
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userPassword = RandomGenerator.alphaNumeric(12);
  const displayName = RandomGenerator.name();
  const user = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: userEmail,
      password: userPassword,
      displayName,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(user);

  // 2. Create several notifications for the user, with varied types/post/comment
  const types = ["reply", "like", "mention", "report_resolved", "system_message"];
  const post1 = typia.random<string & tags.Format<"uuid">>();
  const post2 = typia.random<string & tags.Format<"uuid">>();
  const comment1 = typia.random<string & tags.Format<"uuid">>();
  const makeNotification = async (overrides: Partial<INotification.ICreate> = {}) => {
    const input: INotification.ICreate = {
      user_id: user.id,
      notification_type: RandomGenerator.pick(types),
      content: RandomGenerator.paragraph()(),
      ...overrides,
    } satisfies INotification.ICreate;
    const output = await api.functional.discussionboard.notifications.post(connection, { body: input });
    typia.assert(output);
    return output;
  };
  const n1 = await makeNotification({ notification_type: "reply", post_id: post1 });
  const n2 = await makeNotification({ notification_type: "like", post_id: post2 });
  const n3 = await makeNotification({ notification_type: "mention", comment_id: comment1 });
  const n4 = await makeNotification({ notification_type: "system_message" });

  // 3. List all notifications for this user
  const allRes = await api.functional.discussionboard.notifications.patch(connection, { body: { user_id: user.id } });
  typia.assert(allRes);
  TestValidator.equals("total count matches")(allRes.pagination.records)(4);
  TestValidator.equals("got all notifications")(allRes.data.length)(4);
  allRes.data.forEach((n) => TestValidator.equals("correct recipient")(n.user_id)(user.id));

  // 4. Filter: by notification_type ("reply")
  const replyRes = await api.functional.discussionboard.notifications.patch(connection, { body: { user_id: user.id, notification_type: "reply" } });
  typia.assert(replyRes);
  replyRes.data.forEach(n => TestValidator.equals("type matches")(n.notification_type)("reply"));

  // 5. Filter: by is_read
  const unreadRes = await api.functional.discussionboard.notifications.patch(connection, { body: { user_id: user.id, is_read: false } });
  typia.assert(unreadRes);
  unreadRes.data.forEach(n => TestValidator.equals("is unread")(n.is_read)(false));

  // 6. Pagination (page 2, limit 2)
  const pagedRes = await api.functional.discussionboard.notifications.patch(connection, { body: { user_id: user.id, page: 2, limit: 2 } });
  typia.assert(pagedRes);
  TestValidator.equals("pagination: page=2")(pagedRes.pagination.current)(2);
  TestValidator.equals("pagination: limit=2")(pagedRes.pagination.limit)(2);
  TestValidator.equals("pagination: total")(pagedRes.pagination.records)(4);
  TestValidator.equals("pagination: pages")(pagedRes.pagination.pages)(2);

  // 7. Edge: filter with no result
  const noneRes = await api.functional.discussionboard.notifications.patch(connection, { body: { user_id: user.id, notification_type: "nonexistent_type" } });
  typia.assert(noneRes);
  TestValidator.equals("empty result")(noneRes.data.length)(0);
  TestValidator.equals("empty result - total")(noneRes.pagination.records)(0);
  TestValidator.equals("empty result - page")(noneRes.pagination.current)(1);
}

