import type { IPageINotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageINotification";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 알림 조회 API의 필터/페이징 입력 검증과 권한 거부를 검증하는 E2E 테스트
 *
 * 이 테스트는 디스커션보드 알림 리스트를 조회할 때 (1) 잘못된/허용범위 초과 파라미터를 입력할 경우 400 Bad Request가 반환되는지 및 (2) 권한 없는 유저가 타인의 알림을 인가 없이 조회 시도할 때 오류(403/401 등)가 정상적으로 발생하는지 확인한다.
 *
 * [진행 과정]
 * 1. 테스트용 유저A를 생성한다.
 * 2. 유저A에게 알림을 한 건 이상 생성한다.
 * 3. 유효성 규칙을 위반하는 파라미터(e.g. limit=201)로 알림 목록 요청 → 400 에러 검증
 * 4. 별도 유저B를 생성 후, 해당 세션(권한이동 미구현 시 동일 connection으로 대리 테스트)으로 user_id: 유저A의 알림을 열람 요청 → 권한에러(403 등) 검증
 */
export async function test_api_discussionboard_test_list_notifications_with_invalid_filter_parameters(
  connection: api.IConnection,
) {
  // 1. 테스트용 유저A(알림 수신자) 생성
  const userAEmail = typia.random<string & tags.Format<"email">>();
  const userA = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: userAEmail,
      password: "TestPassword123!",
      displayName: RandomGenerator.name(),
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(userA);

  // 2. 유저A에게 임의 알림 생성
  const notification = await api.functional.discussionboard.notifications.post(connection, {
    body: {
      user_id: userA.id,
      notification_type: "reply",
      content: "You've got a reply!",
    } satisfies INotification.ICreate,
  });
  typia.assert(notification);

  // 3. 최대 허용(limit=200) 초과 파라미터로 조회 시 400 에러 확인
  await TestValidator.error("알림 limit 초과 400 Bad Request")(() =>
    api.functional.discussionboard.notifications.patch(connection, {
      body: {
        user_id: userA.id,
        limit: 201, // 최대 200을 넘는 값으로 유효성 위반
      } satisfies INotification.IRequest,
    })
  );

  // 4. 유저B 생성 후, userA의 알림 열람 시도 → 권한 오류(시스템이 인증/스위칭 제공시 분리 필요)
  const userBEmail = typia.random<string & tags.Format<"email">>();
  const userB = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: userBEmail,
      password: "TestPassword123!",
      displayName: RandomGenerator.name(),
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(userB);

  // 유저B가 유저A 알림을 불법 조회하는 시나리오 (실환경선 토큰 스위칭 필요) → 권한 에러 검증
  await TestValidator.error("타인 알림 권한 거부 403/401 등")(() =>
    api.functional.discussionboard.notifications.patch(connection, {
      body: {
        user_id: userA.id,
        limit: 10,
      } satisfies INotification.IRequest,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
