/**
 * Validate that a discussionboard notification recipient can successfully retrieve their notification details by ID.
 *
 * This test ensures:
 * - A new user is created (simulating an actual platform user), and a notification is generated with that user as the recipient.
 * - Using the recipient’s (authenticated) context, a request is made to fetch the notification by its ID.
 * - All expected fields (ID, user_id, actor_id, post_id, comment_id, report_id, notification_type, content, is_read, created_at, read_at) are present and correct.
 * - The returned notification’s data matches precisely what was stored/created—especially user linkage, content, metadata, IDs, and type.
 * - Optionally, test that if business rules allow, an admin user can also fetch this notification; otherwise, check that access is denied (not implemented because no admin endpoint exists).
 *
 * Steps:
 * 1. Create a new user with unique email (discussionboard.users.post).
 * 2. Create a notification directed to that user (discussionboard.notifications.post) — with type, content, and minimal necessary entity links.
 * 3. Fetch the notification as the recipient using notification ID (discussionboard.notifications.getById) — check that all fields match and access is correct.
 * 4. Additional admin/cross-user access checks omitted due to lack of relevant API endpoints.
 */
export async function test_api_discussionboard_notifications_test_get_notification_by_id_with_proper_authorization(
  connection: api.IConnection,
) {
  // 1. Create a recipient user
  const recipientEmail: string = typia.random<string & tags.Format<"email">>();
  const recipient = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: recipientEmail,
      password: "test-password1!",
      displayName: RandomGenerator.name(),
      avatarUrl: undefined,
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(recipient);

  // 2. Create a notification for this user
  const notificationInput = {
    user_id: recipient.id,
    actor_id: null,
    post_id: null,
    comment_id: null,
    report_id: null,
    notification_type: "system_message",
    content: "This is a test notification.",
  } satisfies INotification.ICreate;
  const createdNotification = await api.functional.discussionboard.notifications.post(connection, {
    body: notificationInput,
  });
  typia.assert(createdNotification);
  TestValidator.equals("notification user_id")(createdNotification.user_id)(recipient.id);
  TestValidator.equals("notification content")(createdNotification.content)(notificationInput.content);
  TestValidator.equals("notification type")(createdNotification.notification_type)(notificationInput.notification_type);

  // 3. Fetch as recipient
  const fetched = await api.functional.discussionboard.notifications.getById(connection, {
    id: createdNotification.id,
  });
  typia.assert(fetched);
  TestValidator.equals("notification ID")(fetched.id)(createdNotification.id);
  TestValidator.equals("user_id")(fetched.user_id)(recipient.id);
  TestValidator.equals("content")(fetched.content)(notificationInput.content);
  TestValidator.equals("notification_type")(fetched.notification_type)(notificationInput.notification_type);
  TestValidator.predicate("is_read is boolean")(typeof fetched.is_read === "boolean");
  // (Optional: Cross-user/admin access test omitted as no admin creation/auth APIs are provided.)
}

