import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { INotification } from "@ORGANIZATION/PROJECT-api/lib/structures/INotification";

/**
 * Validate that an admin can create notification events for a recipient user with all required fields, supporting various notification types.
 *
 * This test ensures the notification creation API (/discussionboard/notifications) allows an administrator to create different types of notifications (reply, like, mention) for a valid recipient user. It verifies that the returned notification object preserves correct recipient, actor, type, and content values, enforcing business rules and expected data propagation. Each type scenario is covered for robust notification logic validation.
 *
 * Steps:
 * 1. Create an admin user (with valid email, password, display name, active status)
 * 2. Create a recipient user (same structure as above)
 * 3. Create a notification (type="reply") as admin for the recipient
 *    - Verify the notification's recipient and type fields and actor are correct
 * 4. Create a notification (type="like") as admin for the recipient
 *    - Verify type correctness
 * 5. Create a notification (type="mention") as admin for the recipient
 *    - Verify type correctness
 */
export async function test_api_discussionboard_test_create_notification_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Create an admin user
  const adminInput = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "adminPass123!",
    displayName: RandomGenerator.name(),
    isActive: true,
  } satisfies IDiscussionboardUser.ICreate;
  const admin = await api.functional.discussionboard.users.post(connection, { body: adminInput });
  typia.assert(admin);

  // 2. Create a recipient user
  const userInput = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "userPass456!",
    displayName: RandomGenerator.name(),
    isActive: true,
  } satisfies IDiscussionboardUser.ICreate;
  const recipient = await api.functional.discussionboard.users.post(connection, { body: userInput });
  typia.assert(recipient);

  // 3. Create notification of type "reply"
  const notifReplyInput = {
    user_id: recipient.id,
    actor_id: admin.id,
    notification_type: "reply",
    content: "You received a reply on your discussion.",
  } satisfies INotification.ICreate;
  const notifReply = await api.functional.discussionboard.notifications.post(connection, { body: notifReplyInput });
  typia.assert(notifReply);
  TestValidator.equals("notification recipient matches")(notifReply.user_id)(recipient.id);
  TestValidator.equals("notification type is reply")(notifReply.notification_type)("reply");
  TestValidator.equals("actor id matches")(notifReply.actor_id)(admin.id);

  // 4. Create notification of type "like"
  const notifLikeInput = {
    user_id: recipient.id,
    actor_id: admin.id,
    notification_type: "like",
    content: "Your post was liked!",
  } satisfies INotification.ICreate;
  const notifLike = await api.functional.discussionboard.notifications.post(connection, { body: notifLikeInput });
  typia.assert(notifLike);
  TestValidator.equals("notification type is like")(notifLike.notification_type)("like");

  // 5. Create notification of type "mention"
  const notifMentionInput = {
    user_id: recipient.id,
    actor_id: admin.id,
    notification_type: "mention",
    content: "You have been mentioned in a post.",
  } satisfies INotification.ICreate;
  const notifMention = await api.functional.discussionboard.notifications.post(connection, { body: notifMentionInput });
  typia.assert(notifMention);
  TestValidator.equals("notification type is mention")(notifMention.notification_type)("mention");
}

