 */
export async function test_api_discussionboard_test_create_notification_for_nonexistent_user_returns_error(
  connection: api.IConnection,
) {
  // Step 1: Generate a random non-existent user_id
  const nonExistentUserId: string = typia.random<string & tags.Format<"uuid">>();

