    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { INotification } from "@ORGANIZATION/PROJECT-api/lib/structures/INotification";

/**
 * Test creation of a notification with missing required fields.
 *
 * Validates that attempting to create a notification without required fields such as "notification_type" or "user_id" triggers API validation errors (400 Bad Request).
 *
 * Business context:
 * Creating notifications programmatically requires specifying at minimum a recipient (user_id) and the type/category (notification_type). APIs must strictly validate these base invariants.
 *
 * Steps:
 * 1. Create a valid user to serve as notification recipient (for use in partial payloads)
 * 2. Attempt to create a notification omitting "notification_type"
 * 3. Attempt to create a notification omitting "user_id"
 * 4. Attempt to create a notification omitting both required fields
 *    - For each case, validate that API responds with 400 Bad Request
 *    - This confirms that server-side validation is correctly enforced
 */
export async function test_api_discussionboard_test_create_notification_with_missing_required_fields(
  connection: api.IConnection,
) {
  // 1. Create a valid user
  const user = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "123456Test!",
      displayName: RandomGenerator.name(),
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(user);

  // 2. Attempt notification creation missing "notification_type"
  await TestValidator.error("Missing notification_type triggers 400 Bad Request")(async () => {
    await api.functional.discussionboard.notifications.post(connection, {
      body: {
        user_id: user.id,
        // notification_type omitted
        content: "This notification should fail",
      } as any, // Only inside error case for negative test
    });
  });

  // 3. Attempt notification creation missing "user_id"
  await TestValidator.error("Missing user_id triggers 400 Bad Request")(async () => {
    await api.functional.discussionboard.notifications.post(connection, {
      body: {
        notification_type: "mention",
        content: "This notification should fail (no user_id)",
      } as any,
    });
  });

  // 4. Attempt creation missing both required fields
  await TestValidator.error("Missing both notification_type and user_id triggers 400 Bad Request")(async () => {
    await api.functional.discussionboard.notifications.post(connection, {
      body: {
        content: "This notification should fail (no fields)",
      } as any,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { INotification } from "@ORGANIZATION/PROJECT-api/lib/structures/INotification";

/**
 * Validate updating of a notification's read status by admin or recipient.
 *
 * This test ensures the notification update endpoint works according to business logic:
 * - Recipients and admins can change notification status (is_read, read_at) for granular notification management.
 * - System should return updated notification object with correct is_read and read_at fields.
 * - Only allowed fields should be updated, critical data like user_id/content/type must not change.
 *
 * 1. Create a user to be the notification recipient.
 * 2. Create an admin account (for role-based update check).
 * 3. Admin (or recipient) creates a notification for that user.
 * 4. Recipient marks the notification as read (updates is_read = true, read_at = now).
 * 5. Verify response has is_read = true and correct read_at timestamp.
 * 6. Try updating with is_read = false and read_at = null, and verify state reverts.
 * 7. (Optional) Try forbidden user update and expect error (if business logic enforced).
 */
export async function test_api_discussionboard_test_update_notification_status_to_read(
  connection: api.IConnection,
) {
  // 1. Create user (recipient for notification)
  const userEmail = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: userEmail,
      password: "Password123!",
      displayName: RandomGenerator.name(),
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(user);

  // 2. Create admin user (simulate admin)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: adminEmail,
      password: "Password123!",
      displayName: "Admin User",
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(admin);

  // 3. Admin creates notification for recipient
  const notification = await api.functional.discussionboard.notifications.post(connection, {
    body: {
      user_id: user.id,
      actor_id: admin.id,
      notification_type: "system_message",
      content: "This is a test notification.",
    } satisfies INotification.ICreate,
  });
  typia.assert(notification);

  // 4. Recipient marks notification as read
  const now = new Date().toISOString();
  const updated = await api.functional.discussionboard.notifications.putById(connection, {
    id: notification.id,
    body: {
      is_read: true,
      read_at: now,
    } satisfies INotification.IUpdate,
  });
  typia.assert(updated);
  TestValidator.equals("notification is_read")(updated.is_read)(true);
  TestValidator.equals("notification read_at")(updated.read_at !== undefined && updated.read_at !== null)(true);

  // 5. Recipient marks notification as unread
  const reverted = await api.functional.discussionboard.notifications.putById(connection, {
    id: notification.id,
    body: {
      is_read: false,
      read_at: null,
    } satisfies INotification.IUpdate,
  });
  typia.assert(reverted);
  TestValidator.equals("notification is_read reverted")(reverted.is_read)(false);
  TestValidator.equals("notification read_at is null")(reverted.read_at === null || reverted.read_at === undefined)(true);

  // 6. Confirm forbidden user cannot update (skipped - insufficient API for permission switching)
}

