import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { INotification } from "@ORGANIZATION/PROJECT-api/lib/structures/INotification";

/**
 * 알림(Notification) 수정 권한 및 비허용 필드 변경 시도 방지 검증.
 *
 * 본 테스트는 다음 시나리오를 검증한다:
 * 1. 알림의 수신자(recipient)가 알림 is_read 플래그를 정상적으로 변경할 수 있음
 * 2. 수신자가 아닌 제3자(권한 없는 유저)가 해당 알림의 is_read를 수정 시도할 경우 403 Forbidden 오류가 발생함
 * 3. content, user_id 등 알림의 주요 필드(비허용 필드)는 아예 업데이트 DTO에 없으므로 컴파일 타임에 변경 시도가 불가(실제 테스트 불필요)
 *
 * 선행 작업:
 *  - recipient, admin(관리자/실제로는 일반 계정), thirdUser 세 개 계정 생성
 *  - recipient에게 알림(Notification) 생성
 *
 * 절차:
 * 1. recipient 자신의 알림을 is_read=true로 정상 변경(성공)
 * 2. thirdUser(수신자가 아님)로 같은 알림의 is_read=false 변경 시도(403 Forbidden 오류 기대)
 *    (세션/토큰 스위치는 실제 로그인 API 제공 시 구현; 여기서는 계정 구분 목적만)
 * 3. content/user_id 등 주요 속성 변경 시도는 IUpdate DTO에 존재하지 않아 타입상/런타임상 구현 불가
 */
export async function test_api_discussionboard_notifications_test_update_notification_with_forbidden_field_change(
  connection: api.IConnection,
) {
  // 1. 액터: recipient, thirdUser(제3자), admin(관리자-구현불가) 3개 계정 생성
  const recipientEmail = typia.random<string & tags.Format<"email">>();
  const thirdUserEmail = typia.random<string & tags.Format<"email">>();
  // recipient 생성
  const recipient = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: recipientEmail,
      password: "TestPassw0rd!",
      displayName: "RecipientUser",
      isActive: true,
    },
  });
  typia.assert(recipient);
  // admin 생성(관리자 플래그 없음, 일반 계정)
  const admin = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "TestPassw0rd!",
      displayName: "AdminUser",
      isActive: true,
    },
  });
  typia.assert(admin);
  // thirdUser 생성
  const thirdUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: thirdUserEmail,
      password: "TestPassw0rd!",
      displayName: "ThirdUser",
      isActive: true,
    },
  });
  typia.assert(thirdUser);

  // 2. recipient에게 알림(Notification) 생성
  const notification = await api.functional.discussionboard.notifications.post(connection, {
    body: {
      user_id: recipient.id,
      notification_type: "mention",
      content: "You were mentioned in a post.",
      actor_id: null,
      post_id: null,
      comment_id: null,
      report_id: null,
    },
  });
  typia.assert(notification);

  // 3. recipient(본인) 권한으로 is_read 변경(정상 케이스)
  const updated = await api.functional.discussionboard.notifications.putById(connection, {
    id: notification.id,
    body: {
      is_read: true,
      read_at: new Date().toISOString(),
    },
  });
  typia.assert(updated);
  TestValidator.equals("is_read 플래그가 true로 반영되어야 함")(updated.is_read)(true);

  // 4. thirdUser(수신자가 아닌 사용자) 권한으로 is_read 변경 시도(403 Forbidden 발생 확인)
  await TestValidator.error("수신자가 아닌 계정은 알림을 수정할 수 없어야 함")(
    async () => {
      await api.functional.discussionboard.notifications.putById(connection, {
        id: notification.id,
        body: {
          is_read: false,
          read_at: null,
        },
      });
    },
  );

  // 5. 비허용 필드(예: content, user_id 등) 변경은 IUpdate 제공X → 타입상 시도 자체가 불가(테스트 불필요)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { INotification } from "@ORGANIZATION/PROJECT-api/lib/structures/INotification";

/**
 * Validates soft deletion of a notification by its recipient.
 *
 * This test ensures that a notification can be deleted (soft delete) by the user who owns it. It performs the following steps:
 * 1. Create a new discussion board user who will be the owner/recipient of the notification.
 * 2. As this user, create a notification (with themselves as recipient).
 * 3. Execute the notification delete (soft delete) operation.
 * 4. Validate that the delete API returns confirmation and the notification is not visible in further queries (if list/detail APIs existed).
 * 5. (If audit log or soft-deleted retrieval APIs become available, confirm the record persists for compliance.)
 *
 * Edge case: Attempt deleting the notification with a non-owner user (should fail -- not implemented due to API constraints).
 *
 * Only valid, type-safe interactions are included. As listing or detail retrieval APIs are not available in current SDK, validation is limited to API response from the delete itself.
 */
export async function test_api_discussionboard_test_delete_notification_as_owner(
  connection: api.IConnection,
) {
  // 1. Create recipient user
  const user = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(12),
      displayName: RandomGenerator.name(),
      avatarUrl: undefined,
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(user);

  // 2. Create a notification for this user
  const notification = await api.functional.discussionboard.notifications.post(connection, {
    body: {
      user_id: user.id,
      actor_id: null,
      post_id: null,
      comment_id: null,
      report_id: null,
      notification_type: "system_message",
      content: "Test notification for soft deletion.",
    } satisfies INotification.ICreate,
  });
  typia.assert(notification);
  TestValidator.equals("recipient of notification")(notification.user_id)(user.id);

  // 3. Delete (soft delete) the notification as recipient
  const deleted = await api.functional.discussionboard.notifications.eraseById(connection, {
    id: notification.id,
  });
  typia.assert(deleted);
  // Should include soft-deletion evidence only if API returns it; otherwise, check basic response property set
  TestValidator.equals("deleted notification id")(deleted.id)(notification.id);
  TestValidator.equals("deleted notification user")(deleted.user_id)(user.id);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { INotification } from "@ORGANIZATION/PROJECT-api/lib/structures/INotification";

/**
 * Test deletion of a notification by an unauthorized user and a not-found scenario.
 *
 * This test verifies that only the recipient or an admin can delete a notification.
 * It attempts to delete a notification as an unauthorized user and checks for denial,
 * and separately tries to delete a non-existent notification (random id) and checks for not-found.
 *
 * Steps:
 * 1. Register recipient user
 * 2. Register unauthorized user
 * 3. As recipient, create a notification for self
 * 4. As unauthorized user, attempt deletion of the recipient's notification (should error)
 * 5. Attempt to delete a notification with a random (non-existent) id (should error)
 */
export async function test_api_discussionboard_test_delete_notification_unauthorized_access_denied(
  connection: api.IConnection,
) {
  // 1. Register recipient user
  const recipientEmail = typia.random<string & tags.Format<"email">>();
  const recipientPassword = typia.random<string & tags.Format<"password">>();
  const recipient: IDiscussionboardUser = await api.functional.discussionboard.users.post(
    connection,
    {
      body: {
        email: recipientEmail,
        password: recipientPassword,
        displayName: RandomGenerator.name(),
      } satisfies IDiscussionboardUser.ICreate,
    },
  );
  typia.assert(recipient);

  // 2. Register unauthorized user
  const unauthorizedEmail = typia.random<string & tags.Format<"email">>();
  const unauthorizedPassword = typia.random<string & tags.Format<"password">>();
  const unauthorized: IDiscussionboardUser = await api.functional.discussionboard.users.post(
    connection,
    {
      body: {
        email: unauthorizedEmail,
        password: unauthorizedPassword,
        displayName: RandomGenerator.name(),
      } satisfies IDiscussionboardUser.ICreate,
    },
  );
  typia.assert(unauthorized);

  // 3. As recipient, create a notification for themselves
  const notification: INotification = await api.functional.discussionboard.notifications.post(
    connection,
    {
      body: {
        user_id: recipient.id,
        notification_type: "test-case",
        content: "This is a test notification",
      } satisfies INotification.ICreate,
    },
  );
  typia.assert(notification);

  // 4. As unauthorized user, attempt to delete (should fail)
  // (Simulate as if logged in as unauthorized user if API checks auth by connection context)
  // If there's no login endpoint, assume connection/session context controls permissions.
  // For this test, just perform the call assuming context is changed per SDK or environment
  // -- If this is incorrect, adjust as necessary for your authentication system.
  connection.headers = { ...(connection.headers ?? {}), "x-user-id": unauthorized.id };
  await TestValidator.error("Only recipient or admin can delete notification")(
    async () => {
      await api.functional.discussionboard.notifications.eraseById(connection, {
        id: notification.id,
      });
    },
  );

  // 5. Attempt to delete a non-existent notification id (should get not found)
  await TestValidator.error("Deleting non-existent notification returns error")(
    async () => {
      await api.functional.discussionboard.notifications.eraseById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
