    body: {
      email: userEmail,
      password: userPassword,
      displayName: userDisplayName,
    } satisfies IDiscussionboardUser.ICreate,
  });

  // 2. 권한 없는 유저로 프로필 목록 조회 시도 (접근 거부 오류 검증)
  TestValidator.error("권한 없는 일반 사용자는 profiles 목록 접근 불가")(
    async () => {
      await api.functional.discussionboard.users.profiles.patch(connection, {
        body: {},
      });
    },
  );

  // 3. 인증 없는 상태로 profiles 목록 조회 시도 (접근 거부 오류 검증)
  TestValidator.error("비인증 유저 역시 profiles 목록 접근 불가")(
    async () => {
      await api.functional.discussionboard.users.profiles.patch(connection, {
        body: {},
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { IDiscussionboardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUserProfile";

/**
 * 유저 프로필 상세 조회 API 성공 케이스 검증
 *
 * 신규 유저 생성 후, 그 유저를 위한 프로필을 생성한 뒤
 * 해당 프로필 ID(==userId)로 상세 조회 API를 호출한다.
 *
 * 조회 결과로 반환되는 profile 객체가 실제 입력한 값, 연동된 userId,
 * 그리고 타입 구조, 필수 필드 등이 모두 올바른지 typia와 TestValidator로 검증한다.
 *
 * 1. 신규 유저를 생성한다. (ID, email, 닉네임 등 부여)
 * 2. 해당 유저 ID(userId)로 프로필 정보를 직접 입력해 생성한다.
 * 3. 생성된 프로필의 id(userId 동일)로 상세 조회 API를 조회한다.
 * 4. 상세 조회 결과의 id/userId 일치 및 전체 구조, 입력값, 필수 metadata 타입 assert 및 equals 비교한다.
 */
export async function test_api_discussionboard_test_fetch_user_profile_detail_success(
  connection: api.IConnection,
) {
  // 1. 신규 유저 생성
  const user = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
      displayName: RandomGenerator.name(),
      avatarUrl: RandomGenerator.alphaNumeric(12),
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(user);

  // 2. 해당 유저 ID로 프로필 정보 생성 (임의/직접 입력값)
  const profileInput = {
    userId: user.id,
    bio: RandomGenerator.paragraph()(),
    location: RandomGenerator.alphaNumeric(8),
    websiteUrl: `https://www.${RandomGenerator.alphaNumeric(6)}.com`,
    twitterHandle: `@${RandomGenerator.alphaNumeric(10)}`,
  } satisfies IDiscussionboardUserProfile.ICreate;

  const profile = await api.functional.discussionboard.users.profiles.post(connection, {
    body: profileInput,
  });
  typia.assert(profile);

  // 3. 생성된 프로필 ID(userId와 동일)로 상세조회 API 호출
  const fetched = await api.functional.discussionboard.users.profiles.getById(connection, {
    id: profile.id,
  });
  typia.assert(fetched);

  // 4. 상세 필드/구조 검증
  TestValidator.equals("프로필 id 일치")(fetched.id)(profile.id);
  TestValidator.equals("userId 일치")(fetched.userId)(user.id);
  TestValidator.equals("bio 일치")(fetched.bio)(profileInput.bio);
  TestValidator.equals("location 일치")(fetched.location)(profileInput.location);
  TestValidator.equals("websiteUrl 일치")(fetched.websiteUrl)(profileInput.websiteUrl);
  TestValidator.equals("twitterHandle 일치")(fetched.twitterHandle)(profileInput.twitterHandle);
  TestValidator.predicate("createdAt/updatedAt 존재 및 형식")(
    typeof fetched.createdAt === "string" &&
    typeof fetched.updatedAt === "string" &&
    fetched.createdAt.length > 0 &&
    fetched.updatedAt.length > 0
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUserProfile";

/**
 * Discussionboard_user_profile 프로필 상세 조회 API의 "존재하지 않는 id(UUID)" 및 "비정상/UUID 형식이 아닌 값" 요청에 대한 404 Not Found 및 유효성 실패 케이스 검증 E2E 테스트.
 *
 * - 존재하지 않는 UUID로 프로필 detail 요청 시 404 Not Found가 반환되어야 함을 검증
 * - 잘못된(비-UUID) 문자열 값으로 요청 시 validation error(400 등) 발생을 확인
 * - 정상, 비정상 각 상황마다 명확하게 HttpError가 발생하는지 확인
 *
 * [테스트 시나리오]
 * 1. 임의의 존재하지 않는(랜덤) UUID로 profile detail 요청 → 404 HttpError 발생 체크
 * 2. 잘못된 형식의 id(예: "not-a-uuid" 또는 빈 문자열 등)로 profile 요청 → 400 HttpError(혹은 validation error) 발생 체크
 *
 * 각 케이스에서 HttpError가 발생하면 성공, 발생하지 않으면 실패로 간주함
 */
export async function test_api_discussionboard_users_profiles_getById_not_found(
  connection: api.IConnection,
) {
  // 1. 존재하지 않는/랜덤 UUID로 프로필 조회 시 404 Not Found 발생 확인
  await TestValidator.error("존재하지 않는 id는 404 반환")(
    async () => {
      await api.functional.discussionboard.users.profiles.getById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );

  // 2. UUID 포맷이 아닌 잘못된 값으로 요청시 validation 에러(400 등) 확인
  const malformedIds = ["not-a-uuid", "", "1234", "zz-zz-zz-zz" ];
  for (const malformedId of malformedIds) {
    await TestValidator.error(`id 비정상값(${malformedId})은 validation 에러`) (
      async () => {
        await api.functional.discussionboard.users.profiles.getById(connection, {
          id: malformedId as string & tags.Format<"uuid">,
        });
      }
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { IDiscussionboardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUserProfile";

/**
 * Permission enforcement test for discussionboard user profile detail fetch
 *
 * This E2E test validates that only the profile's owner can access their profile details
 * via GET /discussionboard/users/profiles/{id}.
 *
 * The test verifies:
 *   1. A user ('User A') can fetch their own profile (should succeed)
 *   2. Another user ('User B') is forbidden from accessing User A's profile (should error)
 *   3. An unauthenticated request also cannot fetch the profile (should error)
 *
 * Preconditions/setup:
 *   - Create two users: Owner (A) and Other (B)
 *   - Create a profile for Owner (A)
 *
 * Admin/moderator access is NOT tested here since no API for privileged user creation is present in current SDK materials.
 */
export async function test_api_discussionboard_test_fetch_user_profile_detail_permission_enforcement(
  connection: api.IConnection,
) {
  // 1. Create User A (profile owner)
  const userAEmail = typia.random<string & tags.Format<'email'>>();
  const userA = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: userAEmail,
      password: 'UserApassword123!',
      displayName: RandomGenerator.name(),
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(userA);

  // 2. Create User B (other, non-privileged account)
  const userBEmail = typia.random<string & tags.Format<'email'>>();
  const userB = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: userBEmail,
      password: 'UserBpassword123!',
      displayName: RandomGenerator.name(),
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(userB);

  // 3. Create a profile for User A
  const profile = await api.functional.discussionboard.users.profiles.post(connection, {
    body: {
      userId: userA.id,
      bio: RandomGenerator.paragraph()(),
      location: RandomGenerator.alphaNumeric(8),
      websiteUrl: 'https://example.com',
      twitterHandle: RandomGenerator.alphaNumeric(6),
