 *
 * This test ensures that only the profile owner, admin, or moderator are allowed to update a profile,
 * and unauthorized users are denied with proper error response.
 *
 * Test steps:
 * 1. Register two general users (Owner, Other).
 * 2. Create a profile for the owner user.
 * 3. Attempt to update the owner's profile as the non-privileged 'Other' user (should fail).
 * 4. (Edge) Attempt to update as self (should succeed) — positive scenario for coverage.
 *
 * Validation:
 * - Step 3: Expect an error (typically 403 Forbidden).
 * - Step 4: Profile update returns with correct data.
 */
export async function test_api_discussionboard_test_update_user_profile_permission_enforcement(connection: api.IConnection) {
  // 1. Register profile owner
  const owner = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "1234abcd!", // Must be sufficiently strong per password policy
      displayName: RandomGenerator.name(),
      avatarUrl: undefined,
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(owner);

  // 2. Register other (non-privileged) user
  const stranger = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "1234abcd!",
      displayName: RandomGenerator.name(),
      avatarUrl: undefined,
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(stranger);

  // 3. Create profile tied to owner
  const ownerProfile = await api.functional.discussionboard.users.profiles.post(connection, {
    body: {
      userId: owner.id,
      bio: RandomGenerator.paragraph()(),
      location: "Seoul",
      websiteUrl: "https://example.com",
      twitterHandle: "testuser123",
    } satisfies IDiscussionboardUserProfile.ICreate,
  });
  typia.assert(ownerProfile);

  // 4. As "stranger" (non-owner), attempt to update owner's profile
  // (Assume context-switch mechanism / authentication changes here to simulate stranger's session)
  // Here, we just use the shared connection and document the assumption, since auth mechanism is not present.
  await TestValidator.error("Stranger cannot update another user's profile")(
    async () => {
      await api.functional.discussionboard.users.profiles.putById(connection, {
        id: ownerProfile.id,
        body: {
          bio: "Unauthorized update by stranger",
        } satisfies IDiscussionboardUserProfile.IUpdate,
      });
    },
  );

  // 5. (Optional/Edge) As owner, update own profile (should succeed)
  // Again, note assumption about session/identity switching.
  const updatedProfile = await api.functional.discussionboard.users.profiles.putById(connection, {
    id: ownerProfile.id,
    body: {
      bio: "Updated bio by owner",
      location: "Busan",
      websiteUrl: "https://owner.com",
      twitterHandle: "ownerhandle",
    } satisfies IDiscussionboardUserProfile.IUpdate,
  });
  typia.assert(updatedProfile);
  TestValidator.equals("Updated bio")(updatedProfile.bio)("Updated bio by owner");
}

