import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IDiscussionboardBookmark } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBookmark";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionboardBookmark } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardBookmark";

/**
 * 성공적으로 로그인된 유저의 북마크 목록을 정상적으로 페이지네이션+필터링해서 조회할 수 있는지 테스트합니다.
 *
 * - 신규 유저를 회원가입합니다.
 * - 별도의 thread_id를 사용하여 두 개의 게시글을 만듭니다 (각각 1번 작성).
 * - 위 유저 정보와 두 게시글을 이용해 북마크를 각각 생성합니다 (즉, 해당 유저는 두 건의 북마크를 갖게 됨).
 * - PATCH /discussionboard/bookmark 엔드포인트로 본인(user_id) 조건, page, limit, sort_by 파라미터를 포함해 목록을 요청합니다.
 * - response로 내려온 북마크 데이터들이 모두 해당 user_id로만 소유된 북마크이며, 정렬(order)과 paging이 input 조건과 일치하는지 검증합니다.
 *
 * 테스트 단계:
 * 1. 신규 유저 회원가입
 * 2. 서로 다른 thread_id로 2개 게시글 작성
 * 3. 2개 게시글 각각에 대해 북마크 생성 (총 2건의 북마크)
 * 4. 본인 user_id 조건으로 북마크 목록 PATCH 조회 (pagination: page=1, limit=1, sort_by=created_at)
 * 5. 조회 결과의 pagination, data length(paging 갯수=1), user_id 값 일치
 * 6. 본인 소유 북마크만 포함되어 있는지, 그리고 정렬 조건 충족하는지 검증
 */
export async function test_api_discussionboard_test_list_bookmarks_with_valid_filter_and_pagination(
  connection: api.IConnection,
) {
  // 1. 신규 테스트 유저 생성
  const email = typia.random<string & tags.Format<"email">>();
  const password = typia.random<string & tags.Format<"password">>();
  const displayName = RandomGenerator.name();
  const user = await api.functional.discussionboard.users.post(connection, {
    body: {
      email,
      password,
      displayName
    } satisfies IDiscussionboardUser.ICreate
  });
  typia.assert(user);

  // 2. 서로 다른 thread_id로 2개 게시글 작성
  const threadId1 = typia.random<string & tags.Format<"uuid">>();
  const threadId2 = typia.random<string & tags.Format<"uuid">>();
  const post1 = await api.functional.discussionboard.posts.post(connection, {
    body: {
      thread_id: threadId1,
      content: RandomGenerator.paragraph()()
    } satisfies IDiscussionboardPost.ICreate
  });
  typia.assert(post1);
  const post2 = await api.functional.discussionboard.posts.post(connection, {
    body: {
      thread_id: threadId2,
      content: RandomGenerator.paragraph()()
    } satisfies IDiscussionboardPost.ICreate
  });
  typia.assert(post2);

  // 3. 각각의 게시글에 대해 북마크 생성
  const bookmark1 = await api.functional.discussionboard.bookmark.post(connection, {
    body: {
      user_id: user.id,
      post_id: post1.id
    } satisfies IDiscussionboardBookmark.ICreate
  });
  typia.assert(bookmark1);
  const bookmark2 = await api.functional.discussionboard.bookmark.post(connection, {
    body: {
      user_id: user.id,
      post_id: post2.id
    } satisfies IDiscussionboardBookmark.ICreate
  });
  typia.assert(bookmark2);

  // 4. 본인 user_id 조건, page=1, limit=1, sort_by=created_at로 북마크 목록 요청
  const pageRequest = {
    page: 1,
    limit: 1
  } satisfies IPage.IRequest;
  const filter = {
    user_id: user.id,
    pagination: pageRequest,
    sort_by: "created_at"
  } satisfies IDiscussionboardBookmark.IRequest;
  const response = await api.functional.discussionboard.bookmark.patch(connection, {
    body: filter
  });
  typia.assert(response);

  // 5. pagination, length, 필터 결과 확인
  TestValidator.equals("pagination current page")(response.pagination.current)(1);
  TestValidator.equals("pagination limit")(response.pagination.limit)(1);
  TestValidator.equals("data length = limit")(response.data.length)(1);

  // 6. 반환 데이터의 user_id 정확성, 소유 북마크만 응답
  for (const b of response.data) {
    TestValidator.equals("user_id matches")(b.user_id)(user.id);
  }

  // 7. 두 번째 페이지 요청 - 나머지 북마크 데이터 조회, 조건 위와 동일
  const responsePage2 = await api.functional.discussionboard.bookmark.patch(connection, {
    body: {
      ...filter,
      pagination: {
        ...pageRequest,
        page: 2
      }
    } satisfies IDiscussionboardBookmark.IRequest
  });
  typia.assert(responsePage2);
  TestValidator.equals("pagination current page")(responsePage2.pagination.current)(2);
  TestValidator.equals("pagination limit")(responsePage2.pagination.limit)(1);
  TestValidator.equals("data length = limit or less")(responsePage2.data.length)(1);
  for (const b of responsePage2.data) {
    TestValidator.equals("user_id matches")(b.user_id)(user.id);
  }

  // 8. 정렬 검증 (created_at이 page1 데이터가 page2 데이터보다 이후여야 함)
  if (response.data.length === 1 && responsePage2.data.length === 1) {
    const firstCreatedAt = response.data[0].created_at;
    const secondCreatedAt = responsePage2.data[0].created_at;
    TestValidator.predicate("bookmark sorted by created_at desc")(
      new Date(firstCreatedAt) >= new Date(secondCreatedAt)
    );
  }
}

