/**
 * Validate updating a discussionboard bookmark owned by a user.
 *
 * Ensures a user can update the bookmark they own, specifically changing the target post
 * (the only updatable field per provided DTO). This covers end-to-end creation and update.
 *
 * 1. Register a new user.
 * 2. Create a post (for initial bookmark).
 * 3. Create a bookmark to that post with the user.
 * 4. Create a second post (for update testing).
 * 5. Update the bookmark to target the second post (only post_id is updatable).
 * 6. Check that response has the new post id, original id and user_id.
 */
export async function test_api_discussionboard_test_update_bookmark_owned_by_user(
  connection: api.IConnection,
) {
  // 1. Register a new user
  const user = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
      displayName: RandomGenerator.name(),
      isActive: true,
    },
  });
  typia.assert(user);

  // 2. Create the first post to be bookmarked
  const post1 = await api.functional.discussionboard.posts.post(connection, {
    body: {
      thread_id: typia.random<string & tags.Format<"uuid">>(),
      content: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(post1);

  // 3. Create a bookmark on post1 for the new user
  const bookmark = await api.functional.discussionboard.bookmark.post(connection, {
    body: {
      user_id: user.id,
      post_id: post1.id,
    },
  });
  typia.assert(bookmark);

  // 4. Create a second post to move the bookmark to
  const post2 = await api.functional.discussionboard.posts.post(connection, {
    body: {
      thread_id: typia.random<string & tags.Format<"uuid">>(),
      content: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(post2);

  // 5. Update the bookmark with the new post_id
  const updateBody = { post_id: post2.id } satisfies IDiscussionboardBookmark.IUpdate;
  const updatedBookmark = await api.functional.discussionboard.bookmark.putById(connection, {
    id: bookmark.id,
    body: updateBody,
  });
  typia.assert(updatedBookmark);
  // 6. Validate bookmark now points to post2, with id/user_id unchanged
  TestValidator.equals("updated post_id")(updatedBookmark.post_id)(post2.id);
  TestValidator.equals("bookmark id")(updatedBookmark.id)(bookmark.id);
  TestValidator.equals("user id unchanged")(updatedBookmark.user_id)(user.id);
}

