import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { IDiscussionboardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThread";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IPageIDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 게시글 목록 API의 페이지네이션, 필터, boundary, count, 일관성 검증
 *
 * - 다양한 조건(thread_id, created_by_user_id, is_deleted, page/limit) 조합으로 GET 요청
 * - 각 요청에서 반환된 데이터가 요구조건을 항상 만족하는지(게시글/필터/개수/페이지) 상세히 점검
 *
 * [비즈니스 시나리오 Step-by-Step]
 * 1. 신규 유저 2명 생성
 * 2. 신규 쓰레드 2개 생성
 * 3. 각 유저-쓰레드 조합별 N개 게시글 생성 (총 20개)
 * 4. 여러 조합의 필터와 pagination으로 목록 페치 및 검증
 *   (1) threadA 전체, limit 5, page 1/2
 *   (2) threadB 전체, limit 3, page 1/2/3
 *   (3) threadA+userA, limit 10, page 1
 *   (4) threadA+userB, limit 1, page 1~3
 *   (5) threadB+userB, limit 10, page 1, is_deleted false
 *   (6) threadA, limit 50, is_deleted false, page 1
 * 5. 각 리스트 응답의 post/메타 정보가 조건에 정확히 부합하는지 TestValidator로 개별 검사
 */
export async function test_api_discussionboard_test_list_posts_with_basic_pagination_and_filters(
  connection: api.IConnection,
) {
  // 1. 테스트용 유저 계정 2개 생성
  const userA = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
      displayName: RandomGenerator.name(),
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(userA);

  const userB = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
      displayName: RandomGenerator.name(),
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(userB);

  // 2. 테스트용 쓰레드 2개 생성
  const threadA = await api.functional.discussionboard.threads.post(connection, {
    body: {
      board_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(),
      slug: RandomGenerator.alphaNumeric(12),
    } satisfies IDiscussionboardThread.ICreate,
  });
  typia.assert(threadA);

  const threadB = await api.functional.discussionboard.threads.post(connection, {
    body: {
      board_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(),
      slug: RandomGenerator.alphaNumeric(12),
    } satisfies IDiscussionboardThread.ICreate,
  });
  typia.assert(threadB);

  // 3. 각 유저-쓰레드 조합으로 게시글 시드 데이터 대량 생성
  // userA/threadA: 7, userA/threadB: 2, userB/threadA: 3, userB/threadB: 8
  const userPosts: Record<"userA"|"userB", Record<"threadA"|"threadB", string[]>> = {
    userA: { threadA: [], threadB: [] },
    userB: { threadA: [], threadB: [] },
  };
  for (let i = 0; i < 7; ++i) {
    const post = await api.functional.discussionboard.posts.post(connection, {
      body: {
        thread_id: threadA.id,
        content: RandomGenerator.content()()(),
      } satisfies IDiscussionboardPost.ICreate,
    });
    typia.assert(post);
    userPosts.userA.threadA.push(post.id);
  }
  for (let i = 0; i < 2; ++i) {
    const post = await api.functional.discussionboard.posts.post(connection, {
      body: {
        thread_id: threadB.id,
        content: RandomGenerator.content()()(),
      } satisfies IDiscussionboardPost.ICreate,
    });
    typia.assert(post);
    userPosts.userA.threadB.push(post.id);
  }
  for (let i = 0; i < 3; ++i) {
    const post = await api.functional.discussionboard.posts.post(connection, {
      body: {
        thread_id: threadA.id,
        content: RandomGenerator.content()()(),
      } satisfies IDiscussionboardPost.ICreate,
    });
    typia.assert(post);
    userPosts.userB.threadA.push(post.id);
  }
  for (let i = 0; i < 8; ++i) {
    const post = await api.functional.discussionboard.posts.post(connection, {
      body: {
        thread_id: threadB.id,
        content: RandomGenerator.content()()(),
      } satisfies IDiscussionboardPost.ICreate,
    });
    typia.assert(post);
    userPosts.userB.threadB.push(post.id);
  }

  // 4. 다양한 필터와 pagination 조합으로 GET 요청 및 응답 검증
  // (1) threadA 전체, limit 5, page 1/2
  for (const page of [1, 2]) {
    const result = await api.functional.discussionboard.posts.patch(connection, {
      body: {
        thread_id: threadA.id,
        page,
        limit: 5,
      } satisfies IDiscussionboardPost.IRequest,
    });
    typia.assert(result);
    TestValidator.equals("pagination.current")(result.pagination.current)(page);
    TestValidator.equals("pagination.limit")(result.pagination.limit)(5);
    for (const post of result.data)
      TestValidator.equals("thread_id matches")(post.thread_id)(threadA.id);
  }
  // (2) threadB 전체, limit 3, page 1/2/3
  for (const page of [1, 2, 3]) {
    const result = await api.functional.discussionboard.posts.patch(connection, {
      body: {
        thread_id: threadB.id,
        page,
        limit: 3,
      } satisfies IDiscussionboardPost.IRequest,
    });
    typia.assert(result);
    TestValidator.equals("pagination.current")(result.pagination.current)(page);
    TestValidator.equals("pagination.limit")(result.pagination.limit)(3);
    for (const post of result.data)
      TestValidator.equals("thread_id matches")(post.thread_id)(threadB.id);
  }
  // (3) threadA/created_by_user_id==userA, limit 10, page 1
  {
    const result = await api.functional.discussionboard.posts.patch(connection, {
      body: {
        thread_id: threadA.id,
        created_by_user_id: userA.id,
        limit: 10,
        page: 1,
      } satisfies IDiscussionboardPost.IRequest,
    });
    typia.assert(result);
    TestValidator.equals("pagination.limit")(result.pagination.limit)(10);
    for (const post of result.data) {
      TestValidator.equals("thread_id matches")(post.thread_id)(threadA.id);
      TestValidator.equals("author is userA")(post.created_by_user_id)(userA.id);
    }
  }
  // (4) threadA/created_by_user_id==userB, limit 1, page 1~3
  for (const page of [1, 2, 3]) {
    const result = await api.functional.discussionboard.posts.patch(connection, {
      body: {
        thread_id: threadA.id,
        created_by_user_id: userB.id,
        limit: 1,
        page,
      } satisfies IDiscussionboardPost.IRequest,
    });
    typia.assert(result);
    TestValidator.equals("pagination.limit")(result.pagination.limit)(1);
    for (const post of result.data) {
      TestValidator.equals("thread_id matches")(post.thread_id)(threadA.id);
      TestValidator.equals("author is userB")(post.created_by_user_id)(userB.id);
    }
  }
  // (5) threadB/created_by_user_id==userB, limit 10(page1), is_deleted false
  {
    const result = await api.functional.discussionboard.posts.patch(connection, {
      body: {
        thread_id: threadB.id,
        created_by_user_id: userB.id,
        limit: 10,
        page: 1,
        is_deleted: false,
      } satisfies IDiscussionboardPost.IRequest,
    });
    typia.assert(result);
    for (const post of result.data) {
      TestValidator.equals("thread_id matches")(post.thread_id)(threadB.id);
      TestValidator.equals("author is userB")(post.created_by_user_id)(userB.id);
      TestValidator.equals("not deleted")(post.is_deleted)(false);
    }
  }
  // (6) threadA 전체, limit 50, is_deleted false, page 1
  {
    const result = await api.functional.discussionboard.posts.patch(connection, {
      body: {
        thread_id: threadA.id,
        limit: 50,
        is_deleted: false,
        page: 1,
      } satisfies IDiscussionboardPost.IRequest,
    });
    typia.assert(result);
    for (const post of result.data) {
      TestValidator.equals("thread_id matches")(post.thread_id)(threadA.id);
      TestValidator.equals("not deleted")(post.is_deleted)(false);
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
