/**
 * Ensure invalid filtering in /discussionboard/posts PATCH returns 400 Bad Request.
 *
 * This test simulates a range of invalid request payloads to the post list/filter endpoint:
 *  - Providing a value with wrong type or format (e.g., thread_id is not a uuid string)
 *  - Using unsupported values in enum-limited fields like order_by
 *  - Out-of-range pagination (e.g., limit too low)
 *
 * For each case, the test asserts that the API throws an error (typically 400 Bad Request) and does not succeed.
 *
 * Steps:
 * 1. Invalid format for thread_id (not a uuid)
 * 2. Invalid enum value in order_by
 * 3. Invalid pagination limit (out of allowed range)
 */
export async function test_api_discussionboard_test_list_posts_with_invalid_filter_returns_error(
  connection: api.IConnection,
) {
  // 1. Invalid format for thread_id (not a uuid string)
  await TestValidator.error("invalid uuid format for thread_id should fail")(
    async () =>
      await api.functional.discussionboard.posts.patch(connection, {
        body: {
          thread_id: "not-a-uuid" as string & tags.Format<"uuid">,
        },
      }),
  );

  // 2. Invalid enum value for order_by
  await TestValidator.error("invalid enum value in order_by should fail")(
    async () =>
      await api.functional.discussionboard.posts.patch(connection, {
        body: {
          thread_id: typia.random<string & tags.Format<"uuid">>(),
          order_by: "not_valid_order" as "created_at" | "updated_at" | null,
        },
      }),
  );

  // 3. Invalid pagination limit (less than allowed minimum)
  await TestValidator.error("limit value under minimum should fail")(
    async () =>
      await api.functional.discussionboard.posts.patch(connection, {
        body: {
          thread_id: typia.random<string & tags.Format<"uuid">>(),
          limit: 0 as number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<100>,
        },
      }),
  );
}

