/**
 * 기존 discussionboard_post 엔터티의 상세 정보를 GET /discussionboard/posts/{id}로 조회할 때
 * 모든 필드가 생성 당시 값과 동일하게 정확하게 반환되는지 검증한다.
 *
 * 비즈니스 목적:
 * - 이 API는 게시글 개별 상세 화면, 권한 제어, 데이터 무결성 확보에 꼭 필요하다.
 * - 실제 E2E 플로우에서 생성 → 조회 전체를 거치며, 모든 필드(작성자/스레드/본문/삭제여부/타임스탬프 등)가
 *   손실/변형 없이 적절히 반환되는지 (API response mapping 오류 등 포함) 확인할 필요가 있다.
 *
 * 시나리오 요약:
 * 1. 게시글의 작성자로 discussionboard_user를 생성한다.
 * 2. 게시글이 연결될 discussionboard_thread를 생성한다.
 * 3. 위 user, thread에 연결된 discussionboard_post 엔터티를 생성한다.
 * 4. 생성된 게시글의 id로 GET /discussionboard/posts/{id} API를 호출한다.
 * 5. 상세조회 응답의 각 필드 값이 post 생성 결과와 완전히 일치하는지 검증한다.
 */
export async function test_api_discussionboard_test_get_post_details_successful(
  connection: api.IConnection,
) {
  // 1. 게시글 작성자(disucssionboard_user) 생성
  const userEmail = typia.random<string & tags.Format<'email'>>();
  const userPassword = typia.random<string & tags.Format<'password'>>();
  const user: IDiscussionboardUser = await api.functional.discussionboard.users.post(
    connection,
    {
      body: {
        email: userEmail,
        password: userPassword,
        displayName: RandomGenerator.name(),
        avatarUrl: RandomGenerator.pick([
          undefined,
          "https://picsum.photos/200"
        ]),
        isActive: true,
      } satisfies IDiscussionboardUser.ICreate,
    },
  );
  typia.assert(user);

  // 2. 게시글이 속할 discussionboard_thread 생성
  const thread: IDiscussionboardThread = await api.functional.discussionboard.threads.post(
    connection,
    {
      body: {
        board_id: typia.random<string & tags.Format<'uuid'>>(),
        topic_id: null,
        title: RandomGenerator.paragraph()(1),
        slug: RandomGenerator.alphaNumeric(10),
        is_pinned: false,
        is_locked: false,
      } satisfies IDiscussionboardThread.ICreate,
    },
  );
  typia.assert(thread);

  // 3. 게시글 생성 (방금 만든 thread 연결, 내용 랜덤)
  const post: IDiscussionboardPost = await api.functional.discussionboard.posts.post(
    connection,
    {
      body: {
        thread_id: thread.id,
        content: RandomGenerator.content()()(),
      } satisfies IDiscussionboardPost.ICreate,
    },
  );
  typia.assert(post);

  // 4. 상세 정보 GET
  const detail: IDiscussionboardPost = await api.functional.discussionboard.posts.getById(
    connection,
    { id: post.id },
  );
  typia.assert(detail);

  // 5. 필드별 완전 일치 검증
  TestValidator.equals("id 일치")(detail.id)(post.id);
  TestValidator.equals("thread_id 일치")(detail.thread_id)(post.thread_id);
  TestValidator.equals("created_by_user_id 일치")(detail.created_by_user_id)(post.created_by_user_id);
  TestValidator.equals("content 일치")(detail.content)(post.content);
  TestValidator.equals("is_edited 일치")(detail.is_edited)(post.is_edited);
  TestValidator.equals("is_deleted 일치")(detail.is_deleted)(post.is_deleted);
  TestValidator.equals("created_at 일치")(detail.created_at)(post.created_at);
  TestValidator.equals("updated_at 일치")(detail.updated_at)(post.updated_at);
  TestValidator.equals("deleted_at 일치")(detail.deleted_at ?? null)(post.deleted_at ?? null);
}

