import type { IDiscussionboardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThread";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";

/**
 * 원 게시글 작성자가 자신이 쓴 게시글의 본문을 수정할 수 있는지 검증합니다.
 *
 * - 사용자는 기존 게시글의 본문을 오타 등 정정 목적으로 수정할 수 있어야 합니다.
 * - 수정 시 반드시 is_edited 플래그가 true로 설정되며, updated_at 타임스탬프도 변경되어야 합니다.
 * - 게시글 최초 생성자는 본인임을 검증하고, 수정 후 content/플래그/타임스탬프 상태를 모두 체크합니다.
 *
 * **검증 시나리오:**
 * 1. Discussionboard user(작성자) 생성
 * 2. (테스트 목적) 랜덤 board_id로 스레드 생성
 * 3. 첫 게시글 생성 (thread에 대해 본문 작성)
 * 4. 수정 전 content 및 updated_at 기록, is_edited==false 확인
 * 5. putById로 새로운 본문, is_edited=true 로 수정 요청
 * 6. 응답의 content, is_edited, updated_at 모두 올바르게 갱신됐는지 체크
 *
 * ※ 주의: board_id 등은 실제 존재하는 보드 UUID가 아님에 유의(통합 E2E에는 board 생성 필요)
 */
export async function test_api_discussionboard_test_update_post_content_by_author(
  connection: api.IConnection,
) {
  // 1. 작성자(user) 생성
  const email = typia.random<string & tags.Format<"email">>();
  const password = typia.random<string & tags.Format<"password">>();
  const displayName = RandomGenerator.name();
  const user = await api.functional.discussionboard.users.post(connection, {
    body: {
      email,
      password,
      displayName,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(user);

  // 2. (테스트용 랜덤 board id)로 thread 생성
  const boardId = typia.random<string & tags.Format<"uuid">>();
  const thread = await api.functional.discussionboard.threads.post(connection, {
    body: {
      board_id: boardId,
      title: RandomGenerator.paragraph()(),
      slug: RandomGenerator.alphaNumeric(12),
    } satisfies IDiscussionboardThread.ICreate,
  });
  typia.assert(thread);

  // 3. 게시글(post) 생성
  const originalContent = RandomGenerator.paragraph()();
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: {
      thread_id: thread.id,
      content: originalContent,
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // 4. 수정 전 상태 기록
  const prevUpdatedAt = post.updated_at;
  TestValidator.equals("수정 전 플래그 false")(post.is_edited)(false);

  // 5. 게시글 본문을 수정 (is_edited: true)
  const updatedContent = RandomGenerator.paragraph()();
  const updatedPost = await api.functional.discussionboard.posts.putById(connection, {
    id: post.id,
    body: {
      content: updatedContent,
      is_edited: true,
    } satisfies IDiscussionboardPost.IUpdate,
  });
  typia.assert(updatedPost);

  // 6. 상태 변화 체크: 내용/플래그/타임스탬프
  TestValidator.notEquals("본문 변경 확인")(updatedPost.content)(originalContent);
  TestValidator.equals("수정 플래그 true")(updatedPost.is_edited)(true);
  TestValidator.notEquals("updated_at 시간 반영")(updatedPost.updated_at)(prevUpdatedAt);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { IDiscussionboardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThread";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";

/**
 * Validate that permission model is correctly enforced for post updates.
 *
 * This test ensures that:
 * - Only the author can update their own post; attempts by other users are forbidden.
 * - Posts that are soft-deleted (is_deleted=true) or marked deleted (deleted_at set) cannot be updated (even by the author).
 * - The API consistently rejects unauthorized edit attempts with an error.
 *
 * Test Steps:
 * 1. Create two users: an author and a secondary (malicious) user.
 * 2. Create a thread for the post to belong to.
 * 3. Create a post authored by the first user.
 * 4. Attempt to update the post as the non-author (malicious user) — should fail.
 * 5. Mark the post as deleted as the author.
 * 6. Attempt to update the deleted post as the author — should fail.
 *
 * These steps validate that permission enforcement and forbidden states work as expected.
 */
export async function test_api_discussionboard_test_update_post_by_non_author_or_forbidden_state(
  connection: api.IConnection,
) {
  // 1. Create the author user
  const authorUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "A-secure_pw1#",
      displayName: RandomGenerator.name(),
      isActive: true,
    },
  });
  typia.assert(authorUser);

  // 2. Create the secondary (malicious) user
  const maliciousUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "B-secure_pw2#",
      displayName: RandomGenerator.name(),
      isActive: true,
    },
  });
  typia.assert(maliciousUser);

  // 3. Create a thread associated with a board
  const thread = await api.functional.discussionboard.threads.post(connection, {
    body: {
      board_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(8),
      slug: RandomGenerator.alphabets(16),
    },
  });
  typia.assert(thread);

  // 4. Create a post on the thread (by the author)
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: {
      thread_id: thread.id,
      content: RandomGenerator.content()(8)(),
    },
  });
  typia.assert(post);

  // 5. Attempt to update the post as the secondary (malicious) user (should be forbidden)
  await TestValidator.error("Non-author attempting to update post should be forbidden")(async () => {
    await api.functional.discussionboard.posts.putById(connection, {
      id: post.id,
      body: {
        content: "Malicious update attempt",
        is_edited: true,
      },
    });
  });

  // 6. Soft-delete the post as the author
  const deletedPost = await api.functional.discussionboard.posts.putById(connection, {
    id: post.id,
    body: {
      is_deleted: true,
      deleted_at: new Date().toISOString(),
      content: post.content,
      is_edited: true,
    },
  });
  typia.assert(deletedPost);

  // 7. Attempt to update the post after deletion (should also be forbidden)
  await TestValidator.error("Cannot update a deleted post")(async () => {
    await api.functional.discussionboard.posts.putById(connection, {
      id: post.id,
      body: {
        content: "Edit after delete should fail",
        is_edited: true,
      },
    });
  });
}

