 * 2. Assign moderator role to the second user
 * 3. Create a thread
 * 4. Author creates a post in the thread
 * 5. Author soft-deletes the post and validate effect
 * 6. Recreate post as author; then moderator soft-deletes and validate
 */
export async function test_api_discussionboard_test_delete_post_by_author_or_moderator(
