    id: post.id,
  });
  // NOTE: No "get-by-id" endpoint to re-query soft-deleted post; effects must be trusted or verified with admin in separate flows

  // 7. Recreate another post to demo moderator deletion
  const authorSecondPost: IDiscussionboardPost = await api.functional.discussionboard.posts.post(connection, {
