  TestValidator.equals("not deleted")(authorSecondPost.is_deleted)(false);

  // 8. Moderator soft-deletes the post (simulate privilege)
  await api.functional.discussionboard.posts.eraseById(connection, {
    id: authorSecondPost.id,
  });
