 * - 다양한 닉네임, 권한/활성 여부, 가입 시점으로 유저를 최소 6명 생성
 * - 닉네임에 특정 키워드("探求")가 포함된 이달 가입 유저 2명 포함
 * - 목록조회 API에 '이달 가입', '닉네임에 키워드 포함', page=1, limit=2, 최신 가입자 우선 sort("created_at desc") 필터 전달
 * - 응답의 pagination metadata(전체 개수/페이지수/현재페이지)와 결과모두 의도한 조건부합 및 응답 type을 typia.assert로 검증
 */
export async function test_api_discussionboard_test_list_users_with_filter_pagination_sorting_successful(
  connection: api.IConnection,
) {
  // 오늘/이달 기준 날짜
  const now = new Date();
  const year = now.getFullYear();
  const month = now.getMonth(); // 0-indexed
  const thisMonthStart = new Date(year, month, 1, 0, 0, 0, 0).toISOString();
  const nextMonthStart = new Date(year, month + 1, 1, 0, 0, 0, 0).toISOString();

  // 테스트에 쓸 닉네임 키워드
  const KEYWORD = "探求";

  // 유저 데이터 샘플링: 6명(닉네임/이월/비활성/벤케이스 혼합)
  // 이달 가입, 닉네임 포함(탐구1/2), 관리자권한 가정
  const users: { input: IDiscussionboardUser.ICreate, created: IDiscussionboardUser }[] = [];

  // 2명: 이달 가입 & 닉네임에 키워드 포함
  for (let i = 0; i < 2; ++i) {
    const displayName = `${KEYWORD}_${RandomGenerator.alphaNumeric(5)}`;
    const user: IDiscussionboardUser = await api.functional.discussionboard.users.post(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: "Password!123",
        displayName,
        avatarUrl: undefined,
        isActive: true,
      } satisfies IDiscussionboardUser.ICreate,
    });
    users.push({ input: { ...user, password: "Password!123" }, created: user });
  }

  // 2명: 이달 가입, 키워드 미포함, 일반 닉네임, 비활성/벤 여부 혼합
  const inMonthVariants = [
    { isActive: false, isBanned: false },
    { isActive: true, isBanned: true },
  ];
  for (const variant of inMonthVariants) {
    const displayName = RandomGenerator.alphaNumeric(8);
    const user: IDiscussionboardUser = await api.functional.discussionboard.users.post(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: "Password!123",
        displayName,
        avatarUrl: undefined,
        isActive: variant.isActive,
      } satisfies IDiscussionboardUser.ICreate,
    });
    // 벤 여부 속성은 응답으로만 판단(생성 API엔 미포함, 이후 조회에서 필터로 활용)
    users.push({ input: { ...user, password: "Password!123" }, created: user });
  }

  // 2명: 지난달 가입자로 createdAt 조정(직접 생성 불가하므로 filter조건 확인용, 무작위 생성)
  for (let i = 0; i < 2; ++i) {
    const displayName = `Legacy_${RandomGenerator.alphaNumeric(5)}`;
    const user: IDiscussionboardUser = await api.functional.discussionboard.users.post(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: "Password!123",
        displayName,
        avatarUrl: undefined,
        isActive: true,
      } satisfies IDiscussionboardUser.ICreate,
    });
    // createdAt 조정은 불가하므로 등록일 기준으로 필터링만 검증(이달과 지난달 혼재 보장)
    users.push({ input: { ...user, password: "Password!123" }, created: user });
  }

  // 1페이지당 2명만
  const PAGE_LIMIT = 2;
  const PAGE_NUM = 1;

  // 목록 필터링: 이달 가입+닉네임에 키워드 포함, 최신가입자순 desc
  const filter: IDiscussionboardUser.IRequest = {
    displayName: KEYWORD, // 포함 검색(부분일치)
    registeredFrom: thisMonthStart,
    registeredTo: nextMonthStart,
    sort: "created_at desc",
    page: PAGE_NUM,
    limit: PAGE_LIMIT,
  };
  const result = await api.functional.discussionboard.users.patch(connection, {
    body: filter,
  });
  typia.assert(result);

  // Pagination 메타
  const pagination = result.pagination;
  TestValidator.equals("page number")(pagination.current)(PAGE_NUM);
  TestValidator.equals("page limit")(pagination.limit)(PAGE_LIMIT);
  TestValidator.predicate("전체 개수 >= 2명 이상 필터됨 카운트 적합")(pagination.records >= 2);
  TestValidator.predicate("전체 페이지 1개 이상")(pagination.pages >= 1);

  // 데이터 각각의 조건 검증: 닉네임, 기간
  for (const u of result.data) {
    typia.assert(u);
    TestValidator.predicate("닉네임에 키워드 포함")(u.displayName.includes(KEYWORD));
    // 날짜(이달 가입) 조건:
    // createdAt는 응답 요약엔 없지만, 실제 전체 fetch시 사용
  }
}

