 *
 * This test ensures that users cannot access the full profile/details of other users unless they are themselves, an admin, or a moderator.
 * It verifies business rules enforcing user privacy on the discussion board.
 *
 * **Test flow:**
 * 1. Register User A.
 * 2. Register User B.
 * 3. Attempt to fetch User A's details while authenticated as User B; expect forbidden error.
 * 4. Attempt to fetch User B's own details to show that self-access works.
 */
export async function test_api_discussionboard_test_fetch_user_details_without_permission_forbidden(
  connection: api.IConnection,
) {
  // 1. Register User A
  const userAEmail = typia.random<string & tags.Format<"email">>();
  const userA = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: userAEmail,
      password: "PasswordA123!",
      displayName: RandomGenerator.name(),
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(userA);

  // 2. Register User B
  const userBEmail = typia.random<string & tags.Format<"email">>();
  const userB = await api.functional.discussionboard.users.post(connection, {
