import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";

/**
 * Validates the update of a user record by an admin in the discussion board system.
 *
 * This test ensures that an admin can update a user's email, display name, and avatar URL by specifying the user's ID. All business rules are explicitly checked: email uniqueness and value constraints for mutable fields. The test covers end-to-end update workflow and validates the response integrity.
 *
 * Steps:
 * 1. Register a new user who will be updated (dependency).
 * 2. Prepare new random values for email (unique), display name, and avatar URL.
 * 3. Update the user with the new values using the admin operation.
 * 4. Validate the returned user record reflects all new values and retains immutable fields.
 * 5. Try to update the user with a duplicate email (should fail) for error scenario.
 */
export async function test_api_discussionboard_test_update_user_record_as_admin_successful(
  connection: api.IConnection,
) {
  // 1. Register a new user
  const baseUserEmail = typia.random<string & tags.Format<"email">>();
  const baseUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: baseUserEmail,
      password: "Secure!Passw0rd",
      displayName: RandomGenerator.name(),
      avatarUrl: undefined,
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(baseUser);

  // 2. Prepare new random values for all mutable fields (must use new unique email!)
  const newEmail = typia.random<string & tags.Format<"email">>();
  const newDisplayName = RandomGenerator.name();
  const newAvatarUrl = "https://cdn.example.com/avatar/" + typia.random<string & tags.Format<"uuid">>() + ".png";

  // 3. Update the user
  const updatedUser = await api.functional.discussionboard.users.putById(connection, {
    id: baseUser.id,
    body: {
      email: newEmail,
      displayName: newDisplayName,
      avatarUrl: newAvatarUrl,
    } satisfies IDiscussionboardUser.IUpdate,
  });
  typia.assert(updatedUser);

  // 4. Validate the returned user record
  TestValidator.equals("user id")(updatedUser.id)(baseUser.id);
  TestValidator.equals("email updated")(updatedUser.email)(newEmail);
  TestValidator.equals("display name updated")(updatedUser.displayName)(newDisplayName);
  TestValidator.equals("avatar url updated")(updatedUser.avatarUrl)(newAvatarUrl);
  TestValidator.equals("isActive unchanged")(updatedUser.isActive)(baseUser.isActive);
  TestValidator.equals("isBanned unchanged")(updatedUser.isBanned)(baseUser.isBanned);
  TestValidator.equals("createdAt unchanged")(updatedUser.createdAt)(baseUser.createdAt);
  TestValidator.notEquals("updatedAt must be later")(updatedUser.updatedAt)(baseUser.updatedAt);

  // 5. Error scenario: Try to update with duplicate email
  // Register another user to produce a duplicate email scenario
  const otherUserEmail = typia.random<string & tags.Format<"email">>();
  const otherUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: otherUserEmail,
      password: "AnotherPassw0rd!",
      displayName: RandomGenerator.name(),
      avatarUrl: undefined,
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(otherUser);

  // Try to update the baseUser to use the duplicate email of otherUser
  await TestValidator.error("updating with duplicate email should fail")(async () => {
    await api.functional.discussionboard.users.putById(connection, {
      id: baseUser.id,
      body: {
        email: otherUserEmail,
      },
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
