import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";

/**
 * Ensure that a user can successfully update their own allowed record fields and is prevented from updating sensitive fields.
 *
 * Business context:
 * Users should be able to self-update certain profile fields (display name, avatar), but should NOT be able to escalate their own permissions or ban themselves (fields like isBanned and isActive should only be mutable by moderators/admins).
 *
 * Test procedure:
 * 1. Register a new user (saving id, allowed credentials)
 * 2. Update profile fields (displayName, avatarUrl)
 *    - Check changed fields are updated, others not affected
 * 3. Attempt to update sensitive fields (isActive, isBanned) as the same user
 *    - Expect error or no effect to be applied (security enforcement)
 */
export async function test_api_discussionboard_test_update_own_user_record_successful(connection: api.IConnection) {
  // 1. Register a new user
  const userEmail = typia.random<string & tags.Format<"email">>();
  const password = "TestPassword!1234";
  const displayName = RandomGenerator.name();
  const avatarUrl = `https://example.com/avatar/${typia.random<string>()}.png`;

  const user = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: userEmail,
      password,
      displayName,
      avatarUrl,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(user);

  // 2. Update allowed fields: displayName and avatarUrl
  const newDisplayName = RandomGenerator.name();
  const newAvatarUrl = `https://example.com/avatar/${typia.random<string>()}.jpg`;
  const updatedUser = await api.functional.discussionboard.users.putById(connection, {
    id: user.id,
    body: {
      displayName: newDisplayName,
      avatarUrl: newAvatarUrl,
    } satisfies IDiscussionboardUser.IUpdate,
  });
  typia.assert(updatedUser);

  TestValidator.equals("displayName updated")(updatedUser.displayName)(newDisplayName);
  TestValidator.equals("avatarUrl updated")(updatedUser.avatarUrl)(newAvatarUrl);
  TestValidator.equals("email remains the same")(updatedUser.email)(user.email);
  TestValidator.equals("isActive remains unchanged")(updatedUser.isActive)(user.isActive);
  TestValidator.equals("isBanned remains unchanged")(updatedUser.isBanned)(user.isBanned);

  // 3. Attempt to update sensitive fields (isActive, isBanned) as self
  for (const [field, value] of [["isActive", false], ["isBanned", true]] as const) {
    await TestValidator.error(`self-update of sensitive field '${field}' should fail`)(async () => {
      await api.functional.discussionboard.users.putById(connection, {
        id: user.id,
        body: {
          [field]: value,
        } as IDiscussionboardUser.IUpdate,
      });
    });
  }
}

