/**
 * Validate that updating a user's email to one already in use by another user fails with a conflict error.
 *
 * This test verifies the backend enforces global email uniqueness on user record updates:
 *
 * 1. Register User A with a random email (emailA).
 * 2. Register User B with a different random email (emailB).
 * 3. Confirm that emailA != emailB.
 * 4. Attempt to update User B's email to emailA via PUT /discussionboard/users/{id}.
 * 5. Validate that the update fails and a conflict error (409) is thrown,
 *    confirming the system prevents duplicate user emails.
 */
export async function test_api_discussionboard_test_update_user_record_with_duplicate_email_fails(
  connection: api.IConnection,
) {
  // 1. Register User A
  const emailA: string = typia.random<string & tags.Format<"email">>();
  const userA = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: emailA,
      password: typia.random<string & tags.Format<"password">>(),
      displayName: "User A",
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(userA);

