/**
 * Test that an admin can soft-delete a user account.
 *
 * Business rules:
 * - Soft-deleting a user sets the deleted_at timestamp but does not remove actual user data, ensuring compliance/auditability.
 * - A deleted user must no longer appear in standard user queries (though retrieval API is not specified in available SDK and thus cannot be verified in this test).
 * - Attempting to delete an admin/protected account should fail with appropriate error (actual admin/protected user creation or API is not specified, so this will be commented for future extension).
 * - The operation must return the updated user object with deletedAt set, confirming audit logging behavior (no explicit log API, so only verify data in returned object).
 *
 * Test steps:
 * 1. Register a regular user.
 * 2. (Assume admin privileges on the connection.)
 * 3. Soft-delete the registered user via /discussionboard/users/{id} DELETE as admin.
 * 4. Validate the deletedAt field is set and other user details are retained.
 * 5. (Optionally: Try deleting an 'admin' user and confirm failure - cannot be implemented without admin registration API; leave as comment.)
 */
export async function test_api_discussionboard_test_soft_delete_user_as_admin_successful(
  connection: api.IConnection,
) {
  // 1. Register a regular user
  const newUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphabets(12),
      displayName: RandomGenerator.name(),
      avatarUrl: undefined,
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(newUser);
  TestValidator.predicate("precondition: user not deleted")(!newUser.deletedAt);

  // 2. (Assume: connection is an admin and can delete)

  // 3. Soft-delete the registered user
  const deletedUser = await api.functional.discussionboard.users.eraseById(connection, {
    id: newUser.id,
  });
