  TestValidator.predicate("deleted_at is set")(!!deletedUser.deletedAt);

  // 4b. Validate other user fields remain
  TestValidator.equals("retain id")(deletedUser.id)(newUser.id);
  TestValidator.equals("retain email")(deletedUser.email)(newUser.email);
  TestValidator.equals("retain displayName")(deletedUser.displayName)(newUser.displayName);

  // 5. (Optionally: Deleting an admin/protected account should be denied)
  //    This cannot be tested unless admin/protected user creation API or admin fixtures are available.
}

