import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardOrganization } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardOrganization";
import type { IPageIDiscussionboardOrganization } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardOrganization";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 조직(organization) 목록 조회 및 검색/페이징 기능 E2E 테스트
 *
 * [비즈니스 목적]
 * - 관리자 권한으로 다양한 이름/생성일 조직 다수를 생성한 후,
 *   다양한 필터·페이징·에지케이스 조합으로 /discussionboard/organizations PATCH
 *   엔드포인트의 목록/검색/메타데이터 응답이 실제 비즈니스 요건대로 동작하는지 검증
 *
 * [검증 프로세스]
 * 1. 이름/생성일자 조합이 모두 다른 조직 6개를 생성
 * 2. 이름에 대한 부분검색 필터로 조회 결과 올바른지(msg 포함)
 * 3. created_at 날짜 범위로 필터 검색시 기대 데이터만 나오는지 체크
 * 4. 페이징(page/limit) 테스트: 결과 올바른지 및 pagination 메타, 전체 레코드, page수 등 검증
 * 5. 없는 조직명 검색 시 결과 0여야 함(negative-case)
 * 6. 모든 응답에 대해 typia.assert로 응답구조 체크, 비즈니스 기준 TestValidator로 진짜 데이터 검증
 */
export async function test_api_discussionboard_test_list_organizations_with_valid_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. 고유 이름/날짜로 6개 조직 생성 (테스트 신뢰도와 페이징/검색 기능 검증 위해)
  const baseNames = ["AlphaCorp", "BetaSolutions", "GammaGroup", "DeltaForce", "EpsilonTech", "ZetaOrg"];
  const createdOrgs: IDiscussionboardOrganization[] = [];
  for (let i = 0; i < baseNames.length; ++i) {
    // 조직명은 겹치지 않게 생성, created_at은 자동으로 각기 다르게 발급
    const org = await api.functional.discussionboard.organizations.post(connection, {
      body: {
        name: `${baseNames[i]}_${RandomGenerator.alphaNumeric(6)}`,
      },
    });
    typia.assert(org);
    createdOrgs.push(org);
  }
  // created_at 오름차순 정렬 (날짜 필터/페이징 결과 연산시 사용)
  createdOrgs.sort((a, b) => a.created_at.localeCompare(b.created_at));

  // 2. 이름 부분검색: "Beta" 포함된 조직 필터, 기대값만 응답에 있는지 체크
  const partialName = "Beta";
  const nameFiltered = createdOrgs.filter(o => o.name.includes(partialName));
  const nameResult = await api.functional.discussionboard.organizations.patch(connection, {
    body: {
      page: 1,
      limit: 10,
      name: partialName,
    },
  });
  typia.assert(nameResult);
  // 필터된 조직이 모두 포함됐는지
  const resultNames = nameResult.data.map(o => o.name);
  for (const org of nameFiltered) {
    TestValidator.predicate(`이름 부분검색 포함됨: ${org.name}`)(resultNames.includes(org.name));
  }

  // 3. created_at 일자 범위 부분검색(앞 3개만 포함): 기대값/결과 개수 매칭도 체크
  const createdAtFrom = createdOrgs[0].created_at;
  const createdAtTo = createdOrgs[2].created_at;
  const dateFiltered = createdOrgs.filter(o => o.created_at >= createdAtFrom && o.created_at <= createdAtTo);
  const dateResult = await api.functional.discussionboard.organizations.patch(connection, {
    body: {
      page: 1,
      limit: 10,
      created_at_from: createdAtFrom,
      created_at_to: createdAtTo,
    },
  });
  typia.assert(dateResult);
  // 모든 결과가 일자범위에 있고, 개수도 기대 매칭
  for (const org of dateResult.data) {
    TestValidator.predicate(`일자범위 ${createdAtFrom}~${createdAtTo} 내에 존재`)(org.created_at >= createdAtFrom && org.created_at <= createdAtTo);
  }
  TestValidator.equals("일자범위 필터 개수")(dateResult.data.length)(dateFiltered.length);

  // 4. 페이징: 2개씩 쪼개어 각 페이지 응답/메타/데이터 일치 체크
  const pageSize = 2;
  const totalPages = Math.ceil(createdOrgs.length / pageSize);
  for (let page = 1; page <= totalPages; ++page) {
    const expectedSlice = createdOrgs.slice((page - 1) * pageSize, page * pageSize);
    const pageResp = await api.functional.discussionboard.organizations.patch(connection, {
      body: {
        page,
        limit: pageSize,
      },
    });
    typia.assert(pageResp);
    TestValidator.equals("현재페이지 번호")(pageResp.pagination.current)(page);
    TestValidator.equals("페이지별 최대개수")(pageResp.pagination.limit)(pageSize);
    TestValidator.equals("전체 레코드수")(pageResp.pagination.records)(createdOrgs.length);
    TestValidator.equals("총 페이지수")(pageResp.pagination.pages)(totalPages);
    // 값 검증 (이름 기준 정렬)
    const actualNames = pageResp.data.map(o => o.name).sort();
    const expectedNames = expectedSlice.map(o => o.name).sort();
    TestValidator.equals(`페이지 ${page} 데이터 이름 기준 매핑`)(actualNames)(expectedNames);
  }

  // 5. 결과가 없는 이름검색: 비존재 조직, 결과 0개여야 함
  const noResult = await api.functional.discussionboard.organizations.patch(connection, {
    body: {
      page: 1,
      limit: 10,
      name: "NonExistent",
    },
  });
  typia.assert(noResult);
  TestValidator.equals("비존재 결과 0개여야 함")(noResult.data.length)(0);
}

