 *
 * Steps:
 * 1. Attempt organization listing with a negative `page` value (should cause API to reject the request)
 * 2. Attempt organization listing with a negative `limit` value (should cause API to reject the request)
 * 3. Confirm that a valid request with legitimate parameters succeeds for comparison
 * 4. Ensure in error cases that no data is leaked, and that errors are thrown
 */
export async function test_api_discussionboard_test_list_organizations_with_invalid_filter_parameters(
