  const likePost = await api.functional.discussionboard.likes.post(connection, {
    body: {
      user_id: user.id,
      post_id: post.id
    } satisfies IDiscussionboardLike.ICreate,
  });
  typia.assert(likePost);

  // 5. User likes the comment
  const likeComment = await api.functional.discussionboard.likes.post(connection, {
    body: {
      user_id: user.id,
      comment_id: comment.id
    } satisfies IDiscussionboardLike.ICreate,
  });
  typia.assert(likeComment);

  // 6. Retrieve likes filtered by user_id (should yield both likes)
  const userLikesOutput = await api.functional.discussionboard.likes.patch(connection, {
    body: {
      user_id: user.id,
      page: 1,
      limit: 10,
    } satisfies IDiscussionboardLikes.IRequest,
  });
  typia.assert(userLikesOutput);
  TestValidator.predicate("user like count >= 2")(userLikesOutput.data.length >= 2);
  TestValidator.equals("pagination current")(userLikesOutput.pagination.current)(1);
  TestValidator.equals("pagination limit")(userLikesOutput.pagination.limit)(10);
  TestValidator.equals("pagination records")(userLikesOutput.pagination.records)(userLikesOutput.data.length);
  TestValidator.equals("all likes by user")(userLikesOutput.data.every(like => like.user_id === user.id))(true);

  // 7. Filter by post_id (should yield the post like)
  const postLikesOutput = await api.functional.discussionboard.likes.patch(connection, {
    body: {
      post_id: post.id
    } satisfies IDiscussionboardLikes.IRequest,
  });
  typia.assert(postLikesOutput);
  TestValidator.predicate("only likes for post")(postLikesOutput.data.every(like => like.post_id === post.id));

  // 8. Filter by comment_id (should yield the comment like)
  const commentLikesOutput = await api.functional.discussionboard.likes.patch(connection, {
    body: {
      comment_id: comment.id
    } satisfies IDiscussionboardLikes.IRequest,
  });
  typia.assert(commentLikesOutput);
  TestValidator.predicate("only likes for comment")(commentLikesOutput.data.every(like => like.comment_id === comment.id));

  // 9. Filter by date range (earliest to latest like)
  const earliest = likePost.created_at < likeComment.created_at ? likePost.created_at : likeComment.created_at;
  const latest = likePost.created_at > likeComment.created_at ? likePost.created_at : likeComment.created_at;
  const rangeLikes = await api.functional.discussionboard.likes.patch(connection, {
    body: {
      created_at_from: earliest,
      created_at_to: latest
    } satisfies IDiscussionboardLikes.IRequest,
  });
  typia.assert(rangeLikes);
  TestValidator.predicate("all likes in range")(rangeLikes.data.every(like => like.created_at >= earliest && like.created_at <= latest));

  // 10. Use a future date range (should yield empty results)
  const futureStart = new Date(Date.now() + 1e10).toISOString();
  const futureLikes = await api.functional.discussionboard.likes.patch(connection, {
    body: {
      created_at_from: futureStart
    } satisfies IDiscussionboardLikes.IRequest,
  });
  typia.assert(futureLikes);
  TestValidator.equals("empty for future date")(futureLikes.data.length)(0);
  TestValidator.equals("pagination records for empty")(futureLikes.pagination.records)(0);

  // 11. Pagination: limit = 1, check metadata and data count
  const pagedLikes1 = await api.functional.discussionboard.likes.patch(connection, {
    body: {
      user_id: user.id,
      page: 1,
      limit: 1,
    } satisfies IDiscussionboardLikes.IRequest,
  });
  typia.assert(pagedLikes1);
  TestValidator.equals("limit one")(pagedLikes1.data.length)(1);
  TestValidator.equals("pagination current page")(pagedLikes1.pagination.current)(1);
  TestValidator.predicate("pagination pages >= 2")(pagedLikes1.pagination.pages >= 2);

  // 12. Pagination: next page (page 2)
  const pagedLikes2 = await api.functional.discussionboard.likes.patch(connection, {
    body: {
      user_id: user.id,
      page: 2,
      limit: 1,
    } satisfies IDiscussionboardLikes.IRequest,
  });
  typia.assert(pagedLikes2);
  TestValidator.equals("limit one page 2")(pagedLikes2.data.length)(1);
  TestValidator.equals("page 2")(pagedLikes2.pagination.current)(2);
}

