/**
 * 게시판의 좋아요 이벤트(Like) 상세 조회 테스트.
 *
 * 비즈니스 컨텍스트: 특정 좋아요(Like) 이벤트의 상세 정보를 제대로 조회할 수 있는지 검증한다. 테스트에서는 유저를 신규 등록하고, 해당 유저가 게시글을 생성한 뒤, 그 게시글에 좋아요 이벤트를 기록한다. 이후, 생성된 좋아요 이벤트의 ID로 상세 조회 API를 호출함으로써, 반환된 데이터가 모든 메타데이터 및 타겟(글/댓글) 참조 정보(특히 user_id, post_id 등)를 올바르게 반영하는지 확인한다.
 *
 * 테스트 절차:
 * 1. 테스트용 유저 등록
 * 2. 게시글 생성
 * 3. 게시글에 대해 좋아요 이벤트 생성
 * 4. 생성된 좋아요 이벤트의 ID로 상세 조회 API 호출
 * 5. 좋아요 상세 레코드의 모든 메타데이터(user_id, post_id, created_at 등) 및 타겟 참조 일치 검증
 */
export async function test_api_discussionboard_test_get_like_by_id_success(
  connection: api.IConnection,
) {
  // 1. 테스트용 유저 등록
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userPassword = typia.random<string & tags.Format<"password">>();
  const user: IDiscussionboardUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: userEmail,
      password: userPassword,
      displayName: RandomGenerator.name(),
      avatarUrl: typia.random<string>(),
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(user);

  // 2. 게시글 생성 (임의 thread_id)
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const postContent = RandomGenerator.content()()();
  const post: IDiscussionboardPost = await api.functional.discussionboard.posts.post(connection, {
    body: {
      thread_id: threadId,
      content: postContent,
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // 3. 좋아요 이벤트 생성 (게시글 좋아요)
  const like: IDiscussionboardLike = await api.functional.discussionboard.likes.post(connection, {
    body: {
      user_id: user.id,
      post_id: post.id,
      comment_id: null,
    } satisfies IDiscussionboardLike.ICreate,
  });
  typia.assert(like);
  TestValidator.equals("like event target post")(like.post_id)(post.id);
  TestValidator.equals("like event actor user")(like.user_id)(user.id);
  TestValidator.equals("like event is post, not comment")(like.comment_id)(null);

  // 4. 생성된 좋아요 이벤트의 ID로 상세 조회
  const likeDetail: IDiscussionboardLikes = await api.functional.discussionboard.likes.getById(connection, {
    id: like.id,
  });
  typia.assert(likeDetail);

  // 5. 좋아요 상세 조회 정보 일치 검증
  TestValidator.equals("상세 user_id")(likeDetail.user_id)(user.id);
  TestValidator.equals("상세 post_id")(likeDetail.post_id)(post.id);
  TestValidator.equals("상세 comment_id null")(likeDetail.comment_id)(null);
  TestValidator.equals("상세 like id")(likeDetail.id)(like.id);
  TestValidator.equals("like created_at 일치")(likeDetail.created_at)(like.created_at);
}

