 * The system should respond with a 409 conflict error if a duplicate like is attempted.
 *
 * Steps:
 * 1. Register a new user who will perform the like operation.
 * 2. Create a new post to be liked by the user (within a thread).
 * 3. Create a like for the (user, post) pair—should succeed.
 * 4. Attempt to create the same like again for the same (user, post) pair—should fail with a 409 conflict error indicating duplicate like is not allowed.
 *
 * Assertions:
 * - The first like creation succeeds and returns a valid like entity.
 * - The second like creation attempt results in an error (expected: conflict).
 */
export async function test_api_discussionboard_test_create_like_duplicate_returns_conflict(
  connection: api.IConnection,
) {
  // 1. Register a new user
  const userInput: IDiscussionboardUser.ICreate = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    displayName: RandomGenerator.name(),
    // avatarUrl optional
    isActive: true,
  };
  const user = await api.functional.discussionboard.users.post(connection, {
    body: userInput,
  });
  typia.assert(user);

  // 2. Create a new post in a dummy thread
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const postInput: IDiscussionboardPost.ICreate = {
    thread_id: threadId,
    content: RandomGenerator.paragraph()(),
  };
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: postInput,
  });
  typia.assert(post);

  // 3. Create the first like (should succeed)
  const likeInput: IDiscussionboardLike.ICreate = {
    user_id: user.id,
    post_id: post.id,
    comment_id: null,
  };
  const like = await api.functional.discussionboard.likes.post(connection, {
    body: likeInput,
  });
  typia.assert(like);

  // 4. Attempt to create duplicate like (should fail with 409 conflict)
  await TestValidator.error("duplicate like returns 409")(
    async () => {
      await api.functional.discussionboard.likes.post(connection, {
        body: likeInput,
      });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { IDiscussionboardLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardLike";

/**
 * Validate rejection of invalid like target creation requests.
 *
 * This test verifies input validation, business logic, and error handling for the like creation endpoint (/discussionboard/likes), particularly for the following cases:
 *
 * 1. The payload omits both post_id and comment_id (no target provided)
 * 2. The payload sets both post_id and comment_id (mutual exclusivity violated)
 * 3. The payload sets an invalid/unregistered post_id
 * 4. The payload sets an invalid/unregistered comment_id
 *
 * The API must return 400 Bad Request for #1 and #2, and 404 Not Found for #3 and #4.
 *
 * Prerequisite:
 * - Register a valid user, then use their ID for each invalid like creation attempt.
 *
 * Steps:
 * 1. Register a discussionboard_user using valid random credentials.
 * 2. Attempt to create a like with no post_id and no comment_id (should fail with 400).
 * 3. Attempt to create a like with both post_id and comment_id set (should fail with 400).
 * 4. Attempt to create a like with a non-existent (random) post_id (should fail with 404).
 * 5. Attempt to create a like with a non-existent (random) comment_id (should fail with 404).
 */
export async function test_api_discussionboard_test_create_like_invalid_target_rejected(
  connection: api.IConnection,
) {
  // 1. Register a valid user
  const user = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
      displayName: RandomGenerator.name(),
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(user);

  // 2. Attempt to like with both post_id and comment_id omitted (should fail 400)
  await TestValidator.error("like with neither post_id nor comment_id should be rejected")(async () => {
    await api.functional.discussionboard.likes.post(connection, {
      body: {
        user_id: user.id,
      } satisfies IDiscussionboardLike.ICreate,
    });
  });

  // 3. Attempt to like with both post_id and comment_id present (should fail 400)
  await TestValidator.error("like with both post_id and comment_id should be rejected")(async () => {
    await api.functional.discussionboard.likes.post(connection, {
      body: {
        user_id: user.id,
        post_id: typia.random<string & tags.Format<"uuid">>(),
        comment_id: typia.random<string & tags.Format<"uuid">>(),
      } satisfies IDiscussionboardLike.ICreate,
    });
  });

  // 4. Attempt to like with an invalid (random, non-existent) post_id (should fail 404)
  await TestValidator.error("like with nonexistent post_id should return 404")(async () => {
    await api.functional.discussionboard.likes.post(connection, {
      body: {
        user_id: user.id,
