/**
 * Test updating a like record to change its target from a post to a comment, enforcing mutual exclusivity and uniqueness constraints.
 *
 * This test verifies business rules that a like must only reference a single target (either a post or a comment, never both or neither), demonstrates migration of a like from a post to a comment, and ensures that the (user, target) pair remains unique.
 *
 * Step-by-step process:
 * 1. Create a user who will own the like.
 * 2. Create a post (as the initial target for the like).
 * 3. Create a comment (the new target to update the like to).
 * 4. Create a like for the user pointing to the post (post_id set, comment_id null).
 * 5. Update the like by ID, changing the target to the comment (set comment_id, clear post_id).
 * 6. Verify in the response that:
 *      - The like's comment_id is updated and matches the created comment ID.
 *      - The like's post_id is null (ensuring mutual exclusivity).
 *      - No duplicate likes exist for the same user and target.
 */
export async function test_api_discussionboard_test_update_like_target_success(
  connection: api.IConnection,
) {
  // 1. Create user
  const user = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "StrongPassword#123",
      displayName: RandomGenerator.name(),
      avatarUrl: typia.random<string & tags.Format<"uri">>(),
    },
  });
  typia.assert(user);

  // 2. Create post with a random thread_id
  const thread_id = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: {
      thread_id,
      content: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(post);

  // 3. Create comment on the post by the user
  const comment = await api.functional.discussionboard.comments.post(connection, {
    body: {
      post_id: post.id,
      created_by_user_id: user.id,
      content: RandomGenerator.content()()(),
    },
  });
  typia.assert(comment);

  // 4. Create like for the user, on the post (not the comment yet)
  const like = await api.functional.discussionboard.likes.post(connection, {
    body: {
      user_id: user.id,
      post_id: post.id,
      comment_id: null,
    },
  });
  typia.assert(like);

  TestValidator.equals("like post_id matches")(like.post_id)(post.id);
  TestValidator.equals("like comment_id should be null")(like.comment_id)(null);

  // 5. Update the like to point to the comment, clearing post reference
  const updated = await api.functional.discussionboard.likes.putById(connection, {
    id: like.id,
    body: {
      post_id: null,
      comment_id: comment.id,
    },
  });
  typia.assert(updated);

  TestValidator.equals("like id unchanged")(updated.id)(like.id);
  TestValidator.equals("like post_id cleared")(updated.post_id)(null);
  TestValidator.equals("like comment_id updated")(updated.comment_id)(comment.id);
}

