/**
 * Validate that updating a like to point to a target (post or comment) that the user has already liked elsewhere results in a conflict error instead of allowing a duplicate like event (unique constraint violation).
 *
 * This scenario requires first setting up:
 *   1. A user (U) who will perform the operations
 *   2. At least two different posts (P1, P2) that can be liked
 *   3. User U likes both P1 and P2 by creating two separate like records (L1, L2), each pointing to a different post
 *   4. Attempt to update like L1 such that it now points to P2 (which would mean user U now has two likes for P2)
 *   5. The update must fail with a conflict error, and the server must not allow the duplicate like (for same [user_id, post_id] pair)
 *   6. Validate that the error is properly thrown, and no extraneous data is leaked or mutated
 */
export async function test_api_discussionboard_test_update_like_target_to_duplicate_returns_conflict(
  connection: api.IConnection,
) {
  // 1. Create user
  const user = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "Password!123",
      displayName: RandomGenerator.name(),
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(user);

  // 2. Create two posts (distinct threads)
  const threadId1 = typia.random<string & tags.Format<"uuid">>();
  const threadId2 = typia.random<string & tags.Format<"uuid">>();
  const post1 = await api.functional.discussionboard.posts.post(connection, {
    body: {
      thread_id: threadId1,
      content: RandomGenerator.paragraph()(),
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post1);
  const post2 = await api.functional.discussionboard.posts.post(connection, {
    body: {
      thread_id: threadId2,
      content: RandomGenerator.paragraph()(),
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post2);

  // 3. Create two likes for user: L1 likes P1, L2 likes P2
  const like1 = await api.functional.discussionboard.likes.post(connection, {
    body: {
      user_id: user.id,
      post_id: post1.id,
    } satisfies IDiscussionboardLike.ICreate,
  });
  typia.assert(like1);
  const like2 = await api.functional.discussionboard.likes.post(connection, {
    body: {
      user_id: user.id,
      post_id: post2.id,
    } satisfies IDiscussionboardLike.ICreate,
  });
  typia.assert(like2);

  // 4. Attempt to update like1 so its target is changed to post2
  // This should trigger conflict: user now would have two likes for the same post (invalid)
  await TestValidator.error("duplicate like update should result in conflict")(
    async () => {
      await api.functional.discussionboard.likes.putById(connection, {
        id: like1.id,
        body: {
          post_id: post2.id,
          comment_id: null,
        } satisfies IDiscussionboardLike.IUpdate,
      });
    },
  );
}

