import api from "@ORGANIZATION/PROJECT-api";
import type { ISystemEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/ISystemEvent";
import type { IPageSystemEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageSystemEvent";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate listing and pagination of system event logs with filters.
 *
 * This test creates multiple system events with varying types and statuses, then queries
 * a paginated, filtered list using event_type and event_status. Verifies that response
 * data and pagination meta are correct, as needed for admin analytics/audit tools.
 *
 * Steps:
 * 1. Create several system event entries (using different event_type and event_status)
 * 2. Choose filter criteria that match at least some created events.
 * 3. Fetch a paginated filtered list (limit=2) using PATCH with filters.
 * 4. Assert results:
 *    - Returned events match filters
 *    - Pagination meta is correct (limit, current)
 *    - All expected events appear (by ID)
 */
export async function test_api_discussionboard_test_list_system_events_with_valid_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create several system event log entries with different types/statuses
  const events: ISystemEvent[] = [];
  const eventTypes = ["backup", "error", "prune", "import"];
  const eventStatuses = ["success", "error", "pending"];
  for (let i = 0; i < 6; ++i) {
    const type = eventTypes[i % eventTypes.length];
    const status = eventStatuses[i % eventStatuses.length];
    const event = await api.functional.discussionboard.systemEvents.post(connection, {
      body: {
        event_type: type,
        event_status: status,
        details: `e2e-event-${i}`,
      } satisfies ISystemEvent.ICreate,
    });
    typia.assert(event);
    events.push(event);
  }

  // 2. Filter by a type/status that should match at least 2 events
  const filterType = "backup";
  const filterStatus = "success";
  const filtered = events.filter(e => e.event_type === filterType && e.event_status === filterStatus);

  // 3. Query paginated system event log list (limit=2, first page)
  const pageRes = await api.functional.discussionboard.systemEvents.patch(connection, {
    body: {
      event_type: filterType,
      event_status: filterStatus,
      limit: 2,
      page: 1,
      sort_by: "created_at",
      sort_order: "desc",
      date_from: null,
      date_to: null,
    } satisfies ISystemEvent.IRequest,
  });
  typia.assert(pageRes);

  // 4. Validate filtered results & pagination
  const { data, pagination } = pageRes;
  TestValidator.predicate("all events match filter")(data.every(e => e.event_type === filterType && e.event_status === filterStatus));
  TestValidator.equals("pagination.limit")(pagination.limit)(2);
  TestValidator.equals("pagination.current")(pagination.current)(1);
  TestValidator.predicate("records count >= expected")(pagination.records >= filtered.length);
  // Each created event that matches should be in returned page at least if <= 2 events
  const returnedIds = data.map(e => e.id);
  for (const id of filtered.map(e => e.id))
    TestValidator.predicate("expected event present")(returnedIds.includes(id));
}

