import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { IDiscussionboardFollow } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardFollow";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionboardFollow } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardFollow";

/**
 * Validate listing follows for authenticated users with pagination and filtering.
 *
 * Ensures:
 *  - Each user only sees their own follow relationships (users and threads)
 *  - Filtering by followed_user_id, followed_thread_id, and creation date works correctly
 *  - Pagination metadata reflects actual query results
 *
 * Steps:
 * 1. Register two users: primary/secondary
 * 2. Primary: follows two users & two threads (simulate thread IDs)
 * 3. Secondary: creates a follow for ownership data isolation
 * 4. List with default params—verify only primary's records returned
 * 5. Filter by followed_user_id/ followed_thread_id / created_at_range
 * 6. Validate pagination metadata
 */
export async function test_api_discussionboard_test_list_follows_for_authenticated_user_with_valid_pagination_and_filter(connection: api.IConnection) {
  // 1. Register two users: primary and secondary
  const primaryEmail = typia.random<string & tags.Format<"email">>();
  const primaryPassword = typia.random<string & tags.Format<"password">>();
  const secondaryEmail = typia.random<string & tags.Format<"email">>();
  const secondaryPassword = typia.random<string & tags.Format<"password">>();

  const primaryUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: primaryEmail,
      password: primaryPassword,
      displayName: RandomGenerator.name(),
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(primaryUser);

  const secondaryUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: secondaryEmail,
      password: secondaryPassword,
      displayName: RandomGenerator.name(),
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(secondaryUser);

  // 2. Primary follows: two other users, two threads (simulate thread UUIDs)
  // We'll follow secondary user and a third generated user
  const thirdUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
      displayName: RandomGenerator.name(),
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(thirdUser);

  // Thread IDs are simulated UUIDs
  const threadId1: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const threadId2: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();

  // Follows for primary user
  const primaryFollows: IDiscussionboardFollow[] = [];
  // Follow: secondary user
  primaryFollows.push(
    await api.functional.discussionboard.follows.post(connection, {
      body: {
        follower_user_id: primaryUser.id,
        followed_user_id: secondaryUser.id,
        followed_thread_id: null,
      },
    })
  );
  // Follow: third user
  primaryFollows.push(
    await api.functional.discussionboard.follows.post(connection, {
      body: {
        follower_user_id: primaryUser.id,
        followed_user_id: thirdUser.id,
        followed_thread_id: null,
      },
    })
  );
  // Follow: threadId1
  primaryFollows.push(
    await api.functional.discussionboard.follows.post(connection, {
      body: {
        follower_user_id: primaryUser.id,
        followed_user_id: null,
        followed_thread_id: threadId1,
      },
    })
  );
  // Follow: threadId2
  primaryFollows.push(
    await api.functional.discussionboard.follows.post(connection, {
      body: {
        follower_user_id: primaryUser.id,
        followed_user_id: null,
        followed_thread_id: threadId2,
      },
    })
  );

  // 3. Secondary user creates a follow (to check isolation)
  // e.g., follows primary user
  const secondaryFollow = await api.functional.discussionboard.follows.post(connection, {
    body: {
      follower_user_id: secondaryUser.id,
      followed_user_id: primaryUser.id,
      followed_thread_id: null,
    },
  });

  // 4. List with default params (no filters): should see ONLY primary's records
  const resultAll = await api.functional.discussionboard.follows.patch(connection, {
    body: {
      follower_user_id: primaryUser.id,
      pagination: { page: 1, limit: 10 },
    },
  });
  typia.assert(resultAll);
  // Only primary's follows must be present
  TestValidator.equals("all returned follows belong to primary user")(resultAll.data.every((f) => f.follower_user_id === primaryUser.id))(true);
  // All 4 primary follows must be present
  TestValidator.equals("primary follow count")(resultAll.data.length)(4);
  // Pagination matches
  TestValidator.equals("pagination: total records")(resultAll.pagination.records)(4);
  TestValidator.equals("pagination: current page")(resultAll.pagination.current)(1);
  TestValidator.equals("pagination: limit")(resultAll.pagination.limit)(10);

  // 5. Filter by followed_user_id: Get only follows to secondaryUser
  const filteredByFollowedUser = await api.functional.discussionboard.follows.patch(connection, {
    body: {
      follower_user_id: primaryUser.id,
      followed_user_id: secondaryUser.id,
      pagination: { page: 1, limit: 10 },
    },
  });
  typia.assert(filteredByFollowedUser);
  // Only one such record
  TestValidator.equals("follows to secondary user")(filteredByFollowedUser.data.length)(1);
  TestValidator.equals("followed_user_id matches")(filteredByFollowedUser.data[0].followed_user_id)(secondaryUser.id);
  TestValidator.equals("follower matches")(filteredByFollowedUser.data[0].follower_user_id)(primaryUser.id);

  // 6. Filter by followed_thread_id: Get only follows to threadId1
  const filteredByThread = await api.functional.discussionboard.follows.patch(connection, {
    body: {
      follower_user_id: primaryUser.id,
      followed_thread_id: threadId1,
      pagination: { page: 1, limit: 10 },
    },
  });
  typia.assert(filteredByThread);
  TestValidator.equals("follows to thread id1")(filteredByThread.data.length)(1);
  TestValidator.equals("followed_thread_id matches")(filteredByThread.data[0].followed_thread_id)(threadId1);
  TestValidator.equals("follower matches")(filteredByThread.data[0].follower_user_id)(primaryUser.id);

  // 7. Filter by creation date range (for primary); create a suitable range
  // Use one of the follow's created_at (e.g., the first)
  const rangeStart = primaryFollows[0].created_at;
  const rangeEnd = primaryFollows[primaryFollows.length-1].created_at;
  const filteredByDate = await api.functional.discussionboard.follows.patch(connection, {
    body: {
      follower_user_id: primaryUser.id,
      created_at_range: [rangeStart, rangeEnd],
      pagination: { page: 1, limit: 10 },
    },
  });
  typia.assert(filteredByDate);
  // All returned records should have created_at within [rangeStart, rangeEnd]
  TestValidator.predicate("created_at in range")(
    filteredByDate.data.every((f) => f.created_at >= rangeStart && f.created_at <= rangeEnd)
  );

  // 8. Pagination checks: page/limit slices data properly
  const paged = await api.functional.discussionboard.follows.patch(connection, {
    body: {
      follower_user_id: primaryUser.id,
      pagination: { page: 2, limit: 2 },
    },
  });
  typia.assert(paged);
  TestValidator.equals("pagination: current page")(paged.pagination.current)(2);
  TestValidator.equals("pagination: limit")(paged.pagination.limit)(2);
  // Must be only 2 records for page 2
  TestValidator.equals("paged follow count")(paged.data.length)(2);
  // Total records meta is still 4
  TestValidator.equals("pagination: total records")(paged.pagination.records)(4);
  TestValidator.equals("pagination: total pages")(paged.pagination.pages)(2);
}

