  TestValidator.equals("팔로워 유저 ID 일치")(follow.follower_user_id)(user.id);
  TestValidator.equals("팔로우 스레드 ID 일치")(follow.followed_thread_id)(thread.id);
  TestValidator.predicate("팔로우는 유저 팔로우가 아님")(follow.followed_user_id === null || follow.followed_user_id === undefined);
}

