import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { IDiscussionboardFollow } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardFollow";

/**
 * Test that creating a duplicate follow (same follower and target) returns a 409 Conflict error.
 *
 * This test ensures that the API enforces a uniqueness constraint on the follows table:
 *   - A user cannot follow the same user or thread more than once.
 *   - Creating a follow with (follower_user_id, followed_user_id) or (follower_user_id, followed_thread_id) that already exists must fail with a 409 error.
 *
 * Workflow:
 * 1. Register two users: follower and target.
 * 2. As follower, create the initial follow of target user.
 * 3. Attempt to create the same follow relationship again (duplicate).
 * 4. Verify that a 409 Conflict error is thrown on duplicate creation.
 * 5. (Optional) Repeat for followed_thread_id, but this test only covers user-to-user follows due to available APIs.
 */
export async function test_api_discussionboard_test_create_duplicate_follow_returns_conflict(
  connection: api.IConnection,
) {
  // 1. Register follower
  const followerEmail = typia.random<string & tags.Format<"email">>();
  const followerPassword = "TestPassword123!";
  const follower: IDiscussionboardUser =
    await api.functional.discussionboard.users.post(connection, {
      body: {
        email: followerEmail,
        password: followerPassword,
        displayName: RandomGenerator.name(),
      } satisfies IDiscussionboardUser.ICreate,
    });
  typia.assert(follower);

  // 2. Register target user
  const targetEmail = typia.random<string & tags.Format<"email">>();
  const targetPassword = "TestPassword123!";
  const target: IDiscussionboardUser =
    await api.functional.discussionboard.users.post(connection, {
      body: {
        email: targetEmail,
        password: targetPassword,
        displayName: RandomGenerator.name(),
      } satisfies IDiscussionboardUser.ICreate,
    });
  typia.assert(target);

  // 3. Follower creates the follow (user-to-user)
  const follow = await api.functional.discussionboard.follows.post(connection, {
    body: {
      follower_user_id: follower.id,
      followed_user_id: target.id,
    } satisfies IDiscussionboardFollow.ICreate,
  });
  typia.assert(follow);

  // 4. Follower attempts to follow the same user again (duplicate)
  await TestValidator.error("duplicate follow should return 409")(
    async () => {
      await api.functional.discussionboard.follows.post(connection, {
        body: {
          follower_user_id: follower.id,
          followed_user_id: target.id,
        } satisfies IDiscussionboardFollow.ICreate,
      });
    },
  );
}

