import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { IDiscussionboardFollow } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardFollow";

/**
 * Ensure a user can update their follow to another target (user A → user B) and that uniqueness is retained.
 *
 * Business context: A user should be able to update an existing follow record (e.g., switch who they are following to a different user or thread).
 * Only one target can be set and the (follower, followed_user | followed_thread) combination must remain unique.
 * This is essential for correct social/in-app feed mechanics.
 *
 * Steps:
 * 1. Register three users: owner (will be the follower), userA (initial follow target), and userB (secondary/alternative follow target).
 * 2. Owner creates a follow for userA (/follows with followed_user_id=userA).
 * 3. Owner updates that follow to instead follow userB (PUT /follows/{id}).
 * 4. Validate that the returned record now refers to userB, not userA, and doesn't create duplicates.
 * 5. Optionally, attempt to update the follow to point to both user (userB) and thread at once and expect rejection (edge case not implementable here unless thread creation is available).
 */
export async function test_api_discussionboard_follows_test_update_follow_target_successful_change(
  connection: api.IConnection,
) {
  // 1. Register owner and two other users
  const ownerEmail: string = typia.random<string & tags.Format<"email">>();
  const userAEmail: string = typia.random<string & tags.Format<"email">>();
  const userBEmail: string = typia.random<string & tags.Format<"email">>();

  const owner = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: ownerEmail,
      password: "Password123!",
      displayName: RandomGenerator.name(),
    },
  });
  typia.assert(owner);

  const userA = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: userAEmail,
      password: "Password123!",
      displayName: RandomGenerator.name(),
    },
  });
  typia.assert(userA);

  const userB = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: userBEmail,
      password: "Password123!",
      displayName: RandomGenerator.name(),
    },
  });
  typia.assert(userB);

  // 2. Owner creates a follow for userA
  const follow = await api.functional.discussionboard.follows.post(connection, {
    body: {
      follower_user_id: owner.id,
      followed_user_id: userA.id,
    },
  });
  typia.assert(follow);

  // 3. Owner updates follow target to userB (should only set followed_user_id)
  const updated = await api.functional.discussionboard.follows.putById(connection, {
    id: follow.id,
    body: {
      follower_user_id: owner.id,
      followed_user_id: userB.id,
    },
  });
  typia.assert(updated);

  // 4. Validate that the record has switched to userB
  TestValidator.equals("follow user id changed")(updated.follower_user_id)(owner.id);
  TestValidator.equals("target user switched")(updated.followed_user_id)(userB.id);
  TestValidator.equals("thread target is null")(updated.followed_thread_id)(null);
  TestValidator.notEquals("not following previous user anymore")(updated.followed_user_id)(userA.id);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { IDiscussionboardFollow } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardFollow";

/**
 * 이미 팔로우한 대상을 가리키도록 기존 follow 레코드를 업데이트하면 중복(409 Conflict) 오류가 발생함을 검증합니다.
 *
 * - 테스트 목적: 동일 유저가 동일 타겟(사용자)에 대해 중복 follow를 생성하지 못하도록 제약이 동작하는지 테스트합니다.
 * - 시나리오:
 *   1. 팔로우의 주체(Owner) 유저와 팔로우 타겟 역할을 할 두 유저(TargetA, TargetB)를 각각 생성합니다.
 *   2. Owner가 TargetA, TargetB를 각각 팔로우하여 두 follow(A, B)를 만듭니다.
 *   3. followA의 대상을 TargetB로 변경(update)해 중복 관계를 시도합니다.
 *   4. 이때 409 Conflict 오류가 발생해야 하며, TestValidator.error로 검증합니다.
 *
 * 이로써 update API에서 중복 follow 예외 처리(유니크 제약)가 의도대로 동작하는지 확인할 수 있습니다.
 */
export async function test_api_discussionboard_test_update_follow_target_to_duplicate_returns_conflict(
  connection: api.IConnection,
) {
  // 1. Owner, TargetA, TargetB 유저 생성
  const owner = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<'email'>>(),
      password: 'password1234',
      displayName: RandomGenerator.name(),
    },
  });
  typia.assert(owner);

  const targetA = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<'email'>>(),
      password: 'password1234',
      displayName: RandomGenerator.name(),
    },
  });
  typia.assert(targetA);

  const targetB = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<'email'>>(),
      password: 'password1234',
      displayName: RandomGenerator.name(),
    },
  });
  typia.assert(targetB);

  // 2. Owner가 TargetA 팔로우
  const followA = await api.functional.discussionboard.follows.post(connection, {
    body: {
      follower_user_id: owner.id,
      followed_user_id: targetA.id,
      followed_thread_id: null,
    },
  });
  typia.assert(followA);

  // 3. Owner가 TargetB 팔로우
  const followB = await api.functional.discussionboard.follows.post(connection, {
    body: {
      follower_user_id: owner.id,
      followed_user_id: targetB.id,
      followed_thread_id: null,
    },
  });
  typia.assert(followB);

  // 4. FollowA의 대상(followed_user_id)를 TargetB로 업데이트 시도 (이미 followB가 TargetB를 가리키므로 중복) - 409 Conflict
  await TestValidator.error('중복 팔로우 업데이트시 409 Conflict 오류 발생')(
    async () => {
      await api.functional.discussionboard.follows.putById(connection, {
        id: followA.id,
        body: {
          follower_user_id: owner.id,
          followed_user_id: targetB.id,
          followed_thread_id: null,
        },
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
