/**
 * Validate forbidden update of a follow record by a non-owner.
 *
 * This test ensures that only the owner of a follow record can update it: if another user attempts the update, the API must return a 403 Forbidden error. It simulates the creation of two user accounts and a follow relationship, then attempts a forbidden update by a non-owner, verifying proper access control enforcement.
 *
 * Steps:
 * 1. Register User1
 * 2. Register User2
 * 3. User1 creates a follow record, following User2
 * 4. User2 (not the owner) attempts to update the follow record
 * 5. Validate the API rejects this with a forbidden error (403)
 */
export async function test_api_discussionboard_test_update_follow_record_not_owner_forbidden(
  connection: api.IConnection,
) {
  // 1. Register User1
  const user1Email = typia.random<string & tags.Format<"email">>();
  const user1Password = "password123!";
  const user1 = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: user1Email,
      password: user1Password as string & tags.Format<"password">,
      displayName: RandomGenerator.name(),
      avatarUrl: undefined,
      isActive: true,
    },
  });
  typia.assert(user1);

  // 2. Register User2
  const user2Email = typia.random<string & tags.Format<"email">>();
  const user2Password = "password456!";
  const user2 = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: user2Email,
      password: user2Password as string & tags.Format<"password">,
      displayName: RandomGenerator.name(),
      avatarUrl: undefined,
      isActive: true,
    },
  });
  typia.assert(user2);

  // 3. User1 creates a follow record following User2
  const follow = await api.functional.discussionboard.follows.post(connection, {
    body: {
      follower_user_id: user1.id,
      followed_user_id: user2.id,
      followed_thread_id: null,
    },
  });
  typia.assert(follow);

  // 4. User2 (not the owner) attempts to update the follow record
  //    Tries to change the followed target to a thread
  await TestValidator.error("non-owner cannot update follow record")(async () => {
    await api.functional.discussionboard.follows.putById(connection, {
      id: follow.id,
      body: {
        follower_user_id: user1.id,
        followed_user_id: null,
        followed_thread_id: typia.random<string & tags.Format<"uuid">>(),
      },
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
