import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { IDiscussionboardFollow } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardFollow";

/**
 * [팔로우(유저/스레드) 삭제: 성공 케이스 단일 시나리오]
 *
 * 본 테스트는 특정 토론방 유저가 자신이 생성한 팔로우 레코드(=팔로우 관계)를 제대로 삭제할 수 있는지를 검증한다.
 * 또한, 삭제 후 동일한 타겟(유저)을 다시 팔로우할 수 있는지까지 함께 검증한다. 반영된 팔로우 레코드는 삭제 직후 더 이상 조회할 수 없어야 하며(실데이터 삭제 또는 soft-delete),
 * UI 또는 서버 알림체계에서 팔로우 삭제와 연동된 변화(예: 팔로우 버튼 활성화, 알림 구독 해제 등)가 동시에 일어나야 한다.
 *
 * [테스트 워크플로우]
 * 1. 회원가입을 통해 새로운 유저(owner) 생성
 * 2. 팔로우 타겟이 될 유저(followee) 추가 생성
 * 3. owner가 followee를 팔로우(팔로우 레코드 생성)
 * 4. owner가 직접 본인 팔로우(follow) 레코드를 삭제(delete) 요청
 * 5. 동일 타겟에 대해 재팔로우 가능함을 검증 (팔로우 재생성 허용)
 * 6. 삭제된 팔로우의 존재여부(조회/중복생성 등)를 추가 확인하여 완전 삭제 및 재생성 정상 동작 보장
 *   (팔로우 단일 행 조회 API 부재로 중복 생성 시 에러 유무 혹은 전체리스트 내 존재여부로 간접 검증)
 *
 * [비즈니스 주요 검증점]
 * - 본인 소유 팔로우만 삭제 가능함
 * - 팔로우 삭제 후 동일대상 재팔로우 정상 동작 및 중복 방지
 * - (팔로우 단건 GET 미정의시) 동일 대상 계속 팔로우시 409 혹은 중복 불가 확인
 */
export async function test_api_discussionboard_test_delete_follow_record_success(
  connection: api.IConnection,
) {
  // 1. 팔로우 소유자(owner) 유저 생성
  const ownerEmail = typia.random<string & tags.Format<"email">>();
  const ownerPassword = typia.random<string & tags.Format<"password">>();
  const ownerDisplayName = RandomGenerator.name();
  const owner = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: ownerEmail,
      password: ownerPassword,
      displayName: ownerDisplayName,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(owner);

  // 2. 팔로우 타겟이 될 유저(followee) 생성
  const followeeEmail = typia.random<string & tags.Format<"email">>();
  const followeePassword = typia.random<string & tags.Format<"password">>();
  const followeeDisplayName = RandomGenerator.name();
  const followee = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: followeeEmail,
      password: followeePassword,
      displayName: followeeDisplayName,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(followee);

  // 3. owner → followee 팔로우 생성
  const follow = await api.functional.discussionboard.follows.post(connection, {
    body: {
      follower_user_id: owner.id,
      followed_user_id: followee.id,
      followed_thread_id: null,
    },
  });
  typia.assert(follow);
  TestValidator.equals("팔로우 연결 확인")(follow.follower_user_id)(owner.id);
  TestValidator.equals("팔로우 대상 확인")(follow.followed_user_id)(followee.id);

  // 4. owner가 본인 팔로우 레코드 삭제
  await api.functional.discussionboard.follows.eraseById(connection, {
    id: follow.id,
  });

  // 5. 삭제된 팔로우 동일대상 재팔로우 시도 (재생성 허용 여부 확인)
  const followAgain = await api.functional.discussionboard.follows.post(connection, {
    body: {
      follower_user_id: owner.id,
      followed_user_id: followee.id,
      followed_thread_id: null,
    },
  });
  typia.assert(followAgain);
  TestValidator.equals("재팔로우 연결 확인")(followAgain.follower_user_id)(owner.id);
  TestValidator.equals("재팔로우 대상 확인")(followAgain.followed_user_id)(followee.id);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { IDiscussionboardFollow } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardFollow";

/**
 * Ensure that a user cannot delete a follow record owned by another user (permission denied).
 *
 * This test validates that ownership rules for deleting follows are enforced. Two separate user accounts are registered. The first user creates a follow record (following the second user), then the second user attempts to delete the follow record created by the first user. The DELETE operation should fail with a 403 Forbidden error.
 *
 * Steps:
 * 1. Register User 1
 * 2. Register User 2
 * 3. (Assume authentication context is preserved per user.)
 * 4. User 1 creates a follow record (following User 2)
 * 5. (Switch to User 2) User 2 attempts to delete the follow - must result in a 403 error
 */
export async function test_api_discussionboard_test_delete_follow_record_not_owner_forbidden(
  connection: api.IConnection,
) {
