import api from "@ORGANIZATION/PROJECT-api";
import type { ISetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ISetting";
import type { IPageSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageSetting";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionboardSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSetting";

/**
 * Validate paginated and filtered listing of discussion board settings.
 *
 * This test ensures the /discussionboard/settings PATCH endpoint returns correct, filtered, and paginated configuration records given a variety of valid search and filter requests. It creates multiple configuration settings first to ensure non-trivial search results, then verifies filtering by board_id, enabled status, partial key match, and pagination. It checks that the returned data corresponds to filter conditions, and that pagination information (page, limit, etc.) is accurate.
 *
 * Steps:
 * 1. Create several configuration settings, some global and some board-specific, with distinct keys and enabled/disabled states.
 * 2. Filter by a specific board_id and check that only that board's settings are returned.
 * 3. Filter for enabled=true (deleted_at == null) and enabled=false (deleted_at != null) and check results.
 * 4. Filter by partial key substring and verify matching only relevant records.
 * 5. Query with limit/page values and verify correct pagination and metadata.
 * 6. Confirm that each response's data matches the specified request/filter.
 */
export async function test_api_discussionboard_test_list_settings_with_valid_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create board IDs for specificity
  const boardId: string = typia.random<string & tags.Format<"uuid">>();
  const otherBoardId: string = typia.random<string & tags.Format<"uuid">>();

  // Create a global enabled setting
  const globalEnabled = await api.functional.discussionboard.settings.post(connection, {
    body: {
      key: "posts_enabled",
      value: "true",
    } satisfies IDiscussionboardSetting.ICreate,
  });
  typia.assert(globalEnabled);

  // Create a global disabled (soft-deleted) setting (we'll "disable" by simulating deletion)
  const globalDisabled = await api.functional.discussionboard.settings.post(connection, {
    body: {
      key: "comments_enabled",
      value: "false",
    } satisfies IDiscussionboardSetting.ICreate,
  });
  typia.assert(globalDisabled);

  // Create a board-specific enabled setting
  const boardSetting1 = await api.functional.discussionboard.settings.post(connection, {
    body: {
      board_id: boardId,
      key: "min_post_length",
      value: "10",
      description: "Minimum post chars",
    } satisfies IDiscussionboardSetting.ICreate,
  });
  typia.assert(boardSetting1);

  // Create a board-specific disabled setting (again, logic for disabling is business, assume all created are enabled)
  const boardSetting2 = await api.functional.discussionboard.settings.post(connection, {
    body: {
      board_id: boardId,
      key: "max_attachment_size",
      value: "100",
      description: "Max attachment MB",
    } satisfies IDiscussionboardSetting.ICreate,
  });
  typia.assert(boardSetting2);

  // Create another board's setting
  const otherSetting = await api.functional.discussionboard.settings.post(connection, {
    body: {
      board_id: otherBoardId,
      key: "allow_guests",
      value: "false",
    } satisfies IDiscussionboardSetting.ICreate,
  });
  typia.assert(otherSetting);

  // 2. Filter by board_id=boardId
  let res = await api.functional.discussionboard.settings.patch(connection, {
    body: {
      board_id: boardId,
    } satisfies ISetting.IRequest,
  });
  typia.assert(res);
  TestValidator.predicate("Only settings with requested board_id present")(
    res.data.every((s) => s.board_id === boardId),
  );

  // 3. Filter for enabled=true (deleted_at == null)
  res = await api.functional.discussionboard.settings.patch(connection, {
    body: {
      enabled: true,
    } satisfies ISetting.IRequest,
  });
  typia.assert(res);
  TestValidator.predicate("All returned settings are enabled")(
    res.data.every((s) => !s.deleted_at),
  );

  // 4. Filter for enabled=false (deleted_at != null)
  res = await api.functional.discussionboard.settings.patch(connection, {
    body: {
      enabled: false,
    } satisfies ISetting.IRequest,
  });
  typia.assert(res);
  TestValidator.predicate("All returned settings are disabled")(
    res.data.every((s) => !!s.deleted_at),
  );

  // 5. Filter by partial key substring (e.g. "post")
  res = await api.functional.discussionboard.settings.patch(connection, {
    body: {
      key: "post",
    } satisfies ISetting.IRequest,
  });
  typia.assert(res);
  TestValidator.predicate("Only settings whose key contains substring")(
    res.data.every((s) => s.key.includes("post")),
  );

  // 6. Pagination: limit=2, page=1
  res = await api.functional.discussionboard.settings.patch(connection, {
    body: {
      limit: 2,
      page: 1,
    } satisfies ISetting.IRequest,
  });
  typia.assert(res);
  TestValidator.equals("Page 1")(res.pagination.current)(1);
  TestValidator.equals("Limit 2")(res.pagination.limit)(2);
  TestValidator.predicate("Count <= 2")(res.data.length <= 2);

  // 7. Pagination: limit=2, page=2
  res = await api.functional.discussionboard.settings.patch(connection, {
    body: {
      limit: 2,
      page: 2,
    } satisfies ISetting.IRequest,
  });
  typia.assert(res);
  TestValidator.equals("Page 2")(res.pagination.current)(2);
  TestValidator.equals("Limit 2")(res.pagination.limit)(2);
}

