 *
 * 해당 테스트는 실제 존재하는 설정 항목을 생성 후, 그 id로 단건 설정 조회 API를 호출했을 때,
 * 정확한 데이터가 반환되는지, 필드들이 올바르게 채워져 있는지 검증합니다.
 *
 * 주요 검증 포인트:
 * 1. IDiscussionboardSetting.ICreate 랜덤값으로 설정 생성
 * 2. 생성결과 id로 getById 호출
 * 3. 조회값이 생성값과 일치하는지(key, value, description, board_id)
 * 4. 필수 고유필드(id, created_at, updated_at 등) 포맷이 올바른지 typia.assert
 * 5. deleted_at이 null 혹은 undefined로 soft-deletion 방지됨을 확인
 */
export async function test_api_discussionboard_settings_getById(
  connection: api.IConnection,
) {
  // 1. IDiscussionboardSetting.ICreate 타입으로 랜덤한 설정을 생성
  const createInput: IDiscussionboardSetting.ICreate = {
    board_id: typia.random<string & tags.Format<"uuid">>(),
    key: RandomGenerator.alphabets(8),
    value: RandomGenerator.alphaNumeric(6),
    description: RandomGenerator.paragraph()(),
  };
  const created: IDiscussionboardSetting = await api.functional.discussionboard.settings.post(connection, { body: createInput });
  typia.assert(created);

  // 2. 생성된 id로 GET /discussionboard/settings/{id} 조회
  const fetched: IDiscussionboardSetting = await api.functional.discussionboard.settings.getById(connection, { id: created.id });
  typia.assert(fetched);

  // 3. 생성값과 반환값 주요 필드(key, value, description, board_id) 일치 확인
  TestValidator.equals("key 일치")(fetched.key)(createInput.key);
  TestValidator.equals("value 일치")(fetched.value)(createInput.value);
  TestValidator.equals("description 일치")(fetched.description)(createInput.description);
  TestValidator.equals("board_id 일치")(fetched.board_id)(createInput.board_id);

  // 4. id, created_at, updated_at 포맷이 잘 맞는지 typia.assert로 검증
  typia.assert<string & tags.Format<"uuid">>(fetched.id);
  typia.assert<string & tags.Format<"date-time">>(fetched.created_at);
  typia.assert<string & tags.Format<"date-time">>(fetched.updated_at);

  // 5. deleted_at 필드는 null 또는 undefined 인지 확인하여 soft-delete 아님을 확인
  TestValidator.predicate("deleted_at null or undefined")(fetched.deleted_at === null || fetched.deleted_at === undefined);
}

