import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSetting";

/**
 * Test updating an existing discussion board setting with valid data.
 *
 * This test verifies that an existing configuration setting can be successfully updated using a valid PUT request.
 * The test ensures the following:
 * 1. The setting is first created (dependency step), then updated.
 * 2. Only allowed fields (such as `value` or `description`) are changed in the request.
 * 3. The update operation returns the updated setting object, and modifications are persisted.
 * 4. Non-modified fields (e.g., key, board association, created timestamp) are unchanged.
 * 5. Business rules, such as updateable fields and uniqueness constraints, are honored.
 *
 * Test Steps:
 * 1. Create a new setting using the POST endpoint.
 * 2. Issue a PUT request to update an allowed field (e.g., `value` or `description`).
 * 3. Assert the response is of correct type and reflects the updated value.
 * 4. Assert other immutable fields are not unintentionally altered.
 * 5. Ensure update time is refreshed and not deleted.
 */
export async function test_api_discussionboard_test_update_setting_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Create an initial setting to be updated
  const originalSetting = await api.functional.discussionboard.settings.post(connection, {
    body: {
      key: "max_post_length",
      value: "200",
      description: "Maximum length of a post in characters.",
      board_id: null
    } satisfies IDiscussionboardSetting.ICreate,
  });
  typia.assert(originalSetting);

  // 2. Prepare valid update data (change value and description)
  const updateBody: IDiscussionboardSetting.IUpdate = {
    value: "300",
    description: "Maximum length updated to 300 characters."
  };

  // 3. Update the setting
  const updatedSetting = await api.functional.discussionboard.settings.putById(connection, {
    id: originalSetting.id,
    body: updateBody,
  });
  typia.assert(updatedSetting);

  // 4. Validate updated fields
  TestValidator.equals("value updated")(updatedSetting.value)(updateBody.value!);
  TestValidator.equals("description updated")(updatedSetting.description)(updateBody.description!);

  // 5. Validate unchanged fields
  TestValidator.equals("key should not change")(updatedSetting.key)(originalSetting.key);
  TestValidator.equals("id should not change")(updatedSetting.id)(originalSetting.id);
  TestValidator.equals("board_id should not change")(updatedSetting.board_id)(originalSetting.board_id);
  TestValidator.equals("created_at should not change")(updatedSetting.created_at)(originalSetting.created_at);

  // 6. Ensure update timestamp is refreshed
  TestValidator.notEquals("updated_at should update")(updatedSetting.updated_at)(originalSetting.updated_at);

  // 7. Ensure not deleted
  TestValidator.equals("deleted_at should remain unchanged")(updatedSetting.deleted_at)(originalSetting.deleted_at ?? null);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
