/**
 * Validate uniqueness constraint for (board_id, key) when updating a setting.
 *
 * This test ensures that updating a discussionboard setting's key to duplicate the key of another setting (for the same board_id) results in a uniqueness violation error (conflict) rather than succeeding.
 *
 * 1. Create two settings (A, B) with the SAME board_id but DIFFERENT keys.
 * 2. Attempt to update setting A's key to the same as setting B's key (for the same board_id).
 * 3. Confirm the update fails due to a uniqueness constraint (conflict error).
 */
export async function test_api_discussionboard_test_update_setting_with_conflicting_key(
  connection: api.IConnection,
) {
  // 1. Create a random board_id
  const boardId = typia.random<string & tags.Format<"uuid">>();

  // 2. Create Setting A (boardId, keyA)
  const keyA = `test_key_A_${RandomGenerator.alphaNumeric(6)}`;
  const settingA = await api.functional.discussionboard.settings.post(connection, {
    body: {
      board_id: boardId,
      key: keyA,
      value: RandomGenerator.alphaNumeric(8),
      description: "Setting A for uniqueness test",
    } satisfies IDiscussionboardSetting.ICreate,
  });
  typia.assert(settingA);

  // 3. Create Setting B (same boardId, keyB)
  const keyB = `test_key_B_${RandomGenerator.alphaNumeric(6)}`;
  const settingB = await api.functional.discussionboard.settings.post(connection, {
    body: {
      board_id: boardId,
      key: keyB,
      value: RandomGenerator.alphaNumeric(8),
      description: "Setting B for uniqueness test",
    } satisfies IDiscussionboardSetting.ICreate,
  });
  typia.assert(settingB);

  // 4. Attempt to update Setting A's key to match Setting B's key (should cause uniqueness conflict)
  await TestValidator.error("should fail to update key to duplicate another setting's key for same board_id")(
    async () => {
      await api.functional.discussionboard.settings.putById(connection, {
        id: settingA.id,
        body: {
          key: settingB.key,
        } satisfies IDiscussionboardSetting.IUpdate,
      });
    },
  );
}

