import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { IDiscussionboardBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBan";
import type { IPageIDiscussionboardBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardBan";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate listing/searching of user bans with various query criteria and permission checks.
 *
 * This function tests retrieval of user ban records (audits, compliance, moderation cases) via the /discussionboard/bans PATCH endpoint, which supports paginated and filtered queries. It validates both data retrieval accuracy (filtering by banned user, moderator, date range, pagination, and edge cases like empty results or invalid filters) and access control policies (only 'admin' or 'moderator' roles can fetch ban lists).
 *
 * Test Workflow:
 * 1. Prepare test users for: bannedUser (to be banned), adminIssuer (admin), modIssuer (moderator), normalUser (cannot access ban listing)
 * 2. Create several ban records with variety for filter/pagination edge cases
 * 3. As adminIssuer and modIssuer, test listing:
 *    - All bans (no filters)
 *    - By banned user
 *    - By moderator/admin
 *    - By date range
 *    - Pagination (limit/page), high page size, out-of-range page index
 *    - Invalid filters (gibberish UUIDs), expect empty/0 result
 * 4. As normalUser, confirm patch /discussionboard/bans is denied (throws)
 */
export async function test_api_discussionboard_test_list_user_bans_with_various_filters(
  connection: api.IConnection,
) {
  // --- Step 1: Create test users ---
  // Simulate roles: "adminIssuer", "modIssuer", "normalUser", "bannedUser", plus anotherBanned
  const adminUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "adminPW1234!", // For E2E, role is determined by business test, as no role info in DTO
      displayName: "AdminIssuer",
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(adminUser);

  const modUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "modPW1234!",
      displayName: "ModeratorIssuer",
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(modUser);

  const bannedUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "bannedPW1234!",
      displayName: "BannedUser",
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(bannedUser);

  const anotherBanned = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "anotherPW1234!",
      displayName: "AnotherBanned",
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(anotherBanned);

  const normalUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "normalPW1234!",
      displayName: "NormalUser",
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(normalUser);

  // --- Step 2: Create ban records ---
  // For test variety, adminIssuer bans bannedUser (perm), modIssuer bans anotherBanned (temp)
  // Fake moderationActionId
  const modActionId: string = typia.random<string & tags.Format<"uuid">>();
  const adminActionId: string = typia.random<string & tags.Format<"uuid">>();

  // Ban 1: admin bans bannedUser (permanent ban)
  const ban1 = await api.functional.discussionboard.bans.post(connection, {
    body: {
      user_id: bannedUser.id,
      moderator_id: adminUser.id,
      moderation_action_id: adminActionId,
      start_at: new Date(Date.now() - 1000 * 60 * 60 * 7).toISOString(), // 7 hours ago
      end_at: null,
      ban_reason: "Permanent violation by test",
    } satisfies IDiscussionboardBan.ICreate,
  });
  typia.assert(ban1);

  // Ban 2: mod bans anotherBanned (temporary ban, ends in future)
  const ban2 = await api.functional.discussionboard.bans.post(connection, {
    body: {
      user_id: anotherBanned.id,
      moderator_id: modUser.id,
      moderation_action_id: modActionId,
      start_at: new Date(Date.now() - 1000 * 60 * 60).toISOString(), // 1 hour ago
      end_at: new Date(Date.now() + 1000 * 60 * 60 * 2).toISOString(), // in 2 hours
      ban_reason: "Temp ban for policy test",
    } satisfies IDiscussionboardBan.ICreate,
  });
  typia.assert(ban2);

  // Ban 3: admin bans anotherBanned again (overlapping, for multiple-ban filtering)
  const ban3 = await api.functional.discussionboard.bans.post(connection, {
    body: {
      user_id: anotherBanned.id,
      moderator_id: adminUser.id,
      moderation_action_id: typia.random<string & tags.Format<"uuid">>(),
      start_at: new Date().toISOString(),
      end_at: null,
      ban_reason: "Second admin action",
    } satisfies IDiscussionboardBan.ICreate,
  });
  typia.assert(ban3);

  // --- Step 3: Listing as adminUser and modUser (simulate as both, permissions by scenario) ---
  // a. List all bans (no filters)
  const listAll = await api.functional.discussionboard.bans.patch(connection, {
    body: {},
  });
  typia.assert(listAll);
  TestValidator.predicate("contains known ban1")(listAll.data.some(b => b.id === ban1.id));
  TestValidator.predicate("contains known ban2")(listAll.data.some(b => b.id === ban2.id));
  TestValidator.predicate("pagination meta present")(
    typeof listAll.pagination.current === "number"
      && typeof listAll.pagination.limit === "number"
      && typeof listAll.pagination.pages === "number"
      && typeof listAll.pagination.records === "number"
  );

  // b. Filter by banned user: only that user's bans
  const listBannedUser = await api.functional.discussionboard.bans.patch(connection, {
    body: { user_id: bannedUser.id },
  });
  typia.assert(listBannedUser);
  TestValidator.predicate("only bannedUser bans")(
    listBannedUser.data.every(b => b.user_id === bannedUser.id)
  );

  // c. Filter by moderator/admin
  const listByAdmin = await api.functional.discussionboard.bans.patch(connection, {
    body: { moderator_id: adminUser.id },
  });
  typia.assert(listByAdmin);
  TestValidator.predicate("only admin-issued bans")(
    listByAdmin.data.every(b => b.moderator_id === adminUser.id)
  );

  // d. Date range filter (from_start_at)
  const startRange = new Date(Date.now() - 1000 * 60 * 60 * 2).toISOString(); // 2 hr ago
  const listByDate = await api.functional.discussionboard.bans.patch(connection, {
    body: { from_start_at: startRange },
  });
  typia.assert(listByDate);
  TestValidator.predicate("all after from_start_at")(
    listByDate.data.every(b => new Date(b.start_at) >= new Date(startRange))
  );

  // e. Pagination: limit and page, high page size, out-of-range (e.g., page > total pages)
  const paged1 = await api.functional.discussionboard.bans.patch(connection, {
    body: { limit: 1, page: 1 },
  });
  typia.assert(paged1);
  TestValidator.equals("first page size")(paged1.data.length)(1);

  const paged2 = await api.functional.discussionboard.bans.patch(connection, {
    body: { limit: 1, page: 2 },
  });
  typia.assert(paged2);
  TestValidator.equals("second page size")(paged2.data.length)(1);
  TestValidator.notEquals("different page data")(paged2.data[0].id)(paged1.data[0].id);

  // High page size
  const highLimitPaged = await api.functional.discussionboard.bans.patch(connection, {
    body: { limit: 999 },
  });
  typia.assert(highLimitPaged);
  TestValidator.predicate("high limit returns >= 1")(highLimitPaged.data.length >= 1);

  // Out-of-range page (should return empty data)
  const outOfRangePage = await api.functional.discussionboard.bans.patch(connection, {
    body: { limit: 2, page: 99 },
  });
  typia.assert(outOfRangePage);
  TestValidator.equals("empty result out-of-range")(outOfRangePage.data.length)(0);

  // Invalid user id filter (unknown UUID)
  const invalidFilter = await api.functional.discussionboard.bans.patch(connection, {
    body: { user_id: typia.random<string & tags.Format<"uuid">>() },
  });
  typia.assert(invalidFilter);
  TestValidator.equals("invalid user yields empty")(invalidFilter.data.length)(0);

  // --- Step 4: As normal user (simulate by business logic), confirm forbidden/denied ---
  // As direct user role auth/api isn't present, simulate error check manually via expectation.
  TestValidator.error("normal user unauthorized list")(
    async () => {
      await api.functional.discussionboard.bans.patch(connection, {
        body: {},
      });
    },
  );
}

