/**
 * 특정 유저 밴 레코드를 고유 ID로 조회하는 API의 성공/실패 동작 검증
 *
 * - 밴 데이터는 민감하므로 관리자/모더레이터 토큰 상황에서만 정상 동작(여기선 토큰 권한강화 미테스트)
 * - 성공 시 전체 필드(유저/모더레이터 UUID, 사유, 시작/종료일, 모더레이션 액션 등) 모두 일치 확인
 * - 존재하지 않는 UUID로 조회 시 404 등 적절한 오류 응답 확인
 *
 * 주요 절차:
 * 1. 밴 대상 유저, 모더레이터 각 1명 생성
 * 2. 모더레이터가 대상 유저 밴 등록(사유/기간 포함)
 * 3. 방금 등록한 ban id로 GET 성공 조회 및 필드값 검증
 * 4. 임의/존재하지 않는 랜덤 UUID(Get)로 404 처리 검증
 */
export async function test_api_discussionboard_bans_test_get_ban_by_id_success_and_not_found(
  connection: api.IConnection,
) {
  // 1. 밴 대상 유저, 모더레이터 유저 1명씩 생성
  const bannedUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<'email'>>(),
      password: 'banTestUserPW1!@#',
      displayName: RandomGenerator.name(),
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(bannedUser);

  const moderator = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<'email'>>(),
      password: 'moderTestPW2$%^',
      displayName: RandomGenerator.name(),
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(moderator);

  // 2. 모더레이터가 유저에 대해 밴 등록 (사유 및 기간)
  const now = new Date().toISOString();
  const banInput: IDiscussionboardBan.ICreate = {
    user_id: bannedUser.id,
    moderator_id: moderator.id,
    moderation_action_id: typia.random<string & tags.Format<'uuid'>>(),
    start_at: now,
    end_at: null,
    ban_reason: '테스트 밴 사유 (비매너 언행)',
  };
  const createdBan = await api.functional.discussionboard.bans.post(connection, { body: banInput });
  typia.assert(createdBan);

  // 3. 정상: 생성된 ban id로 GET 조회, 필드 일치 검증
  const banDetail = await api.functional.discussionboard.bans.getById(connection, { id: createdBan.id });
  typia.assert(banDetail);
  TestValidator.equals('ban.id')(banDetail.id)(createdBan.id);
  TestValidator.equals('ban.user_id')(banDetail.user_id)(banInput.user_id);
  TestValidator.equals('ban.moderator_id')(banDetail.moderator_id)(banInput.moderator_id);
  TestValidator.equals('ban.ban_reason')(banDetail.ban_reason)(banInput.ban_reason);
  TestValidator.equals('ban.start_at')(banDetail.start_at)(banInput.start_at);
  TestValidator.equals('ban.end_at')(banDetail.end_at)(banInput.end_at);
  TestValidator.equals('ban.moderation_action_id')(banDetail.moderation_action_id)(banInput.moderation_action_id);

  // 4. 존재하지 않는/랜덤 UUID로 404 등 오류 응답 확인
  await TestValidator.error('존재하지 않는 ban id 조회시 404 등 오류')(async () => {
    await api.functional.discussionboard.bans.getById(connection, {
      id: typia.random<string & tags.Format<'uuid'>>()
    });
  });
}

