import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { IDiscussionboardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerationAction";
import type { IDiscussionboardBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBan";

/**
 * Validate that an admin/moderator can successfully create a user ban and prevent duplicate/overlapping bans for the same period and user.
 *
 * Business rationale: Proper ban enforcement is critical for platform moderation and compliance. Creating a ban must be auditable, attributable to a moderator, linked to its causative moderation action, and accurately time-bound. The system must also prevent overlapping bans (for the same user and time period) to avoid audit inconsistency or redundant moderation actions.
 *
 * Test workflow:
 * 1. Create two users: one to be banned, and one acting as moderator/admin.
 * 2. Create a moderation action performed by the moderator for this ban context.
 * 3. Apply a ban event against the first user, citing the moderator and moderation action, with bounded start/end times and a human-readable reason.
 * 4. Validate ban creation and all returned fields for accuracy and audit trace.
 * 5. Attempt to create another ban on the same user with an identical period, ensuring business logic prevents duplicates/overlapping bans.
 */
export async function test_api_discussionboard_test_create_user_ban_valid_and_duplicate(
  connection: api.IConnection,
) {
  // 1. Create two users (target and moderator)
  const targetUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
      displayName: RandomGenerator.name(),
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(targetUser);

  const moderator = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
      displayName: RandomGenerator.name(),
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(moderator);

  // 2. Create moderation action for this ban
  const moderationAction = await api.functional.discussionboard.moderationActions.post(connection, {
    body: {
      actor_moderator_id: moderator.id,
      target_user_id: targetUser.id,
      action_type: "ban",
      action_reason: "Violation of community guidelines.",
    } satisfies IDiscussionboardModerationAction.ICreate,
  });
  typia.assert(moderationAction);

  // 3. Apply a ban against the target user
  const now = new Date();
  const banStart = now.toISOString();
  const banEnd = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000).toISOString(); // 7 days
  const banReason = "Repeated rule violation, abusive posts.";

  const ban = await api.functional.discussionboard.bans.post(connection, {
    body: {
      user_id: targetUser.id,
      moderator_id: moderator.id,
      moderation_action_id: moderationAction.id,
      start_at: banStart,
      end_at: banEnd,
      ban_reason: banReason,
    } satisfies IDiscussionboardBan.ICreate,
  });
  typia.assert(ban);
  TestValidator.equals("banned user matches")(ban.user_id)(targetUser.id);
  TestValidator.equals("moderator matches")(ban.moderator_id)(moderator.id);
  TestValidator.equals("moderation action link")(ban.moderation_action_id)(moderationAction.id);
  TestValidator.equals("start time matches")(ban.start_at)(banStart);
  TestValidator.equals("end time matches")(ban.end_at)(banEnd);
  TestValidator.equals("ban reason matches")(ban.ban_reason)(banReason);

  // 4. Attempt to create a duplicate/overlapping ban for the same user and period
  await TestValidator.error("duplicate or overlapping bans are prohibited")(async () => {
    await api.functional.discussionboard.bans.post(connection, {
      body: {
        user_id: targetUser.id,
        moderator_id: moderator.id,
        moderation_action_id: moderationAction.id,
        start_at: banStart,
        end_at: banEnd,
        ban_reason: banReason,
      } satisfies IDiscussionboardBan.ICreate,
    });
  });
}

