 *  - Creating a ban as a normal user (not admin/moderator) results in an authorization failure (HTTP 403).
 *
 * Test sequence:
 * 1. Create a valid user account (regular user) for use as a typical discussion board user (target for non-admin attempt).
 * 2. Create a valid moderator/admin account (for use in valid ban requests and as a valid moderator in payloads).
 * 3. Try to create a ban with various invalid payloads (missing moderator_id, invalid UUIDs, missing moderation_action_id, missing required fields, invalid or null times, negative-end dates before start, empty/invalid reason, etc). Each should produce a validation error.
 * 4. Attempt to create a ban as a non-admin/regular user (even if payload is otherwise valid). This must trigger a 403 error.
 *
 * No clean-up is required as bans are not actually created with invalid data.
 *
 * All errors are validated using TestValidator.error(), and valid responses must never occur for invalid cases.
 */
export async function test_api_discussionboard_test_create_ban_with_invalid_fields_and_permission_error(connection: api.IConnection) {
  // Step 1: Create a valid regular user
  const normalUser = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
