        // moderator_id omitted
        moderation_action_id: typia.random<string & tags.Format<"uuid">>(),
        start_at: new Date().toISOString(),
        end_at: null,
        ban_reason: "No moderator set",
      } as any, // forcibly omit property
    });
  });

  // Step 3b: Invalid user_id format
  await TestValidator.error("invalid user_id format")(async () => {
    await api.functional.discussionboard.bans.post(connection, {
      body: {
        user_id: "not-a-uuid",
        moderator_id: moderator.id,
        moderation_action_id: typia.random<string & tags.Format<"uuid">>(),
        start_at: new Date().toISOString(),
        end_at: null,
        ban_reason: "Invalid user id string",
      } as any,
    });
  });

  // Step 3c: start_at missing
  await TestValidator.error("missing start_at")(async () => {
    await api.functional.discussionboard.bans.post(connection, {
      body: {
        user_id: normalUser.id,
        moderator_id: moderator.id,
        moderation_action_id: typia.random<string & tags.Format<"uuid">>(),
        // start_at omitted
        end_at: null,
        ban_reason: "No start_at",
      } as any,
    });
