    });
  });

  // Step 3e: ban_reason missing
  await TestValidator.error("missing ban_reason")(async () => {
    await api.functional.discussionboard.bans.post(connection, {
      body: {
        user_id: normalUser.id,
        moderator_id: moderator.id,
        moderation_action_id: typia.random<string & tags.Format<"uuid">>(),
        start_at: new Date().toISOString(),
        end_at: null,
        // ban_reason missing
      } as any,
    });
