  // Step 4: Try to create a ban as a regular user (should fail permission check)
  // In reality, the connection should represent the user's identity/context. If not possible, consider the test as abstract.
  // Here we assume the connection is for normalUser
  // Note: If switching context is not supported, this block can be pseudo-code or skipped with a comment.
  await TestValidator.error("regular user ban creation forbidden")(async () => {
    await api.functional.discussionboard.bans.post(connection, {
      body: {
        user_id: typia.random<string & tags.Format<"uuid">>(),
        moderator_id: normalUser.id, // normalUser shouldn't have mod privileges
        moderation_action_id: typia.random<string & tags.Format<"uuid">>(),
        start_at: new Date().toISOString(),
        end_at: null,
        ban_reason: "Attempt by normal user",
      } satisfies IDiscussionboardBan.ICreate,
