import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardUser";
import type { IDiscussionboardBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBan";

/**
 * E2E test for updating a discussion board user ban with valid modifications and business rule enforcement.
 *
 * This test covers not only the happy path (a moderator/admin updating a ban reason or end time for an existing ban),
 * but also multiple edge and negative cases: attempting to update forbidden attributes (e.g., user_id change),
 * attempts by unprivileged users, updates to non-existent bans (expect 404), and illegal state transitions.
 * Audit/traceability preservation is also assumed, and attempted via state validation after the update.
 *
 * Steps:
 * 1. Register two users: one who will play the role of moderator/admin (`moderator`), one regular user to be banned (`user`).
 * 2. Create a ban for the user, issued by the moderator.
 * 3. As the moderator, perform a valid update (change ban_reason and/or end_at - test shortening and lengthening ban).
 *    - Verify response: fields match update, no forbidden edits occurred.
 * 4. Attempt to update forbidden properties (such as changing banned user) and expect error.
 *    - Note: If not technically possible per API design/type info, this sub-step is omitted.
 * 5. Emulate an update attempt by a regular/non-moderator user and expect error. (Omitted if no auth/user context applies.)
 * 6. Attempt to update a non-existent ban (random UUID), expect a 404 error.
 * 7. Confirm that the updated ban state matches expected fields, and no audit-destructive mutation occurred.
 */
export async function test_api_discussionboard_bans_test_update_user_ban_valid_modification_and_restrictions(
  connection: api.IConnection,
) {
  // 1. Register a moderator.
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: moderatorEmail,
      password: typia.random<string & tags.Format<"password">>(),
      displayName: RandomGenerator.name(),
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(moderator);

  // 2. Register a user who will be banned.
  const userEmail = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: userEmail,
      password: typia.random<string & tags.Format<"password">>(),
      displayName: RandomGenerator.name(),
      isActive: true,
    } satisfies IDiscussionboardUser.ICreate,
  });
  typia.assert(user);

  // 3. Moderator creates a ban on the user.
  const moderationActionId = typia.random<string & tags.Format<"uuid">>();
  const startAt = new Date(Date.now() - 60 * 1000).toISOString(); // 1m ago (ensure active)
  const endAt = new Date(Date.now() + 3600 * 1000).toISOString(); // 1 hour after
  const ban = await api.functional.discussionboard.bans.post(connection, {
    body: {
      user_id: user.id,
      moderator_id: moderator.id,
      moderation_action_id: moderationActionId,
      start_at: startAt,
      end_at: endAt,
      ban_reason: "Obvious spam activity.",
    } satisfies IDiscussionboardBan.ICreate,
  });
  typia.assert(ban);

  // 4. Valid update by moderator: extend the ban by 1 hour and change reason
  const newEndAt = new Date(Date.parse(endAt) + 3600 * 1000).toISOString();
  const newReason = "Spam confirmed, extended.";
  const updated = await api.functional.discussionboard.bans.putById(connection, {
    id: ban.id,
    body: {
      end_at: newEndAt,
      ban_reason: newReason,
    } satisfies IDiscussionboardBan.IUpdate,
  });
  typia.assert(updated);
  TestValidator.equals("ban id not changed")(updated.id)(ban.id);
  TestValidator.equals("banned user not changed")(updated.user_id)(ban.user_id);
  TestValidator.equals("moderator not changed")(updated.moderator_id)(ban.moderator_id);
  TestValidator.equals("moderation_action_id not changed")(updated.moderation_action_id)(ban.moderation_action_id);
  TestValidator.equals("ban start_at not changed")(updated.start_at)(ban.start_at);
  TestValidator.equals("ban end_at updated")(updated.end_at)(newEndAt);
  TestValidator.equals("reason updated")(updated.ban_reason)(newReason);

  // 5. Failure case: try to update a non-existent ban (expect 404)
  await TestValidator.error("update of non-existent ban should 404")(async () => {
    await api.functional.discussionboard.bans.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: {
        end_at: new Date(Date.now() + 10 * 3600 * 1000).toISOString(),
        ban_reason: "Invalid ban update attempt.",
      } satisfies IDiscussionboardBan.IUpdate,
    });
  });

  // 6. Forbidden field change (user_id) is not available via the IUpdate DTO.
  //    Therefore, this scenario can't be coded. Skipped per technical limitation.

  // 7. Emulation of update by a non-privileged user.
  //    No explicit authentication context/role in available APIs, so this negative test is omitted.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
