import type { IDeleteResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IDeleteResult";

/**
 * Validate `DELETE /discussionboard/bans/{id}` (soft-delete a ban record) endpoint for authorization and error handling.
 *
 * This test ensures:
 * - Only moderators/admins can delete a ban (by ID) successfully.
 * - Ban is soft-deleted and removed from active bans. (Audit may persist, but that's outside this test's API scope.)
 * - Deletion as a regular user (unauthorized) is forbidden (should yield 403 error).
 * - Attempting to delete non-existent ban returns not found (404 error).
 *
 * Steps:
 * 1. Register a moderator/admin user.
 * 2. Register a regular user.
 * 3. Moderator issues a ban for the regular user.
 * 4. Moderator deletes (soft-deletes) the ban (should succeed).
 * 5. Regular user attempts to delete the same ban (should fail: 403/permission denied).
 * 6. Deletion of a non-existent ban (should fail: 404).
 *
 * Note: If the SDK does not provide authentication/session switching between users, these steps simulate intent only.
 */
export async function test_api_discussionboard_test_delete_ban_record_soft_delete_authorized_and_unauthorized(
  connection: api.IConnection,
) {
  // 1. Register moderator admin user
  const moderatorEmail: string = typia.random<string & tags.Format<"email">>();
  const moderator = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: moderatorEmail,
      password: "modPassw0rd!",
      displayName: "ModUser",
      isActive: true,
      avatarUrl: undefined,
    },
  });
  typia.assert(moderator);

  // 2. Register a regular user
  const regularEmail: string = typia.random<string & tags.Format<"email">>();
  const regular = await api.functional.discussionboard.users.post(connection, {
    body: {
      email: regularEmail,
      password: "userPassw0rd!",
      displayName: "RegUser",
      isActive: true,
      avatarUrl: undefined,
    },
  });
  typia.assert(regular);

  // 3. Moderator bans the regular user
  const ban = await api.functional.discussionboard.bans.post(connection, {
    body: {
      user_id: regular.id,
      moderator_id: moderator.id,
      moderation_action_id: typia.random<string & tags.Format<"uuid">>(),
      start_at: new Date().toISOString(),
      end_at: null,
      ban_reason: "Abusive behavior",
    },
  });
  typia.assert(ban);

  // 4. Moderator (authorized) deletes the ban record (expect success)
  const deleteResult = await api.functional.discussionboard.bans.eraseById(connection, { id: ban.id });
  typia.assert(deleteResult);
  TestValidator.equals("delete success")(deleteResult.success)(true);
  TestValidator.equals("deleted id")(deleteResult.deleted_id)(ban.id);

  // 5. Regular user tries to delete same ban (should fail with 403/permission denied)
  // NOTE: SDK does not provide account switching; this is demonstrating expected authorization failure only.
  await TestValidator.error("delete as unauthorized user must fail (403)")(
    async () => {
      await api.functional.discussionboard.bans.eraseById(connection, { id: ban.id });
    }
  );

  // 6. Attempt to delete a non-existent ban (should fail with 404)
  await TestValidator.error("delete non-existent ban must fail (404)")(
    async () => {
      await api.functional.discussionboard.bans.eraseById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
      });
    }
  );
}
